fn is_letter(b: u8) -> bool {
    (b >= 97 && b <= 122) || (b >= 65 && b <= 90)
}

fn lower(b: u8) -> u8 {
    if b >= 65 && b <= 90 { b + 32 } else { b }
}

fn main(input: Dir) -> Result<Str, Str> {
    let text = input.read_to_string("text.txt")?;
    let bytes = text.as_bytes();

    let mut words: Vec<Str> = Vec::new();
    let mut counts: Vec<i64> = Vec::new();
    let mut cur: Vec<u8> = Vec::new();

    let mut i = 0;
    while i <= bytes.len() {
        let in_word = i < bytes.len() && is_letter(bytes[i]);
        if in_word {
            cur.push(lower(bytes[i]));
        } else if cur.len() > 0 {
            let w = Str::from_utf8(cur.clone())?;
            let mut found = false;
            let mut j = 0;
            while j < words.len() {
                if words[j] == w {
                    counts[j] = counts[j] + 1;
                    found = true;
                    break;
                }
                j = j + 1;
            }
            if !found {
                words.push(w);
                counts.push(1);
            }
            cur.clear();
        }
        i = i + 1;
    }

    // Select the top five: highest count first, ties broken alphabetically.
    let mut taken: Vec<bool> = Vec::new();
    let mut k = 0;
    while k < words.len() {
        taken.push(false);
        k = k + 1;
    }

    let mut out = Str::new();
    let mut rank = 0;
    while rank < 5 && rank < words.len() {
        let mut best: i64 = -1;
        let mut j = 0;
        while j < words.len() {
            if !taken[j] {
                if best < 0
                    || counts[j] > counts[best as usize]
                    || (counts[j] == counts[best as usize] && words[j] < words[best as usize])
                {
                    best = j as i64;
                }
            }
            j = j + 1;
        }
        if best < 0 {
            break;
        }
        let b = best as usize;
        taken[b] = true;
        out.push_str(&format!("{} {}\n", words[b], counts[b]));
        rank = rank + 1;
    }

    Ok(out)
}

