struct Agg {
    region: Str,
    qty: i64,
    cents: i64,
}

fn parse_int(s: &Str) -> Option<i64> {
    match s.parse::<i64>() {
        Ok(v) => Some(v),
        Err(_) => None,
    }
}

fn main(input: Dir) -> Result<Str, Str> {
    let content = input.read("sales.csv")?;

    let mut aggs: Vec<Agg> = Vec::new();
    let mut skipped: i64 = 0;

    for (i, line) in content.lines().enumerate() {
        if i == 0 {
            continue; // header
        }
        let t = line.trim();
        if t.is_empty() {
            continue;
        }

        let fields: Vec<Str> = t.split(',').map(|f| f.trim().to_string()).collect();
        if fields.len() != 5 {
            skipped += 1;
            continue;
        }

        let qty = match parse_int(&fields[3]) {
            Some(v) => v,
            None => {
                skipped += 1;
                continue;
            }
        };
        let unit = match parse_int(&fields[4]) {
            Some(v) => v,
            None => {
                skipped += 1;
                continue;
            }
        };

        let region = fields[1].clone();
        let row_cents = qty * unit;

        let mut found = false;
        for a in aggs.iter_mut() {
            if a.region == region {
                a.qty += qty;
                a.cents += row_cents;
                found = true;
                break;
            }
        }
        if !found {
            aggs.push(Agg {
                region: region,
                qty: qty,
                cents: row_cents,
            });
        }
    }

    aggs.sort_by(|a, b| b.cents.cmp(&a.cents).then(a.region.cmp(&b.region)));

    let mut out = Str::new();
    for a in aggs.iter() {
        out.push_str(&format!(
            "{} {} {}.{:02}\n",
            a.region,
            a.qty,
            a.cents / 100,
            a.cents % 100
        ));
    }
    out.push_str(&format!("skipped {}", skipped));

    Ok(out)
}

