fn parse_int(s: Str) -> (bool, i64) {
    let mut digits: i64 = 0;
    let mut neg = false;
    let mut ok = true;
    let mut v: i64 = 0;
    let mut first = true;
    for c in s.chars() {
        if first && c == '-' {
            neg = true;
        } else if c >= '0' && c <= '9' {
            let d: i64 = (c as u32 - '0' as u32) as i64;
            v = v * 10 + d;
            digits = digits + 1;
        } else {
            ok = false;
        }
        first = false;
    }
    if digits == 0 {
        ok = false;
    }
    if neg {
        v = -v;
    }
    (ok, v)
}

