        for j in (i + 1)..n {
            if cents[j] > cents[best] || (cents[j] == cents[best] && regions[j] < regions[best]) {
                best = j;
            }
        }
        if best != i {
            let tc: i64 = cents[i];
            cents[i] = cents[best];
            cents[best] = tc;
            let tq: i64 = qtys[i];
            qtys[i] = qtys[best];
            qtys[best] = tq;
            let tr: Str = regions[i].clone();
            regions[i] = regions[best].clone();
            regions[best] = tr;
        }
    }

    let mut out = Str::new();
    for i in 0..n {
        let frac: i64 = cents[i] % 100;
        let fs: Str = if frac < 10 {
            format!("0{}", frac)
        } else {
            format!("{}", frac)
        };
        let row: Str = format!("{} {} {}.{}\n", regions[i], qtys[i], cents[i] / 100, fs);
        out.push_str(&row);
    }
    out.push_str(&format!("skipped {}", skipped));

    Ok(out)
}

use std::collections::BTreeMap;

fn parse_status(s: &Str) -> Option<u32> {
