        return None;
    }
    let mut n: u32 = 0;
    for c in s.chars() {
        let d = c.to_digit(10)?;
        n = n * 10 + d;
    }
    Some(n)
}

fn parse_size(s: &Str) -> Option<u64> {
    if s == "-" {
        return Some(0);
    }
    if s.len() == 0 {
        return None;
    }
    let mut n: u64 = 0;
    for c in s.chars() {
        let d = c.to_digit(10)?;
        n = n * 10 + d as u64;
    }
    Some(n)
}

fn parse_line(line: &Str) -> Option<(Str, u32, u64, Str)> {
    let open = line.find('"')?;
    let prefix = line[..open].trim();
    let ip = prefix.split_whitespace().next()?;

    let rest = &line[open + 1..];
    let close = rest.find('"')?;
    let request = &rest[..close];

    let mut req = request.split_whitespace();
    let _method = req.next()?;
    let raw_path = req.next()?;
    let path = match raw_path.find('?') {
        Some(i) => &raw_path[..i],
        None => raw_path,
    };

    let mut tail = rest[close + 1..].split_whitespace();
    let status_s = tail.next()?;
    let size_s = tail.next()?;
    if tail.next().is_some() {
        return None;
    }

    let status = parse_status(&status_s.to_string())?;
    let size = parse_size(&size_s.to_string())?;
    Some((ip.to_string(), status, size, path.to_string()))
}

