        if let Some((ip, status, size, path)) = parse_line(&line.to_string()) {
            *statuses.entry(status).or_insert(0) += 1;
            bytes += size;
            *paths.entry(path).or_insert(0) += 1;
            if status >= 500 && status <= 599 {
                *errors.entry(ip).or_insert(0) += 1;
            }
        }
    }

