    for (code, n) in &statuses {
        out.push(format!("{} {}", code, n));
    }

    out.push(format!("bytes {}", bytes));

    let mut best: Option<(Str, u64)> = None;
    for (p, n) in &paths {
        match &best {
            Some((_, bn)) if *n <= *bn => {}
            _ => best = Some((p.clone(), *n)),
        }
    }
    if let Some((p, n)) = best {
        out.push(format!("top {} {}", p, n));
    }

