    }

    // Error IPs: collect in alphabetical order, then emit by count descending.
    let mut list: Vec<(Str, u64)> = Vec::new();
    for (ip, n) in errors {
        list.push((ip, n));
    }

    let mut maxc: u64 = 0;
    for i in 0..list.len() {
        let (_, n) = list[i].clone();
        if n > maxc {
            maxc = n;
        }
    }

    let mut c: u64 = maxc;
    while c > 0 {
        for i in 0..list.len() {
            let (ip, n) = list[i].clone();
            if n == c {
                out.push(format!("errors {} {}", ip, n));
            }
        }
        c -= 1;
    }

    Ok(out.join("\n"))
}

enum Json {
    Null,
    Num(i64),
    Str(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct Parser {
    bytes: Vec<u8>,
    pos: usize,
}

fn bad() -> Str {
    "invalid orders.json".to_string()
}

fn hex(c: u8) -> Result<u32, Str> {
    if c >= 48 && c <= 57 {
        Ok((c - 48) as u32)
    } else if c >= 97 && c <= 102 {
        Ok((c - 87) as u32)
    } else if c >= 65 && c <= 70 {
        Ok((c - 55) as u32)
    } else {
        Err(bad())
    }
}

impl Parser {
    fn peek(&self) -> u8 {
        if self.pos < self.bytes.len() { self.bytes[self.pos] } else { 0 }
    }

    fn skip_ws(&mut self) {
        while self.peek() == 32 || self.peek() == 9 || self.peek() == 10 || self.peek() == 13 {
            self.pos += 1;
        }
    }

    fn eat(&mut self, c: u8) -> Result<(), Str> {
        self.skip_ws();
        if self.peek() == c {
            self.pos += 1;
            Ok(())
        } else {
            Err(bad())
        }
    }

    fn value(&mut self) -> Result<Json, Str> {
        self.skip_ws();
        let c = self.peek();
        if c == 123 {
            return self.object();
        }
        if c == 91 {
            return self.array();
        }
        if c == 34 {
            let s = self.string()?;
            return Ok(Json::Str(s));
        }
        if c == 45 || (c >= 48 && c <= 57) {
            return self.number();
        }
        if c == 116 {
            self.pos += 4; // true
            return Ok(Json::Null);
        }
        if c == 102 {
            self.pos += 5; // false
            return Ok(Json::Null);
        }
        if c == 110 {
            self.pos += 4; // null
            return Ok(Json::Null);
        }
        Err(bad())
    }

    fn number(&mut self) -> Result<Json, Str> {
        let mut neg = false;
        if self.peek() == 45 {
            neg = true;
            self.pos += 1;
        }
        let mut n: i64 = 0;
        while self.peek() >= 48 && self.peek() <= 57 {
            n = n * 10 + (self.peek() - 48) as i64;
            self.pos += 1;
        }
        // Skip any fraction or exponent; only integers matter here.
        while self.peek() == 46 || self.peek() == 101 || self.peek() == 69
            || self.peek() == 43 || self.peek() == 45
            || (self.peek() >= 48 && self.peek() <= 57) {
            self.pos += 1;
        }
        if neg {
            n = -n;
        }
        Ok(Json::Num(n))
    }

    fn read_hex4(&mut self) -> Result<u32, Str> {
        let mut code: u32 = 0;
        for _ in 0..4 {
            code = code * 16 + hex(self.peek())?;
            self.pos += 1;
        }
        Ok(code)
    }

    fn string(&mut self) -> Result<Str, Str> {
        self.pos += 1; // opening quote
        let mut out: Vec<u8> = Vec::new();
        loop {
            if self.pos >= self.bytes.len() {
                return Err(bad());
            }
            let c = self.bytes[self.pos];
            self.pos += 1;
            if c == 34 {
                break;
            }
            if c != 92 {
                out.push(c);
                continue;
            }
            let e = self.peek();
            self.pos += 1;
            if e == 117 {
                let mut code = self.read_hex4()?;
                if code >= 0xD800 && code <= 0xDBFF && self.peek() == 92
                    && self.pos + 1 < self.bytes.len() && self.bytes[self.pos + 1] == 117 {
                    self.pos += 2;
                    let low = self.read_hex4()?;
                    code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                }
                let ch = char::from_u32(code).unwrap_or('?');
                let enc = ch.to_string();
                out.extend_from_slice(enc.as_bytes());
            } else if e == 110 {
                out.push(10);
            } else if e == 116 {
                out.push(9);
            } else if e == 114 {
                out.push(13);
            } else if e == 98 {
                out.push(8);
            } else if e == 102 {
                out.push(12);
            } else {
                out.push(e); // \" \\ \/
            }
        }
        Str::from_utf8(out).map_err(|_| bad())
    }

    fn array(&mut self) -> Result<Json, Str> {
        self.pos += 1; // [
        let mut items: Vec<Json> = Vec::new();
        self.skip_ws();
        if self.peek() == 93 {
            self.pos += 1;
            return Ok(Json::Arr(items));
        }
        loop {
            let v = self.value()?;
            items.push(v);
            self.skip_ws();
            let c = self.peek();
            self.pos += 1;
            if c == 93 {
                break;
            }
            if c != 44 {
                return Err(bad());
            }
        }
        Ok(Json::Arr(items))
    }

    fn object(&mut self) -> Result<Json, Str> {
        self.pos += 1; // {
        let mut fields: Vec<(Str, Json)> = Vec::new();
        self.skip_ws();
        if self.peek() == 125 {
            self.pos += 1;
            return Ok(Json::Obj(fields));
        }
        loop {
            self.skip_ws();
            if self.peek() != 34 {
                return Err(bad());
            }
            let key = self.string()?;
            self.eat(58)?; // :
            let v = self.value()?;
            fields.push((key, v));
            self.skip_ws();
            let c = self.peek();
            self.pos += 1;
            if c == 125 {
                break;
            }
            if c != 44 {
                return Err(bad());
            }
        }
        Ok(Json::Obj(fields))
    }
}

fn index_of(fields: &Vec<(Str, Json)>, key: &str) -> Option<usize> {
    let mut i = 0;
    while i < fields.len() {
        if fields[i].0 == key {
            return Some(i);
        }
        i += 1;
    }
    None
}

fn str_field(fields: &Vec<(Str, Json)>, key: &str) -> Result<Str, Str> {
    match index_of(fields, key) {
        Some(i) => match &fields[i].1 {
            Json::Str(s) => Ok(s.clone()),
            _ => Err(bad()),
        },
        None => Err(bad()),
    }
}

fn num_field(fields: &Vec<(Str, Json)>, key: &str) -> Result<i64, Str> {
    match index_of(fields, key) {
        Some(i) => match &fields[i].1 {
            Json::Num(n) => Ok(*n),
            _ => Err(bad()),
        },
        None => Err(bad()),
    }
}

fn order_total(fields: &Vec<(Str, Json)>) -> Result<i64, Str> {
    let mut total: i64 = 0;
    if let Some(i) = index_of(fields, "items") {
        match &fields[i].1 {
            Json::Arr(items) => {
                for item in items.iter() {
                    match item {
                        Json::Obj(f) => {
                            let qty = num_field(f, "qty")?;
                            let price = num_field(f, "price_cents")?;
                            total += qty * price;
                        }
                        _ => return Err(bad()),
                    }
                }
            }
            _ => return Err(bad()),
        }
    }
    Ok(total)
}

fn main(input: Dir) -> Result<Str, Str> {
    let text = input
        .read_to_str("orders.json")
        .map_err(|_| "cannot read input/orders.json".to_string())?;

    let mut parser = Parser { bytes: text.as_bytes().to_vec(), pos: 0 };
    let root = parser.value()?;
    let orders = match root {
        Json::Arr(v) => v,
        _ => return Err("orders.json must be an array".to_string()),
    };

    // BTreeMap orders keys by byte-wise Ord, so uppercase sorts before lowercase.
    let mut paid: BTreeMap<Str, (i64, i64)> = BTreeMap::new();
    let mut refunded_n: i64 = 0;
    let mut refunded_total: i64 = 0;
    let mut pending_n: i64 = 0;

    for order in orders.iter() {
        let fields = match order {
            Json::Obj(f) => f,
            _ => return Err(bad()),
        };
        let status = str_field(fields, "status")?;
        if status == "paid" {
            let customer = str_field(fields, "customer")?;
            let total = order_total(fields)?;
            let entry = paid.entry(customer).or_insert((0, 0));
            entry.0 += 1;
            entry.1 += total;
        } else if status == "refunded" {
            let total = order_total(fields)?;
            refunded_n += 1;
            refunded_total += total;
        } else if status == "pending" {
            pending_n += 1;
        }
    }

    let mut out = Str::new();
    for (name, v) in paid.iter() {
        out.push_str(&format!("{} {} {}\n", name, v.0, v.1));
    }
    out.push_str(&format!("refunded {} {}\n", refunded_n, refunded_total));
    out.push_str(&format!("pending {}\n", pending_n));
    Ok(out)
}

fn bad() -> Str {
