}

fn hex(c: u8) -> Result<u32, Str> {
    if c >= 48 && c <= 57 {
        Ok((c - 48) as u32)
    } else if c >= 97 && c <= 102 {
        Ok((c - 87) as u32)
    } else if c >= 65 && c <= 70 {
        Ok((c - 55) as u32)
    } else {
        Err(bad())
    }
}

fn main(input: Dir) -> Result<Str, Str> {
    let text = input
        .read_to_str("orders.json")
        .map_err(|_| "cannot read input/orders.json".to_string())?;

    let bytes: Vec<u8> = text.as_bytes().to_vec();
    let n: usize = bytes.len();

    // BTreeMap orders keys by byte-wise Ord, so uppercase sorts before lowercase.
    let mut paid: BTreeMap<Str, (i64, i64)> = BTreeMap::new();
    let mut refunded_n: i64 = 0;
    let mut refunded_total: i64 = 0;
    let mut pending_n: i64 = 0;

    // Streaming scanner state.
    // depth: number of currently open brackets (order objects sit at depth 2,
    //        item objects at depth 4).
    // pend: which known key the next scalar value belongs to
    //       (1 status, 2 customer, 3 qty, 4 price_cents, 0 none).
    let mut depth: i64 = 0;
    let mut pend: i64 = 0;
    let mut cur_status: Str = Str::new();
    let mut cur_customer: Str = Str::new();
    let mut cur_total: i64 = 0;
    let mut cur_qty: i64 = 0;
    let mut cur_price: i64 = 0;

    let mut i: usize = 0;
    while i < n {
        let c = bytes[i];
        if c == 123 || c == 91 {
            // '{' or '['
            depth += 1;
            pend = 0;
            if c == 123 && depth == 2 {
                cur_status = Str::new();
                cur_customer = Str::new();
                cur_total = 0;
            }
            if c == 123 && depth == 4 {
                cur_qty = 0;
                cur_price = 0;
            }
            i += 1;
        } else if c == 125 || c == 93 {
            // '}' or ']'
            if c == 125 && depth == 4 {
                cur_total += cur_qty * cur_price;
            }
            if c == 125 && depth == 2 {
                if cur_status == "paid" {
                    let entry = paid.entry(cur_customer.clone()).or_insert((0, 0));
                    entry.0 += 1;
                    entry.1 += cur_total;
                } else if cur_status == "refunded" {
                    refunded_n += 1;
                    refunded_total += cur_total;
                } else if cur_status == "pending" {
                    pending_n += 1;
                }
            }
            depth -= 1;
            pend = 0;
            i += 1;
        } else if c == 34 {
            // string: read it, decoding escapes
            let mut out: Vec<u8> = Vec::new();
            i += 1;
            loop {
                if i >= n {
                    return Err(bad());
                }
                let d = bytes[i];
                i += 1;
                if d == 34 {
                    break;
                }
                if d != 92 {
                    out.push(d);
                    continue;
                }
                if i >= n {
                    return Err(bad());
                }
                let e = bytes[i];
                i += 1;
                if e == 117 {
                    if i + 4 > n {
                        return Err(bad());
                    }
                    let mut code: u32 = 0;
                    let mut k = 0;
                    while k < 4 {
                        code = code * 16 + hex(bytes[i])?;
                        i += 1;
                        k += 1;
                    }
                    if code >= 0xD800 && code <= 0xDBFF && i + 6 <= n
                        && bytes[i] == 92 && bytes[i + 1] == 117 {
                        i += 2;
                        let mut low: u32 = 0;
                        k = 0;
                        while k < 4 {
                            low = low * 16 + hex(bytes[i])?;
                            i += 1;
                            k += 1;
                        }
                        if low >= 0xDC00 && low <= 0xDFFF {
                            code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                        } else {
                            code = 0xFFFD;
                        }
                    }
                    let ch = char::from_u32(code).unwrap_or('?');
                    let enc = ch.to_string();
                    out.extend_from_slice(enc.as_bytes());
                } else if e == 110 {
                    out.push(10);
                } else if e == 116 {
                    out.push(9);
                } else if e == 114 {
                    out.push(13);
                } else if e == 98 {
                    out.push(8);
                } else if e == 102 {
                    out.push(12);
                } else {
                    out.push(e);
                }
            }
            let s = Str::from_utf8(out).map_err(|_| bad())?;

            // Is this string a key? Look past whitespace for ':'.
            let mut j = i;
            while j < n && (bytes[j] == 32 || bytes[j] == 9 || bytes[j] == 10 || bytes[j] == 13) {
                j += 1;
            }
            if j < n && bytes[j] == 58 {
                pend = 0;
                if depth == 2 {
                    if s == "status" {
                        pend = 1;
                    } else if s == "customer" {
                        pend = 2;
                    }
                } else if depth == 4 {
                    if s == "qty" {
                        pend = 3;
                    } else if s == "price_cents" {
                        pend = 4;
                    }
                }
                i = j;
            } else {
                // string value
                if pend == 1 {
                    cur_status = s;
                } else if pend == 2 {
                    cur_customer = s;
                }
                pend = 0;
            }
        } else if c == 45 || (c >= 48 && c <= 57) {
            // number
            let mut neg = false;
            if c == 45 {
                neg = true;
                i += 1;
            }
            let mut v: i64 = 0;
            while i < n && bytes[i] >= 48 && bytes[i] <= 57 {
                v = v * 10 + (bytes[i] - 48) as i64;
                i += 1;
            }
            // Skip any fraction or exponent; only integers matter here.
            while i < n && (bytes[i] == 46 || bytes[i] == 101 || bytes[i] == 69
                || bytes[i] == 43 || bytes[i] == 45
                || (bytes[i] >= 48 && bytes[i] <= 57)) {
                i += 1;
            }
            if neg {
                v = -v;
            }
            if pend == 3 {
                cur_qty = v;
            } else if pend == 4 {
                cur_price = v;
            }
            pend = 0;
        } else if c >= 97 && c <= 122 {
            // true / false / null
            pend = 0;
            i += 1;
        } else {
            // whitespace, ',' and ':'
            i += 1;
        }
    }

    if depth != 0 {
        return Err(bad());
    }

    let mut out = Str::new();
    for (name, v) in paid.iter() {
        out = format!("{}{} {} {}\n", out, name, v.0, v.1);
    }
    out = format!("{}refunded {} {}\n", out, refunded_n, refunded_total);
    out = format!("{}pending {}\n", out, pending_n);
    Ok(out)
}

