                i += 1;
            }
            if neg {
                v = -v;
            }
            if pend == 3 {
                cur_qty = v;
            } else if pend == 4 {
                cur_price = v;
            }
            pend = 0;
        } else if c >= 97 && c <= 122 {
            // true / false / null
            pend = 0;
            i += 1;
        } else {
            // whitespace, ',' and ':'
            i += 1;
        }
    }

    if depth != 0 {
        return Err(bad());
    }

    // Sort customers by name, byte-wise (selection sort over parallel vectors).
    let m: usize = names.len();
    let mut a: usize = 0;
    while a < m {
        let mut b: usize = a + 1;
        while b < m {
            if names[b] < names[a] {
                let tn = names[a].clone();
                names[a] = names[b].clone();
                names[b] = tn;
                let tc = counts[a];
                counts[a] = counts[b];
                counts[b] = tc;
                let tt = totals[a];
                totals[a] = totals[b];
                totals[b] = tt;
            }
            b += 1;
        }
        a += 1;
    }

    let mut out = Str::new();
    let mut p: usize = 0;
    while p < m {
        out = format!("{}{} {} {}\n", out, names[p], counts[p], totals[p]);
        p += 1;
    }
    out = format!("{}refunded {} {}\n", out, refunded_n, refunded_total);
    out = format!("{}pending {}\n", out, pending_n);
    Ok(out)
}

fn bad() -> Str {
    "invalid orders.json".to_string()
}

fn hex(c: u8) -> Result<u32, Str> {
    if c >= 48 && c <= 57 {
        Ok((c - 48) as u32)
    } else if c >= 97 && c <= 102 {
        Ok((c - 87) as u32)
    } else if c >= 65 && c <= 70 {
        Ok((c - 55) as u32)
    } else {
        Err(bad())
    }
}

fn eq_bytes(a: Vec<u8>, b: Vec<u8>) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut k: usize = 0;
    while k < a.len() {
        if a[k] != b[k] {
            return false;
        }
        k += 1;
    }
    true
}

// Returns -1 if a < b, 0 if equal, 1 if a > b (byte-wise).
fn cmp_bytes(a: Vec<u8>, b: Vec<u8>) -> i64 {
    let la: usize = a.len();
    let lb: usize = b.len();
    let mut k: usize = 0;
    while k < la && k < lb {
        if a[k] < b[k] {
            return -1;
        }
        if a[k] > b[k] {
            return 1;
        }
        k += 1;
    }
    if la < lb {
        -1
    } else if la > lb {
        1
    } else {
        0
    }
}

fn eq_lit(a: Vec<u8>, lit: Str) -> bool {
    let b: Vec<u8> = lit.as_bytes().to_vec();
    eq_bytes(a, b)
}

fn status_code(s: Vec<u8>) -> i64 {
    if eq_lit(s.clone(), "paid".to_string()) {
        return 1;
    }
    if eq_lit(s.clone(), "refunded".to_string()) {
        return 2;
    }
    if eq_lit(s, "pending".to_string()) {
        return 3;
    }
    0
}

fn key_code(s: Vec<u8>, depth: i64) -> i64 {
    if depth == 2 {
        if eq_lit(s.clone(), "status".to_string()) {
            return 1;
        }
        if eq_lit(s, "customer".to_string()) {
            return 2;
        }
        return 0;
    }
    if depth == 4 {
        if eq_lit(s.clone(), "qty".to_string()) {
            return 3;
        }
        if eq_lit(s, "price_cents".to_string()) {
            return 4;
        }
        return 0;
    }
    0
}

fn main(input: Dir) -> Result<Str, Str> {
    let text = input
        .read_to_str("orders.json")
        .map_err(|_| "cannot read input/orders.json".to_string())?;

    let bytes: Vec<u8> = text.as_bytes().to_vec();
    let n: usize = bytes.len();

    // Parallel vectors: names[k], counts[k], totals[k] describe one customer.
    let mut names: Vec<Vec<u8>> = Vec::new();
    let mut counts: Vec<i64> = Vec::new();
    let mut totals: Vec<i64> = Vec::new();
    let mut refunded_n: i64 = 0;
    let mut refunded_total: i64 = 0;
    let mut pending_n: i64 = 0;

    // Scanner state.
    // depth: open brackets (order objects at depth 2, item objects at depth 4).
    // pend: key the next scalar belongs to (1 status, 2 customer, 3 qty, 4 price_cents, 0 none).
    // cur_status: 0 unknown, 1 paid, 2 refunded, 3 pending.
    let mut depth: i64 = 0;
    let mut pend: i64 = 0;
    let mut cur_status: i64 = 0;
    let mut cur_customer: Vec<u8> = Vec::new();
    let mut cur_total: i64 = 0;
    let mut cur_qty: i64 = 0;
    let mut cur_price: i64 = 0;

    let mut i: usize = 0;
    while i < n {
        let c = bytes[i];
        if c == 123 || c == 91 {
            // '{' or '['
            depth += 1;
            pend = 0;
            if c == 123 && depth == 2 {
                cur_status = 0;
                cur_customer = Vec::new();
                cur_total = 0;
            }
            if c == 123 && depth == 4 {
                cur_qty = 0;
                cur_price = 0;
            }
            i += 1;
        } else if c == 125 || c == 93 {
            // '}' or ']'
            if c == 125 && depth == 4 {
                cur_total += cur_qty * cur_price;
            }
            if c == 125 && depth == 2 {
                if cur_status == 1 {
                    let mut idx: usize = names.len();
                    let mut p: usize = 0;
                    while p < names.len() {
                        if eq_bytes(names[p].clone(), cur_customer.clone()) {
                            idx = p;
                        }
                        p += 1;
                    }
                    if idx == names.len() {
                        names.push(cur_customer.clone());
                        counts.push(0);
                        totals.push(0);
                    }
                    counts[idx] = counts[idx] + 1;
                    totals[idx] = totals[idx] + cur_total;
                } else if cur_status == 2 {
                    refunded_n += 1;
                    refunded_total += cur_total;
                } else if cur_status == 3 {
                    pending_n += 1;
                }
            }
            depth -= 1;
            pend = 0;
            i += 1;
        } else if c == 34 {
            // string: read it, decoding escapes
            let mut out: Vec<u8> = Vec::new();
            i += 1;
            loop {
                if i >= n {
                    return Err(bad());
                }
                let d = bytes[i];
                i += 1;
                if d == 34 {
                    break;
                }
                if d != 92 {
                    out.push(d);
                    continue;
                }
                if i >= n {
                    return Err(bad());
                }
                let e = bytes[i];
                i += 1;
                if e == 117 {
                    if i + 4 > n {
                        return Err(bad());
                    }
                    let mut code: u32 = 0;
                    let mut k: usize = 0;
                    while k < 4 {
                        code = code * 16 + hex(bytes[i])?;
                        i += 1;
                        k += 1;
                    }
                    if code >= 0xD800 && code <= 0xDBFF && i + 6 <= n
                        && bytes[i] == 92 && bytes[i + 1] == 117 {
                        i += 2;
                        let mut low: u32 = 0;
                        k = 0;
                        while k < 4 {
                            low = low * 16 + hex(bytes[i])?;
                            i += 1;
                            k += 1;
                        }
                        if low >= 0xDC00 && low <= 0xDFFF {
                            code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                        } else {
                            code = 0xFFFD;
                        }
                    }
                    // Lone surrogates and out-of-range values become U+FFFD.
                    let mut cp: u32 = code;
                    if (cp >= 0xD800 && cp <= 0xDFFF) || cp > 0x10FFFF {
                        cp = 0xFFFD;
                    }
                    // Encode the code point as UTF-8 by hand.
                    if cp < 0x80 {
                        out.push(cp as u8);
                    } else if cp < 0x800 {
                        out.push((0xC0 | (cp >> 6)) as u8);
                        out.push((0x80 | (cp & 0x3F)) as u8);
                    } else if cp < 0x10000 {
                        out.push((0xE0 | (cp >> 12)) as u8);
                        out.push((0x80 | ((cp >> 6) & 0x3F)) as u8);
                        out.push((0x80 | (cp & 0x3F)) as u8);
                    } else {
                        out.push((0xF0 | (cp >> 18)) as u8);
                        out.push((0x80 | ((cp >> 12) & 0x3F)) as u8);
                        out.push((0x80 | ((cp >> 6) & 0x3F)) as u8);
                        out.push((0x80 | (cp & 0x3F)) as u8);
                    }
                } else if e == 110 {
                    out.push(10);
                } else if e == 116 {
                    out.push(9);
                } else if e == 114 {
                    out.push(13);
                } else if e == 98 {
                    out.push(8);
                } else if e == 102 {
                    out.push(12);
                } else {
                    out.push(e);
                }
            }

            // Is this string a key? Look past whitespace for ':'.
            let mut j: usize = i;
            while j < n && (bytes[j] == 32 || bytes[j] == 9 || bytes[j] == 10 || bytes[j] == 13) {
                j += 1;
            }
            if j < n && bytes[j] == 58 {
                pend = key_code(out, depth);
                i = j;
            } else {
                // string value
                if pend == 1 {
                    cur_status = status_code(out);
                } else if pend == 2 {
                    cur_customer = out;
                }
                pend = 0;
            }
        } else if c == 45 || (c >= 48 && c <= 57) {
            // number
            let mut neg = false;
            if c == 45 {
                neg = true;
                i += 1;
            }
            let mut v: i64 = 0;
            while i < n && bytes[i] >= 48 && bytes[i] <= 57 {
                v = v * 10 + (bytes[i] - 48) as i64;
                i += 1;
            }
            // Skip any fraction or exponent; only integers matter here.
            while i < n && (bytes[i] == 46 || bytes[i] == 101 || bytes[i] == 69
                || bytes[i] == 43 || bytes[i] == 45
                || (bytes[i] >= 48 && bytes[i] <= 57)) {
                i += 1;
            }
            if neg {
                v = -v;
            }
            if pend == 3 {
                cur_qty = v;
            } else if pend == 4 {
                cur_price = v;
            }
            pend = 0;
        } else if c >= 97 && c <= 122 {
            // true / false / null
            pend = 0;
            i += 1;
        } else {
            // whitespace, ',' and ':'
            i += 1;
        }
    }

    if depth != 0 {
        return Err(bad());
    }

    // Sort customers by name, byte-wise (selection sort over parallel vectors).
    let m: usize = names.len();
    let mut a: usize = 0;
    while a < m {
        let mut b: usize = a + 1;
        while b < m {
            if cmp_bytes(names[b].clone(), names[a].clone()) < 0 {
                let tn: Vec<u8> = names[a].clone();
                names[a] = names[b].clone();
                names[b] = tn;
                let tc: i64 = counts[a];
                counts[a] = counts[b];
                counts[b] = tc;
                let tt: i64 = totals[a];
                totals[a] = totals[b];
                totals[b] = tt;
            }
            b += 1;
        }
        a += 1;
    }

    let mut out = Str::new();
    let mut p: usize = 0;
    while p < m {
        let nm = Str::from_utf8(names[p].clone()).map_err(|_| bad())?;
        out = format!("{}{} {} {}\n", out, nm, counts[p], totals[p]);
        p += 1;
    }
    out = format!("{}refunded {} {}\n", out, refunded_n, refunded_total);
    out = format!("{}pending {}\n", out, pending_n);
    Ok(out)
}

use std::collections::BTreeSet;

fn normalize(line: &str) -> Option<String> {
    let s = line.trim().to_lowercase();
    let parts: Vec<&str> = s.split('@').collect();
    if parts.len() != 2 {
        return None;
    }
    let domain = parts[1];
    if parts[0].is_empty() {
        return None;
    }
    if domain.is_empty()
        || !domain.contains('.')
        || domain.starts_with('.')
        || domain.ends_with('.')
    {
        return None;
    }

    let mut local = parts[0].to_string();
    if domain == "gmail.com" {
        if let Some(i) = local.find('+') {
            local = local[..i].to_string();
        }
        local = local.replace('.', "");
    }
    Some(format!("{}@{}", local, domain))
}

fn main(input: Dir) -> Result<Str, Str> {
    let text = match input.read_to_string("emails.txt") {
        Ok(t) => t,
        Err(e) => return Err(format!("{}", e)),
    };

    let mut set: BTreeSet<String> = BTreeSet::new();
    let mut invalid: usize = 0;

    for line in text.lines() {
        let t = line.trim();
        if t.is_empty() {
            continue;
        }
        match normalize(t) {
            Some(addr) => {
                set.insert(addr);
            }
            None => {
                invalid += 1;
            }
        }
    }

    let mut out = String::new();
    for addr in set.iter() {
        out.push_str(addr);
        out.push('\n');
    }
    out.push_str(&format!("invalid {}", invalid));
    Ok(out)
}

