fn roman_value(c: char) -> i64 {
    match c {
        'I' => 1,
        'V' => 5,
        'X' => 10,
        'L' => 50,
        'C' => 100,
        'D' => 500,
        'M' => 1000,
        _ => 0,
    }
}

fn is_roman(s: &str) -> bool {
    if s.len() == 0 {
        return false;
    }
    for c in s.chars() {
        match c {
            'I' | 'V' | 'X' | 'L' | 'C' | 'D' | 'M' => {}
            _ => return false,
        }
    }
    true
}

fn is_decimal(s: &str) -> bool {
    if s.len() == 0 {
        return false;
    }
    for c in s.chars() {
        if c < '0' || c > '9' {
            return false;
        }
    }
    true
}

// Returns a value above 3999 as soon as it is exceeded, so long inputs cannot overflow.
fn parse_decimal(s: &str) -> i64 {
    let mut v: i64 = 0;
    for c in s.chars() {
        v = v * 10 + ((c as i64) - 48);
        if v > 3999 {
            return 4000;
        }
    }
    v
}

fn from_roman(s: &str) -> i64 {
    let chars: Vec<char> = s.chars().collect();
    let n: usize = chars.len();
    let mut total: i64 = 0;
    let mut i: usize = 0;
    while i < n {
        let v = roman_value(chars[i]);
        if i + 1 < n && v < roman_value(chars[i + 1]) {
            total -= v;
        } else {
            total += v;
        }
        i += 1;
    }
    total
}

fn to_roman(value: i64) -> String {
    let mut n = value;
    let mut out = String::new();
    while n >= 1000 {
        out.push_str("M");
        n -= 1000;
    }
    if n >= 900 {
        out.push_str("CM");
        n -= 900;
    }
    if n >= 500 {
        out.push_str("D");
        n -= 500;
    }
    if n >= 400 {
        out.push_str("CD");
        n -= 400;
    }
    while n >= 100 {
        out.push_str("C");
        n -= 100;
    }
    if n >= 90 {
        out.push_str("XC");
        n -= 90;
    }
    if n >= 50 {
        out.push_str("L");
        n -= 50;
    }
    if n >= 40 {
        out.push_str("XL");
        n -= 40;
    }
    while n >= 10 {
        out.push_str("X");
        n -= 10;
    }
    if n >= 9 {
        out.push_str("IX");
        n -= 9;
    }
    if n >= 5 {
        out.push_str("V");
        n -= 5;
    }
    if n >= 4 {
        out.push_str("IV");
        n -= 4;
    }
    while n >= 1 {
        out.push_str("I");
        n -= 1;
    }
    out
}

fn convert(line: &str) -> String {
    if is_decimal(line) {
        let v = parse_decimal(line);
        if v >= 1 && v <= 3999 {
            return to_roman(v);
        }
        return "invalid".to_string();
    }
    if is_roman(line) {
        let v = from_roman(line);
        if v >= 1 && v <= 3999 && to_roman(v) == line {
            return v.to_string();
        }
    }
    "invalid".to_string()
}

fn main(input: Dir) -> Result<Str, Str> {
    let text = match input.read_to_string("numbers.txt") {
        Ok(t) => t,
        Err(_) => return Err("cannot read input/numbers.txt".to_string()),
    };
    let mut out = String::new();
    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }
        out.push_str(line);
        out.push_str(" = ");
        out.push_str(&convert(line));
        out.push('\n');
    }
