fn closer_for(c: char) -> char {
    match c {
        '(' => ')',
        '[' => ']',
        _ => '}',
    }
}

fn is_opener(c: char) -> bool {
    c == '(' || c == '[' || c == '{'
}

fn is_closer(c: char) -> bool {
    c == ')' || c == ']' || c == '}'
}

fn check(line: &str) -> Str {
    let mut stack: Vec<char> = Vec::new();
    let mut col: i64 = 0;
    for c in line.chars() {
        col = col + 1;
        if is_opener(c) {
            stack.push(c);
        } else if is_closer(c) {
            match stack.pop() {
                None => return format!("col {}: unexpected {}", col, c),
                Some(open) => {
                    let want = closer_for(open);
                    if want != c {
                        return format!("col {}: expected {}, found {}", col, want, c);
                    }
                }
            }
        }
    }
    match stack.pop() {
        None => "ok".to_string(),
        Some(open) => format!("unclosed {}", closer_for(open)),
    }
}

