}

fn top(stack: Str) -> Str {
    let mut t: Str = "";
    for ch in stack.chars() {
        t = ch;
    }
    t
}

fn drop_top(stack: Str) -> Str {
    let mut out: Str = "";
    let mut pending: Str = "";
    for ch in stack.chars() {
        if pending != "" {
            out = out + pending;
        }
        pending = ch;
    }
    out
}

fn check(line: Str) -> Str {
    let mut stack: Str = "";
    let mut col: i64 = 0;
    for c in line.chars() {
        col = col + 1;
        if is_opener(c.clone()) {
            stack = stack + c;
        } else if is_closer(c.clone()) {
            if stack == "" {
                return "col " + col.to_str() + ": unexpected " + c;
            }
            let open = top(stack.clone());
            stack = drop_top(stack);
            let want = closer_for(open);
            if want != c {
                return "col " + col.to_str() + ": expected " + want + ", found " + c;
            }
        }
    }
