fn main(input: Dir) -> Result<Str, Str> {
    let text = input.read("timings.log")?;

    // Each record's key is "METHOD PATH". Methods contain no spaces and
    // paths cannot contain spaces (split_whitespace), so sorting these
    // keys bytewise is the same as sorting by (method, path).
    let mut recs: Vec<Rec> = Vec::new();
    for line in text.lines() {
        let fields: Vec<Str> = line.split_whitespace().collect();
        if fields.len() != 3 {
            continue;
        }
        match parse_int(fields[2].clone()) {
            Some(ms) => recs.push(Rec {
                key: format!("{} {}", fields[0], fields[1]),
                ms: ms,
            }),
            None => {}
        }
    }

    let mut keys: Vec<Str> = Vec::new();
    let mut k = 0;
    while k < recs.len() {
        keys.push(recs[k].key.clone());
        k += 1;
    }
    keys.sort();

    // Deduplicate the sorted keys.
    let mut uniq: Vec<Str> = Vec::new();
    let mut i = 0;
    while i < keys.len() {
        if i == 0 || !(keys[i] == keys[i - 1]) {
            uniq.push(keys[i].clone());
        }
        i += 1;
    }

    let mut lines: Vec<Str> = Vec::new();
    let mut u = 0;
    while u < uniq.len() {
        let key = uniq[u].clone();

        let mut times: Vec<i64> = Vec::new();
        let mut j = 0;
        while j < recs.len() {
            if recs[j].key == key {
                times.push(recs[j].ms);
            }
            j += 1;
        }
        times.sort();

        let n = times.len();
        let p50 = times[rank(50, n) - 1];
        let p95 = times[rank(95, n) - 1];
        let max = times[n - 1];

        lines.push(format!(
            "{} count={} p50={} p95={} max={}",
            key, n, p50, p95, max
        ));
        u += 1;
    }

    Ok(lines.join("\n"))
}

fn intern(names: &mut Vec<Str>, name: &str) -> usize {
    for i in 0..names.len() {
        if names[i] == name {
            return i;
        }
    }
    names.push(name.to_string());
    names.len() - 1
}

fn distances_to(n: usize, roads: &Vec<(usize, usize, i64)>, dest: usize) -> Vec<i64> {
    let inf: i64 = 1000000000000000;
    let mut dist: Vec<i64> = Vec::new();
    for _ in 0..n {
        dist.push(inf);
    }
    dist[dest] = 0;
    let mut changed = true;
    while changed {
        changed = false;
        for r in roads.iter() {
            let (a, b, w) = *r;
            if dist[a] + w < dist[b] {
                dist[b] = dist[a] + w;
                changed = true;
            }
            if dist[b] + w < dist[a] {
                dist[a] = dist[b] + w;
                changed = true;
            }
        }
    }
    dist
}

fn main(input: Dir) -> Result<Str, Str> {
    let text = input.read_to_string("routes.txt")?;

    let mut names: Vec<Str> = Vec::new();
    let mut roads: Vec<(usize, usize, i64)> = Vec::new();
    let mut trips: Vec<(usize, usize)> = Vec::new();

    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with("#") {
            continue;
        }
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts[0] == "road" && parts.len() == 4 {
            let a = intern(&mut names, parts[1]);
            let b = intern(&mut names, parts[2]);
            let w: i64 = parts[3].parse::<i64>()?;
            roads.push((a, b, w));
        } else if parts[0] == "trip" && parts.len() == 3 {
            let x = intern(&mut names, parts[1]);
            let y = intern(&mut names, parts[2]);
            trips.push((x, y));
        }
    }

    let n = names.len();
    let inf: i64 = 1000000000000000;
    let mut out = Str::new();

    for t in 0..trips.len() {
        let (x, y) = trips[t];

        if x == y {
            out.push_str(&names[x]);
            out.push_str(" 0\n");
            continue;
        }

        // dist[v] = cheapest cost from v to y
        let dist = distances_to(n, &roads, y);

        if dist[x] >= inf {
            out.push_str(&names[x]);
            out.push_str(" ");
            out.push_str(&names[y]);
            out.push_str(" unreachable\n");
            continue;
        }

        // Walk greedily: at each step take the smallest town that
        // lies on some cheapest route to y.
        let mut path: Vec<usize> = Vec::new();
        path.push(x);
        let mut cur = x;
        while cur != y {
            let mut best: usize = n;
            for r in roads.iter() {
                let (a, b, w) = *r;
                let mut nb: usize = n;
                if a == cur {
                    nb = b;
                } else if b == cur {
                    nb = a;
                }
                if nb == n {
                    continue;
                }
                if dist[nb] < inf && dist[cur] == w + dist[nb] {
                    if best == n || names[nb] < names[best] {
                        best = nb;
                    }
                }
            }
            cur = best;
            path.push(cur);
        }

        let mut line = names[path[0]].clone();
        for i in 1..path.len() {
            line.push_str(" -> ");
            line.push_str(&names[path[i]]);
        }
        line.push_str(" ");
        line.push_str(&dist[x].to_string());
        line.push_str("\n");
        out.push_str(&line);
    }

    Ok(out)
}

fn intern(names: Vec<Str>, name: Str) -> (usize, Vec<Str>) {
