            let mut best: usize = n;
            for j in 0..ra.len() {
                let a = ra[j];
                let b = rb[j];
                let w = rw[j];
                let mut nb: usize = n;
                if a == cur {
                    nb = b;
                } else if b == cur {
                    nb = a;
                }
                if nb == n {
                    continue;
                }
                if dist[nb] < inf && dist[cur] == w + dist[nb] {
                    if best == n || names[nb] < names[best] {
                        best = nb;
                    }
                }
            }
            cur = best;
            path.push(cur);
        }

        let mut line: Str = names[path[0]].clone();
        for i in 1..path.len() {
            line.push_str(" -> ");
            line.push_str(names[path[i]].clone());
        }
        line.push_str(" ");
        line.push_str(dist[x].to_string());
        line.push_str("\n");
        out.push_str(line);
    }

    Ok(out)
}

