fn distances_to(n: usize, ra: Vec<usize>, rb: Vec<usize>, rw: Vec<i64>, dest: usize) -> Vec<i64> {
    let inf: i64 = 1000000000000000;
    let mut dist: Vec<i64> = Vec::new();
    for k in 0..n {
        dist.push(inf);
    }
    dist[dest] = 0;
    let mut changed = true;
