        changed = false;
        for j in 0..ra.len() {
            let a = ra[j];
            let b = rb[j];
            let w = rw[j];
            if dist[a] + w < dist[b] {
                dist[b] = dist[a] + w;
                changed = true;
            }
            if dist[b] + w < dist[a] {
                dist[a] = dist[b] + w;
                changed = true;
            }
        }
    }
    dist
}

