enum Json {
    Null,
    Bool(bool),
    Num(i64),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

fn lit(s: &str) -> Str {
    let mut o = Str::new();
    o.push_str(s);
    o
}

fn hex(c: char) -> Result<u32, Str> {
    if c >= '0' && c <= '9' {
        Ok(c as u32 - 48)
    } else if c >= 'a' && c <= 'f' {
        Ok(c as u32 - 87)
    } else if c >= 'A' && c <= 'F' {
        Ok(c as u32 - 55)
    } else {
        Err(lit("json: bad hex digit"))
    }
}

struct Parser {
    cs: Vec<char>,
    pos: usize,
}

impl Parser {
    fn peek(&self) -> char {
        if self.pos < self.cs.len() {
            self.cs[self.pos]
        } else {
            '\0'
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.cs.len() {
            let c = self.cs[self.pos];
            if c == ' ' || c == '\n' || c == '\r' || c == '\t' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn expect(&mut self, c: char) -> Result<(), Str> {
        self.skip_ws();
        if self.peek() == c {
            self.pos += 1;
            Ok(())
        } else {
            Err(lit("json: unexpected character"))
        }
    }

    fn word(&mut self, w: &str) -> bool {
        let wc: Vec<char> = w.chars().collect();
        if self.pos + wc.len() > self.cs.len() {
            return false;
        }
        for i in 0..wc.len() {
            if self.cs[self.pos + i] != wc[i] {
                return false;
            }
        }
        self.pos += wc.len();
        true
    }

    fn value(&mut self) -> Result<Json, Str> {
        self.skip_ws();
        let c = self.peek();
        if c == '{' {
            self.obj()
        } else if c == '[' {
            self.arr()
        } else if c == '"' {
            Ok(Json::Text(self.string()?))
        } else if c == '-' || (c >= '0' && c <= '9') {
            self.num()
        } else if self.word("true") {
            Ok(Json::Bool(true))
        } else if self.word("false") {
            Ok(Json::Bool(false))
        } else if self.word("null") {
            Ok(Json::Null)
        } else {
            Err(lit("json: bad value"))
        }
    }

    fn obj(&mut self) -> Result<Json, Str> {
        self.expect('{')?;
        let mut items: Vec<(Str, Json)> = Vec::new();
        self.skip_ws();
        if self.peek() == '}' {
            self.pos += 1;
            return Ok(Json::Obj(items));
        }
        loop {
            let k = self.string()?;
            self.expect(':')?;
            let v = self.value()?;
            items.push((k, v));
            self.skip_ws();
            if self.peek() == ',' {
                self.pos += 1;
            } else {
                self.expect('}')?;
                break;
            }
        }
        Ok(Json::Obj(items))
    }

    fn arr(&mut self) -> Result<Json, Str> {
        self.expect('[')?;
        let mut items: Vec<Json> = Vec::new();
        self.skip_ws();
        if self.peek() == ']' {
            self.pos += 1;
            return Ok(Json::Arr(items));
        }
        loop {
            let v = self.value()?;
            items.push(v);
            self.skip_ws();
            if self.peek() == ',' {
                self.pos += 1;
            } else {
                self.expect(']')?;
                break;
            }
        }
        Ok(Json::Arr(items))
    }

    fn string(&mut self) -> Result<Str, Str> {
        self.skip_ws();
        if self.peek() != '"' {
            return Err(lit("json: expected string"));
        }
        self.pos += 1;
        let mut out = Str::new();
        loop {
            if self.pos >= self.cs.len() {
                return Err(lit("json: unterminated string"));
            }
            let c = self.cs[self.pos];
            self.pos += 1;
            if c == '"' {
                break;
            }
            if c == '\\' {
                let e = self.peek();
                self.pos += 1;
                if e == 'n' {
                    out.push('\n');
                } else if e == 't' {
                    out.push('\t');
                } else if e == 'r' {
                    out.push('\r');
                } else if e == 'b' {
                    out.push('\u{8}');
                } else if e == 'f' {
                    out.push('\u{c}');
                } else if e == 'u' {
                    let mut code: u32 = 0;
                    for _ in 0..4 {
                        let h = self.peek();
                        self.pos += 1;
                        code = code * 16 + hex(h)?;
                    }
                    match char::from_u32(code) {
                        Some(ch) => out.push(ch),
                        None => return Err(lit("json: bad unicode escape")),
                    }
                } else {
                    out.push(e);
                }
            } else {
                out.push(c);
            }
        }
        Ok(out)
    }

    fn num(&mut self) -> Result<Json, Str> {
        let mut neg = false;
        if self.peek() == '-' {
            neg = true;
            self.pos += 1;
        }
        let mut n: i64 = 0;
        let mut digits = 0;
        while self.peek() >= '0' && self.peek() <= '9' {
            let d = (self.peek() as u32 - 48) as i64;
            n = n * 10 + d;
            digits += 1;
            self.pos += 1;
        }
        if digits == 0 {
            return Err(lit("json: bad number"));
        }
        Ok(Json::Num(if neg { -n } else { n }))
    }
}

fn parse(text: Str) -> Result<Json, Str> {
    let mut p = Parser {
        cs: text.chars().collect(),
        pos: 0,
    };
    let v = p.value()?;
    p.skip_ws();
    if p.pos != p.cs.len() {
        return Err(lit("json: trailing data"));
    }
    Ok(v)
}

fn find(items: &Vec<(Str, Json)>, k: &Str) -> Option<usize> {
    for i in 0..items.len() {
        if items[i].0 == *k {
            return Some(i);
        }
    }
    None
}

// Merge `over` into `base`. Nulls in `over` remove keys; objects merge
// recursively; anything else in `over` replaces the base value.
fn merge_obj(mut base: Vec<(Str, Json)>, over: Vec<(Str, Json)>) -> Vec<(Str, Json)> {
    for (k, v) in over {
        let at = find(&base, &k);
        match v {
            Json::Null => {
                if let Some(i) = at {
                    base.remove(i);
                }
            }
            Json::Obj(ov) => {
                let existing = match at {
                    Some(i) => Some(base.remove(i).1),
                    None => None,
                };
                let merged = match existing {
                    Some(Json::Obj(bv)) => merge_obj(bv, ov),
                    _ => merge_obj(Vec::new(), ov),
                };
                base.push((k, Json::Obj(merged)));
            }
            other => {
                if let Some(i) = at {
                    base.remove(i);
                }
                base.push((k, other));
            }
        }
    }
    base
}

fn hexchar(d: u32) -> char {
    if d < 10 {
        char::from_u32(48 + d).unwrap()
    } else {
        char::from_u32(87 + d).unwrap()
    }
}

fn quote(s: &Str) -> Str {
    let mut o = Str::new();
    o.push('"');
    for c in s.chars() {
        if c == '"' {
            o.push_str("\\\"");
        } else if c == '\\' {
            o.push_str("\\\\");
        } else if c == '\n' {
            o.push_str("\\n");
        } else if c == '\r' {
            o.push_str("\\r");
        } else if c == '\t' {
            o.push_str("\\t");
        } else if (c as u32) < 0x20 {
            let n = c as u32;
            o.push_str("\\u00");
            o.push(hexchar(n / 16));
            o.push(hexchar(n % 16));
        } else {
            o.push(c);
        }
    }
    o.push('"');
    o
}

fn render(v: &Json) -> Str {
    match v {
        Json::Null => lit("null"),
        Json::Bool(b) => {
            if *b {
                lit("true")
            } else {
                lit("false")
            }
        }
        Json::Num(n) => n.to_string(),
        Json::Text(s) => quote(s),
        Json::Arr(_) => lit("[]"),
        Json::Obj(_) => lit("{}"),
    }
}

fn join(path: &Str, key: &Str) -> Str {
    if path.len() == 0 {
        key.clone()
    } else {
        let mut o = path.clone();
        o.push('.');
        o.push_str(key);
        o
    }
}

fn flatten(path: &Str, v: &Json, out: &mut Vec<(Str, Str)>) {
    match v {
        Json::Obj(items) => {
            if items.len() == 0 {
                out.push((path.clone(), lit("{}")));
            } else {
                for (k, c) in items.iter() {
                    flatten(&join(path, k), c, out);
                }
            }
        }
        Json::Arr(items) => {
            if items.len() == 0 {
                out.push((path.clone(), lit("[]")));
            } else {
                for i in 0..items.len() {
                    let idx = i.to_string();
                    flatten(&join(path, &idx), &items[i], out);
                }
            }
        }
        _ => out.push((path.clone(), render(v))),
    }
}

fn sort_rows(v: &mut Vec<(Str, Str)>) {
    for i in 1..v.len() {
        let mut j = i;
        while j > 0 && v[j - 1].0 > v[j].0 {
            v.swap(j - 1, j);
            j -= 1;
        }
    }
}

fn main(input: Dir) -> Result<Str, Str> {
    let base_text = input.read("base.json")?;
    let over_text = input.read("override.json")?;
    let base = parse(base_text)?;
    let over = parse(over_text)?;

    let base_items = match base {
        Json::Obj(items) => items,
        _ => return Err(lit("base.json is not an object")),
    };
    let over_items = match over {
        Json::Obj(items) => items,
        _ => return Err(lit("override.json is not an object")),
    };

    let merged = Json::Obj(merge_obj(base_items, over_items));

    let mut rows: Vec<(Str, Str)> = Vec::new();
    flatten(&Str::new(), &merged, &mut rows);
    sort_rows(&mut rows);

    let mut out = Str::new();
    for i in 0..rows.len() {
        if i > 0 {
            out.push('\n');
        }
        out.push_str(&rows[i].0);
        out.push('=');
        out.push_str(&rows[i].1);
    }
    Ok(out)
}

enum Json {
    Null,
    Bool(bool),
    Num(i64),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

fn lit(s: Str) -> Str {
    s
}

fn hex(c: char) -> Result<u32, Str> {
    if c >= '0' && c <= '9' {
        Ok(c as u32 - 48)
    } else if c >= 'a' && c <= 'f' {
        Ok(c as u32 - 87)
    } else if c >= 'A' && c <= 'F' {
        Ok(c as u32 - 55)
    } else {
        Err(lit("json: bad hex digit"))
    }
}

// The character buffer ends with a '\0' sentinel, which doubles as end of input.
struct Parser {
    cs: Vec<char>,
    pos: usize,
}

fn skip_ws(p: Parser) -> Parser {
    let mut p = p;
    loop {
        let c = p.cs[p.pos];
        if c == ' ' || c == '\n' || c == '\r' || c == '\t' {
            p.pos += 1;
        } else {
            break;
        }
    }
    p
}

fn expect_char(p: Parser, c: char) -> Result<Parser, Str> {
    let mut p = skip_ws(p);
    if p.cs[p.pos] == c {
        p.pos += 1;
        Ok(p)
    } else {
        Err(lit("json: unexpected character"))
    }
}

fn parse_word(p: Parser, w: Str) -> (Parser, bool) {
    let mut p = p;
    let wc: Vec<char> = w.chars().collect();
    if p.pos + wc.len() > p.cs.len() {
        return (p, false);
    }
    for i in 0..wc.len() {
        if p.cs[p.pos + i] != wc[i] {
            return (p, false);
        }
    }
    p.pos += wc.len();
    (p, true)
}

fn parse_value(p: Parser) -> Result<(Parser, Json), Str> {
    let p = skip_ws(p);
    let c = p.cs[p.pos];
    if c == '{' {
        parse_obj(p)
    } else if c == '[' {
        parse_arr(p)
    } else if c == '"' {
        let (p, s) = parse_string(p)?;
        Ok((p, Json::Text(s)))
    } else if c == '-' || (c >= '0' && c <= '9') {
        parse_num(p)
    } else {
        let (p, ok) = parse_word(p, lit("true"));
        if ok {
            return Ok((p, Json::Bool(true)));
        }
        let (p, ok) = parse_word(p, lit("false"));
        if ok {
            return Ok((p, Json::Bool(false)));
        }
        let (p, ok) = parse_word(p, lit("null"));
        if ok {
            return Ok((p, Json::Null));
        }
        Err(lit("json: bad value"))
    }
}

fn parse_obj(p: Parser) -> Result<(Parser, Json), Str> {
    let p = expect_char(p, '{')?;
    let mut p = skip_ws(p);
    let mut items: Vec<(Str, Json)> = Vec::new();
    if p.cs[p.pos] == '}' {
        p.pos += 1;
        return Ok((p, Json::Obj(items)));
    }
    loop {
        let (np, k) = parse_string(p)?;
        let np = expect_char(np, ':')?;
        let (np, v) = parse_value(np)?;
        items.push((k, v));
        let mut np = skip_ws(np);
        if np.cs[np.pos] == ',' {
            np.pos += 1;
            p = np;
        } else {
            p = expect_char(np, '}')?;
            break;
        }
    }
    Ok((p, Json::Obj(items)))
}

fn parse_arr(p: Parser) -> Result<(Parser, Json), Str> {
    let p = expect_char(p, '[')?;
    let mut p = skip_ws(p);
    let mut items: Vec<Json> = Vec::new();
    if p.cs[p.pos] == ']' {
        p.pos += 1;
        return Ok((p, Json::Arr(items)));
    }
    loop {
        let (np, v) = parse_value(p)?;
        items.push(v);
        let mut np = skip_ws(np);
        if np.cs[np.pos] == ',' {
            np.pos += 1;
            p = np;
        } else {
            p = expect_char(np, ']')?;
            break;
        }
    }
    Ok((p, Json::Arr(items)))
}

fn parse_string(p: Parser) -> Result<(Parser, Str), Str> {
    let mut p = skip_ws(p);
    if p.cs[p.pos] != '"' {
        return Err(lit("json: expected string"));
    }
    p.pos += 1;
    let mut out = Str::new();
    loop {
        let c = p.cs[p.pos];
        if c == '\0' {
            return Err(lit("json: unterminated string"));
        }
        p.pos += 1;
        if c == '"' {
            break;
        }
        if c == '\\' {
            let e = p.cs[p.pos];
            if e == '\0' {
                return Err(lit("json: unterminated string"));
            }
            p.pos += 1;
            if e == 'n' {
                out.push('\n');
            } else if e == 't' {
                out.push('\t');
            } else if e == 'r' {
                out.push('\r');
            } else if e == 'b' {
                out.push('\u{8}');
            } else if e == 'f' {
                out.push('\u{c}');
            } else if e == 'u' {
                let mut code: u32 = 0;
                for _ in 0..4 {
                    let h = p.cs[p.pos];
                    p.pos += 1;
                    code = code * 16 + hex(h)?;
                }
                match char::from_u32(code) {
                    Some(ch) => out.push(ch),
                    None => return Err(lit("json: bad unicode escape")),
                }
            } else {
                out.push(e);
            }
        } else {
            out.push(c);
        }
    }
    Ok((p, out))
}

fn parse_num(p: Parser) -> Result<(Parser, Json), Str> {
    let mut p = p;
    let mut neg = false;
    if p.cs[p.pos] == '-' {
        neg = true;
        p.pos += 1;
    }
    let mut n: i64 = 0;
    let mut digits = 0;
    while p.cs[p.pos] >= '0' && p.cs[p.pos] <= '9' {
        let d = (p.cs[p.pos] as u32 - 48) as i64;
        n = n * 10 + d;
        digits += 1;
        p.pos += 1;
    }
    if digits == 0 {
        return Err(lit("json: bad number"));
    }
    Ok((p, Json::Num(if neg { -n } else { n })))
}

fn parse(text: Str) -> Result<Json, Str> {
    let mut cs: Vec<char> = text.chars().collect();
    cs.push('\0');
    let p = Parser { cs: cs, pos: 0 };
    let (p, v) = parse_value(p)?;
    let p = skip_ws(p);
    if p.pos + 1 != p.cs.len() {
        return Err(lit("json: trailing data"));
    }
    Ok(v)
}

// Remove `k` from `base`, returning the remaining entries and the removed value.
fn take_key(base: Vec<(Str, Json)>, k: Str) -> (Vec<(Str, Json)>, Option<Json>) {
    let mut kept: Vec<(Str, Json)> = Vec::new();
    let mut found: Option<Json> = None;
    for (ik, iv) in base {
        if ik == k {
            found = Some(iv);
        } else {
            kept.push((ik, iv));
        }
    }
    (kept, found)
}

// Merge `over` into `base`. Nulls in `over` remove keys; objects merge
// recursively; anything else in `over` replaces the base value.
fn merge_obj(base: Vec<(Str, Json)>, over: Vec<(Str, Json)>) -> Vec<(Str, Json)> {
    let mut base = base;
    for (k, v) in over {
        match v {
            Json::Null => {
                let (rest, _) = take_key(base, k);
                base = rest;
            }
            Json::Obj(ov) => {
                let (rest, existing) = take_key(base, k.clone());
                let merged = match existing {
                    Some(Json::Obj(bv)) => merge_obj(bv, ov),
                    _ => merge_obj(Vec::new(), ov),
                };
                base = rest;
                base.push((k, Json::Obj(merged)));
            }
            other => {
                let (rest, _) = take_key(base, k.clone());
                base = rest;
                base.push((k, other));
            }
        }
    }
    base
}

fn hexchar(d: u32) -> char {
    if d < 10 {
        char::from_u32(48 + d).unwrap()
    } else {
        char::from_u32(87 + d).unwrap()
    }
}

fn quote(s: Str) -> Str {
    let mut o = Str::new();
    o.push('"');
    for c in s.chars() {
        if c == '"' {
            o.push_str(lit("\\\""));
        } else if c == '\\' {
            o.push_str(lit("\\\\"));
        } else if c == '\n' {
            o.push_str(lit("\\n"));
        } else if c == '\r' {
            o.push_str(lit("\\r"));
        } else if c == '\t' {
            o.push_str(lit("\\t"));
        } else if (c as u32) < 0x20 {
            let n = c as u32;
            o.push_str(lit("\\u00"));
            o.push(hexchar(n / 16));
            o.push(hexchar(n % 16));
        } else {
            o.push(c);
        }
    }
    o.push('"');
    o
}

fn render(v: Json) -> Str {
    match v {
        Json::Null => lit("null"),
        Json::Bool(b) => {
            if b {
                lit("true")
            } else {
                lit("false")
            }
        }
        Json::Num(n) => n.to_string(),
        Json::Text(s) => quote(s),
        Json::Arr(_) => lit("[]"),
        Json::Obj(_) => lit("{}"),
    }
}

fn join(path: Str, key: Str) -> Str {
    if path.len() == 0 {
        key
    } else {
        let mut o = path;
        o.push('.');
        o.push_str(key);
        o
    }
}

fn flatten(path: Str, v: Json, out: Vec<(Str, Str)>) -> Vec<(Str, Str)> {
    let mut out = out;
    match v {
        Json::Obj(items) => {
            if items.len() == 0 {
                out.push((path, lit("{}")));
            } else {
                for (k, c) in items {
                    let key = join(path.clone(), k);
                    out = flatten(key, c, out);
                }
            }
        }
        Json::Arr(items) => {
            if items.len() == 0 {
                out.push((path, lit("[]")));
            } else {
                let mut i: usize = 0;
                for c in items {
                    let key = join(path.clone(), i.to_string());
                    out = flatten(key, c, out);
                    i += 1;
                }
            }
        }
        other => {
            out.push((path, render(other)));
        }
    }
    out
}

fn sort_rows(v: Vec<(Str, Str)>) -> Vec<(Str, Str)> {
    let mut v = v;
    for i in 1..v.len() {
        let mut j = i;
        while j > 0 && v[j - 1].0 > v[j].0 {
            v.swap(j - 1, j);
            j -= 1;
        }
    }
    v
}

fn main(input: Dir) -> Result<Str, Str> {
    let base_text = input.read("base.json")?;
    let over_text = input.read("override.json")?;
    let base = parse(base_text)?;
    let over = parse(over_text)?;

    let base_items = match base {
        Json::Obj(items) => items,
        _ => return Err(lit("base.json is not an object")),
    };
    let over_items = match over {
        Json::Obj(items) => items,
        _ => return Err(lit("override.json is not an object")),
    };

    let merged = merge_obj(base_items, over_items);

    let rows = flatten(Str::new(), Json::Obj(merged), Vec::new());
    let rows = sort_rows(rows);

    let mut out = Str::new();
    let mut first = true;
    for (k, v) in rows {
        if !first {
            out.push('\n');
        }
        first = false;
        out.push_str(k);
        out.push('=');
        out.push_str(v);
    }
    Ok(out)
}

