fn lit(s: Str) -> Str {
    s
}

// Split a string into its characters, each kept as a one-character Str.
fn split(s: Str) -> Vec<Str> {
    let mut out: Vec<Str> = Vec::new();
    for c in s.chars() {
        out.push(c);
    }
    out
}

// Value of a single decimal digit, or -1 if `c` is not a digit.
fn digit(c: Str) -> i64 {
    if c == lit("0") {
        0
    } else if c == lit("1") {
        1
    } else if c == lit("2") {
        2
    } else if c == lit("3") {
        3
    } else if c == lit("4") {
        4
    } else if c == lit("5") {
        5
    } else if c == lit("6") {
        6
    } else if c == lit("7") {
        7
    } else if c == lit("8") {
        8
    } else if c == lit("9") {
        9
    } else {
        -1
    }
}

// The character list ends with an empty-string sentinel, which doubles as end of input.
struct Parser {
    cs: Vec<Str>,
    pos: usize,
}

fn skip_ws(p: Parser) -> Parser {
    let mut p = p;
    loop {
        let c = p.cs[p.pos].clone();
        if c == lit(" ") || c == lit("\n") || c == lit("\r") || c == lit("\t") {
            p.pos += 1;
        } else {
            break;
        }
    }
    p
}

fn expect_char(p: Parser, c: Str) -> Result<Parser, Str> {
    let mut p = skip_ws(p);
    if p.cs[p.pos] == c {
        p.pos += 1;
        Ok(p)
    } else {
        Err(lit("json: unexpected character"))
    }
}

fn parse_word(p: Parser, w: Str) -> (Parser, bool) {
    let mut p = p;
    let wc = split(w);
    if p.pos + wc.len() > p.cs.len() {
        return (p, false);
    }
    for i in 0..wc.len() {
        if p.cs[p.pos + i] != wc[i] {
            return (p, false);
        }
    }
    p.pos += wc.len();
    (p, true)
}

fn parse_value(p: Parser) -> Result<(Parser, Json), Str> {
    let p = skip_ws(p);
    let c = p.cs[p.pos].clone();
    if c == lit("{") {
        parse_obj(p)
    } else if c == lit("[") {
        parse_arr(p)
    } else if c == lit("\"") {
        let (p, s) = parse_string(p)?;
        Ok((p, Json::Text(s)))
    } else if c == lit("-") || digit(c.clone()) >= 0 {
        parse_num(p)
    } else {
        let (p, ok) = parse_word(p, lit("true"));
        if ok {
            return Ok((p, Json::Bool(true)));
        }
        let (p, ok) = parse_word(p, lit("false"));
        if ok {
            return Ok((p, Json::Bool(false)));
        }
        let (p, ok) = parse_word(p, lit("null"));
        if ok {
            return Ok((p, Json::Null));
        }
        Err(lit("json: bad value"))
    }
}

fn parse_obj(p: Parser) -> Result<(Parser, Json), Str> {
    let p = expect_char(p, lit("{"))?;
    let mut p = skip_ws(p);
    let mut items: Vec<(Str, Json)> = Vec::new();
    if p.cs[p.pos] == lit("}") {
        p.pos += 1;
        return Ok((p, Json::Obj(items)));
    }
    loop {
        let (np, k) = parse_string(p)?;
        let np = expect_char(np, lit(":"))?;
        let (np, v) = parse_value(np)?;
        items.push((k, v));
        let mut np = skip_ws(np);
        if np.cs[np.pos] == lit(",") {
            np.pos += 1;
            p = np;
        } else {
            p = expect_char(np, lit("}"))?;
            break;
        }
    }
    Ok((p, Json::Obj(items)))
}

fn parse_arr(p: Parser) -> Result<(Parser, Json), Str> {
    let p = expect_char(p, lit("["))?;
    let mut p = skip_ws(p);
    let mut items: Vec<Json> = Vec::new();
    if p.cs[p.pos] == lit("]") {
        p.pos += 1;
        return Ok((p, Json::Arr(items)));
    }
    loop {
        let (np, v) = parse_value(p)?;
        items.push(v);
        let mut np = skip_ws(np);
        if np.cs[np.pos] == lit(",") {
            np.pos += 1;
            p = np;
        } else {
            p = expect_char(np, lit("]"))?;
            break;
        }
    }
    Ok((p, Json::Arr(items)))
}

fn parse_string(p: Parser) -> Result<(Parser, Str), Str> {
    let mut p = skip_ws(p);
    if p.cs[p.pos] != lit("\"") {
        return Err(lit("json: expected string"));
    }
    p.pos += 1;
    let mut out = Str::new();
    loop {
        let c = p.cs[p.pos].clone();
        if c == lit("") {
            return Err(lit("json: unterminated string"));
        }
        p.pos += 1;
        if c == lit("\"") {
            break;
        }
        if c == lit("\\") {
            let e = p.cs[p.pos].clone();
            if e == lit("") {
                return Err(lit("json: unterminated string"));
            }
            p.pos += 1;
            if e == lit("n") {
                out.push_str(lit("\n"));
            } else if e == lit("t") {
                out.push_str(lit("\t"));
            } else if e == lit("r") {
                out.push_str(lit("\r"));
            } else if e == lit("b") {
                out.push_str(lit("\u{8}"));
            } else if e == lit("f") {
                out.push_str(lit("\u{c}"));
            } else if e == lit("u") {
                return Err(lit("json: unicode escapes are not supported"));
            } else {
                out.push_str(e);
            }
        } else {
            out.push_str(c);
        }
    }
    Ok((p, out))
}

fn parse_num(p: Parser) -> Result<(Parser, Json), Str> {
    let mut p = p;
    let mut neg = false;
    if p.cs[p.pos] == lit("-") {
        neg = true;
        p.pos += 1;
    }
    let mut n: i64 = 0;
    let mut digits = 0;
    loop {
        let d = digit(p.cs[p.pos].clone());
        if d < 0 {
            break;
        }
        n = n * 10 + d;
        digits += 1;
        p.pos += 1;
    }
    if digits == 0 {
        return Err(lit("json: bad number"));
    }
    Ok((p, Json::Num(if neg { -n } else { n })))
}

fn parse(text: Str) -> Result<Json, Str> {
    let mut cs: Vec<Str> = split(text);
    cs.push(lit(""));
    let p = Parser { cs: cs, pos: 0 };
    let (p, v) = parse_value(p)?;
    let p = skip_ws(p);
    if p.pos + 1 != p.cs.len() {
        return Err(lit("json: trailing data"));
    }
    Ok(v)
}

