            return Ok((p, Json::Bool(false)));
        }
        let (p, ok) = parse_word(p, lit("null"));
        if ok {
            return Ok((p, Json::Null));
        }
        Err(lit("json: bad value"))
    }
}

fn parse_obj(p: Parser) -> Result<(Parser, Json), Str> {
    let p = expect_char(p, lit("{"))?;
    let mut p = skip_ws(p);
    let mut items: Vec<(Str, Json)> = Vec::new();
    if p.cs[p.pos] == lit("}") {
        p.pos += 1;
        return Ok((p, Json::Obj(items)));
    }
    loop {
        let (np, k) = parse_string(p)?;
        let np = expect_char(np, lit(":"))?;
        let (np, v) = parse_value(np)?;
        items.push((k, v));
        let mut np = skip_ws(np);
        if np.cs[np.pos] == lit(",") {
            np.pos += 1;
            p = np;
        } else {
            p = expect_char(np, lit("}"))?;
            break;
        }
    }
    Ok((p, Json::Obj(items)))
}

fn parse_arr(p: Parser) -> Result<(Parser, Json), Str> {
    let p = expect_char(p, lit("["))?;
    let mut p = skip_ws(p);
    let mut items: Vec<Json> = Vec::new();
    if p.cs[p.pos] == lit("]") {
        p.pos += 1;
        return Ok((p, Json::Arr(items)));
    }
    loop {
        let (np, v) = parse_value(p)?;
        items.push(v);
        let mut np = skip_ws(np);
        if np.cs[np.pos] == lit(",") {
            np.pos += 1;
            p = np;
        } else {
            p = expect_char(np, lit("]"))?;
            break;
        }
    }
    Ok((p, Json::Arr(items)))
}

fn parse_string(p: Parser) -> Result<(Parser, Str), Str> {
    let mut p = skip_ws(p);
    if p.cs[p.pos] != lit("\"") {
        return Err(lit("json: expected string"));
    }
    p.pos += 1;
    let mut out = Str::new();
    loop {
        let c = p.cs[p.pos].clone();
        if c == lit("") {
            return Err(lit("json: unterminated string"));
        }
        p.pos += 1;
        if c == lit("\"") {
            break;
        }
        if c == lit("\\") {
            let e = p.cs[p.pos].clone();
            if e == lit("") {
                return Err(lit("json: unterminated string"));
            }
            p.pos += 1;
            if e == lit("n") {
                out.push_str(lit("\n"));
            } else if e == lit("t") {
                out.push_str(lit("\t"));
            } else if e == lit("r") {
                out.push_str(lit("\r"));
            } else if e == lit("b") || e == lit("f") || e == lit("u") {
                return Err(lit("json: unsupported escape"));
            } else {
                out.push_str(e);
            }
        } else {
            out.push_str(c);
        }
    }
    Ok((p, out))
}

fn parse_num(p: Parser) -> Result<(Parser, Json), Str> {
    let mut p = p;
    let mut neg = false;
    if p.cs[p.pos] == lit("-") {
        neg = true;
        p.pos += 1;
    }
    let mut n: i64 = 0;
    let mut digits = 0;
    loop {
        let d = digit(p.cs[p.pos].clone());
        if d < 0 {
            break;
        }
        n = n * 10 + d;
        digits += 1;
        p.pos += 1;
    }
    if digits == 0 {
        return Err(lit("json: bad number"));
    }
    Ok((p, Json::Num(if neg { -n } else { n })))
}

fn parse(text: Str) -> Result<Json, Str> {
    let mut cs: Vec<Str> = split(text);
    cs.push(lit(""));
    let p = Parser { cs: cs, pos: 0 };
    let (p, v) = parse_value(p)?;
    let p = skip_ws(p);
    if p.pos + 1 != p.cs.len() {
        return Err(lit("json: trailing data"));
    }
    Ok(v)
}

// Remove `k` from `base`, returning the remaining entries and the removed value.
fn take_key(base: Vec<(Str, Json)>, k: Str) -> (Vec<(Str, Json)>, Option<Json>) {
    let mut kept: Vec<(Str, Json)> = Vec::new();
    let mut found: Option<Json> = None;
    for (ik, iv) in base {
        if ik == k {
            found = Some(iv);
        } else {
            kept.push((ik, iv));
        }
    }
    (kept, found)
}

// Merge `over` into `base`. Nulls in `over` remove keys; objects merge
// recursively; anything else in `over` replaces the base value.
fn merge_obj(base: Vec<(Str, Json)>, over: Vec<(Str, Json)>) -> Vec<(Str, Json)> {
    let mut base = base;
    for (k, v) in over {
        match v {
            Json::Null => {
                let (rest, _) = take_key(base, k);
                base = rest;
            }
            Json::Obj(ov) => {
                let (rest, existing) = take_key(base, k.clone());
                let merged = match existing {
                    Some(Json::Obj(bv)) => merge_obj(bv, ov),
                    _ => merge_obj(Vec::new(), ov),
                };
                base = rest;
                base.push((k, Json::Obj(merged)));
            }
            other => {
                let (rest, _) = take_key(base, k.clone());
                base = rest;
                base.push((k, other));
            }
        }
    }
    base
}

fn quote(s: Str) -> Str {
    let mut o = Str::new();
    o.push_str(lit("\""));
    for c in split(s) {
        if c == lit("\"") {
            o.push_str(lit("\\\""));
        } else if c == lit("\\") {
            o.push_str(lit("\\\\"));
        } else if c == lit("\n") {
            o.push_str(lit("\\n"));
        } else if c == lit("\r") {
            o.push_str(lit("\\r"));
        } else if c == lit("\t") {
            o.push_str(lit("\\t"));
        } else {
            o.push_str(c);
        }
    }
    o.push_str(lit("\""));
    o
}

fn render(v: Json) -> Str {
    match v {
        Json::Null => lit("null"),
        Json::Bool(b) => {
            if b {
                lit("true")
            } else {
                lit("false")
            }
        }
        Json::Num(n) => n.to_string(),
        Json::Text(s) => quote(s),
        Json::Arr(_) => lit("[]"),
        Json::Obj(_) => lit("{}"),
    }
}

fn join(path: Str, key: Str) -> Str {
    if path.len() == 0 {
        key
    } else {
        let mut o = path;
        o.push_str(lit("."));
        o.push_str(key);
        o
    }
}

fn flatten(path: Str, v: Json, out: Vec<(Str, Str)>) -> Vec<(Str, Str)> {
    let mut out = out;
    match v {
        Json::Obj(items) => {
            if items.len() == 0 {
                out.push((path, lit("{}")));
            } else {
                for (k, c) in items {
                    let key = join(path.clone(), k);
                    out = flatten(key, c, out);
                }
            }
        }
        Json::Arr(items) => {
            if items.len() == 0 {
                out.push((path, lit("[]")));
            } else {
                let mut i: usize = 0;
                for c in items {
                    let key = join(path.clone(), i.to_string());
                    out = flatten(key, c, out);
                    i += 1;
                }
            }
        }
        other => {
            out.push((path, render(other)));
        }
    }
    out
}

fn sort_rows(v: Vec<(Str, Str)>) -> Vec<(Str, Str)> {
    let mut v = v;
    for i in 1..v.len() {
        let mut j = i;
        while j > 0 && v[j - 1].0 > v[j].0 {
            v.swap(j - 1, j);
            j -= 1;
        }
    }
    v
}

fn main(input: Dir) -> Result<Str, Str> {
    let base_text = input.read("base.json")?;
    let over_text = input.read("override.json")?;
    let base = parse(base_text)?;
    let over = parse(over_text)?;

    let base_items = match base {
        Json::Obj(items) => items,
        _ => return Err(lit("base.json is not an object")),
    };
    let over_items = match over {
        Json::Obj(items) => items,
        _ => return Err(lit("override.json is not an object")),
    };

    let merged = merge_obj(base_items, over_items);

    let rows = flatten(Str::new(), Json::Obj(merged), Vec::new());
    let rows = sort_rows(rows);

    let mut out = Str::new();
    let mut first = true;
    for (k, v) in rows {
        if !first {
            out.push_str(lit("\n"));
        }
        first = false;
        out.push_str(k);
        out.push_str(lit("="));
        out.push_str(v);
    }
    Ok(out)
}

enum Json {
    Null,
    Bool(bool),
    Num(i64),
    Text(Str),
    Arr(Vec<Json>),
    Obj(Vec<Entry>),
}

struct Entry {
    key: Str,
    val: Json,
}

struct Row {
    path: Str,
    text: Str,
}

// Parser state, threaded by value through every parse step.
struct Parser {
    cs: Vec<Str>,
    pos: usize,
}

// A parsed value together with the parser state after it.
struct Step {
    p: Parser,
    v: Json,
}

// A parsed string together with the parser state after it.
struct StrStep {
    p: Parser,
    s: Str,
}

// Result of a literal-word probe.
struct Probe {
    p: Parser,
    ok: bool,
}

// Result of removing a key: the remaining entries and the removed value.
struct Taken {
    kept: Vec<Entry>,
    found: Option<Json>,
}

fn lit(s: Str) -> Str {
    s
}

// Split a string into its characters, each kept as a one-character Str.
fn split(s: Str) -> Vec<Str> {
    let mut out: Vec<Str> = Vec::new();
    for c in s.chars() {
        out.push(c);
    }
    out
}

// Value of a single decimal digit, or -1 if `c` is not a digit.
fn digit(c: Str) -> i64 {
    if c == lit("0") {
        0
    } else if c == lit("1") {
        1
    } else if c == lit("2") {
        2
    } else if c == lit("3") {
        3
    } else if c == lit("4") {
        4
    } else if c == lit("5") {
        5
    } else if c == lit("6") {
        6
    } else if c == lit("7") {
        7
    } else if c == lit("8") {
        8
    } else if c == lit("9") {
        9
    } else {
        -1
    }
}

// The character list ends with an empty-string sentinel, which doubles as end of input.
fn skip_ws(p: Parser) -> Parser {
    let mut p = p;
    loop {
        let c = p.cs[p.pos].clone();
        if c == lit(" ") || c == lit("\n") || c == lit("\r") || c == lit("\t") {
            p.pos += 1;
        } else {
            break;
        }
    }
    p
}

fn expect_char(p: Parser, c: Str) -> Result<Parser, Str> {
    let mut p = skip_ws(p);
    if p.cs[p.pos] == c {
        p.pos += 1;
        Ok(p)
    } else {
        Err(lit("json: unexpected character"))
    }
}

fn parse_word(p: Parser, w: Str) -> Probe {
    let mut p = p;
    let wc = split(w);
    if p.pos + wc.len() > p.cs.len() {
        return Probe { p: p, ok: false };
    }
    for i in 0..wc.len() {
        if p.cs[p.pos + i] != wc[i] {
            return Probe { p: p, ok: false };
        }
    }
    p.pos += wc.len();
    Probe { p: p, ok: true }
}

fn parse_value(p: Parser) -> Result<Step, Str> {
    let p = skip_ws(p);
    let c = p.cs[p.pos].clone();
    if c == lit("{") {
        parse_obj(p)
    } else if c == lit("[") {
        parse_arr(p)
    } else if c == lit("\"") {
        let r = parse_string(p)?;
        Ok(Step { p: r.p, v: Json::Text(r.s) })
    } else if c == lit("-") || digit(c.clone()) >= 0 {
        parse_num(p)
    } else {
        let w = parse_word(p, lit("true"));
        if w.ok {
            return Ok(Step { p: w.p, v: Json::Bool(true) });
        }
        let w = parse_word(w.p, lit("false"));
        if w.ok {
            return Ok(Step { p: w.p, v: Json::Bool(false) });
        }
        let w = parse_word(w.p, lit("null"));
        if w.ok {
            return Ok(Step { p: w.p, v: Json::Null });
        }
        Err(lit("json: bad value"))
    }
}

fn parse_obj(p: Parser) -> Result<Step, Str> {
    let p = expect_char(p, lit("{"))?;
    let mut p = skip_ws(p);
    let mut items: Vec<Entry> = Vec::new();
    if p.cs[p.pos] == lit("}") {
        p.pos += 1;
        return Ok(Step { p: p, v: Json::Obj(items) });
    }
    loop {
        let kr = parse_string(p)?;
        let np = expect_char(kr.p, lit(":"))?;
        let vr = parse_value(np)?;
        items.push(Entry { key: kr.s, val: vr.v });
        let mut np = skip_ws(vr.p);
        if np.cs[np.pos] == lit(",") {
            np.pos += 1;
            p = np;
        } else {
            p = expect_char(np, lit("}"))?;
            break;
        }
    }
    Ok(Step { p: p, v: Json::Obj(items) })
}

fn parse_arr(p: Parser) -> Result<Step, Str> {
    let p = expect_char(p, lit("["))?;
    let mut p = skip_ws(p);
    let mut items: Vec<Json> = Vec::new();
    if p.cs[p.pos] == lit("]") {
        p.pos += 1;
        return Ok(Step { p: p, v: Json::Arr(items) });
    }
    loop {
        let vr = parse_value(p)?;
        items.push(vr.v);
        let mut np = skip_ws(vr.p);
        if np.cs[np.pos] == lit(",") {
            np.pos += 1;
            p = np;
        } else {
            p = expect_char(np, lit("]"))?;
            break;
        }
    }
    Ok(Step { p: p, v: Json::Arr(items) })
}

fn parse_string(p: Parser) -> Result<StrStep, Str> {
    let mut p = skip_ws(p);
    if p.cs[p.pos] != lit("\"") {
        return Err(lit("json: expected string"));
    }
    p.pos += 1;
    let mut out = Str::new();
    loop {
        let c = p.cs[p.pos].clone();
        if c == lit("") {
            return Err(lit("json: unterminated string"));
        }
        p.pos += 1;
        if c == lit("\"") {
            break;
        }
        if c == lit("\\") {
            let e = p.cs[p.pos].clone();
            if e == lit("") {
                return Err(lit("json: unterminated string"));
            }
            p.pos += 1;
            if e == lit("n") {
                out.push_str(lit("\n"));
            } else if e == lit("t") {
                out.push_str(lit("\t"));
            } else if e == lit("r") {
                out.push_str(lit("\r"));
            } else if e == lit("b") || e == lit("f") || e == lit("u") {
                return Err(lit("json: unsupported escape"));
            } else {
                out.push_str(e);
            }
        } else {
            out.push_str(c);
        }
    }
    Ok(StrStep { p: p, s: out })
}

fn parse_num(p: Parser) -> Result<Step, Str> {
    let mut p = p;
    let mut neg = false;
    if p.cs[p.pos] == lit("-") {
        neg = true;
        p.pos += 1;
    }
    let mut n: i64 = 0;
    let mut digits = 0;
    loop {
        let d = digit(p.cs[p.pos].clone());
        if d < 0 {
            break;
        }
        n = n * 10 + d;
        digits += 1;
        p.pos += 1;
    }
    if digits == 0 {
        return Err(lit("json: bad number"));
    }
    Ok(Step { p: p, v: Json::Num(if neg { -n } else { n }) })
}

fn parse(text: Str) -> Result<Json, Str> {
    let mut cs: Vec<Str> = split(text);
    cs.push(lit(""));
    let p = Parser { cs: cs, pos: 0 };
    let r = parse_value(p)?;
    let p = skip_ws(r.p);
    if p.pos + 1 != p.cs.len() {
        return Err(lit("json: trailing data"));
    }
    Ok(r.v)
}

// Remove `k` from `base`, returning the remaining entries and the removed value.
fn take_key(base: Vec<Entry>, k: Str) -> Taken {
    let mut kept: Vec<Entry> = Vec::new();
    let mut found: Option<Json> = None;
    for e in base {
        if e.key == k {
            found = Some(e.val);
        } else {
            kept.push(e);
        }
    }
    Taken { kept: kept, found: found }
}

// Merge `over` into `base`. Nulls in `over` remove keys; objects merge
// recursively; anything else in `over` replaces the base value.
fn merge_obj(base: Vec<Entry>, over: Vec<Entry>) -> Vec<Entry> {
    let mut base = base;
    for e in over {
        let k = e.key;
        match e.val {
            Json::Null => {
                let t = take_key(base, k);
                base = t.kept;
            }
            Json::Obj(ov) => {
                let t = take_key(base, k.clone());
                let merged = match t.found {
                    Some(Json::Obj(bv)) => merge_obj(bv, ov),
                    _ => merge_obj(Vec::new(), ov),
                };
                base = t.kept;
                base.push(Entry { key: k, val: Json::Obj(merged) });
            }
            other => {
                let t = take_key(base, k.clone());
                base = t.kept;
                base.push(Entry { key: k, val: other });
            }
        }
    }
    base
}

fn quote(s: Str) -> Str {
    let mut o = Str::new();
    o.push_str(lit("\""));
    for c in split(s) {
        if c == lit("\"") {
            o.push_str(lit("\\\""));
        } else if c == lit("\\") {
            o.push_str(lit("\\\\"));
        } else if c == lit("\n") {
            o.push_str(lit("\\n"));
        } else if c == lit("\r") {
            o.push_str(lit("\\r"));
        } else if c == lit("\t") {
            o.push_str(lit("\\t"));
        } else {
            o.push_str(c);
        }
    }
    o.push_str(lit("\""));
    o
}

fn render(v: Json) -> Str {
    match v {
        Json::Null => lit("null"),
        Json::Bool(b) => {
            if b {
                lit("true")
            } else {
                lit("false")
            }
        }
        Json::Num(n) => n.to_string(),
        Json::Text(s) => quote(s),
        Json::Arr(_) => lit("[]"),
        Json::Obj(_) => lit("{}"),
    }
}

fn join(path: Str, key: Str) -> Str {
    if path.len() == 0 {
        key
    } else {
        let mut o = path;
        o.push_str(lit("."));
        o.push_str(key);
        o
    }
}

fn flatten(path: Str, v: Json, out: Vec<Row>) -> Vec<Row> {
    let mut out = out;
    match v {
        Json::Obj(items) => {
            if items.len() == 0 {
                out.push(Row { path: path, text: lit("{}") });
            } else {
                for e in items {
                    let key = join(path.clone(), e.key);
                    out = flatten(key, e.val, out);
                }
            }
        }
        Json::Arr(items) => {
            if items.len() == 0 {
                out.push(Row { path: path, text: lit("[]") });
            } else {
                let mut i: usize = 0;
                for c in items {
                    let key = join(path.clone(), i.to_string());
                    out = flatten(key, c, out);
                    i += 1;
                }
            }
        }
        other => {
            out.push(Row { path: path, text: render(other) });
        }
    }
    out
}

fn sort_rows(v: Vec<Row>) -> Vec<Row> {
    let mut v = v;
    for i in 1..v.len() {
        let mut j = i;
        while j > 0 && v[j - 1].path > v[j].path {
            v.swap(j - 1, j);
            j -= 1;
        }
    }
    v
}

fn main(input: Dir) -> Result<Str, Str> {
    let base_text = input.read("base.json")?;
    let over_text = input.read("override.json")?;
    let base = parse(base_text)?;
    let over = parse(over_text)?;

    let base_items = match base {
        Json::Obj(items) => items,
        _ => return Err(lit("base.json is not an object")),
    };
    let over_items = match over {
        Json::Obj(items) => items,
        _ => return Err(lit("override.json is not an object")),
    };

    let merged = merge_obj(base_items, over_items);

    let rows = flatten(Str::new(), Json::Obj(merged), Vec::new());
    let rows = sort_rows(rows);

    let mut out = Str::new();
    let mut first = true;
    for r in rows {
        if !first {
            out.push_str(lit("\n"));
        }
        first = false;
        out.push_str(r.path);
        out.push_str(lit("="));
        out.push_str(r.text);
    }
    Ok(out)
}

fn main(input: Dir, out: Dir) -> Result<Str, Str> {
    let text = input.read_to_string("app.log")?;

    let mut error = String::new();
    let mut warn = String::new();
    let mut info = String::new();
    let mut n_error = 0;
    let mut n_warn = 0;
    let mut n_info = 0;
    let mut n_other = 0;

    for line in text.lines() {
        if line.trim().is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split_whitespace().collect();
        let level = if fields.len() < 3 {
            String::new()
        } else {
            fields[1].to_uppercase()
        };
        match level.as_str() {
            "ERROR" => {
                error.push_str(line);
                error.push('\n');
                n_error += 1;
            }
            "WARN" | "WARNING" => {
                warn.push_str(line);
                warn.push('\n');
                n_warn += 1;
            }
            "INFO" => {
                info.push_str(line);
                info.push('\n');
                n_info += 1;
            }
            _ => {
                n_other += 1;
            }
        }
    }

    out.write("error.log", &error)?;
    out.write("warn.log", &warn)?;
    out.write("info.log", &info)?;

    Ok(format!(
        "error {}\nwarn {}\ninfo {}\nother {}",
        n_error, n_warn, n_info, n_other
    ))
}

fn main(input: Dir, out: Dir) -> Result<Str, Str> {
    let text = input.read_to_string("app.log")?;

    let mut error = String::new();
    let mut warn = String::new();
    let mut info = String::new();
    let mut n_error = 0;
    let mut n_warn = 0;
    let mut n_info = 0;
    let mut n_other = 0;

    for line in text.lines() {
        if line.trim().is_empty() {
            continue;
        }
        let fields: Vec<Str> = line.split_whitespace().collect();
        if fields.len() < 3 {
            n_other += 1;
            continue;
        }
        let level = fields[1].to_uppercase();
        if level == "ERROR" {
            error.push_str(line);
            error.push_str("\n");
            n_error += 1;
        } else if level == "WARN" || level == "WARNING" {
            warn.push_str(line);
            warn.push_str("\n");
            n_warn += 1;
        } else if level == "INFO" {
            info.push_str(line);
            info.push_str("\n");
            n_info += 1;
        } else {
