struct Row {
    path: Str,
    bytes: i64,
    lines: i64,
}

fn count_lines(data: &[u8]) -> i64 {
    let mut n: i64 = 0;
    for b in data.iter() {
        if *b == b'\n' {
            n += 1;
        }
    }
    if data.len() > 0 && data[data.len() - 1] != b'\n' {
        n += 1;
    }
    n
}

fn walk(dir: &Dir, prefix: &str, rows: &mut Vec<Row>) -> Result<(), Str> {
    for entry in dir.entries()? {
        let name = entry.name();
        let rel = if prefix.len() == 0 {
            name.clone()
        } else {
            format!("{}/{}", prefix, name)
        };
        if entry.is_dir() {
            let sub = dir.open_dir(&name)?;
            walk(&sub, &rel, rows)?;
        } else {
            let data = dir.read_bytes(&name)?;
            rows.push(Row {
                path: rel,
                bytes: data.len() as i64,
                lines: count_lines(&data),
            });
        }
    }
    Ok(())
}

