    let mut rows: Vec<Row> = Vec::new();
    walk(&input, "", &mut rows)?;

    rows.sort_by(|a, b| a.path.cmp(&b.path));

    let mut csv = String::from("path,bytes,lines\n");
    let mut total: i64 = 0;
    for r in rows.iter() {
        csv.push_str(&format!("{},{},{}\n", r.path, r.bytes, r.lines));
        total += r.bytes;
    }

    let mut f = out.create("index.csv")?;
    f.write_all(csv.as_bytes())?;
    f.close()?;

    Ok(format!("files {} bytes {}", rows.len(), total))
}

