    let cs: Vec<char> = line.chars().collect();
    let mut fields: Vec<Str> = Vec::new();
    let mut cur = String::new();
    let mut in_quotes = false;
    let mut i = 0;
    while i < cs.len() {
        let c = cs[i];
        if in_quotes {
            if c == '"' {
                if i + 1 < cs.len() && cs[i + 1] == '"' {
                    cur.push('"');
                    i += 1;
                } else {
                    in_quotes = false;
                }
            } else {
                cur.push(c);
            }
        } else if c == '"' {
            in_quotes = true;
        } else if c == ',' {
            fields.push(cur);
            cur = String::new();
        } else {
            cur.push(c);
        }
        i += 1;
    }
    fields.push(cur);
    fields
}

fn json_str(s: &Str) -> Str {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 32 => out.push(' '),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

