fn split_csv(line: Str) -> Vec<Str> {
    let mut segs: Vec<Str> = Vec::new();
    for s in line.split("\"") {
        segs.push(s.to_string());
    }
    let n = segs.len();
    let mut fields: Vec<Str> = Vec::new();
    let mut cur = String::new();
    let mut in_quotes = false;
    let mut i = 0;
    while i < n {
        let seg = segs[i].clone();
        if in_quotes {
            cur.push_str(seg);
        } else if seg.is_empty() && i > 0 && i + 1 < n {
            // An empty unquoted run between two quotes is an escaped `""`.
            cur.push_str("\"");
        } else {
            let mut first = true;
            for piece in seg.split(",") {
                if first {
                    cur.push_str(piece.to_string());
                    first = false;
                } else {
                    fields.push(cur);
                    cur = piece.to_string();
                }
            }
        }
        in_quotes = !in_quotes;
        i += 1;
    }
    fields.push(cur);
    fields
}

fn json_str(s: Str) -> Str {
    let mut t = s.replace("\\", "\\\\");
    t = t.replace("\"", "\\\"");
    t = t.replace("\n", "\\n");
    t = t.replace("\r", "\\r");
    t = t.replace("\t", "\\t");
    "\"".to_string() + t + "\""
}

fn main(input: Dir, out: Dir) -> Result<Str, Str> {
    let text = input.read_to_string("users.csv")?;
    let mut items: Vec<Str> = Vec::new();
    let mut skipped: i64 = 0;

    for line in text.lines().skip(1) {
        if line.trim().is_empty() {
            continue;
