fn is_part(name: &str) -> bool {
    let b = name.as_bytes();
    if b.len() != 13 {
        return false;
    }
    if !name.starts_with("part-") || !name.ends_with(".txt") {
        return false;
    }
    let mut i = 5;
    while i < 9 {
        if b[i] < b'0' || b[i] > b'9' {
            return false;
        }
        i += 1;
    }
    true
}

fn parse_part(text: &str) -> Option<Vec<i64>> {
    let mut vals: Vec<i64> = Vec::new();
    for line in text.lines() {
        let t = line.trim();
        if t.is_empty() {
            continue;
        }
        match t.parse::<i64>() {
            Ok(v) => vals.push(v),
            Err(_) => return None,
        }
    }
    Some(vals)
}

