                for v in vals {
                    values.push(v);
                }
            }
            None => {
                corrupt += 1;
            }
        }
    }

    values.sort();
    values.dedup();

    let mut body = String::new();
    for v in &values {
        body.push_str(&v.to_string());
        body.push('\n');
    }
    out.write("merged.txt", &body)?;

    Ok(format!(
        "parts {} corrupt {} values {}",
        names.len(),
        corrupt,
        values.len()
    ))
}

