fn parse_int(t: Str) -> Option<i64> {
    let b = t.as_bytes();
    if b.len() == 0 {
        return None;
    }
    let mut i = 0;
    let mut neg = false;
    if b[0] == 45 {
        neg = true;
        i = 1;
    }
    if i >= b.len() {
        return None;
    }
    let mut v: i64 = 0;
    while i < b.len() {
        let c = b[i];
        if c < 48 || c > 57 {
            return None;
        }
        v = v * 10 + ((c - 48) as i64);
        i += 1;
    }
    if neg {
        Some(-v)
    } else {
        Some(v)
    }
}

fn parse_part(text: Str) -> Option<Vec<i64>> {
    let mut vals: Vec<i64> = Vec::new();
    for line in text.lines() {
