    let src_names = src.list(".")?;
    let dst_names = dst.list(".")?;

    let mut names = src_names.clone();
    names.sort();

    let mut lines: Vec<Str> = Vec::new();

    for name in names {
        let content = src.read(name.clone())?;
        if dst_names.contains(name.clone()) {
            let existing = dst.read(name.clone())?;
            if existing == content {
                lines.push("same " + name);
            } else {
                dst.write(name.clone(), content)?;
                lines.push("updated " + name);
            }
        } else {
            dst.write(name.clone(), content)?;
            lines.push("added " + name);
        }
    }

    let mut kept = 0;
    for d in dst_names {
        if !src_names.contains(d.clone()) {
            kept += 1;
        }
    }
    lines.push("kept " + kept.to_str());

    Ok(lines.join("\n"))
}

use std::collections::BTreeMap;

fn main(input: Dir, counts: Kv) -> Result<Str, Str> {
    let text = input.read_to_string("visits.txt")?;

    let mut batch: BTreeMap<String, i64> = BTreeMap::new();
    for line in text.lines() {
        let page = line.trim();
        if page.is_empty() {
            continue;
        }
        *batch.entry(page.to_string()).or_insert(0) += 1;
    }

    for (page, n) in batch.iter() {
        let old = counts.get(page).unwrap_or(0);
        counts.set(page, old + n);
    }

    let mut all: Vec<(String, i64)> = counts.entries();
    all.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));

    let mut out = String::new();
    for (page, total) in all.iter() {
        out.push_str(&format!("{} {}\n", page, total));
    }
    Ok(out)
}

