    }
}

fn fields(value: &Str) -> Vec<&str> {
    value.split_whitespace().collect()
}

fn main(input: Dir, users: Kv) -> Str {
    let text = input.read_text("commands.txt");
    let mut count = read_count(&users);
    let mut out = String::new();

    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }

        let parts: Vec<&str> = line.split_whitespace().collect();
        let n = parts.len();
        let cmd = if n > 0 { parts[0] } else { "" };

        if cmd == "put" && n == 4 {
            let id = parts[1];
            let name = parts[2];
            let email = parts[3];
            if users.get(id).is_none() {
                count += 1;
            }
            users.put(id, format!("{} {}", name, email));
            out.push_str(&format!("ok {}\n", id));
        } else if cmd == "rename" && n == 3 {
            let id = parts[1];
            let name = parts[2];
            match users.get(id) {
                None => out.push_str(&format!("missing {}\n", id)),
                Some(v) => {
                    let f = fields(&v);
                    let email = if f.len() > 1 { f[1] } else { "" };
                    users.put(id, format!("{} {}", name, email));
                    out.push_str(&format!("ok {}\n", id));
                }
            }
        } else if cmd == "get" && n == 2 {
            let id = parts[1];
            match users.get(id) {
                None => out.push_str(&format!("missing {}\n", id)),
                Some(v) => {
                    let f = fields(&v);
                    let name = if f.len() > 0 { f[0] } else { "" };
                    let email = if f.len() > 1 { f[1] } else { "" };
                    out.push_str(&format!(
                        "{{\"id\":\"{}\",\"name\":\"{}\",\"email\":\"{}\"}}\n",
                        id, name, email
                    ));
                }
            }
        } else if cmd == "del" && n == 2 {
            let id = parts[1];
            match users.get(id) {
                None => out.push_str(&format!("missing {}\n", id)),
                Some(_) => {
                    users.del(id);
                    count -= 1;
                    out.push_str(&format!("ok {}\n", id));
                }
            }
        } else if cmd == "count" && n == 1 {
            out.push_str(&format!("count {}\n", count));
        } else {
            out.push_str(&format!("bad {}\n", line));
        }
    }

    users.put(" n", count.to_string());
    out
}

