enum Val {
    S(Str),
    N(i64),
    O,
}

struct Event {
    id: Str,
    account: Str,
    cents: i64,
}

fn skip_ws(c: &Vec<char>, i: &mut usize) {
    while *i < c.len() && (c[*i] == ' ' || c[*i] == '\t' || c[*i] == '\r' || c[*i] == '\n') {
        *i += 1;
    }
}

fn hexval(ch: char) -> Option<u32> {
    match ch {
        '0'..='9' => Some(ch as u32 - '0' as u32),
        'a'..='f' => Some(ch as u32 - 'a' as u32 + 10),
        'A'..='F' => Some(ch as u32 - 'A' as u32 + 10),
        _ => None,
    }
}

fn read_hex4(c: &Vec<char>, i: &mut usize) -> Option<u32> {
    let mut code: u32 = 0;
    for _ in 0..4 {
        if *i >= c.len() {
            return None;
        }
        let h = hexval(c[*i])?;
        code = code * 16 + h;
        *i += 1;
    }
    Some(code)
}

fn parse_string(c: &Vec<char>, i: &mut usize) -> Option<Str> {
    if *i >= c.len() || c[*i] != '"' {
        return None;
    }
    *i += 1;
    let mut out = String::new();
    loop {
        if *i >= c.len() {
            return None;
        }
        let ch = c[*i];
        *i += 1;
        if ch == '"' {
            return Some(out);
        }
        if ch == '\\' {
            if *i >= c.len() {
                return None;
            }
            let e = c[*i];
            *i += 1;
            match e {
                '"' => out.push('"'),
                '\\' => out.push('\\'),
                '/' => out.push('/'),
                'b' => out.push('\u{8}'),
                'f' => out.push('\u{c}'),
                'n' => out.push('\n'),
                'r' => out.push('\r'),
                't' => out.push('\t'),
                'u' => {
                    let mut code = read_hex4(c, i)?;
                    if (0xD800..0xDC00).contains(&code) {
                        if *i + 1 < c.len() && c[*i] == '\\' && c[*i + 1] == 'u' {
                            *i += 2;
                            let lo = read_hex4(c, i)?;
                            if !(0xDC00..0xE000).contains(&lo) {
                                return None;
                            }
                            code = 0x10000 + ((code - 0xD800) << 10) + (lo - 0xDC00);
                        } else {
                            return None;
                        }
                    }
                    match char::from_u32(code) {
                        Some(u) => out.push(u),
                        None => return None,
                    }
                }
                _ => return None,
            }
        } else if (ch as u32) < 0x20 {
            return None;
        } else {
            out.push(ch);
        }
    }
}

fn expect_word(c: &Vec<char>, i: &mut usize, word: &str) -> bool {
    for w in word.chars() {
        if *i >= c.len() || c[*i] != w {
            return false;
        }
        *i += 1;
    }
    true
}

fn parse_number(c: &Vec<char>, i: &mut usize) -> Option<Val> {
    let mut neg = false;
    if *i < c.len() && c[*i] == '-' {
        neg = true;
        *i += 1;
    }
    if *i >= c.len() || !c[*i].is_ascii_digit() {
        return None;
    }
    let first = c[*i];
    let mut digits: Vec<u32> = Vec::new();
    while *i < c.len() && c[*i].is_ascii_digit() {
        digits.push(c[*i] as u32 - '0' as u32);
        *i += 1;
    }
    if digits.len() > 1 && first == '0' {
        return None;
    }

    let mut float = false;
    if *i < c.len() && c[*i] == '.' {
        float = true;
        *i += 1;
        if *i >= c.len() || !c[*i].is_ascii_digit() {
            return None;
        }
        while *i < c.len() && c[*i].is_ascii_digit() {
            *i += 1;
        }
    }
    if *i < c.len() && (c[*i] == 'e' || c[*i] == 'E') {
        float = true;
        *i += 1;
        if *i < c.len() && (c[*i] == '+' || c[*i] == '-') {
            *i += 1;
        }
        if *i >= c.len() || !c[*i].is_ascii_digit() {
            return None;
        }
        while *i < c.len() && c[*i].is_ascii_digit() {
            *i += 1;
        }
    }
    if float {
        return Some(Val::O);
    }

    let mut acc: i64 = 0;
    for d in digits {
        let d = d as i64;
        let m = match acc.checked_mul(10) {
            Some(m) => m,
            None => return Some(Val::O),
        };
        let r = if neg { m.checked_sub(d) } else { m.checked_add(d) };
        match r {
            Some(v) => acc = v,
            None => return Some(Val::O),
        }
    }
    Some(Val::N(acc))
}

fn parse_array(c: &Vec<char>, i: &mut usize) -> Option<()> {
    if *i >= c.len() || c[*i] != '[' {
        return None;
    }
    *i += 1;
    skip_ws(c, i);
    if *i < c.len() && c[*i] == ']' {
        *i += 1;
        return Some(());
    }
    loop {
        skip_ws(c, i);
        parse_value(c, i)?;
        skip_ws(c, i);
        if *i >= c.len() {
            return None;
        }
        if c[*i] == ',' {
            *i += 1;
            continue;
        }
        if c[*i] == ']' {
            *i += 1;
            return Some(());
        }
        return None;
    }
}

fn parse_object(c: &Vec<char>, i: &mut usize) -> Option<Vec<(Str, Val)>> {
    if *i >= c.len() || c[*i] != '{' {
        return None;
    }
    *i += 1;
    let mut fields: Vec<(Str, Val)> = Vec::new();
    skip_ws(c, i);
    if *i < c.len() && c[*i] == '}' {
        *i += 1;
        return Some(fields);
    }
    loop {
        skip_ws(c, i);
        let key = parse_string(c, i)?;
        skip_ws(c, i);
        if *i >= c.len() || c[*i] != ':' {
            return None;
        }
        *i += 1;
        skip_ws(c, i);
        let val = parse_value(c, i)?;
        fields.push((key, val));
        skip_ws(c, i);
        if *i >= c.len() {
            return None;
        }
        if c[*i] == ',' {
            *i += 1;
            continue;
        }
        if c[*i] == '}' {
            *i += 1;
            return Some(fields);
        }
        return None;
    }
}

fn parse_value(c: &Vec<char>, i: &mut usize) -> Option<Val> {
    if *i >= c.len() {
        return None;
    }
    match c[*i] {
        '"' => {
            let s = parse_string(c, i)?;
            Some(Val::S(s))
        }
        '{' => {
            parse_object(c, i)?;
            Some(Val::O)
        }
        '[' => {
            parse_array(c, i)?;
            Some(Val::O)
        }
        't' => {
            if expect_word(c, i, "true") { Some(Val::O) } else { None }
        }
        'f' => {
            if expect_word(c, i, "false") { Some(Val::O) } else { None }
        }
        'n' => {
            if expect_word(c, i, "null") { Some(Val::O) } else { None }
        }
        '-' | '0'..='9' => parse_number(c, i),
        _ => None,
    }
}

fn parse_event(line: &Str) -> Option<Event> {
    let c: Vec<char> = line.chars().collect();
    let mut i: usize = 0;
    skip_ws(&c, &mut i);
    let fields = parse_object(&c, &mut i)?;
    skip_ws(&c, &mut i);
    if i != c.len() {
        return None;
    }

    let mut id: Option<Str> = None;
    let mut account: Option<Str> = None;
    let mut cents: Option<i64> = None;
    for (k, v) in fields {
        if k == "id" {
            match v {
                Val::S(s) => id = Some(s),
                _ => return None,
            }
        } else if k == "account" {
            match v {
                Val::S(s) => account = Some(s),
                _ => return None,
            }
        } else if k == "cents" {
            match v {
                Val::N(n) => cents = Some(n),
                _ => return None,
            }
        }
    }
    Some(Event {
        id: id?,
        account: account?,
        cents: cents?,
    })
}

fn main(input: Dir, state: Kv) -> Result<Str, Str> {
    let text = input.read("events.jsonl")?;

    let mut applied: i64 = 0;
    let mut duplicate: i64 = 0;
    let mut rejected: i64 = 0;

    for line in text.lines() {
        if line.trim().is_empty() {
            continue;
        }
        let ev = match parse_event(&line) {
            Some(e) => e,
            None => {
                rejected += 1;
                continue;
            }
        };

        let app_key = format!("app:{}", ev.id);
        if state.get(&app_key).is_some() {
            duplicate += 1;
            continue;
        }

        let acct_key = format!("bal:{}", ev.account);
        let before: i64 = match state.get(&acct_key) {
            Some(s) => match s.parse::<i64>() {
                Ok(v) => v,
                Err(_) => 0,
            },
            None => 0,
        };
        let after = match before.checked_add(ev.cents) {
            Some(v) => v,
            None => {
                rejected += 1;
                continue;
            }
        };

        let seen_key = format!("seen:{}", ev.account);
        if state.get(&seen_key).is_none() {
            let n: i64 = match state.get("acct_n") {
                Some(s) => match s.parse::<i64>() {
                    Ok(v) => v,
                    Err(_) => 0,
                },
                None => 0,
            };
            state.set(&format!("acct_i:{}", n), &ev.account);
            state.set("acct_n", &(n + 1).to_string());
            state.set(&seen_key, "1");
        }

        state.set(&acct_key, &after.to_string());
        state.set(&app_key, "1");
        applied += 1;
    }

    let n: i64 = match state.get("acct_n") {
        Some(s) => match s.parse::<i64>() {
            Ok(v) => v,
            Err(_) => 0,
        },
        None => 0,
    };

    let mut rows: Vec<(Str, i64)> = Vec::new();
    for idx in 0..n {
        let name = match state.get(&format!("acct_i:{}", idx)) {
            Some(s) => s,
            None => continue,
        };
        let bal: i64 = match state.get(&format!("bal:{}", name)) {
            Some(s) => match s.parse::<i64>() {
                Ok(v) => v,
                Err(_) => 0,
            },
            None => 0,
        };
        rows.push((name, bal));
    }
    rows.sort();

    let mut out = format!("applied {} duplicate {} rejected {}", applied, duplicate, rejected);
    for (name, bal) in rows.iter() {
        out.push_str(&format!("\n{} {}", name, bal));
    }
    Ok(out)
}

enum Val {
    S(Str),
    N(i64),
    O,
}

struct Event {
    id: Str,
    account: Str,
    cents: i64,
}

struct P {
    c: Vec<char>,
    i: usize,
}

fn ws(p: P) -> P {
    let c = p.c;
    let mut i = p.i;
    while i < c.len() && (c[i] == ' ' || c[i] == '\t' || c[i] == '\r' || c[i] == '\n') {
        i += 1;
    }
    P { c: c, i: i }
}

fn hexval(ch: char) -> Option<u32> {
    match ch {
        '0'..='9' => Some(ch as u32 - '0' as u32),
        'a'..='f' => Some(ch as u32 - 'a' as u32 + 10),
        'A'..='F' => Some(ch as u32 - 'A' as u32 + 10),
        _ => None,
    }
}

fn string(p: P) -> Option<(Str, P)> {
    if p.i >= p.c.len() || p.c[p.i] != '"' {
        return None;
    }
    let c = p.c;
    let mut i = p.i + 1;
    let mut out = String::new();
    loop {
        if i >= c.len() {
            return None;
        }
        let ch = c[i];
        i += 1;
        if ch == '"' {
            return Some((out, P { c: c, i: i }));
        }
        if ch == '\\' {
            if i >= c.len() {
                return None;
            }
            let e = c[i];
            i += 1;
            match e {
                '"' => out.push('"'),
                '\\' => out.push('\\'),
                '/' => out.push('/'),
                'b' => out.push('\u{8}'),
                'f' => out.push('\u{c}'),
                'n' => out.push('\n'),
                'r' => out.push('\r'),
                't' => out.push('\t'),
                'u' => {
                    let mut code: u32 = 0;
                    for _ in 0..4 {
                        if i >= c.len() {
                            return None;
                        }
                        let h = hexval(c[i])?;
                        code = code * 16 + h;
                        i += 1;
                    }
                    if code >= 0xD800 && code < 0xDC00 {
                        if i + 1 < c.len() && c[i] == '\\' && c[i + 1] == 'u' {
                            i += 2;
                            let mut lo: u32 = 0;
                            for _ in 0..4 {
                                if i >= c.len() {
                                    return None;
                                }
                                let h = hexval(c[i])?;
                                lo = lo * 16 + h;
                                i += 1;
                            }
                            if !(lo >= 0xDC00 && lo < 0xE000) {
                                return None;
                            }
                            code = 0x10000 + ((code - 0xD800) << 10) + (lo - 0xDC00);
                        } else {
                            return None;
                        }
                    }
                    match char::from_u32(code) {
                        Some(u) => out.push(u),
                        None => return None,
                    }
                }
                _ => return None,
            }
        } else if (ch as u32) < 0x20 {
            return None;
        } else {
            out.push(ch);
        }
    }
}

fn word(p: P, w: Str) -> Option<P> {
    let i0 = p.i;
    let c = p.c;
    let mut i = i0;
    for ch in w.chars() {
        if i >= c.len() || c[i] != ch {
            return None;
        }
        i += 1;
    }
    Some(P { c: c, i: i })
}

fn number(p: P) -> Option<(Val, P)> {
    let c = p.c;
    let mut i = p.i;
    let mut neg = false;
    if i < c.len() && c[i] == '-' {
        neg = true;
        i += 1;
    }
    if i >= c.len() || !c[i].is_ascii_digit() {
        return None;
    }
    let first = c[i];
    let mut digits: Vec<u32> = Vec::new();
    while i < c.len() && c[i].is_ascii_digit() {
        digits.push(c[i] as u32 - '0' as u32);
        i += 1;
    }
    if digits.len() > 1 && first == '0' {
        return None;
    }

    let mut float = false;
    if i < c.len() && c[i] == '.' {
        float = true;
        i += 1;
        if i >= c.len() || !c[i].is_ascii_digit() {
            return None;
        }
        while i < c.len() && c[i].is_ascii_digit() {
            i += 1;
        }
    }
    if i < c.len() && (c[i] == 'e' || c[i] == 'E') {
        float = true;
        i += 1;
        if i < c.len() && (c[i] == '+' || c[i] == '-') {
            i += 1;
        }
        if i >= c.len() || !c[i].is_ascii_digit() {
            return None;
        }
        while i < c.len() && c[i].is_ascii_digit() {
            i += 1;
        }
    }
    if float {
        return Some((Val::O, P { c: c, i: i }));
    }

    let mut acc: i64 = 0;
    for d in digits {
        let d = d as i64;
        let m = match acc.checked_mul(10) {
            Some(m) => m,
            None => return Some((Val::O, P { c: c, i: i })),
        };
        let r = if neg { m.checked_sub(d) } else { m.checked_add(d) };
        match r {
            Some(v) => acc = v,
            None => return Some((Val::O, P { c: c, i: i })),
        }
    }
    Some((Val::N(acc), P { c: c, i: i }))
}

fn array(p: P) -> Option<P> {
    if p.i >= p.c.len() || p.c[p.i] != '[' {
        return None;
    }
    let q = ws(P { c: p.c, i: p.i + 1 });
    if q.i < q.c.len() && q.c[q.i] == ']' {
        return Some(P { c: q.c, i: q.i + 1 });
    }
    let mut cur = q;
    loop {
        let q1 = ws(cur);
        let (_, q2) = value(q1)?;
        let q3 = ws(q2);
        if q3.i >= q3.c.len() {
            return None;
        }
        if q3.c[q3.i] == ',' {
            cur = P { c: q3.c, i: q3.i + 1 };
            continue;
        }
        if q3.c[q3.i] == ']' {
            return Some(P { c: q3.c, i: q3.i + 1 });
        }
        return None;
    }
}

fn object(p: P) -> Option<(Vec<(Str, Val)>, P)> {
    if p.i >= p.c.len() || p.c[p.i] != '{' {
        return None;
    }
    let mut fields: Vec<(Str, Val)> = Vec::new();
    let q = ws(P { c: p.c, i: p.i + 1 });
    if q.i < q.c.len() && q.c[q.i] == '}' {
        return Some((fields, P { c: q.c, i: q.i + 1 }));
    }
    let mut cur = q;
    loop {
        let q1 = ws(cur);
        let (key, q2) = string(q1)?;
        let q3 = ws(q2);
        if q3.i >= q3.c.len() || q3.c[q3.i] != ':' {
            return None;
        }
        let q4 = ws(P { c: q3.c, i: q3.i + 1 });
        let (val, q5) = value(q4)?;
        fields.push((key, val));
        let q6 = ws(q5);
        if q6.i >= q6.c.len() {
            return None;
        }
        if q6.c[q6.i] == ',' {
            cur = P { c: q6.c, i: q6.i + 1 };
            continue;
        }
        if q6.c[q6.i] == '}' {
            return Some((fields, P { c: q6.c, i: q6.i + 1 }));
        }
        return None;
    }
}

fn value(p: P) -> Option<(Val, P)> {
    if p.i >= p.c.len() {
        return None;
    }
    let ch = p.c[p.i];
    if ch == '"' {
        let (s, q) = string(p)?;
        return Some((Val::S(s), q));
    }
    if ch == '{' {
        let (_, q) = object(p)?;
        return Some((Val::O, q));
    }
    if ch == '[' {
        let q = array(p)?;
        return Some((Val::O, q));
    }
    if ch == 't' {
        let q = word(p, "true")?;
        return Some((Val::O, q));
    }
    if ch == 'f' {
        let q = word(p, "false")?;
        return Some((Val::O, q));
    }
    if ch == 'n' {
        let q = word(p, "null")?;
        return Some((Val::O, q));
    }
    if ch == '-' || ch.is_ascii_digit() {
        return number(p);
    }
    None
}

fn parse_event(line: Str) -> Option<Event> {
    let chars: Vec<char> = line.chars().collect();
    let p = ws(P { c: chars, i: 0 });
    let (fields, q) = object(p)?;
    let q2 = ws(q);
    if q2.i != q2.c.len() {
        return None;
    }

    let mut id: Option<Str> = None;
    let mut account: Option<Str> = None;
    let mut cents: Option<i64> = None;
    for (k, v) in fields {
        if k == "id" {
            match v {
                Val::S(s) => id = Some(s),
                _ => return None,
            }
        } else if k == "account" {
            match v {
                Val::S(s) => account = Some(s),
                _ => return None,
            }
        } else if k == "cents" {
            match v {
                Val::N(n) => cents = Some(n),
                _ => return None,
            }
        }
    }
    Some(Event {
        id: id?,
        account: account?,
        cents: cents?,
    })
}

fn main(input: Dir, state: Kv) -> Result<Str, Str> {
    let text = input.read("events.jsonl")?;

    let mut applied: i64 = 0;
    let mut duplicate: i64 = 0;
    let mut rejected: i64 = 0;

    for line in text.lines() {
        if line.trim().is_empty() {
            continue;
        }
        let ev = match parse_event(line.to_string()) {
            Some(e) => e,
            None => {
                rejected += 1;
                continue;
            }
        };

        if state.get(format!("app:{}", ev.id)).is_some() {
            duplicate += 1;
            continue;
        }

        let before: i64 = match state.get(format!("bal:{}", ev.account)) {
            Some(s) => match s.parse::<i64>() {
                Ok(v) => v,
                Err(_) => 0,
            },
            None => 0,
        };
        let after = match before.checked_add(ev.cents) {
            Some(v) => v,
            None => {
                rejected += 1;
                continue;
            }
        };

        if state.get(format!("seen:{}", ev.account)).is_none() {
            let n: i64 = match state.get("acct_n") {
                Some(s) => match s.parse::<i64>() {
                    Ok(v) => v,
                    Err(_) => 0,
                },
                None => 0,
            };
            state.set(format!("acct_i:{}", n), ev.account.clone());
            state.set("acct_n", (n + 1).to_string());
            state.set(format!("seen:{}", ev.account), "1");
        }

        state.set(format!("bal:{}", ev.account), after.to_string());
        state.set(format!("app:{}", ev.id), "1");
        applied += 1;
    }

    let n: i64 = match state.get("acct_n") {
        Some(s) => match s.parse::<i64>() {
            Ok(v) => v,
            Err(_) => 0,
        },
        None => 0,
    };

    let mut rows: Vec<(Str, i64)> = Vec::new();
    let mut idx: i64 = 0;
    while idx < n {
        match state.get(format!("acct_i:{}", idx)) {
            Some(name) => {
                let bal: i64 = match state.get(format!("bal:{}", name)) {
                    Some(s) => match s.parse::<i64>() {
                        Ok(v) => v,
                        Err(_) => 0,
                    },
                    None => 0,
                };
                rows.push((name, bal));
            }
            None => {}
        }
        idx += 1;
    }
    rows.sort();

    let mut out = format!("applied {} duplicate {} rejected {}", applied, duplicate, rejected);
    for (name, bal) in rows {
        out = format!("{}\n{} {}", out, name, bal);
    }
    Ok(out)
}

enum Val {
    S(Str),
    N(i64),
    O,
}

struct Event {
    id: Str,
    account: Str,
    cents: i64,
}

struct P {
    c: Vec<Str>,
    i: usize,
}

fn tokens(s: Str) -> Vec<Str> {
    let mut out: Vec<Str> = Vec::new();
    for t in s.split("") {
        if t.len() > 0 {
            out.push(t.to_string());
        }
    }
    out
}

fn has(list: Vec<Str>, s: Str) -> bool {
    let mut k: usize = 0;
    while k < list.len() {
        if list[k] == s {
            return true;
        }
        k += 1;
    }
    false
}

fn hexval(s: Str) -> i64 {
    let hx = tokens("0123456789abcdefABCDEF");
    let mut k: usize = 0;
    while k < hx.len() {
        if hx[k] == s {
            if k < 16 {
                return k as i64;
            }
            return k as i64 - 6;
        }
        k += 1;
    }
    -1
}

fn is_digit(s: Str) -> bool {
    has(tokens("0123456789"), s)
}

fn is_ws(s: Str) -> bool {
    s == " " || s == "\t" || s == "\r" || s == "\n"
}

fn ws(p: P) -> P {
    let c = p.c;
    let mut i = p.i;
    while i < c.len() && is_ws(c[i].clone()) {
        i += 1;
    }
    P { c: c, i: i }
}

fn string(p: P) -> Option<(Str, P)> {
    let c = p.c;
    let mut i = p.i;
    if i >= c.len() || c[i] != "\"" {
        return None;
    }
    i += 1;
    let ctl = tokens("\u{0}\u{1}\u{2}\u{3}\u{4}\u{5}\u{6}\u{7}\u{8}\u{9}\u{a}\u{b}\u{c}\u{d}\u{e}\u{f}\u{10}\u{11}\u{12}\u{13}\u{14}\u{15}\u{16}\u{17}\u{18}\u{19}\u{1a}\u{1b}\u{1c}\u{1d}\u{1e}\u{1f}");
    let ascii = tokens(" !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~");
    let mut out: Str = String::new();
    loop {
        if i >= c.len() {
            return None;
        }
        if c[i] == "\"" {
            return Some((out, P { c: c, i: i + 1 }));
        }
        if c[i] == "\\" {
            if i + 1 >= c.len() {
                return None;
            }
            let e = c[i + 1].clone();
            i += 2;
            if e == "u" {
                if i + 4 > c.len() {
                    return None;
                }
                let mut code: i64 = 0;
                let mut raw: Str = String::new();
                let mut k: usize = 0;
                while k < 4 {
                    let h = hexval(c[i + k].clone());
                    if h < 0 {
                        return None;
                    }
                    code = code * 16 + h;
                    raw = format!("{}{}", raw, c[i + k]);
                    k += 1;
                }
                i += 4;
                if code >= 32 && code <= 126 {
                    out = format!("{}{}", out, ascii[(code - 32) as usize]);
                } else {
                    out = format!("{}\\u{}", out, raw);
                }
            } else {
                let piece = if e == "\"" {
                    "\""
                } else if e == "\\" {
                    "\\"
                } else if e == "/" {
                    "/"
                } else if e == "b" {
                    "\u{8}"
                } else if e == "f" {
                    "\u{c}"
                } else if e == "n" {
                    "\n"
                } else if e == "r" {
                    "\r"
                } else if e == "t" {
                    "\t"
                } else {
                    return None;
                };
                out = format!("{}{}", out, piece);
            }
        } else {
            if has(ctl.clone(), c[i].clone()) {
                return None;
            }
