}

fn hexval(s: Str) -> i64 {
    let hx = tokens("0123456789abcdefABCDEF");
    let mut k: usize = 0;
    while k < hx.len() {
        if hx[k] == s {
            if k < 16 {
                return k as i64;
            }
            return k as i64 - 6;
        }
        k += 1;
    }
    -1
}

fn is_digit(s: Str) -> bool {
    has(tokens("0123456789"), s)
