fn string(p: P) -> Option<(Str, P)> {
    let c = p.c;
    let mut i = p.i;
    if i >= c.len() || c[i] != "\"" {
        return None;
    }
    i += 1;
    let ascii = tokens(" !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~");
    let mut out: Str = String::new();
    loop {
        if i >= c.len() {
            return None;
        }
        if c[i] == "\"" {
            return Some((out, P { c: c, i: i + 1 }));
        }
        if c[i] == "\\" {
            if i + 1 >= c.len() {
                return None;
            }
            let e = c[i + 1].clone();
            i += 2;
            if e == "u" {
                if i + 4 > c.len() {
                    return None;
                }
                let mut code: i64 = 0;
                let mut raw: Str = String::new();
                let mut k: usize = 0;
                while k < 4 {
                    let h = hexval(c[i + k].clone());
                    if h < 0 {
                        return None;
                    }
                    code = code * 16 + h;
                    raw = format!("{}{}", raw, c[i + k]);
                    k += 1;
                }
                i += 4;
                if code >= 32 && code <= 126 {
                    out = format!("{}{}", out, ascii[(code - 32) as usize]);
                } else {
                    out = format!("{}\\u{}", out, raw);
                }
            } else {
                let piece = if e == "\"" {
                    "\""
                } else if e == "\\" {
                    "\\"
                } else if e == "/" {
                    "/"
                } else if e == "b" {
                    "\\b"
                } else if e == "f" {
                    "\\f"
                } else if e == "n" {
                    "\n"
                } else if e == "r" {
                    "\r"
                } else if e == "t" {
                    "\t"
                } else {
                    return None;
                };
                out = format!("{}{}", out, piece);
            }
        } else {
            let ch = c[i].clone();
            if ch.len() == 1 && !has(ascii.clone(), ch.clone()) {
                return None;
            }
            out = format!("{}{}", out, ch);
            i += 1;
        }
    }
}

