    let c = p.c;
    let mut i = p.i;
    if i >= c.len() || c[i] != "\"" {
        return None;
    }
    i += 1;
    let ascii = tokens(" !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~");
    let mut out: Str = String::new();
    loop {
        if i >= c.len() {
            return None;
        }
        if c[i] == "\"" {
            return Some((out, P { c: c, i: i + 1 }));
        }
        if c[i] == "\\" {
            if i + 1 >= c.len() {
                return None;
            }
            let e = c[i + 1].clone();
            i += 2;
            if e == "u" {
                if i + 4 > c.len() {
                    return None;
                }
                let mut code: i64 = 0;
                let mut raw: Str = String::new();
                let mut k: usize = 0;
                while k < 4 {
                    let h = hexval(c[i + k].clone());
                    if h < 0 {
                        return None;
                    }
                    code = code * 16 + h;
                    raw = format!("{}{}", raw, c[i + k]);
                    k += 1;
                }
                i += 4;
                if code >= 32 && code <= 126 {
                    out = format!("{}{}", out, ascii_at(ascii.clone(), code));
                } else {
                    out = format!("{}\\u{}", out, raw);
                }
            } else {
                let piece = if e == "\"" {
                    "\""
                } else if e == "\\" {
                    "\\"
                } else if e == "/" {
                    "/"
                } else if e == "b" {
                    "\\b"
                } else if e == "f" {
                    "\\f"
                } else if e == "n" {
                    "\n"
                } else if e == "r" {
                    "\r"
                } else if e == "t" {
                    "\t"
                } else {
                    return None;
                };
                out = format!("{}{}", out, piece);
            }
        } else {
            let ch = c[i].clone();
            if ch.len() == 1 && !has(ascii.clone(), ch.clone()) {
                return None;
            }
            out = format!("{}{}", out, ch);
            i += 1;
        }
    }
}

fn word(p: P, w: Str) -> Option<P> {
    let c = p.c;
    let mut i = p.i;
    let want = tokens(w);
    let mut k: usize = 0;
    while k < want.len() {
        if i >= c.len() || c[i] != want[k] {
            return None;
        }
        i += 1;
        k += 1;
    }
    Some(P { c: c, i: i })
}

fn number(p: P) -> Option<(Val, P)> {
    let c = p.c;
    let mut i = p.i;
    let mut text: Str = String::new();
    if i < c.len() && c[i] == "-" {
        text = "-".to_string();
        i += 1;
    }
    if i >= c.len() || !is_digit(c[i].clone()) {
        return None;
    }
    let lead_zero = c[i] == "0";
    let mut ndig: usize = 0;
    while i < c.len() && is_digit(c[i].clone()) {
        text = format!("{}{}", text, c[i]);
        ndig += 1;
        i += 1;
    }
    if lead_zero && ndig > 1 {
        return None;
    }

    let mut float = false;
    if i < c.len() && c[i] == "." {
        float = true;
        i += 1;
        if i >= c.len() || !is_digit(c[i].clone()) {
            return None;
        }
        while i < c.len() && is_digit(c[i].clone()) {
            i += 1;
        }
    }
    if i < c.len() && (c[i] == "e" || c[i] == "E") {
        float = true;
        i += 1;
        if i < c.len() && (c[i] == "+" || c[i] == "-") {
            i += 1;
        }
        if i >= c.len() || !is_digit(c[i].clone()) {
            return None;
        }
        while i < c.len() && is_digit(c[i].clone()) {
            i += 1;
        }
    }
    if float {
        return Some((Val::O, P { c: c, i: i }));
    }

    match text.parse::<i64>() {
        Ok(v) => Some((Val::N(v), P { c: c, i: i })),
        Err(_) => Some((Val::O, P { c: c, i: i })),
    }
}

fn array(p: P) -> Option<P> {
    let c = p.c;
    let i = p.i;
    if i >= c.len() || c[i] != "[" {
        return None;
    }
    let q = ws(P { c: c, i: i + 1 });
    if q.i < q.c.len() && q.c[q.i] == "]" {
        return Some(P { c: q.c, i: q.i + 1 });
    }
    let mut cur = q;
    loop {
        let q1 = ws(cur);
        let (_, q2) = value(q1)?;
        let q3 = ws(q2);
        if q3.i >= q3.c.len() {
            return None;
        }
        if q3.c[q3.i] == "," {
            cur = P { c: q3.c, i: q3.i + 1 };
            continue;
        }
        if q3.c[q3.i] == "]" {
            return Some(P { c: q3.c, i: q3.i + 1 });
        }
        return None;
    }
}

fn object(p: P) -> Option<(Vec<(Str, Val)>, P)> {
    let c = p.c;
    let i = p.i;
    if i >= c.len() || c[i] != "{" {
        return None;
    }
    let mut fields: Vec<(Str, Val)> = Vec::new();
    let q = ws(P { c: c, i: i + 1 });
    if q.i < q.c.len() && q.c[q.i] == "}" {
        return Some((fields, P { c: q.c, i: q.i + 1 }));
    }
    let mut cur = q;
    loop {
        let q1 = ws(cur);
        let (key, q2) = string(q1)?;
        let q3 = ws(q2);
        if q3.i >= q3.c.len() || q3.c[q3.i] != ":" {
            return None;
        }
        let q4 = ws(P { c: q3.c, i: q3.i + 1 });
        let (val, q5) = value(q4)?;
        fields.push((key, val));
        let q6 = ws(q5);
        if q6.i >= q6.c.len() {
            return None;
        }
        if q6.c[q6.i] == "," {
            cur = P { c: q6.c, i: q6.i + 1 };
            continue;
        }
        if q6.c[q6.i] == "}" {
            return Some((fields, P { c: q6.c, i: q6.i + 1 }));
        }
        return None;
    }
}

fn value(p: P) -> Option<(Val, P)> {
    if p.i >= p.c.len() {
        return None;
    }
    let ch = p.c[p.i].clone();
    if ch == "\"" {
        let (s, q) = string(p)?;
        return Some((Val::S(s), q));
    }
    if ch == "{" {
        let (_, q) = object(p)?;
        return Some((Val::O, q));
    }
    if ch == "[" {
        let q = array(p)?;
        return Some((Val::O, q));
    }
    if ch == "t" {
        let q = word(p, "true")?;
        return Some((Val::O, q));
    }
    if ch == "f" {
        let q = word(p, "false")?;
        return Some((Val::O, q));
    }
    if ch == "n" {
        let q = word(p, "null")?;
        return Some((Val::O, q));
    }
    if ch == "-" || is_digit(ch.clone()) {
        return number(p);
    }
    None
}

fn parse_event(line: Str) -> Option<Event> {
    let chars = tokens(line);
    let p = ws(P { c: chars, i: 0 });
    let (fields, q) = object(p)?;
    let q2 = ws(q);
    if q2.i != q2.c.len() {
        return None;
    }

    let mut id: Option<Str> = None;
    let mut account: Option<Str> = None;
    let mut cents: Option<i64> = None;
    for (k, v) in fields {
        if k == "id" {
            match v {
                Val::S(s) => id = Some(s),
                _ => return None,
            }
        } else if k == "account" {
            match v {
                Val::S(s) => account = Some(s),
                _ => return None,
            }
        } else if k == "cents" {
            match v {
                Val::N(n) => cents = Some(n),
                _ => return None,
            }
        }
    }
    Some(Event {
        id: id?,
        account: account?,
        cents: cents?,
    })
}

fn main(input: Dir, state: Kv) -> Result<Str, Str> {
    let text = input.read("events.jsonl")?;

    let mut applied: i64 = 0;
    let mut duplicate: i64 = 0;
    let mut rejected: i64 = 0;

    for line in text.lines() {
        if line.trim().is_empty() {
            continue;
        }
        let ev = match parse_event(line.to_string()) {
            Some(e) => e,
            None => {
                rejected += 1;
                continue;
            }
        };

        if state.get(format!("app:{}", ev.id)).is_some() {
            duplicate += 1;
            continue;
        }

        let before: i64 = match state.get(format!("bal:{}", ev.account)) {
            Some(s) => match s.parse::<i64>() {
                Ok(v) => v,
                Err(_) => 0,
            },
            None => 0,
        };
        let after = match before.checked_add(ev.cents) {
            Some(v) => v,
            None => {
                rejected += 1;
                continue;
            }
        };

        if state.get(format!("seen:{}", ev.account)).is_none() {
            let n: i64 = match state.get("acct_n") {
                Some(s) => match s.parse::<i64>() {
                    Ok(v) => v,
                    Err(_) => 0,
                },
                None => 0,
            };
            state.set(format!("acct_i:{}", n), ev.account.clone());
            state.set("acct_n", (n + 1).to_string());
            state.set(format!("seen:{}", ev.account), "1");
        }

        state.set(format!("bal:{}", ev.account), after.to_string());
        state.set(format!("app:{}", ev.id), "1");
        applied += 1;
    }

    let n: i64 = match state.get("acct_n") {
        Some(s) => match s.parse::<i64>() {
            Ok(v) => v,
            Err(_) => 0,
        },
        None => 0,
    };

    let mut rows: Vec<(Str, i64)> = Vec::new();
    let mut idx: i64 = 0;
    while idx < n {
        match state.get(format!("acct_i:{}", idx)) {
            Some(name) => {
                let bal: i64 = match state.get(format!("bal:{}", name)) {
                    Some(s) => match s.parse::<i64>() {
                        Ok(v) => v,
                        Err(_) => 0,
                    },
                    None => 0,
                };
                rows.push((name, bal));
            }
            None => {}
        }
        idx += 1;
    }
    rows.sort();

    let mut out = format!("applied {} duplicate {} rejected {}", applied, duplicate, rejected);
    for (name, bal) in rows {
        out = format!("{}\n{} {}", out, name, bal);
    }
    Ok(out)
}

fn main(input: Dir, limits: Kv) -> Result<Str, Str> {
    let text = input.read_to_string("requests.txt")?;
    let mut out = String::new();

    for line in text.lines() {
        let fields: Vec<&str> = line.split_whitespace().collect();
        if fields.len() != 2 {
            continue;
        }
        let t: i64 = match fields[0].parse() {
            Ok(v) => v,
            Err(_) => continue,
        };
        let client = fields[1];
        let window = t / 60;
        // Client names contain no whitespace, so "window client" is an unambiguous key.
        let key = format!("{} {}", window, client);

        let count: i64 = match limits.get(&key)? {
            Some(s) => s.parse().unwrap_or(0),
            None => 0,
        };

        if count < 3 {
            limits.set(&key, &(count + 1).to_string())?;
            out.push_str(&format!("{} {} allow\n", fields[0], client));
        } else {
            out.push_str(&format!("{} {} deny\n", fields[0], client));
        }
    }

    Ok(out)
}

