struct Row {
    name: Str,
    points: i64,
    played: i64,
}

fn main(input: Dir, board: Kv) -> Result<Str, Str> {
    let text = input.read("games.txt")?;

    // Load the existing player index and totals from the persistent store.
    let index = board.get("names").unwrap_or("");
    let mut rows: Vec<Row> = Vec::new();
    for name in index.split(' ') {
        if name == "" {
            continue;
        }
        let stored = board.get(name).unwrap_or("0 0");
        let mut parts = stored.split(' ');
        let points = parts.next().unwrap_or("0").parse_i64().unwrap_or(0);
        let played = parts.next().unwrap_or("0").parse_i64().unwrap_or(0);
        rows.push(Row { name: name.to_string(), points, played });
    }

    // Apply this run's games.
    for line in text.lines() {
        let tokens: Vec<&str> = line.split_whitespace().collect();
        let (winner, loser, is_draw) = if tokens.len() == 2 {
            (tokens[0], tokens[1], false)
        } else if tokens.len() == 3 && tokens[2] == "draw" {
            (tokens[0], tokens[1], true)
        } else {
            continue;
        };

        let wi = find_or_add(&mut rows, winner);
        let li = find_or_add(&mut rows, loser);

        if is_draw {
            rows[wi].points += 1;
            rows[li].points += 1;
        } else {
            rows[wi].points += 3;
        }
        rows[wi].played += 1;
        rows[li].played += 1;
    }

    // Persist totals and the player index.
    let mut names_out = String::new();
    for row in rows.iter() {
        board.set(&row.name, &format!("{} {}", row.points, row.played));
        if names_out.len() > 0 {
            names_out.push_str(" ");
        }
        names_out.push_str(&row.name);
    }
    board.set("names", &names_out);

    // Rank: points desc, played asc, name asc.
    rows.sort_by(|a, b| {
        b.points
            .cmp(&a.points)
            .then(a.played.cmp(&b.played))
            .then(a.name.cmp(&b.name))
    });

    let mut out = String::new();
    let top = if rows.len() < 3 { rows.len() } else { 3 };
    for i in 0..top {
        let r = &rows[i];
        if i > 0 {
            out.push_str("\n");
        }
        out.push_str(&format!("{}. {} {} {}", i + 1, r.name, r.points, r.played));
    }

    Ok(out)
}

fn find_or_add(rows: &mut Vec<Row>, name: &str) -> usize {
    for i in 0..rows.len() {
        if rows[i].name == name {
            return i;
        }
    }
    rows.push(Row { name: name.to_string(), points: 0, played: 0 });
    rows.len() - 1
}

