fn main(input: Dir, shop: Db) -> Result<Str, Str> {
    shop.exec(
        "CREATE TABLE IF NOT EXISTS orders (
            order_id INTEGER PRIMARY KEY,
            customer TEXT NOT NULL,
            product TEXT NOT NULL,
            qty INTEGER NOT NULL,
            unit_cents INTEGER NOT NULL
        )",
        [],
    )?;

    let text = input.read("orders.csv")?;

    let mut imported: i64 = 0;
    let mut skipped: i64 = 0;
    let mut rejected: i64 = 0;
    let mut first = true;

    for raw in text.lines() {
        if first {
            first = false;
            continue;
        }
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }

        let fields: Vec<Str> = line.split(",").map(|f| f.trim()).collect();
        if fields.len() != 5 {
            rejected += 1;
            continue;
        }

        let order_id: i64 = match fields[0].parse::<i64>() {
            Ok(v) => v,
            Err(_) => {
                rejected += 1;
                continue;
            }
        };
        let qty: i64 = match fields[3].parse::<i64>() {
            Ok(v) => v,
            Err(_) => {
                rejected += 1;
                continue;
            }
        };
        let unit_cents: i64 = match fields[4].parse::<i64>() {
            Ok(v) => v,
            Err(_) => {
                rejected += 1;
                continue;
            }
        };

        let existing = shop.query(
            "SELECT 1 FROM orders WHERE order_id = ?",
            [order_id],
        )?;
        if existing.len() > 0 {
            skipped += 1;
            continue;
        }

        shop.exec(
            "INSERT INTO orders (order_id, customer, product, qty, unit_cents)
             VALUES (?, ?, ?, ?, ?)",
            [order_id, fields[1].clone(), fields[2].clone(), qty, unit_cents],
        )?;
        imported += 1;
    }

    let top = shop.query(
        "SELECT product, SUM(qty * unit_cents) AS rev, COUNT(*) AS n
         FROM orders
         GROUP BY product
         ORDER BY rev DESC, product COLLATE BINARY ASC
         LIMIT 3",
        [],
    )?;

    let mut out = format!(
        "imported {} skipped {} rejected {}\n",
        imported, skipped, rejected
    );
    for row in top {
        let product = row.get_str(0)?;
        let revenue = row.get_int(1)?;
        let orders = row.get_int(2)?;
        out.push_str(&format!("{} {} {}\n", product, revenue, orders));
    }

    Ok(out)
}

