const REPORT_SQL: &str = "
WITH paid AS (
    SELECT c.id AS cid, c.name AS name, c.country AS country,
           o.total_cents AS amt
    FROM orders o
    JOIN customers c ON c.id = o.customer_id
    WHERE o.status = 'paid'
      AND o.placed >= '2026-01-01' AND o.placed < '2027-01-01'
),
per_cust AS (
    SELECT cid, name, country, SUM(amt) AS rev, COUNT(*) AS n
    FROM paid
    GROUP BY cid, name, country
),
per_country AS (
    SELECT country,
           COUNT(*) AS customers,
           SUM(n) AS orders,
           SUM(rev) AS revenue
    FROM per_cust
    GROUP BY country
),
tops AS (
    SELECT country, name
    FROM (
        SELECT country, name,
               ROW_NUMBER() OVER (
                   PARTITION BY country
                   ORDER BY rev DESC, cid ASC
               ) AS rn
        FROM per_cust
    )
    WHERE rn = 1
)
SELECT pc.country, pc.customers, pc.orders, pc.revenue, t.name
FROM per_country pc
JOIN tops t ON t.country = pc.country
ORDER BY pc.revenue DESC, pc.country ASC
";

const TOTAL_SQL: &str = "
SELECT COUNT(*), COALESCE(SUM(o.total_cents), 0)
FROM orders o
JOIN customers c ON c.id = o.customer_id
WHERE o.status = 'paid'
  AND o.placed >= '2026-01-01' AND o.placed < '2027-01-01'
";

fn main(shop: Db) -> Result<Str, Str> {
    let rows = shop.query(REPORT_SQL, [])?;

    let mut out = Str::new();
    for row in rows.rows() {
        let country = row.text(0)?;
        let customers = row.int(1)?;
        let orders = row.int(2)?;
        let revenue = row.int(3)?;
        let top = row.text(4)?;
        out.push_str(&format!(
            "{} customers={} orders={} revenue={} top={}\n",
            country, customers, orders, revenue, top
        ));
    }

    let totals = shop.query(TOTAL_SQL, [])?;
    let trow = totals.rows().first()?;
    let total_orders = trow.int(0)?;
    let total_revenue = trow.int(1)?;
    out.push_str(&format!(
        "total orders={} revenue={}\n",
        total_orders, total_revenue
    ));

    Ok(out)
}

