use std::collections::{BTreeMap, BTreeSet};

struct Batch {
    name: String,
    moves: Vec<(String, i64)>,
    malformed: bool,
}

fn sql_quote(s: &str) -> String {
    s.replace('\'', "''")
}

fn parse_move(line: &str) -> Option<(String, i64)> {
    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() != 2 {
        return None;
    }
    let sku = parts[0];
    let amount = parts[1];
    let (sign, digits) = if let Some(rest) = amount.strip_prefix('+') {
        (1i64, rest)
    } else if let Some(rest) = amount.strip_prefix('-') {
        (-1i64, rest)
    } else {
        return None;
    };
    if digits.is_empty() || !digits.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let n: i64 = match digits.parse() {
        Ok(v) => v,
        Err(_) => return None,
    };
    if n <= 0 {
        return None;
    }
    Some((sku.to_string(), sign * n))
}

fn parse(text: &str) -> Vec<Batch> {
    let mut batches: Vec<Batch> = Vec::new();
    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }
        if let Some(rest) = line.strip_prefix("batch ") {
            batches.push(Batch {
                name: rest.trim().to_string(),
                moves: Vec::new(),
                malformed: false,
            });
        } else if let Some(b) = batches.last_mut() {
            match parse_move(line) {
                Some(m) => b.moves.push(m),
                None => b.malformed = true,
            }
        }
    }
    batches
}

fn main(input: Dir, stock: Db) -> Result<String, String> {
    stock.execute("CREATE TABLE IF NOT EXISTS applied (name TEXT PRIMARY KEY)")?;
    stock.execute(
        "CREATE TABLE IF NOT EXISTS stock (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)",
    )?;

    let mut qty: BTreeMap<String, i64> = BTreeMap::new();
    for row in stock.query("SELECT sku, qty FROM stock")? {
        qty.insert(row.get_str(0)?, row.get_int(1)?);
    }

    let mut applied: BTreeSet<String> = BTreeSet::new();
    for row in stock.query("SELECT name FROM applied")? {
        applied.insert(row.get_str(0)?);
    }

    let text = input.read_to_string("moves.txt")?;
    let mut out = String::new();

    for batch in parse(&text) {
        if applied.contains(&batch.name) {
            out.push_str(&format!("{} skipped\n", batch.name));
            continue;
        }

        // Validate every move in order against a running balance.
        let mut work: BTreeMap<String, i64> = BTreeMap::new();
        let mut ok = !batch.malformed;
        if ok {
            for (sku, d) in &batch.moves {
                let cur = match work.get(sku) {
                    Some(v) => *v,
                    None => qty.get(sku).copied().unwrap_or(0),
                };
                let next = cur + d;
                if next < 0 {
                    ok = false;
                    break;
                }
                work.insert(sku.clone(), next);
            }
        }

        if !ok {
            out.push_str(&format!("{} rejected\n", batch.name));
            continue;
        }

        // Commit the whole batch in one transaction.
        stock.execute("BEGIN")?;
        for (sku, v) in &work {
            stock.execute(&format!(
                "INSERT INTO stock (sku, qty) VALUES ('{}', {}) \
                 ON CONFLICT(sku) DO UPDATE SET qty = excluded.qty",
                sql_quote(sku),
                v
            ))?;
            qty.insert(sku.clone(), *v);
        }
        stock.execute(&format!(
            "INSERT INTO applied (name) VALUES ('{}')",
            sql_quote(&batch.name)
        ))?;
        stock.execute("COMMIT")?;

        applied.insert(batch.name.clone());
        out.push_str(&format!("{} applied\n", batch.name));
    }

    for (sku, v) in &qty {
        if *v != 0 {
            out.push_str(&format!("{} {}\n", sku, v));
        }
    }

    Ok(out.trim_end().to_string())
}

