    if !positive && !negative {
        return None;
    }
    let body: Str = if positive {
        amount.replace("+", "")
    } else {
        amount.replace("-", "")
    };
    // Exactly one sign character was removed.
    if body.len() + 1 != amount.len() {
        return None;
    }
    // Reject a second sign inside the number.
    if body.starts_with("+") || body.starts_with("-") {
        return None;
