        Err(_) => return None,
    };
    if n <= 0 {
        return None;
    }
    if positive {
        Some((sku, n))
    } else {
        Some((sku, -n))
    }
}

fn parse(text: Str) -> Vec<Batch> {
    let mut batches: Vec<Batch> = Vec::new();
    for raw in text.lines() {
        let line = raw.trim().to_string();
        if line.is_empty() {
            continue;
        }
        if line.starts_with("batch ") {
            let mut it = line.split_whitespace();
            it.next();
            let name: Str = match it.next() {
                Some(n) => n.to_string(),
                None => "".to_string(),
            };
            batches.push(Batch {
                name,
                moves: Vec::new(),
                malformed: false,
            });
        } else {
            let n = batches.len();
            if n > 0 {
                match parse_move(line) {
                    Some(m) => batches[n - 1].moves.push(m),
                    None => batches[n - 1].malformed = true,
                }
            }
        }
    }
    batches
}

fn main(input: Dir, stock: Db) -> Result<Str, Str> {
    stock.execute("CREATE TABLE IF NOT EXISTS applied (name TEXT PRIMARY KEY)")?;
    stock.execute("CREATE TABLE IF NOT EXISTS stock (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)")?;

    let mut qty: BTreeMap<Str, i64> = BTreeMap::new();
    for row in stock.query("SELECT sku, qty FROM stock")? {
        qty.insert(row.get_str(0)?, row.get_int(1)?);
    }

    let mut applied: BTreeSet<Str> = BTreeSet::new();
    for row in stock.query("SELECT name FROM applied")? {
        applied.insert(row.get_str(0)?);
    }

    let text = input.read_to_string("moves.txt")?;
    let mut out: Str = "".to_string();

    for batch in parse(text) {
        let name = batch.name;
        let moves = batch.moves;
        let malformed = batch.malformed;

        if applied.contains(name.clone()) {
            out.push_str(format!("{} skipped\n", name));
            continue;
        }

        // Validate every move in order against a running balance.
        let mut work: BTreeMap<Str, i64> = BTreeMap::new();
        let mut ok = !malformed;
        if ok {
            for (sku, d) in moves {
                let base = qty.get(sku.clone()).copied().unwrap_or(0);
                let cur = work.get(sku.clone()).copied().unwrap_or(base);
                let next = cur + d;
                if next < 0 {
                    ok = false;
                    break;
                }
                work.insert(sku, next);
            }
        }

        if !ok {
            out.push_str(format!("{} rejected\n", name));
            continue;
        }

        // Commit the whole batch in one transaction.
        stock.execute("BEGIN")?;
        for (sku, v) in work {
            stock.execute(format!(
                "INSERT INTO stock (sku, qty) VALUES ('{}', {}) ON CONFLICT(sku) DO UPDATE SET qty = excluded.qty",
                sql_quote(sku.clone()),
                v
            ))?;
            qty.insert(sku, v);
        }
        stock.execute(format!(
            "INSERT INTO applied (name) VALUES ('{}')",
            sql_quote(name.clone())
        ))?;
        stock.execute("COMMIT")?;

        applied.insert(name.clone());
        out.push_str(format!("{} applied\n", name));
    }

    for (sku, v) in qty {
        if v != 0 {
            out.push_str(format!("{} {}\n", sku, v));
        }
    }

    Ok(out.trim_end().to_string())
}

struct Batch {
    name: Str,
    moves: Vec<(Str, i64)>,
    malformed: bool,
}

fn sql_quote(s: Str) -> Str {
    s.replace("'", "''")
}

fn parse_move(line: Str) -> Option<(Str, i64)> {
    let mut it = line.split_whitespace();
    let sku = it.next()?.to_string();
    let amount = it.next()?.to_string();
    if it.next().is_some() {
        return None;
    }
    let positive = amount.starts_with("+");
    let negative = amount.starts_with("-");
    if !positive && !negative {
        return None;
    }
    let body: Str = if positive {
        amount.replace("+", "")
    } else {
        amount.replace("-", "")
    };
    // Exactly one sign character was removed.
    if body.len() + 1 != amount.len() {
        return None;
    }
    // Reject a second sign inside the number.
    if body.starts_with("+") || body.starts_with("-") {
        return None;
    }
    let n: i64 = match body.parse() {
        Ok(v) => v,
        Err(_) => return None,
    };
    if n <= 0 {
        return None;
    }
    if positive {
        Some((sku, n))
    } else {
        Some((sku, -n))
    }
}

fn parse(text: Str) -> Vec<Batch> {
    let mut batches: Vec<Batch> = Vec::new();
    for raw in text.lines() {
        let line = raw.trim().to_string();
        if line.is_empty() {
            continue;
        }
        if line.starts_with("batch ") {
            let mut it = line.split_whitespace();
            it.next();
            let name: Str = match it.next() {
                Some(n) => n.to_string(),
                None => "".to_string(),
            };
            batches.push(Batch {
                name,
                moves: Vec::new(),
                malformed: false,
            });
        } else {
            let n = batches.len();
            if n > 0 {
                match parse_move(line) {
                    Some(m) => batches[n - 1].moves.push(m),
                    None => batches[n - 1].malformed = true,
                }
            }
        }
    }
    batches
}

