fn main(input: Dir, crm: Db) -> Result<Str, Str> {
    crm.exec(
        "CREATE TABLE IF NOT EXISTS contacts (email TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL)",
        [],
    )?;

    let text = input.read("contacts.csv")?;

    let mut inserted = 0;
    let mut updated = 0;
    let mut unchanged = 0;
    let mut rejected = 0;
    let mut is_header = true;

    for line in text.lines() {
        if is_header {
            is_header = false;
            continue;
        }
        if line.trim().is_empty() {
            continue;
        }

        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() != 3 {
            rejected += 1;
            continue;
        }

        let email = fields[0].trim().to_lowercase();
        if !email.contains('@') {
            rejected += 1;
            continue;
        }

        let name = fields[1].to_string();
        let phone = fields[2].trim().to_string();

        let rows = crm.query(
            "SELECT name, phone FROM contacts WHERE email = ?",
            [email.clone()],
        )?;

        if rows.is_empty() {
            crm.exec(
                "INSERT INTO contacts (email, name, phone) VALUES (?, ?, ?)",
                [email, name, phone],
            )?;
            inserted += 1;
        } else {
            let old_name = rows[0][0].to_string();
            let old_phone = rows[0][1].to_string();
            if old_name != name || old_phone != phone {
                crm.exec(
                    "UPDATE contacts SET name = ?, phone = ? WHERE email = ?",
                    [name, phone, email],
                )?;
                updated += 1;
            } else {
                unchanged += 1;
            }
        }
    }

    let total_rows = crm.query("SELECT COUNT(*) FROM contacts", [])?;
    let total = total_rows[0][0].to_string();

    let mut out = format!(
        "inserted {} updated {} unchanged {} rejected {}\ncontacts {}",
        inserted, updated, unchanged, rejected, total
    );

    let missing = crm.query(
        "SELECT email FROM contacts WHERE TRIM(phone) = '' ORDER BY email",
        [],
    )?;
    for row in missing {
        out.push_str("\nmissing phone: ");
        out.push_str(&row[0].to_string());
    }

    Ok(out)
}

