const MAX_NAME: usize = 32;
const INDEX_KEY: &str = "#names";

fn valid_name(name: &str) -> bool {
    let n = name.len();
    if n < 1 || n > MAX_NAME {
        return false;
    }
    for c in name.chars() {
        let ok = (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-';
        if !ok {
            return false;
        }
    }
    true
}

fn read_count(counts: &Kv, name: &str) -> Option<i64> {
    match counts.get(name) {
        Some(s) => Some(s.parse::<i64>().unwrap()),
        None => None,
    }
}

fn names(counts: &Kv) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    if let Some(s) = counts.get(INDEX_KEY) {
        if s.len() > 0 {
            for part in s.split(',') {
                out.push(part.to_string());
            }
        }
    }
    out
}

fn reply(res: &Outgoing, status: i64, body: &str) -> String {
    res.status(status);
    res.header("content-type", "application/json");
    res.write(body);
    "ok".to_string()
}

fn bad_name(res: &Outgoing) -> String {
    reply(res, 400, "{\"error\": \"bad name\"}")
}

fn not_found(res: &Outgoing) -> String {
    reply(res, 404, "{\"error\": \"not found\"}")
}

fn main(req: Incoming, res: Outgoing, counts: Kv) -> String {
    let method = req.method();
    let path = req.path();

    if method == "POST" && path.starts_with("/hit/") {
        let name = path[5..].to_string();
        if !valid_name(&name) {
            return bad_name(&res);
        }
        let old = read_count(&counts, &name);
        let new_count = match old {
            Some(v) => v + 1,
            None => 1,
        };
        counts.put(&name, &new_count.to_string());
        if old.is_none() {
            let mut all = names(&counts);
            all.push(name.clone());
            counts.put(INDEX_KEY, &all.join(","));
        }
        let body = format!("{{\"name\": \"{}\", \"count\": {}}}", name, new_count);
        return reply(&res, 200, &body);
    }

    if method == "GET" && path.starts_with("/count/") {
        let name = path[7..].to_string();
        if !valid_name(&name) {
            return bad_name(&res);
        }
        let n = match read_count(&counts, &name) {
            Some(v) => v,
            None => 0,
        };
        let body = format!("{{\"name\": \"{}\", \"count\": {}}}", name, n);
        return reply(&res, 200, &body);
    }

    if method == "GET" && path == "/top" {
        let mut entries: Vec<(i64, String)> = Vec::new();
        for name in names(&counts) {
            let n = match read_count(&counts, &name) {
                Some(v) => v,
                None => 0,
            };
            entries.push((n, name));
        }
        entries.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.cmp(&b.1)));

        let mut body = "[".to_string();
        let mut i = 0;
        for e in entries.iter().take(3) {
            if i > 0 {
                body.push_str(", ");
            }
            body.push_str(&format!("{{\"name\": \"{}\", \"count\": {}}}", e.1, e.0));
            i += 1;
        }
        body.push(']');
        return reply(&res, 200, &body);
    }

    not_found(&res)
}

