fn json_str(s: &Str) -> Str {
    let e = s
        .replace("\\", "\\\\")
        .replace("\"", "\\\"")
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("\t", "\\t");
    format!("\"{}\"", e)
}

fn err(msg: &str) -> Str {
    format!("{{\"error\": \"{}\"}}", msg)
}

fn todo_json(id: i64, title: &Str, done: bool) -> Str {
    format!("{{\"id\": {}, \"title\": {}, \"done\": {}}}", id, json_str(title), done)
}

fn counter(store: &Kv) -> i64 {
    store
        .get("next")
        .and_then(|s| s.parse::<i64>().ok())
        .unwrap_or(1)
}

fn load(store: &Kv, id: i64) -> Option<(Str, bool)> {
    let title = store.get(&format!("t:{}", id))?;
    let done = store
        .get(&format!("d:{}", id))
        .map(|s| s == "true")
        .unwrap_or(false);
    Some((title, done))
}

fn parse_id(s: &Str) -> Option<i64> {
    if s.is_empty() || s.starts_with('0') || !s.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    s.parse::<i64>().ok()
}

fn read_title(body: &Str) -> Option<Str> {
    let v = Json::parse(body).ok()?;
    if !v.is_object() {
        return None;
    }
    let t = v.get("title")?.as_str()?.trim().to_string();
    if t.is_empty() {
        None
    } else {
        Some(t)
    }
}

fn read_patch(body: &Str) -> Option<(Option<Str>, Option<bool>)> {
    let v = Json::parse(body).ok()?;
    if !v.is_object() {
        return None;
    }
    let title = match v.get("title") {
        None => None,
        Some(t) => {
            let s = t.as_str()?.trim().to_string();
            if s.is_empty() {
                return None;
            }
            Some(s)
        }
    };
    let done = match v.get("done") {
        None => None,
        Some(d) => Some(d.as_bool()?),
    };
    Some((title, done))
}

fn create(body: &Str, store: &Kv) -> (i64, Str) {
    match read_title(body) {
        None => (400, err("title required")),
        Some(t) => {
            let id = counter(store);
            store.set(&format!("t:{}", id), &t);
            store.set(&format!("d:{}", id), "false");
            store.set("next", &(id + 1).to_string());
            (201, todo_json(id, &t, false))
        }
    }
}

fn list(filter: Option<bool>, store: &Kv) -> (i64, Str) {
    let next = counter(store);
    let mut items: Vec<Str> = Vec::new();
    for id in 1..next {
        if let Some((title, done)) = load(store, id) {
            let keep = match filter {
                Some(f) => f == done,
                None => true,
            };
            if keep {
                items.push(todo_json(id, &title, done));
            }
        }
    }
    (200, format!("[{}]", items.join(", ")))
}

fn get_one(id: i64, store: &Kv) -> (i64, Str) {
    match load(store, id) {
        None => (404, err("not found")),
        Some((title, done)) => (200, todo_json(id, &title, done)),
    }
}

fn patch(id: i64, body: &Str, store: &Kv) -> (i64, Str) {
    match load(store, id) {
        None => (404, err("not found")),
        Some(_) => match read_patch(body) {
            None => (400, err("bad update")),
            Some((title, done)) => {
                if let Some(t) = &title {
                    store.set(&format!("t:{}", id), t);
                }
                if let Some(d) = done {
                    store.set(&format!("d:{}", id), if d { "true" } else { "false" });
                }
                let (t, d) = load(store, id).unwrap();
                (200, todo_json(id, &t, d))
            }
        },
    }
}

fn delete(id: i64, store: &Kv) -> (i64, Str) {
    match load(store, id) {
        None => (404, err("not found")),
        Some(_) => {
            store.delete(&format!("t:{}", id));
            store.delete(&format!("d:{}", id));
            (204, String::new())
        }
    }
}

fn route(req: &Incoming, store: &Kv) -> (i64, Str) {
    let method = req.method();
    let path = req.path();
    let segs: Vec<Str> = path.split("/").map(|s| s.to_string()).collect();

    if path == "/todos" {
        if method == "POST" {
            return create(&req.body(), store);
        }
        if method == "GET" {
            let q = req.query();
            let filter = if q == "done=true" {
                Some(true)
            } else if q == "done=false" {
                Some(false)
            } else {
                None
            };
            return list(filter, store);
        }
        return (404, err("not found"));
    }

    if segs.len() == 3 && segs[0] == "" && segs[1] == "todos" {
        if let Some(id) = parse_id(&segs[2]) {
            if method == "GET" {
                return get_one(id, store);
            }
            if method == "PATCH" {
                return patch(id, &req.body(), store);
            }
            if method == "DELETE" {
                return delete(id, store);
            }
        }
    }

    (404, err("not found"))
}

fn main(req: Incoming, res: Outgoing, store: Kv) -> Str {
    let (status, body) = route(&req, &store);
    if status == 204 {
        res.status(204);
        res.send("");
    } else {
        res.status(status);
        res.header("content-type", "application/json");
        res.send(&body);
    }
    "ok".to_string()
}

