fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, Str> {
    db.exec("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL)")?;
    db.exec("CREATE TABLE IF NOT EXISTS note_tags (note_id INTEGER NOT NULL, tag TEXT NOT NULL, pos INTEGER NOT NULL, PRIMARY KEY (note_id, tag))")?;
    handle(&req, &res, &db)
}

fn handle(req: &Incoming, res: &Outgoing, db: &Db) -> Result<Str, Str> {
    let method = req.method();
    let segs: Vec<Str> = req.path().split("/").collect();
    // "/notes" -> ["", "notes"]; "/notes/3" -> ["", "notes", "3"]
    if segs.len() < 2 || segs[0] != "" || segs[1] != "notes" {
        return not_found(res);
    }
    if segs.len() == 2 {
        if method == "POST" {
            return create(&req.body(), res, db);
        }
        if method == "GET" {
            return list(&req.query(), res, db);
        }
        return not_found(res);
    }
    if segs.len() == 3 && is_id(&segs[2]) {
        let id = match segs[2].parse_int() {
            Ok(n) => n,
            Err(_) => return not_found(res),
        };
        if method == "GET" {
            return get_one(id, res, db);
        }
        if method == "DELETE" {
            return delete_one(id, res, db);
        }
    }
    not_found(res)
}

fn is_id(s: &Str) -> bool {
    if s.len() == 0 {
        return false;
    }
    for c in s.chars() {
        if !c.is_ascii_digit() {
            return false;
        }
    }
    true
}

fn send_json(res: &Outgoing, status: Int, body: Str) {
    res.status(status);
    res.header("content-type", "application/json");
    res.write(&body);
}

fn not_found(res: &Outgoing) -> Result<Str, Str> {
    send_json(res, 404, "{\"error\": \"not found\"}".to_string());
    Ok("not found".to_string())
}

fn invalid(res: &Outgoing) -> Result<Str, Str> {
    send_json(res, 400, "{\"error\": \"invalid note\"}".to_string());
    Ok("invalid note".to_string())
}

fn json_str_array(items: &Vec<Str>) -> Str {
    let mut out = String::from("[");
    for (i, s) in items.iter().enumerate() {
        if i > 0 {
            out += ", ";
        }
        out += &json::quote(s);
    }
    out += "]";
    out
}

fn tags_of(id: Int, db: &Db) -> Result<Vec<Str>, Str> {
    let rows = db.query_params("SELECT tag FROM note_tags WHERE note_id = ?1 ORDER BY pos", [id])?;
    let mut tags: Vec<Str> = Vec::new();
    for r in rows {
        tags.push(r.str(0));
    }
    Ok(tags)
}

fn create(body: &Str, res: &Outgoing, db: &Db) -> Result<Str, Str> {
    let v = match json::parse(body) {
        Ok(v) => v,
        Err(_) => return invalid(res),
    };
    if !v.is_object() {
        return invalid(res);
    }
    let title = match v.get_str("title") {
        Some(s) => s,
        None => return invalid(res),
