    if let Some(t) = tag {
        sql += " AND id IN (SELECT note_id FROM note_tags WHERE tag = ?)";
        params.push(Value::from(t));
    }
    if let Some(w) = q {
        // instr is case-sensitive, unlike LIKE
        sql += " AND (instr(title, ?) > 0 OR instr(body, ?) > 0)";
        params.push(Value::from(w.clone()));
        params.push(Value::from(w));
    }
    sql += " ORDER BY id DESC";

    let rows = db.query_values(sql, params)?;
    let mut out = String::from("[");
    let mut i: Int = 0;
    for r in rows {
        if i > 0 {
            out += ", ";
        }
        let mut item = String::from("{\"id\": ");
        item += r.int(0).to_str();
        item += ", \"title\": ";
        item += json::quote(r.str(1));
        item += "}";
        out += item;
        i += 1;
    }
    out += "]";
    send_json(res, 200, out);
    Ok("ok".to_string())
}

fn delete_one(id: Int, res: Outgoing, db: Db) -> Result<Str, Str> {
    let rows = db.query_params("SELECT id FROM notes WHERE id = ?1", [id])?;
    if rows.len() == 0 {
        return not_found(res);
    }
    db.exec_params("DELETE FROM note_tags WHERE note_id = ?1", [id])?;
    db.exec_params("DELETE FROM notes WHERE id = ?1", [id])?;
    let mut out = String::from("{\"deleted\": ");
    out += id.to_str();
    out += "}";
    send_json(res, 200, out);
    Ok("deleted".to_string())
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, Str> {
    db.exec("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL)", [])?;
    db.exec("CREATE TABLE IF NOT EXISTS note_tags (note_id INTEGER NOT NULL, tag TEXT NOT NULL, pos INTEGER NOT NULL, PRIMARY KEY (note_id, tag))", [])?;
    handle(req, res, db)
}

fn handle(req: Incoming, res: Outgoing, db: Db) -> Result<Str, Str> {
    let method = req.method();
    let segs: List<Str> = req.path().split("/").collect();
    // "/notes" -> ["", "notes"]; "/notes/3" -> ["", "notes", "3"]
    if segs.len() < 2 || segs[0] != "" || segs[1] != "notes" {
        return not_found(res);
    }
    if segs.len() == 2 {
        if method == "POST" {
            return create(req.body(), res, db);
        }
        if method == "GET" {
            return list(req.query(), res, db);
        }
        return not_found(res);
    }
    if segs.len() == 3 && is_id(segs[2].clone()) {
        let id = match segs[2].parse_int() {
            Ok(n) => n,
            Err(_) => return not_found(res),
        };
        if method == "GET" {
            return get_one(id, res, db);
        }
        if method == "DELETE" {
            return delete_one(id, res, db);
        }
    }
    not_found(res)
}

fn is_id(s: Str) -> Bool {
    if s.len() == 0 {
        return false;
    }
    for c in s.chars() {
        if !c.is_ascii_digit() {
            return false;
        }
    }
    true
}

fn jq(s: Str) -> Str {
    let mut out = String::from("\"");
    let esc = s
        .replace("\\", "\\\\")
        .replace("\"", "\\\"")
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("\t", "\\t");
    out += esc;
    out += "\"";
    out
}

fn send_json(res: Outgoing, status: Int, body: Str) {
    res.send(status, "application/json", body);
}

fn not_found(res: Outgoing) -> Result<Str, Str> {
    send_json(res, 404, String::from("{\"error\": \"not found\"}"));
    Ok(String::from("not found"))
}

fn invalid(res: Outgoing) -> Result<Str, Str> {
    send_json(res, 400, String::from("{\"error\": \"invalid note\"}"));
    Ok(String::from("invalid note"))
}

fn json_str_array(items: List<Str>) -> Str {
    let mut out = String::from("[");
    let mut i: Int = 0;
    for s in items {
        if i > 0 {
            out += ", ";
        }
        out += jq(s);
        i += 1;
    }
    out += "]";
    out
}

fn tags_of(id: Int, db: Db) -> Result<List<Str>, Str> {
    let rows = db.query("SELECT tag FROM note_tags WHERE note_id = ?1 ORDER BY pos", [SqlValue::from(id)])?;
    let mut tags: List<Str> = List::new();
    for r in rows {
        tags.push(r.str(0));
    }
    Ok(tags)
}

fn create(body: Str, res: Outgoing, db: Db) -> Result<Str, Str> {
    let v = match body.parse_json() {
        Ok(v) => v,
        Err(_) => return invalid(res),
    };
    if !v.is_object() {
        return invalid(res);
    }
    let title = match v.get_str("title") {
        Some(s) => s,
        None => return invalid(res),
    };
    if title.len() == 0 {
        return invalid(res);
    }
    let note_body = match v.get_str("body") {
        Some(s) => s,
        None => return invalid(res),
    };

    let mut tags: List<Str> = List::new();
    if let Some(t) = v.get("tags") {
        let arr = match t.as_array() {
            Some(a) => a,
            None => return invalid(res),
        };
        for item in arr {
            let s = match item.as_str() {
                Some(s) => s.to_lowercase(),
                None => return invalid(res),
            };
            let mut dup = false;
            for t in tags.clone() {
                if t == s {
                    dup = true;
                }
            }
            if !dup {
                tags.push(s);
            }
        }
    }

    db.exec("BEGIN", [])?;
    db.exec("INSERT INTO notes (title, body) VALUES (?1, ?2)", [SqlValue::from(title), SqlValue::from(note_body)])?;
    let id = db.last_insert_id();
    let mut pos: Int = 0;
    for tag in tags {
        db.exec("INSERT INTO note_tags (note_id, tag, pos) VALUES (?1, ?2, ?3)", [SqlValue::from(id), SqlValue::from(tag), SqlValue::from(pos)])?;
        pos += 1;
    }
    db.exec("COMMIT", [])?;

    let mut out = String::from("{\"id\": ");
    out += id.to_str();
    out += "}";
    send_json(res, 201, out);
    Ok(String::from("created"))
}

fn get_one(id: Int, res: Outgoing, db: Db) -> Result<Str, Str> {
    let rows = db.query("SELECT title, body FROM notes WHERE id = ?1", [SqlValue::from(id)])?;
    if rows.len() == 0 {
        return not_found(res);
    }
    let title = rows[0].str(0);
    let body = rows[0].str(1);
    let tags = tags_of(id, db)?;
    let mut out = String::from("{\"id\": ");
    out += id.to_str();
    out += ", \"title\": ";
    out += jq(title);
    out += ", \"body\": ";
    out += jq(body);
    out += ", \"tags\": ";
    out += json_str_array(tags);
    out += "}";
    send_json(res, 200, out);
    Ok(String::from("ok"))
}

fn list(query: Str, res: Outgoing, db: Db) -> Result<Str, Str> {
    let mut tag: Option<Str> = None;
    let mut q: Option<Str> = None;
    for kv in query.split("&") {
        let parts: List<Str> = kv.split("=").collect();
        if parts.len() != 2 {
            continue;
        }
        if parts[0] == "tag" && tag.is_none() {
            tag = Some(parts[1].to_lowercase());
        } else if parts[0] == "q" && q.is_none() {
            q = Some(parts[1].clone());
        }
    }

    let mut sql = String::from("SELECT id, title FROM notes WHERE 1=1");
    let mut params: List<SqlValue> = List::new();
    if let Some(t) = tag {
        sql += " AND id IN (SELECT note_id FROM note_tags WHERE tag = ?)";
        params.push(SqlValue::from(t));
    }
    if let Some(w) = q {
        // instr is case-sensitive, unlike LIKE
        sql += " AND (instr(title, ?) > 0 OR instr(body, ?) > 0)";
        params.push(SqlValue::from(w.clone()));
        params.push(SqlValue::from(w));
    }
    sql += " ORDER BY id DESC";

    let rows = db.query(sql, params)?;
    let mut out = String::from("[");
    let mut i: Int = 0;
    for r in rows {
        if i > 0 {
            out += ", ";
        }
        let mut item = String::from("{\"id\": ");
        item += r.int(0).to_str();
        item += ", \"title\": ";
        item += jq(r.str(1));
        item += "}";
        out += item;
        i += 1;
    }
    out += "]";
    send_json(res, 200, out);
    Ok(String::from("ok"))
}

fn delete_one(id: Int, res: Outgoing, db: Db) -> Result<Str, Str> {
    let rows = db.query("SELECT id FROM notes WHERE id = ?1", [SqlValue::from(id)])?;
    if rows.len() == 0 {
        return not_found(res);
    }
    db.exec("DELETE FROM note_tags WHERE note_id = ?1", [SqlValue::from(id)])?;
    db.exec("DELETE FROM notes WHERE id = ?1", [SqlValue::from(id)])?;
    let mut out = String::from("{\"deleted\": ");
    out += id.to_str();
    out += "}";
    send_json(res, 200, out);
    Ok(String::from("deleted"))
}

