        Ok(t) => t,
        Err(_) => return format!("{} unavailable", st.name),
    };
    if temps.len() == 0 {
        return format!("{} no data", st.name);
    }
    let mut min = temps[0];
    let mut max = temps[0];
    let mut sum: i64 = 0;
    for t in &temps {
        if *t < min {
            min = *t;
        }
        if *t > max {
            max = *t;
        }
        sum += *t;
    }
    let n = temps.len() as i64;
    let avg = sum / n;
    format!(
        "{} min={} max={} avg={} n={}",
        st.name,
        fmt_tenths(min),
        fmt_tenths(max),
        fmt_tenths(avg),
        n
    )
}

