// Assumed kio APIs (adjust to the actual std surface if different):
//   api.get(path) -> Result<Response, Str>, api.post(path, headers, body) -> Result<Response, Str>
//   Response { status: I64, body: Str }
//   Json::parse(&Str) -> Result<Json, Str>; Json: get(&Str), as_array(), as_i64(), as_str(), is_null()

fn main(api: Http) -> Result<Str, Str> {
    let mut orders: i64 = 0;
    let mut refunded: i64 = 0;
    let mut paid: Map<Str, i64> = Map::new();
    // (id, cents) of the best paid order so far
    let mut best: Option<(i64, i64)> = None;

    let mut page: i64 = 1;
    loop {
        let resp = api.get(format!("/orders?page={}", page))?;
        if resp.status != 200 {
            return Err(format!("GET /orders?page={} returned {}", page, resp.status));
        }
        let doc = Json::parse(&resp.body)?;

        for o in doc.get("orders")?.as_array()? {
            orders += 1;
            let status = o.get("status")?.as_str()?;
            let id = o.get("id")?.as_i64()?;
            let cents = o.get("cents")?.as_i64()?;
            let currency = o.get("currency")?.as_str()?;

            if status == "refunded" {
                refunded += 1;
            } else if status == "paid" {
                let total = paid.get(&currency).unwrap_or(0);
                paid.insert(currency, total + cents);

                best = match best {
                    None => Some((id, cents)),
                    Some((bid, bc)) => {
                        if cents > bc || (cents == bc && id < bid) {
                            Some((id, cents))
                        } else {
                            Some((bid, bc))
                        }
                    }
                };
            }
        }

        let next = doc.get("next")?;
        if next.is_null() {
            break;
        }
        page = next.as_i64()?;
    }

    // Serialize paid_cents with only the currencies that have paid orders.
    let mut parts: Vec<Str> = Vec::new();
    for (cur, total) in paid.iter() {
        parts.push(format!("\"{}\": {}", cur, total));
    }
    let paid_json = format!("{{{}}}", parts.join(", "));

    let largest_json = match best {
        Some((id, _)) => format!("{}", id),
        None => "null".to_string(),
    };

    let body = format!(
        "{{\"orders\": {}, \"paid_cents\": {}, \"refunded\": {}, \"largest\": {}}}",
        orders, paid_json, refunded, largest_json
    );

    let mut headers: Map<Str, Str> = Map::new();
    headers.insert("content-type", "application/json");

    let resp = api.post("/summaries", headers, body)?;
    if resp.status != 201 {
        return Err(format!("POST /summaries returned {}", resp.status));
    }
    let created = Json::parse(&resp.body)?;
    let id = created.get("id")?.as_str()?;
    Ok(id)
}

// Assumed kio APIs (adjust to the actual std surface if different):
//   api.get(path) -> Result<Response, Str>, api.post(path, headers, body) -> Result<Response, Str>
//   Response { status: I64, body: Str }
//   Json::parse(text) -> Result<Json, Str>; Json: get(key), as_array(), as_i64(), as_str(), is_null()

fn main(api: Http) -> Result<Str, Str> {
    let mut orders: i64 = 0;
    let mut refunded: i64 = 0;
    let mut paid: Map<Str, i64> = Map::new();
    // (id, cents) of the best paid order so far
    let mut best: Option<(i64, i64)> = None;

    let mut page: i64 = 1;
    loop {
        let resp = api.get(format!("/orders?page={}", page))?;
        if resp.status != 200 {
            return Err(format!("GET /orders?page={} returned {}", page, resp.status));
        }
        let doc = Json::parse(resp.body)?;

        for o in doc.get("orders")?.as_array()? {
            orders += 1;
            let status = o.get("status")?.as_str()?;
            let id = o.get("id")?.as_i64()?;
            let cents = o.get("cents")?.as_i64()?;
            let currency = o.get("currency")?.as_str()?;

            if status == "refunded" {
                refunded += 1;
            } else if status == "paid" {
                let total = paid.get(currency).unwrap_or(0);
                paid.insert(currency, total + cents);

                best = match best {
                    None => Some((id, cents)),
                    Some((bid, bc)) => {
                        if cents > bc || (cents == bc && id < bid) {
                            Some((id, cents))
                        } else {
                            Some((bid, bc))
                        }
                    }
                };
            }
        }

        let next = doc.get("next")?;
        if next.is_null() {
            break;
        }
        page = next.as_i64()?;
    }

    // Serialize paid_cents with only the currencies that have paid orders.
    let mut parts: Vec<Str> = Vec::new();
    for (cur, total) in paid.iter() {
        parts.push(format!("\"{}\": {}", cur, total));
    }
    let paid_json = format!("{{{}}}", parts.join(", "));

    let largest_json = match best {
        Some((id, _)) => format!("{}", id),
        None => "null".to_string(),
    };

    let body = format!(
        "{{\"orders\": {}, \"paid_cents\": {}, \"refunded\": {}, \"largest\": {}}}",
        orders, paid_json, refunded, largest_json
    );

    let mut headers: Map<Str, Str> = Map::new();
    headers.insert("content-type", "application/json");

    let resp = api.post("/summaries", headers, body)?;
    if resp.status != 201 {
        return Err(format!("POST /summaries returned {}", resp.status));
    }
    let created = Json::parse(resp.body)?;
    let id = created.get("id")?.as_str()?;
    Ok(id)
}

