fn find(keys: &Vec<Str>, key: &Str) -> Option<usize> {
    let mut i = 0;
    while i < keys.len() {
        if keys[i] == *key {
            return Some(i);
        }
        i += 1;
    }
    None
}

fn main(input: Dir, cache: Kv) -> Result<Str, Str> {
    let text = input.read("ops.txt")?;
    let lines = text.split("\n");
    let cap = lines[0].split(" ")[1].parse::<i64>().unwrap();

    // Cache state, most recently used first.
    let mut keys: Vec<Str> = Vec::new();
    let mut vals: Vec<Str> = Vec::new();
    let mut hits: i64 = 0;
    let mut misses: i64 = 0;
    let mut evictions: i64 = 0;

    // Stored format: hits, misses, evictions, then key/value line pairs (MRU first).
    if let Some(state) = cache.get("state") {
        let parts = state.split("\n");
        hits = parts[0].parse::<i64>().unwrap();
        misses = parts[1].parse::<i64>().unwrap();
        evictions = parts[2].parse::<i64>().unwrap();
        let mut i = 3;
        while i + 1 < parts.len() {
            keys.push(parts[i].clone());
            vals.push(parts[i + 1].clone());
            i += 2;
        }
    }

    let mut out = Str::new();

    // Shrink to the current capacity before the first operation.
    while (keys.len() as i64) > cap {
        let ek = keys.pop().unwrap();
        vals.pop();
        evictions += 1;
        out.push_str(&format!("evict {}\n", ek));
    }

    let mut n = 1;
    while n < lines.len() {
        let line = lines[n].clone();
        let lineno = n + 1;
        n += 1;

        if line == "" {
            continue;
        }

        let w = line.splitn(3, " ");
        let op = w[0].clone();

        if op == "get" && w.len() == 2 && w[1] != "" {
            let key = w[1].clone();
            match find(&keys, &key) {
                Some(i) => {
                    hits += 1;
                    out.push_str(&format!("{}={}\n", key, vals[i]));
                    let k = keys.remove(i);
                    let v = vals.remove(i);
                    keys.insert(0, k);
                    vals.insert(0, v);
                }
                None => {
                    misses += 1;
                    out.push_str(&format!("{} miss\n", key));
                }
            }
        } else if op == "put" && w.len() == 3 && w[1] != "" && w[2] != "" {
            let key = w[1].clone();
            let val = w[2].clone();
            match find(&keys, &key) {
                Some(i) => {
                    keys.remove(i);
                    vals.remove(i);
                }
                None => {
                    if (keys.len() as i64) >= cap {
                        let ek = keys.pop().unwrap();
                        vals.pop();
                        evictions += 1;
                        out.push_str(&format!("evict {}\n", ek));
                    }
                }
            }
            keys.insert(0, key);
            vals.insert(0, val);
        } else if op == "del" && w.len() == 2 && w[1] != "" {
            let key = w[1].clone();
            if let Some(i) = find(&keys, &key) {
                keys.remove(i);
                vals.remove(i);
            }
        } else {
            out.push_str(&format!("bad line {}\n", lineno));
        }
    }

    // Report the cache contents, most recently used first.
    let mut list = Str::new();
    let mut i = 0;
    while i < keys.len() {
        if i > 0 {
            list.push_str(",");
        }
        list.push_str(&keys[i]);
        i += 1;
    }
    if keys.len() == 0 {
        out.push_str("cache:\n");
    } else {
        out.push_str(&format!("cache: {}\n", list));
    }
    out.push_str(&format!(
        "stats hits {} misses {} evictions {}",
        hits, misses, evictions
    ));

    // Persist state for the next run.
    let mut state = format!("{}\n{}\n{}\n", hits, misses, evictions);
    let mut j = 0;
    while j < keys.len() {
        state.push_str(&format!("{}\n{}\n", keys[j], vals[j]));
        j += 1;
    }
    cache.put("state", &state);

    Ok(out)
}

