    // Report the cache contents, most recently used first.
    let mut list = Str::new();
    let mut i = 0;
    while i < keys.len() {
        if i > 0 {
            list.push_str(",");
        }
        list.push_str(keys[i].clone());
        i += 1;
    }
    if keys.len() == 0 {
        out.push_str("cache:\n");
    } else {
        out.push_str(format!("cache: {}\n", list));
    }
    out.push_str(format!(
        "stats hits {} misses {} evictions {}",
        hits, misses, evictions
    ));

    // Persist state for the next run.
    let mut state = format!("{}\n{}\n{}\n", hits, misses, evictions);
    let mut j = 0;
    while j < keys.len() {
        state.push_str(format!("{}\n{}\n", keys[j], vals[j]));
        j += 1;
    }
    cache.put("state", state);

    Ok(out)
}

fn main(input: Dir, cache: Kv) -> Result<Str, Str> {
    let text = input.read("ops.txt")?;
    let lines = text.split("\n");

    let first = lines[0].clone();
    let fparts = first.split(" ");
    let capstr = fparts[1].clone();
    let cap: usize = capstr.parse().unwrap();

    // Cache state, most recently used first.
    let mut keys: Vec<Str> = Vec::new();
    let mut vals: Vec<Str> = Vec::new();
    let mut hits: i64 = 0;
    let mut misses: i64 = 0;
    let mut evictions: i64 = 0;

    // Stored format: hits, misses, evictions, then key/value line pairs (MRU first).
    if let Some(state) = cache.get("state") {
        let parts = state.split("\n");
        let h: Str = parts[0].clone();
        let m: Str = parts[1].clone();
        let e: Str = parts[2].clone();
        hits = h.parse().unwrap();
        misses = m.parse().unwrap();
        evictions = e.parse().unwrap();
        let mut i = 3;
        while i + 1 < parts.len() {
            keys.push(parts[i].clone());
            vals.push(parts[i + 1].clone());
            i += 2;
        }
    }

    let mut out = Str::new();

    // Shrink to the current capacity before the first operation.
    while keys.len() > cap {
        let ek = keys.pop().unwrap();
        vals.pop();
        evictions += 1;
        out.push_str(format!("evict {}\n", ek));
    }

    let mut n = 1;
    while n < lines.len() {
        let line = lines[n].clone();
        let lineno = n + 1;
        n += 1;

        if line == "" {
            continue;
        }

        let w = line.splitn(3, " ");
        let op = w[0].clone();

        if op == "get" && w.len() == 2 && w[1] != "" {
            let key = w[1].clone();
            // pos == keys.len() means not found.
            let mut pos: usize = keys.len();
            let mut i = 0;
            while i < keys.len() {
                if pos == keys.len() && keys[i] == key {
                    pos = i;
                }
                i += 1;
            }
            if pos < keys.len() {
                hits += 1;
                out.push_str(format!("{}={}\n", key, vals[pos]));
                let k = keys.remove(pos);
                let v = vals.remove(pos);
                keys.insert(0, k);
                vals.insert(0, v);
            } else {
                misses += 1;
                out.push_str(format!("{} miss\n", key));
            }
        } else if op == "put" && w.len() == 3 && w[1] != "" && w[2] != "" {
            let key = w[1].clone();
            let val = w[2].clone();
            let mut pos: usize = keys.len();
            let mut i = 0;
            while i < keys.len() {
                if pos == keys.len() && keys[i] == key {
                    pos = i;
                }
                i += 1;
            }
            if pos < keys.len() {
                keys.remove(pos);
                vals.remove(pos);
            } else if keys.len() >= cap {
                let ek = keys.pop().unwrap();
                vals.pop();
                evictions += 1;
                out.push_str(format!("evict {}\n", ek));
            }
            keys.insert(0, key);
            vals.insert(0, val);
        } else if op == "del" && w.len() == 2 && w[1] != "" {
            let key = w[1].clone();
            let mut pos: usize = keys.len();
            let mut i = 0;
            while i < keys.len() {
                if pos == keys.len() && keys[i] == key {
                    pos = i;
                }
                i += 1;
            }
            if pos < keys.len() {
                keys.remove(pos);
                vals.remove(pos);
            }
        } else {
            out.push_str(format!("bad line {}\n", lineno));
        }
    }

    // Report the cache contents, most recently used first.
    let mut list = Str::new();
    let mut i = 0;
    while i < keys.len() {
        if i > 0 {
            list.push_str(",");
        }
        list.push_str(keys[i].clone());
        i += 1;
    }
    if keys.len() == 0 {
        out.push_str("cache:\n");
    } else {
        out.push_str(format!("cache: {}\n", list));
    }
    out.push_str(format!(
        "stats hits {} misses {} evictions {}",
        hits, misses, evictions
    ));

    // Persist state for the next run.
    let mut state = format!("{}\n{}\n{}\n", hits, misses, evictions);
    let mut j = 0;
    while j < keys.len() {
        state.push_str(format!("{}\n{}\n", keys[j], vals[j]));
        j += 1;
    }
    cache.put("state", state);

    Ok(out)
}

