// Build stages, cycles and missing dependencies for input/packages.json.

struct Parser {
    b: Vec<u8>,
    i: usize,
}

impl Parser {
    fn peek(&self) -> u8 {
        if self.i < self.b.len() { self.b[self.i] } else { 0 }
    }

    fn ws(&mut self) {
        while self.i < self.b.len() {
            let c = self.b[self.i];
            if c == 32 || c == 9 || c == 10 || c == 13 {
                self.i += 1;
            } else {
                break;
            }
        }
    }

    // Parses a JSON string at the cursor and returns its decoded bytes.
    fn string(&mut self) -> Option<Vec<u8>> {
        if self.peek() != 34 {
            return None;
        }
        self.i += 1;
        let mut out: Vec<u8> = Vec::new();
        loop {
            if self.i >= self.b.len() {
                return None;
            }
            let c = self.b[self.i];
            self.i += 1;
            if c == 34 {
                return Some(out);
            }
            if c != 92 {
                out.push(c);
                continue;
            }
            if self.i >= self.b.len() {
                return None;
            }
            let e = self.b[self.i];
            self.i += 1;
            match e {
                110 => out.push(10),
                116 => out.push(9),
                114 => out.push(13),
                98 => out.push(8),
                102 => out.push(12),
                117 => {
                    if self.i + 4 > self.b.len() {
                        return None;
                    }
                    let mut cp: u32 = 0;
                    for _ in 0..4 {
                        let h = self.b[self.i];
                        self.i += 1;
                        cp = cp * 16 + hexval(h)?;
                    }
                    push_utf8(&mut out, cp);
                }
                _ => out.push(e),
            }
        }
    }

    // Skips over any JSON value.
    fn skip(&mut self) -> Option<()> {
        self.ws();
        let c = self.peek();
        if c == 34 {
            self.string()?;
            return Some(());
        }
        if c == 123 || c == 91 {
            let close: u8 = if c == 123 { 125 } else { 93 };
            self.i += 1;
            self.ws();
            if self.peek() == close {
                self.i += 1;
                return Some(());
            }
            loop {
                self.ws();
                if c == 123 {
                    self.string()?;
                    self.ws();
                    if self.peek() != 58 {
                        return None;
                    }
                    self.i += 1;
                }
                self.skip()?;
                self.ws();
                match self.peek() {
                    44 => self.i += 1,
                    x if x == close => {
                        self.i += 1;
                        return Some(());
                    }
                    _ => return None,
                }
            }
        }
        // Number, true, false or null: a run of non-delimiter bytes.
        let start = self.i;
        while self.i < self.b.len() {
            let d = self.b[self.i];
            if d == 44 || d == 93 || d == 125 || d == 32 || d == 9 || d == 10 || d == 13 {
                break;
            }
            self.i += 1;
        }
        if self.i == start {
            return None;
        }
        Some(())
    }

    // Some(Some(deps)): an array of strings.
    // Some(None): any other valid JSON value (invalid package entry).
    // None: malformed JSON.
    fn deps(&mut self) -> Option<Option<Vec<Str>>> {
        self.ws();
        if self.peek() != 91 {
            self.skip()?;
            return Some(None);
        }
        self.i += 1;
        let mut items: Vec<Str> = Vec::new();
        let mut ok = true;
        self.ws();
        if self.peek() == 93 {
            self.i += 1;
            return Some(Some(items));
        }
        loop {
            self.ws();
            if self.peek() == 34 {
                let s = self.string()?;
                items.push(to_str(s));
            } else {
                self.skip()?;
                ok = false;
            }
            self.ws();
            match self.peek() {
                44 => self.i += 1,
                93 => {
                    self.i += 1;
                    break;
                }
                _ => return None,
            }
        }
        if ok { Some(Some(items)) } else { Some(None) }
    }
}

fn hexval(c: u8) -> Option<u32> {
    if c >= 48 && c <= 57 {
        Some((c - 48) as u32)
    } else if c >= 97 && c <= 102 {
        Some((c - 87) as u32)
    } else if c >= 65 && c <= 70 {
        Some((c - 55) as u32)
    } else {
        None
    }
}

fn push_utf8(out: &mut Vec<u8>, cp: u32) {
    if cp < 0x80 {
        out.push(cp as u8);
    } else if cp < 0x800 {
        out.push((0xC0 | (cp >> 6)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    } else {
        out.push((0xE0 | (cp >> 12)) as u8);
        out.push((0x80 | ((cp >> 6) & 0x3F)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    }
}

fn to_str(b: Vec<u8>) -> Str {
    Str::from_utf8(b).unwrap_or("".to_string())
}

// Returns the list of (key, value) pairs, or None if the text is not a JSON object.
fn parse(text: Str) -> Option<Vec<(Str, Option<Vec<Str>>)>> {
    let mut p = Parser { b: text.as_bytes().to_vec(), i: 0 };
    let mut entries: Vec<(Str, Option<Vec<Str>>)> = Vec::new();
    p.ws();
    if p.peek() != 123 {
        return None;
    }
    p.i += 1;
    p.ws();
    if p.peek() == 125 {
        p.i += 1;
    } else {
        loop {
            p.ws();
            let k = to_str(p.string()?);
            p.ws();
            if p.peek() != 58 {
                return None;
            }
            p.i += 1;
            let v = p.deps()?;
            entries.push((k, v));
            p.ws();
            match p.peek() {
                44 => p.i += 1,
                125 => {
                    p.i += 1;
                    break;
                }
                _ => return None,
            }
        }
    }
    p.ws();
    if p.i != p.b.len() {
        return None;
    }
    Some(entries)
}

fn find(v: &Vec<Str>, x: &Str) -> Option<usize> {
    for (k, s) in v.iter().enumerate() {
        if s == x {
            return Some(k);
        }
    }
    None
}

fn join(items: &Vec<Str>, sep: &str) -> Str {
    let mut out = "".to_string();
    for (k, s) in items.iter().enumerate() {
        if k > 0 {
            out.push_str(sep);
        }
        out.push_str(s);
    }
    out
}

fn main(input: Dir) -> Str {
    let text = match input.read("packages.json") {
        Ok(t) => t,
        Err(_) => return "error: not an object".to_string(),
    };
    let entries = match parse(text) {
        Some(e) => e,
        None => return "error: not an object".to_string(),
    };

    // Unique keys; a repeated key takes its last value.
    let mut names: Vec<Str> = Vec::new();
    let mut vals: Vec<Option<Vec<Str>>> = Vec::new();
    for (k, v) in entries {
        match find(&names, &k) {
            Some(j) => vals[j] = v,
            None => {
                names.push(k);
                vals.push(v);
            }
        }
    }

    // Valid packages (sorted) and invalid entries (sorted).
    let mut pkgs: Vec<Str> = Vec::new();
    let mut invalid: Vec<Str> = Vec::new();
    for j in 0..names.len() {
        if vals[j].is_some() {
            pkgs.push(names[j].clone());
        } else {
            invalid.push(names[j].clone());
        }
    }
    pkgs.sort();
    invalid.sort();
    let n = pkgs.len();

    // Raw dependency lists, in package order.
    let mut raw: Vec<Vec<Str>> = Vec::new();
    for i in 0..n {
        let j = find(&names, &pkgs[i]).unwrap();
        raw.push(vals[j].clone().unwrap());
    }

    // Edges among valid packages; anything else is a missing dependency.
    let mut deps: Vec<Vec<usize>> = Vec::new();
    let mut has_missing = vec![false; n];
    let mut missing: Vec<Str> = Vec::new();
    let mut needed: Vec<Vec<Str>> = Vec::new();
    for i in 0..n {
        let mut d: Vec<usize> = Vec::new();
        for dep in raw[i].iter() {
            match find(&pkgs, dep) {
                Some(k) => {
                    if !d.contains(&k) {
                        d.push(k);
                    }
                }
                None => {
                    has_missing[i] = true;
                    match find(&missing, dep) {
                        Some(m) => {
                            if !needed[m].contains(&pkgs[i]) {
                                needed[m].push(pkgs[i].clone());
                            }
                        }
                        None => {
                            missing.push(dep.clone());
                            needed.push(vec![pkgs[i].clone()]);
                        }
                    }
                }
            }
        }
        deps.push(d);
    }

    // reach[s][t]: t is reachable from s by a path of at least one edge.
    let mut reach: Vec<Vec<bool>> = Vec::new();
    for s in 0..n {
        let mut seen = vec![false; n];
        let mut stack: Vec<usize> = Vec::new();
        for &d in deps[s].iter() {
            if !seen[d] {
                seen[d] = true;
                stack.push(d);
            }
        }
        while let Some(u) = stack.pop() {
            for &d in deps[u].iter() {
                if !seen[d] {
                    seen[d] = true;
                    stack.push(d);
                }
            }
        }
        reach.push(seen);
    }
    let mut in_cycle = vec![false; n];
    for i in 0..n {
        in_cycle[i] = reach[i][i];
    }

    // Cycle groups: mutually reachable sets, ordered by first name.
    let mut cycle_lines: Vec<Str> = Vec::new();
    let mut assigned = vec![false; n];
    for i in 0..n {
        if !in_cycle[i] || assigned[i] {
            continue;
        }
        let mut group: Vec<Str> = Vec::new();
        for j in 0..n {
            if reach[i][j] && reach[j][i] {
                assigned[j] = true;
                group.push(pkgs[j].clone());
            }
        }
        cycle_lines.push(format!("cycle: {}", join(&group, ", ")));
    }

    // Kahn's algorithm over packages that are not in a cycle and have no missing deps.
    // Packages downstream of a cycle or a missing name never reach zero in-degree.
    let mut eligible = vec![false; n];
    for i in 0..n {
        eligible[i] = !in_cycle[i] && !has_missing[i];
    }
    let mut indeg = vec![0usize; n];
    let mut rdeps: Vec<Vec<usize>> = Vec::new();
    for _ in 0..n {
        rdeps.push(Vec::new());
    }
    for i in 0..n {
        if !eligible[i] {
            continue;
        }
        indeg[i] = deps[i].len();
        for &k in deps[i].iter() {
            rdeps[k].push(i);
        }
    }

    let mut built = vec![false; n];
    let mut stage = vec![0usize; n];
    let mut queue: Vec<usize> = Vec::new();
    for i in 0..n {
        if eligible[i] && indeg[i] == 0 {
            built[i] = true;
            stage[i] = 1;
            queue.push(i);
        }
    }
    let mut head = 0;
    while head < queue.len() {
        let u = queue[head];
        head += 1;
        for &v in rdeps[u].iter() {
            if stage[u] + 1 > stage[v] {
                stage[v] = stage[u] + 1;
            }
            indeg[v] -= 1;
            if indeg[v] == 0 {
                built[v] = true;
                queue.push(v);
            }
        }
    }
    let built_count = queue.len();

    // Stage lines.
    let mut max_stage = 0usize;
    for i in 0..n {
        if built[i] && stage[i] > max_stage {
            max_stage = stage[i];
        }
    }
    let mut stage_lines: Vec<Str> = Vec::new();
    for s in 1..max_stage + 1 {
        let mut members: Vec<Str> = Vec::new();
        for i in 0..n {
            if built[i] && stage[i] == s {
                members.push(pkgs[i].clone());
            }
        }
        if !members.is_empty() {
            stage_lines.push(format!("stage {}: {}", s, join(&members, ", ")));
        }
    }

    // Missing lines, sorted by missing name.
    let mut missing_lines: Vec<Str> = Vec::new();
    let mut sorted_missing = missing.clone();
    sorted_missing.sort();
    for m in sorted_missing.iter() {
        let idx = find(&missing, m).unwrap();
        missing_lines.push(format!("missing: {} (needed by {})", m, join(&needed[idx], ", ")));
    }

    // Blocked: not built and in no cycle.
    let mut blocked: Vec<Str> = Vec::new();
    for i in 0..n {
        if !built[i] && !in_cycle[i] {
            blocked.push(pkgs[i].clone());
        }
    }

    // Assemble output in the required order, omitting empty sections.
    let mut out: Vec<Str> = Vec::new();
    for l in stage_lines {
        out.push(l);
    }
    for l in cycle_lines {
        out.push(l);
    }
    for l in missing_lines {
        out.push(l);
    }
    if !invalid.is_empty() {
        out.push(format!("invalid: {}", join(&invalid, ", ")));
    }
    if !blocked.is_empty() {
        out.push(format!("blocked: {}", join(&blocked, ", ")));
    }
    out.push(format!("built {} of {}", built_count, n));

    join(&out, "\n")
}

// Build stages, cycles and missing dependencies for input/packages.json.

fn is_ws(c: u8) -> bool {
    c == 32 || c == 9 || c == 10 || c == 13
}

fn hexval(c: u8) -> Option<u32> {
    if c >= 48 && c <= 57 {
        Some((c - 48) as u32)
    } else if c >= 97 && c <= 102 {
        Some((c - 87) as u32)
    } else if c >= 65 && c <= 70 {
        Some((c - 55) as u32)
    } else {
        None
    }
}

fn push_utf8(mut out: Vec<u8>, cp: u32) -> Vec<u8> {
    if cp < 0x80 {
        out.push(cp as u8);
    } else if cp < 0x800 {
        out.push((0xC0 | (cp >> 6)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    } else {
        out.push((0xE0 | (cp >> 12)) as u8);
        out.push((0x80 | ((cp >> 6) & 0x3F)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    }
    out
}

fn to_str(b: Vec<u8>) -> Str {
    Str::from_utf8(b).unwrap_or("".to_string())
}

fn index_of(v: Vec<Str>, x: Str) -> Option<usize> {
    for k in 0..v.len() {
        if v[k] == x {
            return Some(k);
        }
    }
    None
}

fn has_index(v: Vec<usize>, x: usize) -> bool {
    for k in 0..v.len() {
        if v[k] == x {
            return true;
        }
    }
    false
}

fn join(items: Vec<Str>, sep: Str) -> Str {
    let mut out: Str = "".to_string();
    for k in 0..items.len() {
        if k > 0 {
            out = format!("{}{}", out, sep);
        }
        out = format!("{}{}", out, items[k]);
    }
    out
}

// b[start] must be a quote. Returns the decoded bytes and the index just past the closing quote.
fn read_str(b: Vec<u8>, start: usize) -> Option<(Vec<u8>, usize)> {
    let n = b.len();
    if start >= n || b[start] != 34 {
        return None;
    }
    let mut i = start + 1;
    let mut out: Vec<u8> = Vec::new();
    loop {
        if i >= n {
            return None;
        }
        let c = b[i];
        i += 1;
        if c == 34 {
            return Some((out, i));
        }
        if c != 92 {
            out.push(c);
            continue;
        }
        if i >= n {
            return None;
        }
        let e = b[i];
        i += 1;
        if e == 110 {
            out.push(10);
        } else if e == 116 {
            out.push(9);
        } else if e == 114 {
            out.push(13);
        } else if e == 98 {
            out.push(8);
        } else if e == 102 {
            out.push(12);
        } else if e == 117 {
            if i + 4 > n {
                return None;
            }
            let mut cp: u32 = 0;
            for _ in 0..4 {
                cp = cp * 16 + hexval(b[i])?;
                i += 1;
            }
            out = push_utf8(out, cp);
        } else {
            out.push(e);
        }
    }
}

// Skips one JSON value starting at start. Returns the index just past it.
fn skip_value(b: Vec<u8>, start: usize) -> Option<usize> {
    let n = b.len();
    let mut i = start;
    let mut depth: usize = 0;
    loop {
        if i >= n {
            return None;
        }
        let c = b[i];
        if c == 34 {
            let (_, j) = read_str(b.clone(), i)?;
            i = j;
        } else if c == 123 || c == 91 {
            depth += 1;
            i += 1;
        } else if c == 125 || c == 93 {
            if depth == 0 {
                break;
            }
            depth -= 1;
            i += 1;
            if depth == 0 {
                return Some(i);
            }
        } else if c == 44 || is_ws(c) {
            if depth == 0 {
                break;
            }
            i += 1;
        } else {
            i += 1;
        }
    }
    if i == start {
        return None;
    }
    Some(i)
}

// Parses the value at start.
// Returns (valid, deps, index after value). valid is true only for an array of strings.
fn value(b: Vec<u8>, start: usize) -> Option<(bool, Vec<Str>, usize)> {
    let n = b.len();
    let mut i = start;
    if i < n && b[i] == 91 {
        i += 1;
        let mut items: Vec<Str> = Vec::new();
        let mut ok = true;
        while i < n && is_ws(b[i]) {
            i += 1;
        }
        if i < n && b[i] == 93 {
            return Some((true, items, i + 1));
        }
        loop {
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            if i < n && b[i] == 34 {
                let (s, j) = read_str(b.clone(), i)?;
                items.push(to_str(s));
                i = j;
            } else {
                i = skip_value(b.clone(), i)?;
                ok = false;
            }
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            if i >= n {
                return None;
            }
            if b[i] == 44 {
                i += 1;
            } else if b[i] == 93 {
                i += 1;
                break;
            } else {
                return None;
            }
        }
        Some((ok, items, i))
    } else {
        let j = skip_value(b.clone(), i)?;
        Some((false, Vec::new(), j))
    }
}

// Returns (key, valid, deps) for each top-level entry, or None if the text is not a JSON object.
fn parse(text: Str) -> Option<Vec<(Str, bool, Vec<Str>)>> {
    let b: Vec<u8> = text.as_bytes().to_vec();
    let n = b.len();
    let mut i: usize = 0;
    let mut out: Vec<(Str, bool, Vec<Str>)> = Vec::new();
    while i < n && is_ws(b[i]) {
        i += 1;
    }
    if i >= n || b[i] != 123 {
        return None;
    }
    i += 1;
    while i < n && is_ws(b[i]) {
        i += 1;
    }
    if i < n && b[i] == 125 {
        i += 1;
    } else {
        loop {
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            let (k, j) = read_str(b.clone(), i)?;
            i = j;
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            if i >= n || b[i] != 58 {
                return None;
            }
            i += 1;
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            let (ok, deps, j2) = value(b.clone(), i)?;
            i = j2;
            out.push((to_str(k), ok, deps));
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            if i >= n {
                return None;
            }
            if b[i] == 44 {
                i += 1;
            } else if b[i] == 125 {
                i += 1;
                break;
            } else {
                return None;
            }
        }
    }
    while i < n && is_ws(b[i]) {
        i += 1;
    }
    if i != n {
        return None;
    }
    Some(out)
}

fn main(input: Dir) -> Str {
    let text = match input.read("packages.json") {
        Ok(t) => t,
        Err(_) => return "error: not an object".to_string(),
    };
    let entries = match parse(text) {
        Some(e) => e,
        None => return "error: not an object".to_string(),
    };

    // Unique keys; a repeated key takes its last value.
    let mut names: Vec<Str> = Vec::new();
    let mut valid: Vec<bool> = Vec::new();
    let mut rawdeps: Vec<Vec<Str>> = Vec::new();
    for (k, ok, d) in entries {
        match index_of(names.clone(), k.clone()) {
            Some(j) => {
                valid[j] = ok;
                rawdeps[j] = d;
            }
            None => {
                names.push(k);
                valid.push(ok);
                rawdeps.push(d);
            }
        }
    }

    // Valid packages (sorted) and invalid entries (sorted).
    let mut pkgs: Vec<Str> = Vec::new();
    let mut invalid: Vec<Str> = Vec::new();
    for j in 0..names.len() {
        if valid[j] {
            pkgs.push(names[j].clone());
        } else {
            invalid.push(names[j].clone());
        }
    }
    pkgs.sort();
    invalid.sort();
    let n = pkgs.len();

    // Raw dependency lists, in package order.
    let mut raw: Vec<Vec<Str>> = Vec::new();
    for i in 0..n {
        let j = index_of(names.clone(), pkgs[i].clone()).unwrap();
        raw.push(rawdeps[j].clone());
    }

    // Edges among valid packages; anything else is a missing dependency.
    let mut deps: Vec<Vec<usize>> = Vec::new();
    let mut has_missing = vec![false; n];
    let mut missing: Vec<Str> = Vec::new();
    let mut needed: Vec<Vec<Str>> = Vec::new();
    for i in 0..n {
        let mut d: Vec<usize> = Vec::new();
        for dep in raw[i].clone() {
            match index_of(pkgs.clone(), dep.clone()) {
                Some(k) => {
                    if !has_index(d.clone(), k) {
                        d.push(k);
                    }
                }
                None => {
                    has_missing[i] = true;
                    match index_of(missing.clone(), dep.clone()) {
                        Some(m) => {
                            if index_of(needed[m].clone(), pkgs[i].clone()).is_none() {
                                needed[m].push(pkgs[i].clone());
                            }
                        }
                        None => {
                            missing.push(dep.clone());
                            needed.push(vec![pkgs[i].clone()]);
                        }
                    }
                }
            }
        }
        deps.push(d);
    }

    // reach[s][t]: t is reachable from s by a path of at least one edge.
    let mut reach: Vec<Vec<bool>> = Vec::new();
    for s in 0..n {
        let mut seen = vec![false; n];
        let mut stack: Vec<usize> = Vec::new();
        for d in deps[s].clone() {
            if !seen[d] {
                seen[d] = true;
                stack.push(d);
            }
        }
        while let Some(u) = stack.pop() {
            for d in deps[u].clone() {
                if !seen[d] {
                    seen[d] = true;
                    stack.push(d);
                }
            }
        }
        reach.push(seen);
    }
    let mut in_cycle = vec![false; n];
    for i in 0..n {
        in_cycle[i] = reach[i][i];
    }

    // Cycle groups: mutually reachable sets, ordered by first name.
    let mut cycle_lines: Vec<Str> = Vec::new();
    let mut assigned = vec![false; n];
    for i in 0..n {
        if !in_cycle[i] || assigned[i] {
            continue;
        }
        let mut group: Vec<Str> = Vec::new();
        for j in 0..n {
            if reach[i][j] && reach[j][i] {
                assigned[j] = true;
                group.push(pkgs[j].clone());
            }
        }
        cycle_lines.push(format!("cycle: {}", join(group, ", ".to_string())));
    }

    // Kahn's algorithm over packages that are not in a cycle and have no missing deps.
    // Packages downstream of a cycle or a missing name never reach zero in-degree.
    let mut eligible = vec![false; n];
    for i in 0..n {
        eligible[i] = !in_cycle[i] && !has_missing[i];
    }
    let mut indeg = vec![0usize; n];
    let mut rdeps: Vec<Vec<usize>> = Vec::new();
    for _ in 0..n {
        rdeps.push(Vec::new());
    }
    for i in 0..n {
        if !eligible[i] {
            continue;
        }
        indeg[i] = deps[i].len();
        for k in deps[i].clone() {
            rdeps[k].push(i);
        }
    }

    let mut built = vec![false; n];
    let mut stage = vec![0usize; n];
    let mut queue: Vec<usize> = Vec::new();
    for i in 0..n {
        if eligible[i] && indeg[i] == 0 {
            built[i] = true;
            stage[i] = 1;
            queue.push(i);
        }
    }
    let mut head: usize = 0;
    while head < queue.len() {
        let u = queue[head];
        head += 1;
        for v in rdeps[u].clone() {
            if stage[u] + 1 > stage[v] {
                stage[v] = stage[u] + 1;
            }
            indeg[v] -= 1;
            if indeg[v] == 0 {
                built[v] = true;
                queue.push(v);
            }
        }
    }
    let built_count = queue.len();

    // Stage lines.
    let mut max_stage: usize = 0;
    for i in 0..n {
        if built[i] && stage[i] > max_stage {
            max_stage = stage[i];
        }
    }
    let mut stage_lines: Vec<Str> = Vec::new();
    for s in 1..max_stage + 1 {
        let mut members: Vec<Str> = Vec::new();
        for i in 0..n {
            if built[i] && stage[i] == s {
                members.push(pkgs[i].clone());
            }
        }
        if !members.is_empty() {
            stage_lines.push(format!("stage {}: {}", s, join(members, ", ".to_string())));
        }
    }

    // Missing lines, sorted by missing name.
    let mut missing_lines: Vec<Str> = Vec::new();
    let mut sorted_missing = missing.clone();
    sorted_missing.sort();
    for m in sorted_missing {
        let idx = index_of(missing.clone(), m.clone()).unwrap();
        missing_lines.push(format!(
            "missing: {} (needed by {})",
            m,
            join(needed[idx].clone(), ", ".to_string())
        ));
    }

    // Blocked: not built and in no cycle.
    let mut blocked: Vec<Str> = Vec::new();
    for i in 0..n {
        if !built[i] && !in_cycle[i] {
            blocked.push(pkgs[i].clone());
        }
    }

    // Assemble output in the required order, omitting empty sections.
    let mut out: Vec<Str> = Vec::new();
    for l in stage_lines {
        out.push(l);
    }
    for l in cycle_lines {
        out.push(l);
    }
    for l in missing_lines {
        out.push(l);
    }
    if !invalid.is_empty() {
        out.push(format!("invalid: {}", join(invalid, ", ".to_string())));
    }
    if !blocked.is_empty() {
        out.push(format!("blocked: {}", join(blocked, ", ".to_string())));
    }
    out.push(format!("built {} of {}", built_count, n));

    join(out, "\n".to_string())
}

