        for dep in raw[i].clone() {
            match index_of(pkgs.clone(), dep.clone()) {
                Some(k) => {
                    if !has_index(d.clone(), k) {
                        d.push(k);
                    }
                }
                None => {
                    has_missing[i] = true;
                    match index_of(missing.clone(), dep.clone()) {
                        Some(m) => {
                            if index_of(needed[m].clone(), pkgs[i].clone()).is_none() {
                                needed[m].push(pkgs[i].clone());
                            }
                        }
                        None => {
                            missing.push(dep.clone());
                            needed.push(vec![pkgs[i].clone()]);
                        }
                    }
                }
            }
        }
        deps.push(d);
    }

    // reach[s][t]: t is reachable from s by a path of at least one edge.
    let mut reach: Vec<Vec<bool>> = Vec::new();
    for s in 0..n {
        let mut seen = vec![false; n];
        let mut stack: Vec<usize> = Vec::new();
        for d in deps[s].clone() {
            if !seen[d] {
                seen[d] = true;
                stack.push(d);
            }
        }
        while let Some(u) = stack.pop() {
            for d in deps[u].clone() {
                if !seen[d] {
                    seen[d] = true;
                    stack.push(d);
                }
            }
        }
        reach.push(seen);
    }
    let mut in_cycle = vec![false; n];
    for i in 0..n {
        in_cycle[i] = reach[i][i];
    }

    // Cycle groups: mutually reachable sets, ordered by first name.
    let mut cycle_lines: Vec<Str> = Vec::new();
    let mut assigned = vec![false; n];
    for i in 0..n {
        if !in_cycle[i] || assigned[i] {
            continue;
        }
        let mut group: Vec<Str> = Vec::new();
        for j in 0..n {
            if reach[i][j] && reach[j][i] {
                assigned[j] = true;
                group.push(pkgs[j].clone());
            }
        }
        cycle_lines.push(format!("cycle: {}", join(group, ", ".to_string())));
    }

    // Kahn's algorithm over packages that are not in a cycle and have no missing deps.
    // Packages downstream of a cycle or a missing name never reach zero in-degree.
    let mut eligible = vec![false; n];
    for i in 0..n {
        eligible[i] = !in_cycle[i] && !has_missing[i];
    }
    let mut indeg = vec![0usize; n];
    let mut rdeps: Vec<Vec<usize>> = Vec::new();
    for _ in 0..n {
        rdeps.push(Vec::new());
    }
    for i in 0..n {
        if !eligible[i] {
            continue;
        }
        indeg[i] = deps[i].len();
        for k in deps[i].clone() {
            rdeps[k].push(i);
        }
    }

    let mut built = vec![false; n];
    let mut stage = vec![0usize; n];
    let mut queue: Vec<usize> = Vec::new();
    for i in 0..n {
        if eligible[i] && indeg[i] == 0 {
            built[i] = true;
            stage[i] = 1;
            queue.push(i);
        }
    }
    let mut head: usize = 0;
    while head < queue.len() {
        let u = queue[head];
        head += 1;
        for v in rdeps[u].clone() {
            if stage[u] + 1 > stage[v] {
                stage[v] = stage[u] + 1;
            }
            indeg[v] -= 1;
            if indeg[v] == 0 {
                built[v] = true;
                queue.push(v);
            }
        }
    }
    let built_count = queue.len();

    // Stage lines.
    let mut max_stage: usize = 0;
    for i in 0..n {
        if built[i] && stage[i] > max_stage {
            max_stage = stage[i];
        }
    }
    let mut stage_lines: Vec<Str> = Vec::new();
    for s in 1..max_stage + 1 {
        let mut members: Vec<Str> = Vec::new();
        for i in 0..n {
            if built[i] && stage[i] == s {
                members.push(pkgs[i].clone());
            }
        }
        if !members.is_empty() {
            stage_lines.push(format!("stage {}: {}", s, join(members, ", ".to_string())));
        }
    }

    // Missing lines, sorted by missing name.
    let mut missing_lines: Vec<Str> = Vec::new();
    let mut sorted_missing = missing.clone();
    sorted_missing.sort();
    for m in sorted_missing {
        let idx = index_of(missing.clone(), m.clone()).unwrap();
        missing_lines.push(format!(
            "missing: {} (needed by {})",
            m,
            join(needed[idx].clone(), ", ".to_string())
        ));
    }

    // Blocked: not built and in no cycle.
    let mut blocked: Vec<Str> = Vec::new();
    for i in 0..n {
        if !built[i] && !in_cycle[i] {
            blocked.push(pkgs[i].clone());
        }
    }

    // Assemble output in the required order, omitting empty sections.
    let mut out: Vec<Str> = Vec::new();
    for l in stage_lines {
        out.push(l);
    }
    for l in cycle_lines {
        out.push(l);
    }
    for l in missing_lines {
        out.push(l);
    }
    if !invalid.is_empty() {
        out.push(format!("invalid: {}", join(invalid, ", ".to_string())));
    }
    if !blocked.is_empty() {
        out.push(format!("blocked: {}", join(blocked, ", ".to_string())));
    }
    out.push(format!("built {} of {}", built_count, n));

    join(out, "\n".to_string())
}

// Build stages, cycles and missing dependencies for input/packages.json.

fn is_ws(c: u8) -> bool {
    c == 32 || c == 9 || c == 10 || c == 13
}

fn hexval(c: u8) -> Option<u32> {
    if c >= 48 && c <= 57 {
        Some((c - 48) as u32)
    } else if c >= 97 && c <= 102 {
        Some((c - 87) as u32)
    } else if c >= 65 && c <= 70 {
        Some((c - 55) as u32)
    } else {
        None
    }
}

fn push_utf8(mut out: Vec<u8>, cp: u32) -> Vec<u8> {
    if cp < 128 {
        out.push(cp as u8);
    } else if cp < 2048 {
        out.push((192 + cp / 64) as u8);
        out.push((128 + cp % 64) as u8);
    } else {
        out.push((224 + cp / 4096) as u8);
        out.push((128 + (cp / 64) % 64) as u8);
        out.push((128 + cp % 64) as u8);
    }
    out
}

fn to_str(b: Vec<u8>) -> Str {
    Str::from_utf8(b).unwrap_or("".to_string())
}

fn index_of(v: Vec<Str>, x: Str) -> Option<usize> {
    for k in 0..v.len() {
        if v[k] == x {
            return Some(k);
        }
    }
    None
}

fn has_index(v: Vec<usize>, x: usize) -> bool {
    for k in 0..v.len() {
        if v[k] == x {
            return true;
        }
    }
    false
}

fn join(items: Vec<Str>, sep: Str) -> Str {
    let mut out: Str = "".to_string();
    for k in 0..items.len() {
        if k > 0 {
            out = format!("{}{}", out, sep);
        }
        out = format!("{}{}", out, items[k]);
    }
    out
}

// b[start] must be a quote. Returns the decoded bytes and the index just past the closing quote.
fn read_str(b: Vec<u8>, start: usize) -> Option<(Vec<u8>, usize)> {
    let n = b.len();
    if start >= n || b[start] != 34 {
        return None;
    }
    let mut i = start + 1;
    let mut out: Vec<u8> = Vec::new();
    loop {
        if i >= n {
            return None;
        }
        let c = b[i];
        i += 1;
        if c == 34 {
            return Some((out, i));
        }
        if c != 92 {
            out.push(c);
            continue;
        }
        if i >= n {
            return None;
        }
        let e = b[i];
        i += 1;
        if e == 110 {
            out.push(10);
        } else if e == 116 {
            out.push(9);
        } else if e == 114 {
            out.push(13);
        } else if e == 98 {
            out.push(8);
        } else if e == 102 {
            out.push(12);
        } else if e == 117 {
            if i + 4 > n {
                return None;
            }
            let mut cp: u32 = 0;
            for _ in 0..4 {
                cp = cp * 16 + hexval(b[i])?;
                i += 1;
            }
            out = push_utf8(out, cp);
        } else {
            out.push(e);
        }
    }
}

// Skips one JSON value starting at start. Returns the index just past it.
fn skip_value(b: Vec<u8>, start: usize) -> Option<usize> {
    let n = b.len();
    let mut i = start;
    let mut depth: usize = 0;
    loop {
        if i >= n {
            return None;
        }
        let c = b[i];
        if c == 34 {
            let (_, j) = read_str(b.clone(), i)?;
            i = j;
        } else if c == 123 || c == 91 {
            depth += 1;
            i += 1;
        } else if c == 125 || c == 93 {
            if depth == 0 {
                break;
            }
            depth -= 1;
            i += 1;
            if depth == 0 {
                return Some(i);
            }
        } else if c == 44 || is_ws(c) {
            if depth == 0 {
                break;
            }
            i += 1;
        } else {
            i += 1;
        }
    }
    if i == start {
        return None;
    }
    Some(i)
}

// Parses the value at start.
// Returns (valid, deps, index after value). valid is true only for an array of strings.
fn value(b: Vec<u8>, start: usize) -> Option<(bool, Vec<Str>, usize)> {
    let n = b.len();
    let mut i = start;
    if i < n && b[i] == 91 {
        i += 1;
        let mut items: Vec<Str> = Vec::new();
        let mut ok = true;
        while i < n && is_ws(b[i]) {
            i += 1;
        }
        if i < n && b[i] == 93 {
            return Some((true, items, i + 1));
        }
        loop {
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            if i < n && b[i] == 34 {
                let (s, j) = read_str(b.clone(), i)?;
                items.push(to_str(s));
                i = j;
            } else {
                i = skip_value(b.clone(), i)?;
                ok = false;
            }
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            if i >= n {
                return None;
            }
            if b[i] == 44 {
                i += 1;
            } else if b[i] == 93 {
                i += 1;
                break;
            } else {
                return None;
            }
        }
        Some((ok, items, i))
    } else {
        let j = skip_value(b.clone(), i)?;
        Some((false, Vec::new(), j))
    }
}

// Returns (key, valid, deps) for each top-level entry, or None if the text is not a JSON object.
fn parse(text: Str) -> Option<Vec<(Str, bool, Vec<Str>)>> {
    let b: Vec<u8> = text.into_bytes();
    let n = b.len();
    let mut i: usize = 0;
    let mut out: Vec<(Str, bool, Vec<Str>)> = Vec::new();
    while i < n && is_ws(b[i]) {
        i += 1;
    }
    if i >= n || b[i] != 123 {
        return None;
    }
    i += 1;
    while i < n && is_ws(b[i]) {
        i += 1;
    }
    if i < n && b[i] == 125 {
        i += 1;
    } else {
        loop {
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            let (k, j) = read_str(b.clone(), i)?;
            i = j;
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            if i >= n || b[i] != 58 {
                return None;
            }
            i += 1;
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            let (ok, deps, j2) = value(b.clone(), i)?;
            i = j2;
            out.push((to_str(k), ok, deps));
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            if i >= n {
                return None;
            }
            if b[i] == 44 {
                i += 1;
            } else if b[i] == 125 {
                i += 1;
                break;
            } else {
                return None;
            }
        }
    }
    while i < n && is_ws(b[i]) {
        i += 1;
    }
    if i != n {
        return None;
    }
    Some(out)
}

fn main(input: Dir) -> Str {
    let text = match input.read("packages.json") {
        Ok(t) => t,
        Err(_) => return "error: not an object".to_string(),
    };
    let entries = match parse(text) {
        Some(e) => e,
        None => return "error: not an object".to_string(),
    };

    // Unique keys; a repeated key takes its last value.
    let mut names: Vec<Str> = Vec::new();
    let mut valid: Vec<bool> = Vec::new();
    let mut rawdeps: Vec<Vec<Str>> = Vec::new();
    for (k, ok, d) in entries {
        match index_of(names.clone(), k.clone()) {
            Some(j) => {
                valid[j] = ok;
                rawdeps[j] = d;
            }
            None => {
                names.push(k);
                valid.push(ok);
                rawdeps.push(d);
            }
        }
    }

    // Valid packages (sorted) and invalid entries (sorted).
    let mut pkgs: Vec<Str> = Vec::new();
    let mut invalid: Vec<Str> = Vec::new();
    for j in 0..names.len() {
        if valid[j] {
            pkgs.push(names[j].clone());
        } else {
            invalid.push(names[j].clone());
        }
    }
    pkgs.sort();
    invalid.sort();
    let n = pkgs.len();

    // Raw dependency lists, in package order.
    let mut raw: Vec<Vec<Str>> = Vec::new();
    for i in 0..n {
        let j = index_of(names.clone(), pkgs[i].clone()).unwrap();
        raw.push(rawdeps[j].clone());
    }

    // Edges among valid packages; anything else is a missing dependency.
    let mut deps: Vec<Vec<usize>> = Vec::new();
    let mut has_missing = vec![false; n];
    let mut missing: Vec<Str> = Vec::new();
    let mut needed: Vec<Vec<Str>> = Vec::new();
    for i in 0..n {
        let mut d: Vec<usize> = Vec::new();
        for dep in raw[i].clone() {
            match index_of(pkgs.clone(), dep.clone()) {
                Some(k) => {
                    if !has_index(d.clone(), k) {
                        d.push(k);
                    }
                }
                None => {
                    has_missing[i] = true;
                    match index_of(missing.clone(), dep.clone()) {
                        Some(m) => {
                            if index_of(needed[m].clone(), pkgs[i].clone()).is_none() {
                                needed[m].push(pkgs[i].clone());
                            }
                        }
                        None => {
                            missing.push(dep.clone());
                            needed.push(vec![pkgs[i].clone()]);
                        }
                    }
                }
            }
        }
        deps.push(d);
    }

    // reach[s][t]: t is reachable from s by a path of at least one edge.
    let mut reach: Vec<Vec<bool>> = Vec::new();
    for s in 0..n {
        let mut seen = vec![false; n];
        let mut stack: Vec<usize> = Vec::new();
        for d in deps[s].clone() {
            if !seen[d] {
                seen[d] = true;
                stack.push(d);
            }
        }
        while let Some(u) = stack.pop() {
            for d in deps[u].clone() {
                if !seen[d] {
                    seen[d] = true;
                    stack.push(d);
                }
            }
        }
        reach.push(seen);
    }
    let mut in_cycle = vec![false; n];
    for i in 0..n {
        in_cycle[i] = reach[i][i];
    }

    // Cycle groups: mutually reachable sets, ordered by first name.
    let mut cycle_lines: Vec<Str> = Vec::new();
    let mut assigned = vec![false; n];
    for i in 0..n {
        if !in_cycle[i] || assigned[i] {
            continue;
        }
        let mut group: Vec<Str> = Vec::new();
        for j in 0..n {
            if reach[i][j] && reach[j][i] {
                assigned[j] = true;
                group.push(pkgs[j].clone());
            }
        }
        cycle_lines.push(format!("cycle: {}", join(group, ", ".to_string())));
    }

    // Kahn's algorithm over packages that are not in a cycle and have no missing deps.
    // Packages downstream of a cycle or a missing name never reach zero in-degree.
    let mut eligible = vec![false; n];
    for i in 0..n {
        eligible[i] = !in_cycle[i] && !has_missing[i];
    }
    let mut indeg = vec![0usize; n];
    let mut rdeps: Vec<Vec<usize>> = Vec::new();
    for _ in 0..n {
        rdeps.push(Vec::new());
    }
    for i in 0..n {
        if !eligible[i] {
            continue;
        }
        indeg[i] = deps[i].len();
        for k in deps[i].clone() {
            rdeps[k].push(i);
        }
    }

    let mut built = vec![false; n];
    let mut stage = vec![0usize; n];
    let mut queue: Vec<usize> = Vec::new();
    for i in 0..n {
        if eligible[i] && indeg[i] == 0 {
            built[i] = true;
            stage[i] = 1;
            queue.push(i);
        }
    }
    let mut head: usize = 0;
    while head < queue.len() {
        let u = queue[head];
        head += 1;
        for v in rdeps[u].clone() {
            if stage[u] + 1 > stage[v] {
                stage[v] = stage[u] + 1;
            }
            indeg[v] -= 1;
            if indeg[v] == 0 {
                built[v] = true;
                queue.push(v);
            }
        }
    }
    let built_count = queue.len();

    // Stage lines.
    let mut max_stage: usize = 0;
    for i in 0..n {
        if built[i] && stage[i] > max_stage {
            max_stage = stage[i];
        }
    }
    let mut stage_lines: Vec<Str> = Vec::new();
    for s in 1..max_stage + 1 {
        let mut members: Vec<Str> = Vec::new();
        for i in 0..n {
            if built[i] && stage[i] == s {
                members.push(pkgs[i].clone());
            }
        }
        if !members.is_empty() {
            stage_lines.push(format!("stage {}: {}", s, join(members, ", ".to_string())));
        }
    }

    // Missing lines, sorted by missing name.
    let mut missing_lines: Vec<Str> = Vec::new();
    let mut sorted_missing = missing.clone();
    sorted_missing.sort();
    for m in sorted_missing {
        let idx = index_of(missing.clone(), m.clone()).unwrap();
        missing_lines.push(format!(
            "missing: {} (needed by {})",
            m,
            join(needed[idx].clone(), ", ".to_string())
        ));
    }

    // Blocked: not built and in no cycle.
    let mut blocked: Vec<Str> = Vec::new();
    for i in 0..n {
        if !built[i] && !in_cycle[i] {
            blocked.push(pkgs[i].clone());
        }
    }

    // Assemble output in the required order, omitting empty sections.
    let mut out: Vec<Str> = Vec::new();
    for l in stage_lines {
        out.push(l);
    }
    for l in cycle_lines {
        out.push(l);
    }
    for l in missing_lines {
        out.push(l);
    }
    if !invalid.is_empty() {
        out.push(format!("invalid: {}", join(invalid, ", ".to_string())));
    }
    if !blocked.is_empty() {
        out.push(format!("blocked: {}", join(blocked, ", ".to_string())));
    }
    out.push(format!("built {} of {}", built_count, n));

    join(out, "\n".to_string())
}

// Build stages, cycles and missing dependencies for input/packages.json.

fn is_ws(c: u8) -> bool {
    c == 32 || c == 9 || c == 10 || c == 13
}

fn hexval(c: u8) -> Option<u8> {
    if c >= 48 && c <= 57 {
        Some(c - 48)
    } else if c >= 97 && c <= 102 {
        Some(c - 87)
    } else if c >= 65 && c <= 70 {
        Some(c - 55)
    } else {
        None
    }
}

// Appends the UTF-8 encoding of the code point hi*256 + lo.
fn push_utf8(mut out: Vec<u8>, hi: u8, lo: u8) -> Vec<u8> {
    if hi == 0 && lo < 128 {
        out.push(lo);
    } else if hi < 8 {
        out.push(192 + hi * 4 + lo / 64);
        out.push(128 + lo % 64);
    } else {
        out.push(224 + hi / 16);
        out.push(128 + (hi % 16) * 4 + lo / 64);
        out.push(128 + lo % 64);
    }
    out
}

fn to_str(b: Vec<u8>) -> Str {
    Str::from_utf8(b).unwrap_or("".to_string())
}

fn index_of(v: Vec<Str>, x: Str) -> Option<usize> {
    for k in 0..v.len() {
        if v[k] == x {
            return Some(k);
        }
    }
    None
}

fn has_index(v: Vec<usize>, x: usize) -> bool {
    for k in 0..v.len() {
        if v[k] == x {
            return true;
        }
    }
    false
}

fn join(items: Vec<Str>, sep: Str) -> Str {
    let mut out: Str = "".to_string();
    for k in 0..items.len() {
        if k > 0 {
            out = format!("{}{}", out, sep);
        }
        out = format!("{}{}", out, items[k]);
    }
    out
}

// b[start] must be a quote. Returns the decoded bytes and the index just past the closing quote.
fn read_str(b: Vec<u8>, start: usize) -> Option<(Vec<u8>, usize)> {
    let n = b.len();
    if start >= n || b[start] != 34 {
        return None;
    }
    let mut i = start + 1;
    let mut out: Vec<u8> = Vec::new();
    loop {
        if i >= n {
            return None;
        }
        let c = b[i];
        i += 1;
        if c == 34 {
            return Some((out, i));
        }
        if c != 92 {
            out.push(c);
            continue;
        }
        if i >= n {
            return None;
        }
        let e = b[i];
        i += 1;
        if e == 110 {
            out.push(10);
        } else if e == 116 {
            out.push(9);
        } else if e == 114 {
            out.push(13);
        } else if e == 98 {
            out.push(8);
        } else if e == 102 {
            out.push(12);
        } else if e == 117 {
            if i + 4 > n {
                return None;
            }
            let d1 = hexval(b[i])?;
            let d2 = hexval(b[i + 1])?;
            let d3 = hexval(b[i + 2])?;
            let d4 = hexval(b[i + 3])?;
            i += 4;
            let hi: u8 = d1 * 16 + d2;
            let lo: u8 = d3 * 16 + d4;
            out = push_utf8(out, hi, lo);
        } else {
            out.push(e);
        }
    }
}

// Skips one JSON value starting at start. Returns the index just past it.
fn skip_value(b: Vec<u8>, start: usize) -> Option<usize> {
    let n = b.len();
    let mut i = start;
    let mut depth: usize = 0;
    loop {
        if i >= n {
            return None;
        }
        let c = b[i];
        if c == 34 {
            let (_, j) = read_str(b.clone(), i)?;
            i = j;
        } else if c == 123 || c == 91 {
            depth += 1;
            i += 1;
        } else if c == 125 || c == 93 {
            if depth == 0 {
                break;
            }
            depth -= 1;
            i += 1;
            if depth == 0 {
                return Some(i);
            }
        } else if c == 44 || is_ws(c) {
            if depth == 0 {
                break;
            }
            i += 1;
        } else {
            i += 1;
        }
    }
    if i == start {
        return None;
    }
    Some(i)
}

// Parses the value at start.
// Returns (valid, deps, index after value). valid is true only for an array of strings.
fn value(b: Vec<u8>, start: usize) -> Option<(bool, Vec<Str>, usize)> {
    let n = b.len();
    let mut i = start;
    if i < n && b[i] == 91 {
        i += 1;
        let mut items: Vec<Str> = Vec::new();
        let mut ok = true;
        while i < n && is_ws(b[i]) {
            i += 1;
        }
        if i < n && b[i] == 93 {
            return Some((true, items, i + 1));
        }
        loop {
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            if i < n && b[i] == 34 {
                let (s, j) = read_str(b.clone(), i)?;
                items.push(to_str(s));
                i = j;
            } else {
                i = skip_value(b.clone(), i)?;
                ok = false;
            }
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            if i >= n {
                return None;
            }
            if b[i] == 44 {
                i += 1;
            } else if b[i] == 93 {
                i += 1;
                break;
            } else {
                return None;
            }
        }
        Some((ok, items, i))
    } else {
        let j = skip_value(b.clone(), i)?;
        Some((false, Vec::new(), j))
    }
}

// Returns (key, valid, deps) for each top-level entry, or None if the text is not a JSON object.
fn parse(text: Str) -> Option<Vec<(Str, bool, Vec<Str>)>> {
    let b: Vec<u8> = text.into_bytes();
    let n = b.len();
    let mut i: usize = 0;
    let mut out: Vec<(Str, bool, Vec<Str>)> = Vec::new();
    while i < n && is_ws(b[i]) {
        i += 1;
    }
    if i >= n || b[i] != 123 {
        return None;
    }
    i += 1;
    while i < n && is_ws(b[i]) {
        i += 1;
    }
    if i < n && b[i] == 125 {
        i += 1;
    } else {
        loop {
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            let (k, j) = read_str(b.clone(), i)?;
            i = j;
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            if i >= n || b[i] != 58 {
                return None;
            }
            i += 1;
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            let (ok, deps, j2) = value(b.clone(), i)?;
            i = j2;
            out.push((to_str(k), ok, deps));
            while i < n && is_ws(b[i]) {
                i += 1;
            }
            if i >= n {
                return None;
            }
            if b[i] == 44 {
                i += 1;
            } else if b[i] == 125 {
                i += 1;
                break;
            } else {
                return None;
            }
        }
    }
    while i < n && is_ws(b[i]) {
        i += 1;
    }
    if i != n {
        return None;
    }
    Some(out)
}

fn main(input: Dir) -> Str {
    let text = match input.read("packages.json") {
        Ok(t) => t,
        Err(_) => return "error: not an object".to_string(),
    };
    let entries = match parse(text) {
        Some(e) => e,
        None => return "error: not an object".to_string(),
    };

    // Unique keys; a repeated key takes its last value.
    let mut names: Vec<Str> = Vec::new();
    let mut valid: Vec<bool> = Vec::new();
    let mut rawdeps: Vec<Vec<Str>> = Vec::new();
    for (k, ok, d) in entries {
        match index_of(names.clone(), k.clone()) {
            Some(j) => {
                valid[j] = ok;
                rawdeps[j] = d;
            }
            None => {
                names.push(k);
                valid.push(ok);
                rawdeps.push(d);
            }
        }
    }

    // Valid packages (sorted) and invalid entries (sorted).
    let mut pkgs: Vec<Str> = Vec::new();
    let mut invalid: Vec<Str> = Vec::new();
    for j in 0..names.len() {
        if valid[j] {
            pkgs.push(names[j].clone());
        } else {
            invalid.push(names[j].clone());
        }
    }
    pkgs.sort();
    invalid.sort();
    let n = pkgs.len();

    // Raw dependency lists, in package order.
    let mut raw: Vec<Vec<Str>> = Vec::new();
    for i in 0..n {
        let j = index_of(names.clone(), pkgs[i].clone()).unwrap();
        raw.push(rawdeps[j].clone());
    }

    // Edges among valid packages; anything else is a missing dependency.
    let mut deps: Vec<Vec<usize>> = Vec::new();
    let mut has_missing = vec![false; n];
    let mut missing: Vec<Str> = Vec::new();
    let mut needed: Vec<Vec<Str>> = Vec::new();
    for i in 0..n {
        let mut d: Vec<usize> = Vec::new();
        for dep in raw[i].clone() {
            match index_of(pkgs.clone(), dep.clone()) {
                Some(k) => {
                    if !has_index(d.clone(), k) {
                        d.push(k);
                    }
                }
                None => {
                    has_missing[i] = true;
                    match index_of(missing.clone(), dep.clone()) {
                        Some(m) => {
                            if index_of(needed[m].clone(), pkgs[i].clone()).is_none() {
                                needed[m].push(pkgs[i].clone());
                            }
                        }
                        None => {
                            missing.push(dep.clone());
                            needed.push(vec![pkgs[i].clone()]);
                        }
                    }
                }
            }
        }
        deps.push(d);
    }

    // reach[s][t]: t is reachable from s by a path of at least one edge.
    let mut reach: Vec<Vec<bool>> = Vec::new();
    for s in 0..n {
        let mut seen = vec![false; n];
        let mut stack: Vec<usize> = Vec::new();
        for d in deps[s].clone() {
            if !seen[d] {
                seen[d] = true;
                stack.push(d);
            }
        }
        while let Some(u) = stack.pop() {
            for d in deps[u].clone() {
                if !seen[d] {
                    seen[d] = true;
                    stack.push(d);
                }
            }
        }
        reach.push(seen);
    }
    let mut in_cycle = vec![false; n];
    for i in 0..n {
        in_cycle[i] = reach[i][i];
    }

    // Cycle groups: mutually reachable sets, ordered by first name.
    let mut cycle_lines: Vec<Str> = Vec::new();
    let mut assigned = vec![false; n];
    for i in 0..n {
        if !in_cycle[i] || assigned[i] {
            continue;
        }
        let mut group: Vec<Str> = Vec::new();
        for j in 0..n {
            if reach[i][j] && reach[j][i] {
                assigned[j] = true;
                group.push(pkgs[j].clone());
            }
        }
        cycle_lines.push(format!("cycle: {}", join(group, ", ".to_string())));
    }

    // Kahn's algorithm over packages that are not in a cycle and have no missing deps.
    // Packages downstream of a cycle or a missing name never reach zero in-degree.
    let mut eligible = vec![false; n];
    for i in 0..n {
        eligible[i] = !in_cycle[i] && !has_missing[i];
    }
    let mut indeg = vec![0usize; n];
    let mut rdeps: Vec<Vec<usize>> = Vec::new();
    for _ in 0..n {
        rdeps.push(Vec::new());
    }
    for i in 0..n {
        if !eligible[i] {
            continue;
        }
        indeg[i] = deps[i].len();
        for k in deps[i].clone() {
            rdeps[k].push(i);
        }
    }

    let mut built = vec![false; n];
    let mut stage = vec![0usize; n];
    let mut queue: Vec<usize> = Vec::new();
    for i in 0..n {
        if eligible[i] && indeg[i] == 0 {
            built[i] = true;
            stage[i] = 1;
            queue.push(i);
        }
    }
    let mut head: usize = 0;
    while head < queue.len() {
        let u = queue[head];
        head += 1;
        for v in rdeps[u].clone() {
            if stage[u] + 1 > stage[v] {
                stage[v] = stage[u] + 1;
            }
            indeg[v] -= 1;
            if indeg[v] == 0 {
                built[v] = true;
                queue.push(v);
            }
        }
    }
    let built_count = queue.len();

    // Stage lines.
    let mut max_stage: usize = 0;
    for i in 0..n {
        if built[i] && stage[i] > max_stage {
            max_stage = stage[i];
        }
    }
    let mut stage_lines: Vec<Str> = Vec::new();
    for s in 1..max_stage + 1 {
        let mut members: Vec<Str> = Vec::new();
        for i in 0..n {
            if built[i] && stage[i] == s {
                members.push(pkgs[i].clone());
            }
        }
        if !members.is_empty() {
            stage_lines.push(format!("stage {}: {}", s, join(members, ", ".to_string())));
        }
    }

    // Missing lines, sorted by missing name.
    let mut missing_lines: Vec<Str> = Vec::new();
    let mut sorted_missing = missing.clone();
    sorted_missing.sort();
    for m in sorted_missing {
        let idx = index_of(missing.clone(), m.clone()).unwrap();
        missing_lines.push(format!(
            "missing: {} (needed by {})",
            m,
            join(needed[idx].clone(), ", ".to_string())
        ));
    }

    // Blocked: not built and in no cycle.
    let mut blocked: Vec<Str> = Vec::new();
    for i in 0..n {
        if !built[i] && !in_cycle[i] {
            blocked.push(pkgs[i].clone());
        }
    }

    // Assemble output in the required order, omitting empty sections.
    let mut out: Vec<Str> = Vec::new();
    for l in stage_lines {
        out.push(l);
    }
    for l in cycle_lines {
        out.push(l);
    }
    for l in missing_lines {
        out.push(l);
    }
    if !invalid.is_empty() {
        out.push(format!("invalid: {}", join(invalid, ", ".to_string())));
    }
    if !blocked.is_empty() {
        out.push(format!("blocked: {}", join(blocked, ", ".to_string())));
    }
    out.push(format!("built {} of {}", built_count, n));

    join(out, "\n".to_string())
}

struct Booking {
    room: String,
    day: String,
    start: i64,
    end: i64,
    who: String,
}

struct Conflict {
    start: i64,
    text: String,
}

// Returns minutes since midnight, or -1 if malformed.
fn parse_time(s: &str, allow_end_of_day: bool) -> i64 {
    let b = s.as_bytes();
    if b.len() != 5 || b[2] != b':' {
        return -1;
    }
    let mut i = 0;
    while i < 5 {
        if i != 2 && (b[i] < b'0' || b[i] > b'9') {
            return -1;
        }
        i += 1;
    }
    let h = (b[0] - b'0') as i64 * 10 + (b[1] - b'0') as i64;
    let m = (b[3] - b'0') as i64 * 10 + (b[4] - b'0') as i64;
    if m > 59 {
        return -1;
    }
    if h <= 23 {
        return h * 60 + m;
    }
    if allow_end_of_day && h == 24 && m == 0 {
        return 1440;
    }
    -1
}

fn two(n: i64) -> String {
    if n < 10 {
        format!("0{}", n)
    } else {
        format!("{}", n)
    }
}

fn fmt_time(m: i64) -> String {
    format!("{}:{}", two(m / 60), two(m % 60))
}

fn gap(a: i64, b: i64) -> String {
    format!("{}-{}", fmt_time(a), fmt_time(b))
}

fn join(items: &Vec<String>) -> String {
    let mut s = String::new();
    let mut i = 0;
    while i < items.len() {
        if i > 0 {
            s.push_str(", ");
        }
        s.push_str(&items[i]);
        i += 1;
    }
    s
}

// Sort order: room, day, start, end.
fn booking_before(a: &Booking, b: &Booking) -> bool {
    if a.room != b.room {
        return a.room < b.room;
    }
    if a.day != b.day {
        return a.day < b.day;
    }
    if a.start != b.start {
        return a.start < b.start;
    }
    a.end < b.end
}

fn conflict_before(a: &Conflict, b: &Conflict) -> bool {
    if a.start != b.start {
        return a.start < b.start;
    }
    a.text < b.text
}

fn render_group(bs: &Vec<Booking>, g: usize, h: usize, out: &mut String) {
    // Merged busy intervals (touching intervals merge).
    let mut ms: Vec<i64> = Vec::new();
    let mut me: Vec<i64> = Vec::new();
    let mut k = g;
    while k < h {
        let s = bs[k].start;
        let e = bs[k].end;
        let n = ms.len();
        if n > 0 && s <= me[n - 1] {
            if e > me[n - 1] {
                me[n - 1] = e;
            }
        } else {
            ms.push(s);
            me.push(e);
        }
        k += 1;
    }

    // Free gaps of at least 30 minutes within 09:00-18:00.
    let mut busy: Vec<String> = Vec::new();
    let mut free: Vec<String> = Vec::new();
    let mut cursor: i64 = 540;
    let mut i = 0;
    while i < ms.len() {
        let hi = if ms[i] < 1080 { ms[i] } else { 1080 };
        if hi - cursor >= 30 {
            free.push(gap(cursor, hi));
        }
        if me[i] > cursor {
            cursor = me[i];
        }
        busy.push(gap(ms[i], me[i]));
        i += 1;
    }
    if 1080 - cursor >= 30 {
        free.push(gap(cursor, 1080));
    }

    out.push_str(&format!("{} {}\n", bs[g].room, bs[g].day));
    out.push_str(&format!("  busy {}\n", join(&busy)));
    if free.len() == 0 {
        out.push_str("  free none\n");
    } else {
        out.push_str(&format!("  free {}\n", join(&free)));
    }

    // Conflicts: overlap of at least one minute.
    let mut confs: Vec<Conflict> = Vec::new();
    let mut a_idx = g;
    while a_idx < h {
        let mut b_idx = a_idx + 1;
        while b_idx < h {
            // Sorted by start, so the overlap starts at bs[b_idx].start.
            let os = bs[b_idx].start;
            let oe = if bs[a_idx].end < bs[b_idx].end {
                bs[a_idx].end
            } else {
                bs[b_idx].end
            };
            if oe - os >= 1 {
                let w1 = bs[a_idx].who.clone();
                let w2 = bs[b_idx].who.clone();
                let (x, y) = if w1 <= w2 { (w1, w2) } else { (w2, w1) };
                let text = format!("  conflict {}/{} {}", x, y, gap(os, oe));
                confs.push(Conflict { start: os, text: text });
            }
            b_idx += 1;
        }
        a_idx += 1;
    }

    // Insertion sort by (start, text).
    let mut c = 1;
    while c < confs.len() {
        let mut d = c;
        while d > 0 && conflict_before(&confs[d], &confs[d - 1]) {
            confs.swap(d, d - 1);
            d -= 1;
        }
        c += 1;
    }
    for cf in confs.iter() {
        out.push_str(&format!("{}\n", cf.text));
    }
}

fn main(input: Dir) -> Result<Str, Str> {
    let text = match input.read_to_string("bookings.csv") {
        Ok(t) => t,
        Err(e) => return Err(format!("cannot read bookings.csv: {}", e)),
    };

    let mut bookings: Vec<Booking> = Vec::new();
    let mut skipped: Vec<i64> = Vec::new();
    let mut lineno: i64 = 0;

    for raw in text.lines() {
        lineno += 1;
        if lineno == 1 {
            continue; // header
        }
        if raw.trim().is_empty() {
            continue; // blank lines are ignored
        }
        let f: Vec<&str> = raw.split(',').collect();
        if f.len() != 5 {
            skipped.push(lineno);
            continue;
        }
        let start = parse_time(f[2], false);
        let end = parse_time(f[3], true);
        if start < 0 || end < 0 || end <= start {
            skipped.push(lineno);
            continue;
        }

        // Exact repeat of an earlier booking is ignored (not counted as skipped).
        let mut dup = false;
        for b in bookings.iter() {
            if b.room == f[0] && b.day == f[1] && b.start == start && b.end == end && b.who == f[4] {
                dup = true;
                break;
            }
        }
        if dup {
            continue;
        }

        bookings.push(Booking {
            room: f[0].to_string(),
            day: f[1].to_string(),
            start: start,
            end: end,
            who: f[4].to_string(),
        });
    }

    // Insertion sort by (room, day, start, end).
    let n = bookings.len();
    let mut i = 1;
    while i < n {
        let mut j = i;
        while j > 0 && booking_before(&bookings[j], &bookings[j - 1]) {
            bookings.swap(j, j - 1);
            j -= 1;
        }
        i += 1;
    }

    let mut out = String::new();
    let mut g = 0;
    while g < n {
        let mut h = g + 1;
        while h < n && bookings[h].room == bookings[g].room && bookings[h].day == bookings[g].day {
            h += 1;
        }
        render_group(&bookings, g, h, &mut out);
        g = h;
    }

    if skipped.len() == 0 {
        out.push_str("skipped: none\n");
    } else {
        let mut nums: Vec<String> = Vec::new();
        for s in skipped.iter() {
            nums.push(format!("{}", s));
        }
        out.push_str(&format!("skipped: {}\n", join(&nums)));
    }

    Ok(out)
}

fn parse_time(s: Str, allow_end_of_day: bool) -> i64 {
    let b = s.as_bytes();
    if b.len() != 5 || b[2] != b':' {
        return -1;
    }
    let mut i = 0;
    while i < 5 {
        if i != 2 && (b[i] < b'0' || b[i] > b'9') {
            return -1;
        }
        i += 1;
    }
    let h = (b[0] - b'0') as i64 * 10 + (b[1] - b'0') as i64;
    let m = (b[3] - b'0') as i64 * 10 + (b[4] - b'0') as i64;
    if m > 59 {
        return -1;
    }
    if h <= 23 {
        return h * 60 + m;
    }
    if allow_end_of_day && h == 24 && m == 0 {
        return 1440;
    }
    -1
}

fn two(n: i64) -> Str {
    if n < 10 {
        format!("0{}", n)
    } else {
        format!("{}", n)
    }
}

fn fmt_time(m: i64) -> Str {
    format!("{}:{}", two(m / 60), two(m % 60))
}

fn gap(a: i64, b: i64) -> Str {
    format!("{}-{}", fmt_time(a), fmt_time(b))
}

fn main(input: Dir) -> Result<Str, Str> {
    let text = match input.read_to_string("bookings.csv") {
        Ok(t) => t,
        Err(e) => return Err(format!("cannot read bookings.csv: {}", e)),
    };

    let mut rooms: Vec<Str> = Vec::new();
    let mut days: Vec<Str> = Vec::new();
    let mut starts: Vec<i64> = Vec::new();
    let mut ends: Vec<i64> = Vec::new();
    let mut whos: Vec<Str> = Vec::new();
    let mut skipped: Vec<i64> = Vec::new();
    let mut lineno: i64 = 0;

    for raw in text.lines() {
        lineno += 1;
        if lineno == 1 {
            continue; // header
        }
        if raw.trim().is_empty() {
            continue; // blank lines are ignored
        }
        let f: Vec<Str> = raw.split(',').collect();
        if f.len() != 5 {
            skipped.push(lineno);
            continue;
        }
        let start = parse_time(f[2].to_string(), false);
        let end = parse_time(f[3].to_string(), true);
        if start < 0 || end < 0 || end <= start {
            skipped.push(lineno);
            continue;
        }

        // Exact repeat of an earlier booking is ignored (not counted as skipped).
        let mut dup = false;
        let mut k = 0;
        while k < rooms.len() {
            if !dup
                && rooms[k] == f[0]
                && days[k] == f[1]
                && starts[k] == start
                && ends[k] == end
                && whos[k] == f[4]
            {
                dup = true;
            }
            k += 1;
        }
        if dup {
            continue;
        }

        rooms.push(f[0].to_string());
        days.push(f[1].to_string());
        starts.push(start);
        ends.push(end);
        whos.push(f[4].to_string());
    }

    let n = rooms.len();

    // Order of records: indices sorted by (room, day, start, end).
    let mut ord: Vec<usize> = Vec::new();
    let mut q0 = 0;
    while q0 < n {
        ord.push(q0);
        q0 += 1;
    }
    let mut si = 1;
    while si < n {
        let mut j = si;
        let mut go = true;
        while go && j > 0 {
            let p = ord[j];
            let q = ord[j - 1];
            let lt = if rooms[p] != rooms[q] {
                rooms[p] < rooms[q]
            } else if days[p] != days[q] {
                days[p] < days[q]
            } else if starts[p] != starts[q] {
                starts[p] < starts[q]
            } else {
                ends[p] < ends[q]
            };
            if lt {
                ord.swap(j, j - 1);
                j -= 1;
            } else {
                go = false;
            }
        }
        si += 1;
    }

    let mut out = String::new();
    let mut g = 0;
    while g < n {
        let mut h = g + 1;
        while h < n && rooms[ord[h]] == rooms[ord[g]] && days[ord[h]] == days[ord[g]] {
            h += 1;
        }
        let r = ord[g];
        out.push_str(format!("{} {}\n", rooms[r], days[r]));

        // Merged busy intervals (touching intervals merge).
        let mut ms: Vec<i64> = Vec::new();
        let mut me: Vec<i64> = Vec::new();
        let mut k = g;
        while k < h {
            let s = starts[ord[k]];
            let e = ends[ord[k]];
            let m = ms.len();
            if m > 0 && s <= me[m - 1] {
                if e > me[m - 1] {
                    me[m - 1] = e;
                }
            } else {
                ms.push(s);
                me.push(e);
            }
            k += 1;
        }

        // Free gaps of at least 30 minutes within 09:00-18:00.
        let mut busy = String::new();
        let mut free = String::new();
        let mut nfree = 0;
        let mut cursor: i64 = 540;
        let mut mi = 0;
        while mi < ms.len() {
            let hi = if ms[mi] < 1080 { ms[mi] } else { 1080 };
            if hi - cursor >= 30 {
                if nfree > 0 {
                    free.push_str(", ");
                }
                free.push_str(gap(cursor, hi));
                nfree += 1;
            }
            if me[mi] > cursor {
                cursor = me[mi];
            }
            if mi > 0 {
                busy.push_str(", ");
            }
