        let mut ms: Vec<i64> = Vec::new();
        let mut me: Vec<i64> = Vec::new();
        let mut k = g;
        while k < h {
            let s = starts[ord[k]];
            let e = ends[ord[k]];
            let m = ms.len();
            if m > 0 && s <= me[m - 1] {
                if e > me[m - 1] {
                    me[m - 1] = e;
                }
            } else {
                ms.push(s);
                me.push(e);
            }
            k += 1;
        }

        // Free gaps of at least 30 minutes within 09:00-18:00.
        let mut busy: Str = "".to_str();
        let mut free: Str = "".to_str();
        let mut nfree = 0;
        let mut cursor: i64 = 540;
        let mut mi = 0;
        while mi < ms.len() {
            let hi = if ms[mi] < 1080 { ms[mi] } else { 1080 };
            if hi - cursor >= 30 {
                if nfree > 0 {
                    free = free + ", ".to_str();
                }
                free = free + gap(cursor, hi);
                nfree += 1;
            }
            if me[mi] > cursor {
                cursor = me[mi];
            }
            if mi > 0 {
                busy = busy + ", ".to_str();
            }
            busy = busy + gap(ms[mi], me[mi]);
            mi += 1;
        }
        if 1080 - cursor >= 30 {
            if nfree > 0 {
                free = free + ", ".to_str();
            }
            free = free + gap(cursor, 1080);
            nfree += 1;
        }

        out = out + "  busy ".to_str() + busy + "\n".to_str();
        if nfree == 0 {
            out = out + "  free none\n".to_str();
        } else {
            out = out + "  free ".to_str() + free + "\n".to_str();
        }

        // Conflicts: overlap of at least one minute.
        let mut ctimes: Vec<i64> = Vec::new();
        let mut ctexts: Vec<Str> = Vec::new();
        let mut a = g;
        while a < h {
            let mut b = a + 1;
            while b < h {
                let pa = ord[a];
                let pb = ord[b];
                // Sorted by start, so the overlap starts at the later start.
                let os = starts[pb];
                let oe = if ends[pa] < ends[pb] { ends[pa] } else { ends[pb] };
                if oe - os >= 1 {
                    let w1 = whos[pa].clone();
                    let w2 = whos[pb].clone();
                    let pair: Str = if w1 <= w2 {
                        w1 + "/".to_str() + w2
                    } else {
                        w2 + "/".to_str() + w1
                    };
                    ctimes.push(os);
                    ctexts.push("  conflict ".to_str() + pair + " ".to_str() + gap(os, oe));
                }
                b += 1;
            }
            a += 1;
        }

        // Insertion sort by (start, text).
        let nc = ctimes.len();
        let mut c = 1;
        while c < nc {
            let mut d = c;
            let mut go2 = true;
            while go2 && d > 0 {
                let lt = if ctimes[d] != ctimes[d - 1] {
                    ctimes[d] < ctimes[d - 1]
                } else {
                    ctexts[d] < ctexts[d - 1]
                };
                if lt {
                    ctimes.swap(d, d - 1);
                    ctexts.swap(d, d - 1);
                    d -= 1;
                } else {
                    go2 = false;
                }
            }
            c += 1;
        }
        let mut c2 = 0;
        while c2 < nc {
            out = out + ctexts[c2].clone() + "\n".to_str();
            c2 += 1;
        }

        g = h;
    }

    if skipped.len() == 0 {
        out = out + "skipped: none\n".to_str();
    } else {
        let mut sk: Str = "".to_str();
        let mut q = 0;
        while q < skipped.len() {
            if q > 0 {
                sk = sk + ", ".to_str();
            }
            sk = sk + skipped[q].to_str();
            q += 1;
        }
        out = out + "skipped: ".to_str() + sk + "\n".to_str();
    }

    Ok(out)
}

// Validate JSONL records against a JSON schema.

enum Json {
    Null,
    Bool(bool),
    Num(f64, bool), // value, written without fraction or exponent
    Str(Str),
    Arr(Vec<Json>),
    Obj(Vec<(Str, Json)>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn peek(&self) -> Option<char> {
        if self.pos < self.chars.len() { Some(self.chars[self.pos]) } else { None }
    }

    fn bump(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\r' || c == '\n' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn expect_word(&mut self, w: &str) -> Result<(), Str> {
        for c in w.chars() {
            if self.bump() != Some(c) {
                return Err("bad literal".to_string());
            }
        }
        Ok(())
    }

    fn value(&mut self) -> Result<Json, Str> {
        self.skip_ws();
        match self.peek() {
            None => Err("unexpected end".to_string()),
            Some('{') => self.object(),
            Some('[') => self.array(),
            Some('"') => Ok(Json::Str(self.string()?)),
            Some('t') => {
                self.expect_word("true")?;
                Ok(Json::Bool(true))
            }
            Some('f') => {
                self.expect_word("false")?;
                Ok(Json::Bool(false))
            }
            Some('n') => {
                self.expect_word("null")?;
                Ok(Json::Null)
            }
            Some(c) if c == '-' || c.is_ascii_digit() => self.number(),
            _ => Err("unexpected character".to_string()),
        }
    }

    fn digits(&mut self) -> Result<(), Str> {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                self.pos += 1;
            } else {
                break;
            }
        }
        if self.pos == start {
            Err("expected digit".to_string())
        } else {
            Ok(())
        }
    }

    fn number(&mut self) -> Result<Json, Str> {
        let start = self.pos;
        let mut is_int = true;
        if self.peek() == Some('-') {
            self.pos += 1;
        }
        self.digits()?;
        if self.peek() == Some('.') {
            is_int = false;
            self.pos += 1;
            self.digits()?;
        }
        if self.peek() == Some('e') || self.peek() == Some('E') {
            is_int = false;
            self.pos += 1;
            if self.peek() == Some('+') || self.peek() == Some('-') {
                self.pos += 1;
            }
            self.digits()?;
        }
        let raw: Str = self.chars[start..self.pos].iter().collect();
        match raw.parse::<f64>() {
            Ok(x) => Ok(Json::Num(x, is_int)),
            Err(_) => Err("bad number".to_string()),
        }
    }

    fn hex4(&mut self) -> Result<u32, Str> {
        let mut v: u32 = 0;
        for _ in 0..4 {
            let d = match self.bump() {
                Some(c) => match c.to_digit(16) {
                    Some(d) => d,
                    None => return Err("bad hex escape".to_string()),
                },
                None => return Err("bad hex escape".to_string()),
            };
            v = v * 16 + d;
        }
        Ok(v)
    }

    fn string(&mut self) -> Result<Str, Str> {
        self.pos += 1; // opening quote
        let mut s = Str::new();
        loop {
            let c = match self.bump() {
                Some(c) => c,
                None => return Err("unterminated string".to_string()),
            };
            if c == '"' {
                return Ok(s);
            }
            if c == '\\' {
                let e = match self.bump() {
                    Some(e) => e,
                    None => return Err("bad escape".to_string()),
                };
                match e {
                    '"' => s.push('"'),
                    '\\' => s.push('\\'),
                    '/' => s.push('/'),
                    'b' => s.push('\u{8}'),
                    'f' => s.push('\u{c}'),
                    'n' => s.push('\n'),
                    'r' => s.push('\r'),
                    't' => s.push('\t'),
                    'u' => {
                        let hi = self.hex4()?;
                        let cp = if hi >= 0xD800 && hi <= 0xDBFF {
                            if self.peek() == Some('\\') && self.chars.get(self.pos + 1) == Some(&'u') {
                                self.pos += 2;
                                let lo = self.hex4()?;
                                if lo >= 0xDC00 && lo <= 0xDFFF {
                                    0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00)
                                } else {
                                    return Err("bad surrogate pair".to_string());
                                }
                            } else {
                                return Err("lone surrogate".to_string());
                            }
                        } else {
                            hi
                        };
                        match char::from_u32(cp) {
                            Some(ch) => s.push(ch),
                            None => return Err("bad unicode escape".to_string()),
                        }
                    }
                    _ => return Err("bad escape".to_string()),
                }
            } else if (c as u32) < 0x20 {
                return Err("control character in string".to_string());
            } else {
                s.push(c);
            }
        }
    }

    fn array(&mut self) -> Result<Json, Str> {
        self.pos += 1;
        let mut items: Vec<Json> = Vec::new();
        self.skip_ws();
        if self.peek() == Some(']') {
            self.pos += 1;
            return Ok(Json::Arr(items));
        }
        loop {
            items.push(self.value()?);
            self.skip_ws();
            match self.bump() {
                Some(',') => {}
                Some(']') => return Ok(Json::Arr(items)),
                _ => return Err("expected , or ]".to_string()),
            }
        }
    }

    fn object(&mut self) -> Result<Json, Str> {
        self.pos += 1;
        let mut fields: Vec<(Str, Json)> = Vec::new();
        self.skip_ws();
        if self.peek() == Some('}') {
            self.pos += 1;
            return Ok(Json::Obj(fields));
        }
        loop {
            self.skip_ws();
            if self.peek() != Some('"') {
                return Err("expected key".to_string());
            }
            let key = self.string()?;
            self.skip_ws();
            if self.bump() != Some(':') {
                return Err("expected :".to_string());
            }
            let v = self.value()?;
            fields.push((key, v));
            self.skip_ws();
            match self.bump() {
                Some(',') => {}
                Some('}') => return Ok(Json::Obj(fields)),
                _ => return Err("expected , or }".to_string()),
            }
        }
    }
}

fn parse_json(text: &str) -> Result<Json, Str> {
    let mut p = Parser { chars: text.chars().collect(), pos: 0 };
    let v = p.value()?;
    p.skip_ws();
    if p.pos != p.chars.len() {
        return Err("trailing characters".to_string());
    }
    Ok(v)
}

fn field<'a>(fields: &'a Vec<(Str, Json)>, name: &str) -> Option<&'a Json> {
    for (k, v) in fields.iter() {
        if k == name {
            return Some(v);
        }
    }
    None
}

fn bound(fields: &Vec<(Str, Json)>, name: &str) -> Option<f64> {
    match field(fields, name) {
        Some(Json::Num(n, _)) => Some(*n),
        _ => None,
    }
}

fn fmt_int(x: f64) -> Str {
    format!("{}", x as i64)
}

fn child(path: &str, name: &str) -> Str {
    format!("{}.{}", path, name)
}

fn add(errs: &mut Vec<(Str, Str)>, path: &str, msg: &str) {
    errs.push((path.to_string(), msg.to_string()));
}

fn type_ok(t: &str, v: &Json) -> bool {
    match v {
        Json::Obj(_) => t == "object",
        Json::Arr(_) => t == "array",
        Json::Str(_) => t == "string",
        Json::Num(_, is_int) => t == "number" || (t == "integer" && *is_int),
        Json::Bool(_) => t == "boolean",
        Json::Null => t == "null",
    }
}

fn str_msg(fields: &Vec<(Str, Json)>, s: &Str) -> Option<Str> {
    let len = s.chars().count() as f64;
    if let Some(m) = bound(fields, "min_length") {
        if len < m {
            return Some(format!("shorter than {}", fmt_int(m)));
        }
    }
    if let Some(m) = bound(fields, "max_length") {
        if len > m {
            return Some(format!("longer than {}", fmt_int(m)));
        }
    }
    if let Some(Json::Arr(opts)) = field(fields, "enum") {
        let ok = opts.iter().any(|o| match o {
            Json::Str(x) => x == s,
            _ => false,
        });
        if !ok {
            return Some("not in enum".to_string());
        }
    }
    None
}

fn num_msg(fields: &Vec<(Str, Json)>, n: f64) -> Option<Str> {
    if let Some(m) = bound(fields, "minimum") {
        if n < m {
            return Some(format!("less than {}", fmt_int(m)));
        }
    }
    if let Some(m) = bound(fields, "maximum") {
        if n > m {
            return Some(format!("greater than {}", fmt_int(m)));
        }
    }
    None
}

fn check_object(schema: &Vec<(Str, Json)>, vf: &Vec<(Str, Json)>, path: &str, errs: &mut Vec<(Str, Str)>) {
    if let Some(Json::Arr(req)) = field(schema, "required") {
        for r in req.iter() {
            if let Json::Str(name) = r {
                if field(vf, name).is_none() {
                    add(errs, &child(path, name), "missing required field");
                }
            }
        }
    }

    let empty: Vec<(Str, Json)> = Vec::new();
    let props: &Vec<(Str, Json)> = match field(schema, "properties") {
        Some(Json::Obj(p)) => p,
        _ => &empty,
    };
    let additional_false = match field(schema, "additional") {
        Some(Json::Bool(false)) => true,
        _ => false,
    };

    for (name, val) in vf.iter() {
        match field(props, name) {
            Some(sub) => validate(sub, val, &child(path, name), errs),
            None => {
                if additional_false {
                    add(errs, &child(path, name), "unexpected field");
                }
            }
        }
    }
}

fn validate(schema: &Json, v: &Json, path: &str, errs: &mut Vec<(Str, Str)>) {
    let fields = match schema {
        Json::Obj(f) => f,
        _ => return,
    };
    let t: Str = match field(fields, "type") {
        Some(Json::Str(s)) => s.clone(),
        _ => return,
    };
    if !type_ok(&t, v) {
        add(errs, path, &format!("expected {}", t));
        return;
    }
    match v {
        Json::Obj(vf) => check_object(fields, vf, path, errs),
        Json::Arr(items) => {
            if let Some(m) = bound(fields, "min_items") {
                if (items.len() as f64) < m {
                    add(errs, path, &format!("fewer than {} items", fmt_int(m)));
                }
            }
            if let Some(item_schema) = field(fields, "items") {
                for (i, item) in items.iter().enumerate() {
                    validate(item_schema, item, &format!("{}[{}]", path, i), errs);
                }
            }
        }
        Json::Str(s) => {
            if let Some(msg) = str_msg(fields, s) {
                add(errs, path, &msg);
            }
        }
        Json::Num(n, _) => {
            if let Some(msg) = num_msg(fields, *n) {
                add(errs, path, &msg);
            }
        }
        _ => {}
    }
}

fn is_blank(line: &str) -> bool {
    line.chars().all(|c| c == ' ' || c == '\t' || c == '\r')
}

fn main(input: Dir) -> Result<Str, Str> {
    let schema_text = input.read("schema.json")?;
    let schema = parse_json(&schema_text)?;
    let records = input.read("records.jsonl")?;

    let mut out: Vec<Str> = Vec::new();
    let mut total: i64 = 0;
    let mut valid: i64 = 0;

    for (idx, raw) in records.split('\n').enumerate() {
        let lineno = idx + 1;
        if is_blank(raw) {
            continue;
        }
        total += 1;
        match parse_json(raw) {
            Err(_) => out.push(format!("line {}: invalid JSON", lineno)),
            Ok(v) => {
                let mut errs: Vec<(Str, Str)> = Vec::new();
                validate(&schema, &v, "$", &mut errs);
                if errs.is_empty() {
                    valid += 1;
                    out.push(format!("line {}: ok", lineno));
                } else {
                    errs.sort();
                    for (p, m) in errs.iter() {
                        out.push(format!("line {}: {}: {}", lineno, p, m));
                    }
                }
            }
        }
    }

    out.push(format!("valid {} of {}", valid, total));
    Ok(out.join("\n"))
}

// Validate JSONL records against a JSON schema.

enum Json {
    Null,
    Bool(bool),
    Num(f64, bool), // value, written without fraction or exponent
    Str(Str),
    Arr(Vec<Json>),
    Obj(Vec<Field>),
}

struct Field {
    name: Str,
    value: Json,
}

// Every function takes its text by value and returns the unconsumed rest.

fn drop_chars(s: Str, n: usize) -> Str {
    let r: Str = s.chars().skip(n).collect();
    r
}

fn skip_ws(s: Str) -> Str {
    let mut t: Str = s;
    loop {
        let c = t.chars().next();
        match c {
            Some(x) if x == ' ' || x == '\t' || x == '\r' || x == '\n' => {
                t = drop_chars(t, 1);
            }
            _ => return t,
        }
    }
}

fn expect_word(s: Str, w: Str) -> Result<Str, Str> {
    let n = w.chars().count();
    let head: Str = s.chars().take(n).collect();
    if head == w {
        Ok(drop_chars(s, n))
    } else {
        Err("bad literal".to_string())
    }
}

fn hex4(h: Str) -> Result<u32, Str> {
    let mut v: u32 = 0;
    for c in h.chars() {
        match c.to_digit(16) {
            Some(d) => {
                v = v * 16 + d;
            }
            None => return Err("bad hex escape".to_string()),
        }
    }
    Ok(v)
}

fn parse_string(s: Str) -> Result<(Str, Str), Str> {
    let cs: Vec<char> = s.chars().collect();
    let mut out = Str::new();
    let mut i: usize = 1; // skip opening quote
    loop {
        if i >= cs.len() {
            return Err("unterminated string".to_string());
        }
        let c = cs[i];
        i += 1;
        if c == '"' {
            let rest: Str = cs[i..].iter().collect();
            return Ok((out, rest));
        }
        if c == '\\' {
            if i >= cs.len() {
                return Err("bad escape".to_string());
            }
            let e = cs[i];
            i += 1;
            match e {
                '"' => out.push('"'),
                '\\' => out.push('\\'),
                '/' => out.push('/'),
                'b' => out.push('\u{8}'),
                'f' => out.push('\u{c}'),
                'n' => out.push('\n'),
                'r' => out.push('\r'),
                't' => out.push('\t'),
                'u' => {
                    if i + 4 > cs.len() {
                        return Err("bad hex escape".to_string());
                    }
                    let h1: Str = cs[i..i + 4].iter().collect();
                    let hi = hex4(h1)?;
                    i += 4;
                    let cp: u32 = if hi >= 0xD800 && hi <= 0xDBFF {
                        if i + 6 <= cs.len() && cs[i] == '\\' && cs[i + 1] == 'u' {
                            let h2: Str = cs[i + 2..i + 6].iter().collect();
                            let lo = hex4(h2)?;
                            i += 6;
                            if lo >= 0xDC00 && lo <= 0xDFFF {
                                0x10000 + (hi - 0xD800) * 1024 + (lo - 0xDC00)
                            } else {
                                return Err("bad surrogate pair".to_string());
                            }
                        } else {
                            return Err("lone surrogate".to_string());
                        }
                    } else {
                        hi
                    };
                    match char::from_u32(cp) {
                        Some(ch) => out.push(ch),
                        None => return Err("bad unicode escape".to_string()),
                    }
                }
                _ => return Err("bad escape".to_string()),
            }
        } else if (c as u32) < 0x20 {
            return Err("control character in string".to_string());
        } else {
            out.push(c);
        }
    }
}

fn parse_number(s: Str) -> Result<(Json, Str), Str> {
    let cs: Vec<char> = s.chars().collect();
    let mut i: usize = 0;
    let mut is_int = true;
    if i < cs.len() && cs[i] == '-' {
        i += 1;
    }
    let int_start = i;
    while i < cs.len() && cs[i].is_ascii_digit() {
        i += 1;
    }
    if i == int_start {
        return Err("expected digit".to_string());
    }
    if i < cs.len() && cs[i] == '.' {
        is_int = false;
        i += 1;
        let frac_start = i;
        while i < cs.len() && cs[i].is_ascii_digit() {
            i += 1;
        }
        if i == frac_start {
            return Err("expected digit".to_string());
        }
    }
    if i < cs.len() && (cs[i] == 'e' || cs[i] == 'E') {
        is_int = false;
        i += 1;
        if i < cs.len() && (cs[i] == '+' || cs[i] == '-') {
            i += 1;
        }
        let exp_start = i;
        while i < cs.len() && cs[i].is_ascii_digit() {
            i += 1;
        }
        if i == exp_start {
            return Err("expected digit".to_string());
        }
    }
    let raw: Str = cs[0..i].iter().collect();
    let rest: Str = cs[i..].iter().collect();
    match raw.parse::<f64>() {
        Ok(x) => Ok((Json::Num(x, is_int), rest)),
        Err(_) => Err("bad number".to_string()),
    }
}

fn parse_array(s: Str) -> Result<(Json, Str), Str> {
    let mut items: Vec<Json> = Vec::new();
    let mut t: Str = skip_ws(drop_chars(s, 1));
    let first = t.chars().next();
    if first == Some(']') {
        return Ok((Json::Arr(items), drop_chars(t, 1)));
    }
    loop {
        let (v, r) = parse_value(t)?;
        items.push(v);
        let r2 = skip_ws(r);
        let c = r2.chars().next();
        match c {
            Some(',') => {
                t = drop_chars(r2, 1);
            }
            Some(']') => {
                return Ok((Json::Arr(items), drop_chars(r2, 1)));
            }
            _ => return Err("expected , or ]".to_string()),
        }
    }
}

fn parse_object(s: Str) -> Result<(Json, Str), Str> {
    let mut fields: Vec<Field> = Vec::new();
    let mut t: Str = skip_ws(drop_chars(s, 1));
    let first = t.chars().next();
    if first == Some('}') {
        return Ok((Json::Obj(fields), drop_chars(t, 1)));
    }
    loop {
        let k = t.chars().next();
        if k != Some('"') {
            return Err("expected key".to_string());
        }
        let (key, r1) = parse_string(t)?;
        let r2 = skip_ws(r1);
        let c2 = r2.chars().next();
        if c2 != Some(':') {
            return Err("expected :".to_string());
        }
        let (v, r3) = parse_value(drop_chars(r2, 1))?;
        fields.push(Field { name: key, value: v });
        let r4 = skip_ws(r3);
        let c4 = r4.chars().next();
        match c4 {
            Some(',') => {
                t = skip_ws(drop_chars(r4, 1));
            }
            Some('}') => {
                return Ok((Json::Obj(fields), drop_chars(r4, 1)));
            }
            _ => return Err("expected , or }".to_string()),
        }
    }
}

fn parse_value(s: Str) -> Result<(Json, Str), Str> {
    let t = skip_ws(s);
    let c = t.chars().next();
    match c {
        None => Err("unexpected end".to_string()),
        Some('{') => parse_object(t),
        Some('[') => parse_array(t),
        Some('"') => {
            let (st, rest) = parse_string(t)?;
            Ok((Json::Str(st), rest))
        }
        Some('t') => {
            let r = expect_word(t, "true".to_string())?;
            Ok((Json::Bool(true), r))
        }
        Some('f') => {
            let r = expect_word(t, "false".to_string())?;
            Ok((Json::Bool(false), r))
        }
        Some('n') => {
            let r = expect_word(t, "null".to_string())?;
            Ok((Json::Null, r))
        }
        Some(x) if x == '-' || x.is_ascii_digit() => parse_number(t),
        _ => Err("unexpected character".to_string()),
    }
}

fn parse_json(text: Str) -> Result<Json, Str> {
    let (v, rest) = parse_value(text)?;
    let r = skip_ws(rest);
    let c = r.chars().next();
    match c {
        None => Ok(v),
        Some(_) => Err("trailing characters".to_string()),
    }
}

fn obj_fields(j: Json) -> Vec<Field> {
    match j {
        Json::Obj(f) => f,
        _ => Vec::new(),
    }
}

fn lookup(fields: Vec<Field>, name: Str) -> Option<Json> {
    for f in fields {
        if f.name == name {
            return Some(f.value.clone());
        }
    }
    None
}

fn bound(fields: Vec<Field>, name: Str) -> Option<f64> {
    match lookup(fields, name) {
        Some(Json::Num(n, _)) => Some(n),
        _ => None,
    }
}

fn has_field(vf: Vec<Field>, name: Str) -> bool {
    for f in vf {
        if f.name == name {
            return true;
        }
    }
    false
}

fn fmt_int(x: f64) -> Str {
    format!("{}", x as i64)
}

fn child(path: Str, name: Str) -> Str {
    format!("{}.{}", path, name)
}

fn type_ok(t: Str, v: Json) -> bool {
    match v {
        Json::Obj(_) => t == "object".to_string(),
        Json::Arr(_) => t == "array".to_string(),
        Json::Str(_) => t == "string".to_string(),
        Json::Num(_, is_int) => t == "number".to_string() || (t == "integer".to_string() && is_int),
        Json::Bool(_) => t == "boolean".to_string(),
        Json::Null => t == "null".to_string(),
    }
}

fn enum_has(opts: Vec<Json>, s: Str) -> bool {
    for o in opts {
        match o {
            Json::Str(x) => {
                if x == s {
                    return true;
                }
            }
            _ => {}
        }
    }
    false
}

fn str_issue(fields: Vec<Field>, s: Str) -> Option<Str> {
    let len = s.chars().count() as f64;
    if let Some(m) = bound(fields.clone(), "min_length".to_string()) {
        if len < m {
            return Some(format!("shorter than {}", fmt_int(m)));
        }
    }
    if let Some(m) = bound(fields.clone(), "max_length".to_string()) {
        if len > m {
            return Some(format!("longer than {}", fmt_int(m)));
        }
    }
    if let Some(Json::Arr(opts)) = lookup(fields, "enum".to_string()) {
        if !enum_has(opts, s) {
            return Some("not in enum".to_string());
        }
    }
    None
}

fn num_issue(fields: Vec<Field>, n: f64) -> Option<Str> {
    if let Some(m) = bound(fields.clone(), "minimum".to_string()) {
        if n < m {
            return Some(format!("less than {}", fmt_int(m)));
        }
    }
    if let Some(m) = bound(fields, "maximum".to_string()) {
        if n > m {
            return Some(format!("greater than {}", fmt_int(m)));
        }
    }
    None
}

fn check_object(
    fields: Vec<Field>,
    vf: Vec<Field>,
    path: Str,
    errs: Vec<(Str, Str)>,
) -> Vec<(Str, Str)> {
    let mut errs = errs;

    let req: Vec<Json> = match lookup(fields.clone(), "required".to_string()) {
        Some(Json::Arr(r)) => r,
        _ => Vec::new(),
    };
    for r in req {
        match r {
            Json::Str(name) => {
                if !has_field(vf.clone(), name.clone()) {
                    errs.push((child(path.clone(), name), "missing required field".to_string()));
                }
            }
            _ => {}
        }
    }

    let props: Vec<Field> = match lookup(fields.clone(), "properties".to_string()) {
        Some(j) => obj_fields(j),
        None => Vec::new(),
    };
    let additional_false: bool = match lookup(fields, "additional".to_string()) {
        Some(Json::Bool(b)) => !b,
        _ => false,
    };

    for f in vf {
        let name = f.name.clone();
        let value = f.value.clone();
        match lookup(props.clone(), name.clone()) {
            Some(sub) => {
                errs = validate(obj_fields(sub), value, child(path.clone(), name), errs);
            }
            None => {
                if additional_false {
                    errs.push((child(path.clone(), name), "unexpected field".to_string()));
                }
            }
        }
    }
    errs
}

fn check_array(
    fields: Vec<Field>,
    items: Vec<Json>,
    path: Str,
    errs: Vec<(Str, Str)>,
) -> Vec<(Str, Str)> {
    let mut errs = errs;

    if let Some(m) = bound(fields.clone(), "min_items".to_string()) {
        if (items.len() as f64) < m {
            errs.push((path.clone(), format!("fewer than {} items", fmt_int(m))));
        }
    }

    let sub: Vec<Field> = match lookup(fields, "items".to_string()) {
        Some(j) => obj_fields(j),
        None => Vec::new(),
    };

    let mut i: usize = 0;
    for item in items {
        let p = format!("{}[{}]", path, i);
        errs = validate(sub.clone(), item, p, errs);
        i += 1;
    }
    errs
}

fn validate(
    fields: Vec<Field>,
    v: Json,
    path: Str,
    errs: Vec<(Str, Str)>,
) -> Vec<(Str, Str)> {
    let t: Str = match lookup(fields.clone(), "type".to_string()) {
        Some(Json::Str(x)) => x,
        _ => return errs,
    };
    if !type_ok(t.clone(), v.clone()) {
        let mut e2 = errs;
        let msg = format!("expected {}", t);
        e2.push((path, msg));
        return e2;
    }
    match v {
        Json::Obj(vf) => check_object(fields, vf, path, errs),
        Json::Arr(items) => check_array(fields, items, path, errs),
        Json::Str(s) => match str_issue(fields, s) {
            Some(msg) => {
                let mut e2 = errs;
                e2.push((path, msg));
                e2
            }
            None => errs,
        },
        Json::Num(n, _) => match num_issue(fields, n) {
            Some(msg) => {
                let mut e2 = errs;
                e2.push((path, msg));
                e2
            }
            None => errs,
        },
        _ => errs,
    }
}

fn is_blank(line: Str) -> bool {
    for c in line.chars() {
        if !(c == ' ' || c == '\t' || c == '\r') {
            return false;
        }
    }
    true
}

fn main(input: Dir) -> Result<Str, Str> {
    let schema_text = input.read("schema.json")?;
    let schema_json = parse_json(schema_text)?;
    let schema = obj_fields(schema_json);
    let records = input.read("records.jsonl")?;

    let mut out: Vec<Str> = Vec::new();
    let mut total: i64 = 0;
    let mut valid: i64 = 0;
    let mut lineno: usize = 0;

    for raw in records.split('\n') {
        lineno += 1;
        let line: Str = raw.to_string();
        if is_blank(line.clone()) {
            continue;
        }
        total += 1;
        match parse_json(line) {
            Err(_) => out.push(format!("line {}: invalid JSON", lineno)),
            Ok(v) => {
                let errs = validate(schema.clone(), v, "$".to_string(), Vec::new());
                if errs.is_empty() {
                    valid += 1;
                    out.push(format!("line {}: ok", lineno));
                } else {
                    let mut sorted = errs;
                    sorted.sort();
                    for (p, m) in sorted {
                        out.push(format!("line {}: {}: {}", lineno, p, m));
                    }
                }
            }
        }
    }

    out.push(format!("valid {} of {}", valid, total));
    Ok(out.join("\n"))
}

// Validate JSONL records against a JSON schema.

#[derive(Clone)]
enum Json {
    Null,
    Bool(bool),
    Num(f64, bool), // value, written without fraction or exponent
    Str(Str),
    Arr(Vec<Json>),
    Obj(Vec<Field>),
}

#[derive(Clone)]
struct Field {
    name: Str,
    value: Json,
}

// Every function takes its text by value and returns the unconsumed rest.

fn drop_chars(s: Str, n: usize) -> Str {
    let r: Str = s.chars().skip(n).collect();
    r
}

// First character of s, or "" when s is empty.
fn peek(s: Str) -> Str {
    match s.chars().next() {
        Some(c) => c,
        None => "".to_string(),
    }
}

// Concatenation of cs[a..b].
fn join_range(cs: Vec<Str>, a: usize, b: usize) -> Str {
    let mut out: Str = "".to_string();
    let mut k: usize = a;
    while k < b {
        out = format!("{}{}", out, cs[k].clone());
        k += 1;
    }
    out
}

// Index of the single-character string c within set, or -1.
fn idx_in(set: Str, c: Str) -> i64 {
    let table: Vec<Str> = set.chars().collect();
    let mut k: usize = 0;
    while k < table.len() {
        if table[k] == c {
            return k as i64;
        }
        k += 1;
    }
    -1
}

fn is_digit(c: Str) -> bool {
    idx_in("0123456789".to_string(), c) >= 0
}

fn is_ws(c: Str) -> bool {
    c == " ".to_string() || c == "\t".to_string() || c == "\r".to_string() || c == "\n".to_string()
}

fn skip_ws(s: Str) -> Str {
    let mut t: Str = s;
    loop {
        let c = peek(t.clone());
        if is_ws(c) {
            t = drop_chars(t, 1);
        } else {
            return t;
        }
    }
}

fn expect_word(s: Str, w: Str) -> Result<Str, Str> {
    let n = w.chars().count();
    let head: Str = s.chars().take(n).collect();
    if head == w {
        Ok(drop_chars(s, n))
    } else {
        Err("bad literal".to_string())
    }
}

fn hex_val(c: Str) -> i64 {
    let i = idx_in("0123456789abcdefABCDEF".to_string(), c);
    if i < 0 {
        -1
    } else if i >= 16 {
        i - 6
    } else {
        i
    }
}

fn hex4(h: Str) -> Result<u32, Str> {
    let mut v: u32 = 0;
    let cs: Vec<Str> = h.chars().collect();
    for c in cs {
        let d = hex_val(c);
        if d < 0 {
            return Err("bad hex escape".to_string());
        }
        v = v * 16 + d as u32;
    }
    Ok(v)
}

fn simple_escape(e: Str) -> Option<Str> {
    if e == "\"".to_string() {
        Some("\"".to_string())
    } else if e == "\\".to_string() {
        Some("\\".to_string())
    } else if e == "/".to_string() {
        Some("/".to_string())
    } else if e == "b".to_string() {
        Some("\u{8}".to_string())
    } else if e == "f".to_string() {
        Some("\u{c}".to_string())
    } else if e == "n".to_string() {
        Some("\n".to_string())
    } else if e == "r".to_string() {
        Some("\r".to_string())
    } else if e == "t".to_string() {
        Some("\t".to_string())
    } else {
        None
    }
}

// Text for a decoded code point. ASCII is exact; other code points
// become a one-character placeholder so that lengths stay correct.
fn code_piece(cp: u32) -> Str {
    if cp >= 0x20 && cp <= 0x7e {
        let table = " !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~".to_string();
        let idx = (cp - 0x20) as usize;
        match table.chars().skip(idx).next() {
            Some(c) => c,
            None => "?".to_string(),
        }
    } else {
        "?".to_string()
    }
}

fn is_control(c: Str) -> bool {
    let ctrl = "\u{0}\u{1}\u{2}\u{3}\u{4}\u{5}\u{6}\u{7}\u{8}\u{9}\u{a}\u{b}\u{c}\u{d}\u{e}\u{f}\u{10}\u{11}\u{12}\u{13}\u{14}\u{15}\u{16}\u{17}\u{18}\u{19}\u{1a}\u{1b}\u{1c}\u{1d}\u{1e}\u{1f}".to_string();
    idx_in(ctrl, c) >= 0
}

fn parse_string(s: Str) -> Result<(Str, Str), Str> {
    let cs: Vec<Str> = s.chars().collect();
    let mut out: Str = "".to_string();
    let mut i: usize = 1; // skip opening quote
    loop {
        if i >= cs.len() {
            return Err("unterminated string".to_string());
        }
        let c = cs[i].clone();
        i += 1;
        if c == "\"".to_string() {
            let rest = drop_chars(s, i);
            return Ok((out, rest));
        }
        if c == "\\".to_string() {
            if i >= cs.len() {
                return Err("bad escape".to_string());
            }
            let e = cs[i].clone();
            i += 1;
            if e == "u".to_string() {
                if i + 4 > cs.len() {
                    return Err("bad hex escape".to_string());
                }
                let hi = hex4(join_range(cs.clone(), i, i + 4))?;
                i += 4;
                if hi >= 0xDC00 && hi <= 0xDFFF {
                    return Err("bad unicode escape".to_string());
                }
                let cp: u32 = if hi >= 0xD800 && hi <= 0xDBFF {
                    if i + 6 <= cs.len() && cs[i] == "\\".to_string() && cs[i + 1] == "u".to_string() {
                        let lo = hex4(join_range(cs.clone(), i + 2, i + 6))?;
                        i += 6;
                        if lo >= 0xDC00 && lo <= 0xDFFF {
                            0x10000 + (hi - 0xD800) * 1024 + (lo - 0xDC00)
                        } else {
                            return Err("bad surrogate pair".to_string());
                        }
                    } else {
                        return Err("lone surrogate".to_string());
                    }
                } else {
                    hi
                };
                let piece = code_piece(cp);
                out = format!("{}{}", out, piece);
            } else {
                match simple_escape(e) {
                    Some(p) => {
                        out = format!("{}{}", out, p);
                    }
                    None => return Err("bad escape".to_string()),
                }
            }
        } else if is_control(c.clone()) {
            return Err("control character in string".to_string());
        } else {
            out = format!("{}{}", out, c);
        }
    }
}

fn parse_number(s: Str) -> Result<(Json, Str), Str> {
    let cs: Vec<Str> = s.chars().collect();
    let n = cs.len();
    let mut i: usize = 0;
    let mut is_int = true;
    if i < n && cs[i] == "-".to_string() {
        i += 1;
    }
    let int_start = i;
    while i < n && is_digit(cs[i].clone()) {
        i += 1;
    }
    if i == int_start {
        return Err("expected digit".to_string());
    }
    if i < n && cs[i] == ".".to_string() {
        is_int = false;
        i += 1;
        let frac_start = i;
        while i < n && is_digit(cs[i].clone()) {
            i += 1;
        }
        if i == frac_start {
            return Err("expected digit".to_string());
        }
    }
    if i < n && (cs[i] == "e".to_string() || cs[i] == "E".to_string()) {
        is_int = false;
        i += 1;
        if i < n && (cs[i] == "+".to_string() || cs[i] == "-".to_string()) {
            i += 1;
        }
        let exp_start = i;
        while i < n && is_digit(cs[i].clone()) {
            i += 1;
        }
        if i == exp_start {
            return Err("expected digit".to_string());
        }
    }
    let raw = join_range(cs, 0, i);
    let rest = drop_chars(s, i);
    match raw.parse::<f64>() {
        Ok(x) => Ok((Json::Num(x, is_int), rest)),
        Err(_) => Err("bad number".to_string()),
    }
}

fn parse_array(s: Str) -> Result<(Json, Str), Str> {
    let mut items: Vec<Json> = Vec::new();
    let mut t: Str = skip_ws(drop_chars(s, 1));
    if peek(t.clone()) == "]".to_string() {
        return Ok((Json::Arr(items), drop_chars(t, 1)));
    }
    loop {
        let (v, r) = parse_value(t)?;
        items.push(v);
        let r2 = skip_ws(r);
        let c = peek(r2.clone());
        if c == ",".to_string() {
            t = drop_chars(r2, 1);
        } else if c == "]".to_string() {
            return Ok((Json::Arr(items), drop_chars(r2, 1)));
        } else {
            return Err("expected , or ]".to_string());
        }
    }
}

fn parse_object(s: Str) -> Result<(Json, Str), Str> {
    let mut fields: Vec<Field> = Vec::new();
    let mut t: Str = skip_ws(drop_chars(s, 1));
    if peek(t.clone()) == "}".to_string() {
        return Ok((Json::Obj(fields), drop_chars(t, 1)));
    }
    loop {
        if peek(t.clone()) != "\"".to_string() {
            return Err("expected key".to_string());
        }
        let (key, r1) = parse_string(t)?;
        let r2 = skip_ws(r1);
        if peek(r2.clone()) != ":".to_string() {
            return Err("expected :".to_string());
        }
        let (v, r3) = parse_value(drop_chars(r2, 1))?;
        fields.push(Field { name: key, value: v });
        let r4 = skip_ws(r3);
        let c4 = peek(r4.clone());
        if c4 == ",".to_string() {
            t = skip_ws(drop_chars(r4, 1));
        } else if c4 == "}".to_string() {
            return Ok((Json::Obj(fields), drop_chars(r4, 1)));
        } else {
            return Err("expected , or }".to_string());
        }
    }
}

fn parse_value(s: Str) -> Result<(Json, Str), Str> {
    let t = skip_ws(s);
    let c = peek(t.clone());
    if c == "".to_string() {
        Err("unexpected end".to_string())
    } else if c == "{".to_string() {
        parse_object(t)
    } else if c == "[".to_string() {
        parse_array(t)
    } else if c == "\"".to_string() {
        let (st, rest) = parse_string(t)?;
        Ok((Json::Str(st), rest))
    } else if c == "t".to_string() {
        let r = expect_word(t, "true".to_string())?;
        Ok((Json::Bool(true), r))
    } else if c == "f".to_string() {
        let r = expect_word(t, "false".to_string())?;
        Ok((Json::Bool(false), r))
    } else if c == "n".to_string() {
        let r = expect_word(t, "null".to_string())?;
        Ok((Json::Null, r))
    } else if c == "-".to_string() || is_digit(c.clone()) {
        parse_number(t)
    } else {
        Err("unexpected character".to_string())
    }
}

fn parse_json(text: Str) -> Result<Json, Str> {
    let (v, rest) = parse_value(text)?;
    let r = skip_ws(rest);
    if peek(r) == "".to_string() {
        Ok(v)
    } else {
        Err("trailing characters".to_string())
    }
}

fn obj_fields(j: Json) -> Vec<Field> {
    match j {
        Json::Obj(f) => f,
        _ => Vec::new(),
    }
}

fn lookup(fields: Vec<Field>, name: Str) -> Option<Json> {
    for f in fields {
        if f.name == name {
            return Some(f.value.clone());
        }
    }
    None
}

fn bound(fields: Vec<Field>, name: Str) -> Option<f64> {
    match lookup(fields, name) {
        Some(Json::Num(n, _)) => Some(n),
        _ => None,
    }
}

fn has_field(vf: Vec<Field>, name: Str) -> bool {
    for f in vf {
        if f.name == name {
            return true;
        }
    }
    false
}

fn fmt_int(x: f64) -> Str {
    format!("{}", x as i64)
}

fn child(path: Str, name: Str) -> Str {
    format!("{}.{}", path, name)
}

fn type_ok(t: Str, v: Json) -> bool {
    match v {
        Json::Obj(_) => t == "object".to_string(),
        Json::Arr(_) => t == "array".to_string(),
        Json::Str(_) => t == "string".to_string(),
