}

fn check_object(
    fields: Vec<Field>,
    vf: Vec<Field>,
    path: Str,
    errs: Vec<(Str, Str)>,
) -> Vec<(Str, Str)> {
    let mut errs = errs;

    let req: Vec<Json> = match lookup(fields.clone(), "required".to_string()) {
        Some(Json::Arr(r)) => r,
        _ => Vec::new(),
    };
    for r in req {
        match r {
            Json::Str(name) => {
                if !has_field(vf.clone(), name.clone()) {
                    errs.push((child(path.clone(), name), "missing required field".to_string()));
                }
            }
            _ => {}
        }
    }

    let props: Vec<Field> = match lookup(fields.clone(), "properties".to_string()) {
        Some(j) => obj_fields(j),
        None => Vec::new(),
    };
    let additional_false: bool = match lookup(fields, "additional".to_string()) {
        Some(Json::Bool(b)) => !b,
        _ => false,
    };

    for f in vf {
        let name = f.name.clone();
        let value = f.value.clone();
        match lookup(props.clone(), name.clone()) {
            Some(sub) => {
                errs = validate(obj_fields(sub), value, child(path.clone(), name), errs);
            }
            None => {
                if additional_false {
                    errs.push((child(path.clone(), name), "unexpected field".to_string()));
                }
            }
        }
    }
    errs
}

fn check_array(
    fields: Vec<Field>,
    items: Vec<Json>,
    path: Str,
    errs: Vec<(Str, Str)>,
) -> Vec<(Str, Str)> {
    let mut errs = errs;

    if let Some(m) = bound(fields.clone(), "min_items".to_string()) {
        if (items.len() as f64) < m {
            errs.push((path.clone(), format!("fewer than {} items", fmt_int(m))));
        }
    }

    let sub: Vec<Field> = match lookup(fields, "items".to_string()) {
        Some(j) => obj_fields(j),
        None => Vec::new(),
    };

    let mut i: usize = 0;
    for item in items {
        let p = format!("{}[{}]", path, i);
        errs = validate(sub.clone(), item, p, errs);
        i += 1;
    }
    errs
}

fn validate(
    fields: Vec<Field>,
    v: Json,
    path: Str,
    errs: Vec<(Str, Str)>,
) -> Vec<(Str, Str)> {
    let t: Str = match lookup(fields.clone(), "type".to_string()) {
        Some(Json::Str(x)) => x,
        _ => return errs,
    };
    if !type_ok(t.clone(), v.clone()) {
        let mut e2 = errs;
        let msg = format!("expected {}", t);
        e2.push((path, msg));
        return e2;
    }
    match v {
        Json::Obj(vf) => check_object(fields, vf, path, errs),
        Json::Arr(items) => check_array(fields, items, path, errs),
        Json::Str(s) => match str_issue(fields, s) {
            Some(msg) => {
                let mut e2 = errs;
                e2.push((path, msg));
                e2
            }
            None => errs,
        },
        Json::Num(n, _) => match num_issue(fields, n) {
            Some(msg) => {
                let mut e2 = errs;
                e2.push((path, msg));
                e2
            }
            None => errs,
        },
        _ => errs,
    }
}

fn is_blank(line: Str) -> bool {
    let cs: Vec<Str> = line.chars().collect();
    for c in cs {
        if !(c == " ".to_string() || c == "\t".to_string() || c == "\r".to_string()) {
            return false;
        }
    }
    true
}

// Splits on newlines; the segment after the last newline is included.
fn split_lines(text: Str) -> Vec<Str> {
    let mut lines: Vec<Str> = Vec::new();
    let mut cur: Str = "".to_string();
    for c in text.chars() {
        if c == "\n".to_string() {
            lines.push(cur);
            cur = "".to_string();
        } else {
            cur = format!("{}{}", cur, c);
        }
    }
    lines.push(cur);
    lines
}

fn main(input: Dir) -> Result<Str, Str> {
    let schema_text = input.read("schema.json")?;
    let schema_json = parse_json(schema_text)?;
    let schema = obj_fields(schema_json);
    let records = input.read("records.jsonl")?;

    let mut out: Vec<Str> = Vec::new();
    let mut total: i64 = 0;
    let mut valid: i64 = 0;
    let mut lineno: usize = 0;

    for raw in split_lines(records) {
        lineno += 1;
        if is_blank(raw.clone()) {
            continue;
        }
        total += 1;
        match parse_json(raw) {
            Err(_) => out.push(format!("line {}: invalid JSON", lineno)),
            Ok(v) => {
                let errs = validate(schema.clone(), v, "$".to_string(), Vec::new());
                if errs.is_empty() {
                    valid += 1;
                    out.push(format!("line {}: ok", lineno));
                } else {
                    let mut sorted = errs;
                    sorted.sort();
                    for (p, m) in sorted {
                        out.push(format!("line {}: {}: {}", lineno, p, m));
                    }
                }
            }
        }
    }

    out.push(format!("valid {} of {}", valid, total));
    Ok(out.join("\n"))
}

// Validate JSONL records against a JSON schema.

enum Json {
    Null,
    Bool(bool),
    Num(f64, bool), // value, written without fraction or exponent
    Str(Str),
    Arr(Vec<Json>),
    Obj(Vec<Field>),
}

struct Field {
    name: Str,
    value: Json,
}

// Every function takes its text by value and returns the unconsumed rest.

fn drop_chars(s: Str, n: usize) -> Str {
    let r: Str = s.chars().skip(n).collect();
    r
}

// First character of s, or "" when s is empty.
fn peek(s: Str) -> Str {
    match s.chars().next() {
        Some(c) => c,
        None => "".to_string(),
    }
}

// Concatenation of cs[a..b].
fn join_range(cs: Vec<Str>, a: usize, b: usize) -> Str {
    let mut out: Str = "".to_string();
    let mut k: usize = a;
    while k < b {
        out = format!("{}{}", out, cs[k].clone());
        k += 1;
    }
    out
}

// Index of the single-character string c within set, or -1.
fn idx_in(set: Str, c: Str) -> i64 {
    let table: Vec<Str> = set.chars().collect();
    let mut k: usize = 0;
    while k < table.len() {
        if table[k] == c {
            return k as i64;
        }
        k += 1;
    }
    -1
}

fn is_digit(c: Str) -> bool {
    idx_in("0123456789".to_string(), c) >= 0
}

fn is_ws(c: Str) -> bool {
    c == " ".to_string() || c == "\t".to_string() || c == "\r".to_string() || c == "\n".to_string()
}

fn skip_ws(s: Str) -> Str {
    let mut t: Str = s;
    loop {
        let c = peek(t.clone());
        if is_ws(c) {
            t = drop_chars(t, 1);
        } else {
            return t;
        }
    }
}

fn expect_word(s: Str, w: Str) -> Result<Str, Str> {
    let n = w.chars().count();
    let head: Str = s.chars().take(n).collect();
    if head == w {
        Ok(drop_chars(s, n))
    } else {
        Err("bad literal".to_string())
    }
}

fn hex_val(c: Str) -> i64 {
    let i = idx_in("0123456789abcdefABCDEF".to_string(), c);
    if i < 0 {
        -1
    } else if i >= 16 {
        i - 6
    } else {
        i
    }
}

fn hex4(h: Str) -> Result<u32, Str> {
    let mut v: u32 = 0;
    let cs: Vec<Str> = h.chars().collect();
    for c in cs {
        let d = hex_val(c);
        if d < 0 {
            return Err("bad hex escape".to_string());
        }
        v = v * 16 + d as u32;
    }
    Ok(v)
}

fn simple_escape(e: Str) -> Option<Str> {
    if e == "\"".to_string() {
        Some("\"".to_string())
    } else if e == "\\".to_string() {
        Some("\\".to_string())
    } else if e == "/".to_string() {
        Some("/".to_string())
    } else if e == "b".to_string() {
        Some("\u{8}".to_string())
    } else if e == "f".to_string() {
        Some("\u{c}".to_string())
    } else if e == "n".to_string() {
        Some("\n".to_string())
    } else if e == "r".to_string() {
        Some("\r".to_string())
    } else if e == "t".to_string() {
        Some("\t".to_string())
    } else {
        None
    }
}

// Text for a decoded code point. ASCII is exact; other code points
// become a one-character placeholder so that lengths stay correct.
fn code_piece(cp: u32) -> Str {
    if cp >= 0x20 && cp <= 0x7e {
        let table = " !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~".to_string();
        let idx = (cp - 0x20) as usize;
        match table.chars().skip(idx).next() {
            Some(c) => c,
            None => "?".to_string(),
        }
    } else {
        "?".to_string()
    }
}

fn is_control(c: Str) -> bool {
    let ctrl = "\u{0}\u{1}\u{2}\u{3}\u{4}\u{5}\u{6}\u{7}\u{8}\u{9}\u{a}\u{b}\u{c}\u{d}\u{e}\u{f}\u{10}\u{11}\u{12}\u{13}\u{14}\u{15}\u{16}\u{17}\u{18}\u{19}\u{1a}\u{1b}\u{1c}\u{1d}\u{1e}\u{1f}".to_string();
    idx_in(ctrl, c) >= 0
}

fn parse_string(s: Str) -> Result<(Str, Str), Str> {
    let cs: Vec<Str> = s.chars().collect();
    let mut out: Str = "".to_string();
    let mut i: usize = 1; // skip opening quote
    loop {
        if i >= cs.len() {
            return Err("unterminated string".to_string());
        }
        let c = cs[i].clone();
        i += 1;
        if c == "\"".to_string() {
            let rest = drop_chars(s, i);
            return Ok((out, rest));
        }
        if c == "\\".to_string() {
            if i >= cs.len() {
                return Err("bad escape".to_string());
            }
            let e = cs[i].clone();
            i += 1;
            if e == "u".to_string() {
                if i + 4 > cs.len() {
                    return Err("bad hex escape".to_string());
                }
                let hi = hex4(join_range(cs.clone(), i, i + 4))?;
                i += 4;
                if hi >= 0xDC00 && hi <= 0xDFFF {
                    return Err("bad unicode escape".to_string());
                }
                let cp: u32 = if hi >= 0xD800 && hi <= 0xDBFF {
                    if i + 6 <= cs.len() && cs[i] == "\\".to_string() && cs[i + 1] == "u".to_string() {
                        let lo = hex4(join_range(cs.clone(), i + 2, i + 6))?;
                        i += 6;
                        if lo >= 0xDC00 && lo <= 0xDFFF {
                            0x10000 + (hi - 0xD800) * 1024 + (lo - 0xDC00)
                        } else {
                            return Err("bad surrogate pair".to_string());
                        }
                    } else {
                        return Err("lone surrogate".to_string());
                    }
                } else {
                    hi
                };
                let piece = code_piece(cp);
                out = format!("{}{}", out, piece);
            } else {
                match simple_escape(e) {
                    Some(p) => {
                        out = format!("{}{}", out, p);
                    }
                    None => return Err("bad escape".to_string()),
                }
            }
        } else if is_control(c.clone()) {
            return Err("control character in string".to_string());
        } else {
            out = format!("{}{}", out, c);
        }
    }
}

fn parse_number(s: Str) -> Result<(Json, Str), Str> {
    let cs: Vec<Str> = s.chars().collect();
    let n = cs.len();
    let mut i: usize = 0;
    let mut is_int = true;
    if i < n && cs[i] == "-".to_string() {
        i += 1;
    }
    let int_start = i;
    while i < n && is_digit(cs[i].clone()) {
        i += 1;
    }
    if i == int_start {
        return Err("expected digit".to_string());
    }
    if i < n && cs[i] == ".".to_string() {
        is_int = false;
        i += 1;
        let frac_start = i;
        while i < n && is_digit(cs[i].clone()) {
            i += 1;
        }
        if i == frac_start {
            return Err("expected digit".to_string());
        }
    }
    if i < n && (cs[i] == "e".to_string() || cs[i] == "E".to_string()) {
        is_int = false;
        i += 1;
        if i < n && (cs[i] == "+".to_string() || cs[i] == "-".to_string()) {
            i += 1;
        }
        let exp_start = i;
        while i < n && is_digit(cs[i].clone()) {
            i += 1;
        }
        if i == exp_start {
            return Err("expected digit".to_string());
        }
    }
    let raw = join_range(cs, 0, i);
    let rest = drop_chars(s, i);
    match raw.parse::<f64>() {
        Ok(x) => Ok((Json::Num(x, is_int), rest)),
        Err(_) => Err("bad number".to_string()),
    }
}

fn parse_array(s: Str) -> Result<(Json, Str), Str> {
    let mut items: Vec<Json> = Vec::new();
    let mut t: Str = skip_ws(drop_chars(s, 1));
    if peek(t.clone()) == "]".to_string() {
        return Ok((Json::Arr(items), drop_chars(t, 1)));
    }
    loop {
        let (v, r) = parse_value(t)?;
        items.push(v);
        let r2 = skip_ws(r);
        let c = peek(r2.clone());
        if c == ",".to_string() {
            t = drop_chars(r2, 1);
        } else if c == "]".to_string() {
            return Ok((Json::Arr(items), drop_chars(r2, 1)));
        } else {
            return Err("expected , or ]".to_string());
        }
    }
}

fn parse_object(s: Str) -> Result<(Json, Str), Str> {
    let mut fields: Vec<Field> = Vec::new();
    let mut t: Str = skip_ws(drop_chars(s, 1));
    if peek(t.clone()) == "}".to_string() {
        return Ok((Json::Obj(fields), drop_chars(t, 1)));
    }
    loop {
        if peek(t.clone()) != "\"".to_string() {
            return Err("expected key".to_string());
        }
        let (key, r1) = parse_string(t)?;
        let r2 = skip_ws(r1);
        if peek(r2.clone()) != ":".to_string() {
            return Err("expected :".to_string());
        }
        let (v, r3) = parse_value(drop_chars(r2, 1))?;
        fields.push(Field { name: key, value: v });
        let r4 = skip_ws(r3);
        let c4 = peek(r4.clone());
        if c4 == ",".to_string() {
            t = skip_ws(drop_chars(r4, 1));
        } else if c4 == "}".to_string() {
            return Ok((Json::Obj(fields), drop_chars(r4, 1)));
        } else {
            return Err("expected , or }".to_string());
        }
    }
}

fn parse_value(s: Str) -> Result<(Json, Str), Str> {
    let t = skip_ws(s);
    let c = peek(t.clone());
    if c == "".to_string() {
        Err("unexpected end".to_string())
    } else if c == "{".to_string() {
        parse_object(t)
    } else if c == "[".to_string() {
        parse_array(t)
    } else if c == "\"".to_string() {
        let (st, rest) = parse_string(t)?;
        Ok((Json::Str(st), rest))
    } else if c == "t".to_string() {
        let r = expect_word(t, "true".to_string())?;
        Ok((Json::Bool(true), r))
    } else if c == "f".to_string() {
        let r = expect_word(t, "false".to_string())?;
        Ok((Json::Bool(false), r))
    } else if c == "n".to_string() {
        let r = expect_word(t, "null".to_string())?;
        Ok((Json::Null, r))
    } else if c == "-".to_string() || is_digit(c.clone()) {
        parse_number(t)
    } else {
        Err("unexpected character".to_string())
    }
}

fn parse_json(text: Str) -> Result<Json, Str> {
    let (v, rest) = parse_value(text)?;
    let r = skip_ws(rest);
    if peek(r) == "".to_string() {
        Ok(v)
    } else {
        Err("trailing characters".to_string())
    }
}

fn obj_fields(j: Json) -> Vec<Field> {
    match j {
        Json::Obj(f) => f,
        _ => Vec::new(),
    }
}

fn lookup(fields: Vec<Field>, name: Str) -> Option<Json> {
    for f in fields {
        if f.name == name {
            return Some(f.value.clone());
        }
    }
    None
}

fn bound(fields: Vec<Field>, name: Str) -> Option<f64> {
    match lookup(fields, name) {
        Some(Json::Num(n, _)) => Some(n),
        _ => None,
    }
}

fn has_field(vf: Vec<Field>, name: Str) -> bool {
    for f in vf {
        if f.name == name {
            return true;
        }
    }
    false
}

fn fmt_int(x: f64) -> Str {
    format!("{}", x as i64)
}

fn child(path: Str, name: Str) -> Str {
    format!("{}.{}", path, name)
}

fn type_ok(t: Str, v: Json) -> bool {
    match v {
        Json::Obj(_) => t == "object".to_string(),
        Json::Arr(_) => t == "array".to_string(),
        Json::Str(_) => t == "string".to_string(),
        Json::Num(_, is_int) => t == "number".to_string() || (t == "integer".to_string() && is_int),
        Json::Bool(_) => t == "boolean".to_string(),
        Json::Null => t == "null".to_string(),
    }
}

fn enum_has(opts: Vec<Json>, s: Str) -> bool {
    for o in opts {
        match o {
            Json::Str(x) => {
                if x == s {
                    return true;
                }
            }
            _ => {}
        }
    }
    false
}

fn str_issue(fields: Vec<Field>, s: Str) -> Option<Str> {
    let len = s.chars().count() as f64;
    if let Some(m) = bound(fields.clone(), "min_length".to_string()) {
        if len < m {
            return Some(format!("shorter than {}", fmt_int(m)));
        }
    }
    if let Some(m) = bound(fields.clone(), "max_length".to_string()) {
        if len > m {
            return Some(format!("longer than {}", fmt_int(m)));
        }
    }
    if let Some(Json::Arr(opts)) = lookup(fields, "enum".to_string()) {
        if !enum_has(opts, s) {
            return Some("not in enum".to_string());
        }
    }
    None
}

fn num_issue(fields: Vec<Field>, n: f64) -> Option<Str> {
    if let Some(m) = bound(fields.clone(), "minimum".to_string()) {
        if n < m {
            return Some(format!("less than {}", fmt_int(m)));
        }
    }
    if let Some(m) = bound(fields, "maximum".to_string()) {
        if n > m {
            return Some(format!("greater than {}", fmt_int(m)));
        }
    }
    None
}

fn check_object(
    fields: Vec<Field>,
    vf: Vec<Field>,
    path: Str,
    errs: Vec<(Str, Str)>,
) -> Vec<(Str, Str)> {
    let mut errs = errs;

    let req: Vec<Json> = match lookup(fields.clone(), "required".to_string()) {
        Some(Json::Arr(r)) => r,
        _ => Vec::new(),
    };
    for r in req {
        match r {
            Json::Str(name) => {
                if !has_field(vf.clone(), name.clone()) {
                    errs.push((child(path.clone(), name), "missing required field".to_string()));
                }
            }
            _ => {}
        }
    }

    let props: Vec<Field> = match lookup(fields.clone(), "properties".to_string()) {
        Some(j) => obj_fields(j),
        None => Vec::new(),
    };
    let additional_false: bool = match lookup(fields, "additional".to_string()) {
        Some(Json::Bool(b)) => !b,
        _ => false,
    };

    for f in vf {
        let name = f.name.clone();
        let value = f.value.clone();
        match lookup(props.clone(), name.clone()) {
            Some(sub) => {
                errs = validate(obj_fields(sub), value, child(path.clone(), name), errs);
            }
            None => {
                if additional_false {
                    errs.push((child(path.clone(), name), "unexpected field".to_string()));
                }
            }
        }
    }
    errs
}

fn check_array(
    fields: Vec<Field>,
    items: Vec<Json>,
    path: Str,
    errs: Vec<(Str, Str)>,
) -> Vec<(Str, Str)> {
    let mut errs = errs;

    if let Some(m) = bound(fields.clone(), "min_items".to_string()) {
        if (items.len() as f64) < m {
            errs.push((path.clone(), format!("fewer than {} items", fmt_int(m))));
        }
    }

    let sub: Vec<Field> = match lookup(fields, "items".to_string()) {
        Some(j) => obj_fields(j),
        None => Vec::new(),
    };

    let mut i: usize = 0;
    for item in items {
        let p = format!("{}[{}]", path, i);
        errs = validate(sub.clone(), item, p, errs);
        i += 1;
    }
    errs
}

fn validate(
    fields: Vec<Field>,
    v: Json,
    path: Str,
    errs: Vec<(Str, Str)>,
) -> Vec<(Str, Str)> {
    let t: Str = match lookup(fields.clone(), "type".to_string()) {
        Some(Json::Str(x)) => x,
        _ => return errs,
    };
    if !type_ok(t.clone(), v.clone()) {
        let mut e2 = errs;
        let msg = format!("expected {}", t);
        e2.push((path, msg));
        return e2;
    }
    match v {
        Json::Obj(vf) => check_object(fields, vf, path, errs),
        Json::Arr(items) => check_array(fields, items, path, errs),
        Json::Str(s) => match str_issue(fields, s) {
            Some(msg) => {
                let mut e2 = errs;
                e2.push((path, msg));
                e2
            }
            None => errs,
        },
        Json::Num(n, _) => match num_issue(fields, n) {
            Some(msg) => {
                let mut e2 = errs;
                e2.push((path, msg));
                e2
            }
            None => errs,
        },
        _ => errs,
    }
}

fn is_blank(line: Str) -> bool {
    let cs: Vec<Str> = line.chars().collect();
    for c in cs {
        if !(c == " ".to_string() || c == "\t".to_string() || c == "\r".to_string()) {
            return false;
        }
    }
    true
}

// Splits on newlines; the segment after the last newline is included.
fn split_lines(text: Str) -> Vec<Str> {
    let mut lines: Vec<Str> = Vec::new();
    let mut cur: Str = "".to_string();
    for c in text.chars() {
        if c == "\n".to_string() {
            lines.push(cur);
            cur = "".to_string();
        } else {
            cur = format!("{}{}", cur, c);
        }
    }
    lines.push(cur);
    lines
}

fn main(input: Dir) -> Result<Str, Str> {
    let schema_text = input.read("schema.json")?;
    let schema_json = parse_json(schema_text)?;
    let schema = obj_fields(schema_json);
    let records = input.read("records.jsonl")?;

    let mut out: Vec<Str> = Vec::new();
    let mut total: i64 = 0;
    let mut valid: i64 = 0;
    let mut lineno: usize = 0;

    for raw in split_lines(records) {
        lineno += 1;
        if is_blank(raw.clone()) {
            continue;
        }
        total += 1;
        match parse_json(raw) {
            Err(_) => out.push(format!("line {}: invalid JSON", lineno)),
            Ok(v) => {
                let errs = validate(schema.clone(), v, "$".to_string(), Vec::new());
                if errs.is_empty() {
                    valid += 1;
                    out.push(format!("line {}: ok", lineno));
                } else {
                    let mut sorted = errs;
                    sorted.sort();
                    for (p, m) in sorted {
                        out.push(format!("line {}: {}: {}", lineno, p, m));
                    }
                }
            }
        }
    }

    out.push(format!("valid {} of {}", valid, total));
    Ok(out.join("\n"))
}

// Validate JSONL records against a JSON schema.

enum Json {
    Null,
    Bool(bool),
    Num(f64, bool), // value, written without fraction or exponent
    Str(Str),
    Arr(Vec<Json>),
    Obj(Vec<Field>),
}

struct Field {
    name: Str,
    value: Json,
}

// Every function takes its text by value and returns the unconsumed rest.

fn drop_chars(s: Str, n: usize) -> Str {
    let r: Str = s.chars().skip(n).collect();
    r
}

// First character of s, or "" when s is empty.
fn peek(s: Str) -> Str {
    match s.chars().next() {
        Some(c) => c,
        None => "".to_string(),
    }
}

// Concatenation of cs[a..b].
fn join_range(cs: Vec<Str>, a: usize, b: usize) -> Str {
    let mut out: Str = "".to_string();
    let mut k: usize = a;
    while k < b {
        out = format!("{}{}", out, cs[k].clone());
        k += 1;
    }
    out
}

// Index of the single-character string c within set, or -1.
fn idx_in(set: Str, c: Str) -> i64 {
    let table: Vec<Str> = set.chars().collect();
    let mut k: usize = 0;
    while k < table.len() {
        if table[k] == c {
            return k as i64;
        }
        k += 1;
    }
    -1
}

fn is_digit(c: Str) -> bool {
    idx_in("0123456789".to_string(), c) >= 0
}

fn is_ws(c: Str) -> bool {
    c == " ".to_string() || c == "\t".to_string() || c == "\r".to_string() || c == "\n".to_string()
}

fn skip_ws(s: Str) -> Str {
    let mut t: Str = s;
    loop {
        let c = peek(t.clone());
        if is_ws(c) {
            t = drop_chars(t, 1);
        } else {
            return t;
        }
    }
}

fn expect_word(s: Str, w: Str) -> Result<Str, Str> {
    let n = w.chars().count();
    let head: Str = s.chars().take(n).collect();
    if head == w {
        Ok(drop_chars(s, n))
    } else {
        Err("bad literal".to_string())
    }
}

fn hex_val(c: Str) -> i64 {
    let i = idx_in("0123456789abcdefABCDEF".to_string(), c);
    if i < 0 {
        -1
    } else if i >= 16 {
        i - 6
    } else {
        i
    }
}

fn hex4(h: Str) -> Result<u32, Str> {
    let mut v: u32 = 0;
    let cs: Vec<Str> = h.chars().collect();
    for c in cs {
        let d = hex_val(c);
        if d < 0 {
            return Err("bad hex escape".to_string());
        }
        v = v * 16 + d as u32;
    }
    Ok(v)
}

// Backspace and form feed have no escape in this language, so they
// decode to the same one-character placeholder used for other
// non-printable text. Lengths stay correct.
fn simple_escape(e: Str) -> Option<Str> {
    if e == "\"".to_string() {
        Some("\"".to_string())
    } else if e == "\\".to_string() {
        Some("\\".to_string())
    } else if e == "/".to_string() {
        Some("/".to_string())
    } else if e == "b".to_string() {
        Some("?".to_string())
    } else if e == "f".to_string() {
        Some("?".to_string())
    } else if e == "n".to_string() {
        Some("\n".to_string())
    } else if e == "r".to_string() {
        Some("\r".to_string())
    } else if e == "t".to_string() {
        Some("\t".to_string())
    } else {
        None
    }
}

// Text for a decoded code point. ASCII is exact; other code points
// become a one-character placeholder so that lengths stay correct.
fn code_piece(cp: u32) -> Str {
    if cp >= 0x20 && cp <= 0x7e {
        let table = " !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~".to_string();
        let idx = (cp - 0x20) as usize;
        match table.chars().skip(idx).next() {
            Some(c) => c,
            None => "?".to_string(),
        }
    } else {
        "?".to_string()
    }
}

// True for the single character c when its code point is below 0x20.
// Byte-order comparison of a one-character string against " " does this.
fn is_control(c: Str) -> bool {
    c < " ".to_string()
}

fn parse_string(s: Str) -> Result<(Str, Str), Str> {
    let cs: Vec<Str> = s.chars().collect();
    let mut out: Str = "".to_string();
    let mut i: usize = 1; // skip opening quote
    loop {
        if i >= cs.len() {
            return Err("unterminated string".to_string());
        }
        let c = cs[i].clone();
        i += 1;
        if c == "\"".to_string() {
            let rest = drop_chars(s, i);
            return Ok((out, rest));
        }
        if c == "\\".to_string() {
            if i >= cs.len() {
                return Err("bad escape".to_string());
            }
            let e = cs[i].clone();
            i += 1;
            if e == "u".to_string() {
                if i + 4 > cs.len() {
                    return Err("bad hex escape".to_string());
                }
                let hi = hex4(join_range(cs.clone(), i, i + 4))?;
                i += 4;
                if hi >= 0xDC00 && hi <= 0xDFFF {
                    return Err("bad unicode escape".to_string());
                }
                let cp: u32 = if hi >= 0xD800 && hi <= 0xDBFF {
                    if i + 6 <= cs.len() && cs[i] == "\\".to_string() && cs[i + 1] == "u".to_string() {
                        let lo = hex4(join_range(cs.clone(), i + 2, i + 6))?;
                        i += 6;
                        if lo >= 0xDC00 && lo <= 0xDFFF {
                            0x10000 + (hi - 0xD800) * 1024 + (lo - 0xDC00)
                        } else {
                            return Err("bad surrogate pair".to_string());
                        }
                    } else {
                        return Err("lone surrogate".to_string());
                    }
                } else {
                    hi
                };
                let piece = code_piece(cp);
                out = format!("{}{}", out, piece);
            } else {
                match simple_escape(e) {
                    Some(p) => {
                        out = format!("{}{}", out, p);
                    }
                    None => return Err("bad escape".to_string()),
                }
            }
        } else if is_control(c.clone()) {
            return Err("control character in string".to_string());
        } else {
            out = format!("{}{}", out, c);
        }
    }
}

fn parse_number(s: Str) -> Result<(Json, Str), Str> {
    let cs: Vec<Str> = s.chars().collect();
    let n = cs.len();
    let mut i: usize = 0;
    let mut is_int = true;
    if i < n && cs[i] == "-".to_string() {
        i += 1;
    }
    let int_start = i;
    while i < n && is_digit(cs[i].clone()) {
        i += 1;
    }
    if i == int_start {
        return Err("expected digit".to_string());
    }
    if i < n && cs[i] == ".".to_string() {
        is_int = false;
        i += 1;
        let frac_start = i;
        while i < n && is_digit(cs[i].clone()) {
            i += 1;
        }
        if i == frac_start {
            return Err("expected digit".to_string());
        }
    }
    if i < n && (cs[i] == "e".to_string() || cs[i] == "E".to_string()) {
        is_int = false;
        i += 1;
        if i < n && (cs[i] == "+".to_string() || cs[i] == "-".to_string()) {
            i += 1;
        }
        let exp_start = i;
        while i < n && is_digit(cs[i].clone()) {
            i += 1;
        }
        if i == exp_start {
            return Err("expected digit".to_string());
        }
    }
    let raw = join_range(cs, 0, i);
    let rest = drop_chars(s, i);
    match raw.parse::<f64>() {
        Ok(x) => Ok((Json::Num(x, is_int), rest)),
        Err(_) => Err("bad number".to_string()),
    }
}

fn parse_array(s: Str) -> Result<(Json, Str), Str> {
    let mut items: Vec<Json> = Vec::new();
    let mut t: Str = skip_ws(drop_chars(s, 1));
    if peek(t.clone()) == "]".to_string() {
        return Ok((Json::Arr(items), drop_chars(t, 1)));
    }
    loop {
        let (v, r) = parse_value(t)?;
        items.push(v);
        let r2 = skip_ws(r);
        let c = peek(r2.clone());
        if c == ",".to_string() {
            t = drop_chars(r2, 1);
        } else if c == "]".to_string() {
            return Ok((Json::Arr(items), drop_chars(r2, 1)));
        } else {
            return Err("expected , or ]".to_string());
        }
    }
}

fn parse_object(s: Str) -> Result<(Json, Str), Str> {
    let mut fields: Vec<Field> = Vec::new();
    let mut t: Str = skip_ws(drop_chars(s, 1));
    if peek(t.clone()) == "}".to_string() {
        return Ok((Json::Obj(fields), drop_chars(t, 1)));
    }
    loop {
        if peek(t.clone()) != "\"".to_string() {
            return Err("expected key".to_string());
        }
        let (key, r1) = parse_string(t)?;
        let r2 = skip_ws(r1);
        if peek(r2.clone()) != ":".to_string() {
            return Err("expected :".to_string());
        }
        let (v, r3) = parse_value(drop_chars(r2, 1))?;
        fields.push(Field { name: key, value: v });
        let r4 = skip_ws(r3);
        let c4 = peek(r4.clone());
        if c4 == ",".to_string() {
            t = skip_ws(drop_chars(r4, 1));
        } else if c4 == "}".to_string() {
            return Ok((Json::Obj(fields), drop_chars(r4, 1)));
        } else {
            return Err("expected , or }".to_string());
        }
    }
}

fn parse_value(s: Str) -> Result<(Json, Str), Str> {
    let t = skip_ws(s);
    let c = peek(t.clone());
    if c == "".to_string() {
        Err("unexpected end".to_string())
    } else if c == "{".to_string() {
        parse_object(t)
    } else if c == "[".to_string() {
        parse_array(t)
    } else if c == "\"".to_string() {
        let (st, rest) = parse_string(t)?;
        Ok((Json::Str(st), rest))
    } else if c == "t".to_string() {
        let r = expect_word(t, "true".to_string())?;
        Ok((Json::Bool(true), r))
    } else if c == "f".to_string() {
        let r = expect_word(t, "false".to_string())?;
        Ok((Json::Bool(false), r))
    } else if c == "n".to_string() {
        let r = expect_word(t, "null".to_string())?;
        Ok((Json::Null, r))
    } else if c == "-".to_string() || is_digit(c.clone()) {
        parse_number(t)
    } else {
        Err("unexpected character".to_string())
    }
}

fn parse_json(text: Str) -> Result<Json, Str> {
    let (v, rest) = parse_value(text)?;
    let r = skip_ws(rest);
    if peek(r) == "".to_string() {
        Ok(v)
    } else {
        Err("trailing characters".to_string())
    }
}

fn obj_fields(j: Json) -> Vec<Field> {
    match j {
        Json::Obj(f) => f,
        _ => Vec::new(),
    }
}

fn lookup(fields: Vec<Field>, name: Str) -> Option<Json> {
    for f in fields {
        if f.name == name {
            return Some(f.value.clone());
        }
    }
    None
}

fn bound(fields: Vec<Field>, name: Str) -> Option<f64> {
    match lookup(fields, name) {
        Some(Json::Num(n, _)) => Some(n),
        _ => None,
    }
}

fn has_field(vf: Vec<Field>, name: Str) -> bool {
    for f in vf {
        if f.name == name {
            return true;
        }
    }
    false
}

fn fmt_int(x: f64) -> Str {
    format!("{}", x as i64)
}

fn child(path: Str, name: Str) -> Str {
    format!("{}.{}", path, name)
}

fn type_ok(t: Str, v: Json) -> bool {
    match v {
        Json::Obj(_) => t == "object".to_string(),
        Json::Arr(_) => t == "array".to_string(),
        Json::Str(_) => t == "string".to_string(),
        Json::Num(_, is_int) => t == "number".to_string() || (t == "integer".to_string() && is_int),
        Json::Bool(_) => t == "boolean".to_string(),
        Json::Null => t == "null".to_string(),
    }
}

fn enum_has(opts: Vec<Json>, s: Str) -> bool {
    for o in opts {
        match o {
            Json::Str(x) => {
                if x == s {
                    return true;
                }
            }
            _ => {}
        }
    }
    false
}

fn str_issue(fields: Vec<Field>, s: Str) -> Option<Str> {
    let len = s.chars().count() as f64;
    if let Some(m) = bound(fields.clone(), "min_length".to_string()) {
        if len < m {
            return Some(format!("shorter than {}", fmt_int(m)));
        }
    }
    if let Some(m) = bound(fields.clone(), "max_length".to_string()) {
        if len > m {
            return Some(format!("longer than {}", fmt_int(m)));
        }
    }
    if let Some(Json::Arr(opts)) = lookup(fields, "enum".to_string()) {
        if !enum_has(opts, s) {
            return Some("not in enum".to_string());
        }
    }
    None
}

fn num_issue(fields: Vec<Field>, n: f64) -> Option<Str> {
    if let Some(m) = bound(fields.clone(), "minimum".to_string()) {
        if n < m {
            return Some(format!("less than {}", fmt_int(m)));
        }
    }
    if let Some(m) = bound(fields, "maximum".to_string()) {
        if n > m {
            return Some(format!("greater than {}", fmt_int(m)));
        }
    }
    None
}

fn check_object(
    fields: Vec<Field>,
    vf: Vec<Field>,
    path: Str,
    errs: Vec<(Str, Str)>,
) -> Vec<(Str, Str)> {
    let mut errs = errs;

    let req: Vec<Json> = match lookup(fields.clone(), "required".to_string()) {
        Some(Json::Arr(r)) => r,
        _ => Vec::new(),
    };
    for r in req {
        match r {
            Json::Str(name) => {
                if !has_field(vf.clone(), name.clone()) {
                    errs.push((child(path.clone(), name), "missing required field".to_string()));
                }
            }
            _ => {}
        }
    }

    let props: Vec<Field> = match lookup(fields.clone(), "properties".to_string()) {
        Some(j) => obj_fields(j),
        None => Vec::new(),
    };
    let additional_false: bool = match lookup(fields, "additional".to_string()) {
        Some(Json::Bool(b)) => !b,
        _ => false,
    };

    for f in vf {
        let name = f.name.clone();
        let value = f.value.clone();
        match lookup(props.clone(), name.clone()) {
            Some(sub) => {
                errs = validate(obj_fields(sub), value, child(path.clone(), name), errs);
            }
            None => {
                if additional_false {
                    errs.push((child(path.clone(), name), "unexpected field".to_string()));
                }
            }
        }
    }
    errs
}

fn check_array(
    fields: Vec<Field>,
    items: Vec<Json>,
    path: Str,
    errs: Vec<(Str, Str)>,
) -> Vec<(Str, Str)> {
    let mut errs = errs;

    if let Some(m) = bound(fields.clone(), "min_items".to_string()) {
        if (items.len() as f64) < m {
            errs.push((path.clone(), format!("fewer than {} items", fmt_int(m))));
        }
    }

    let sub: Vec<Field> = match lookup(fields, "items".to_string()) {
        Some(j) => obj_fields(j),
        None => Vec::new(),
    };

    let mut i: usize = 0;
    for item in items {
        let p = format!("{}[{}]", path, i);
        errs = validate(sub.clone(), item, p, errs);
        i += 1;
    }
    errs
}

fn validate(
    fields: Vec<Field>,
    v: Json,
    path: Str,
    errs: Vec<(Str, Str)>,
) -> Vec<(Str, Str)> {
    let t: Str = match lookup(fields.clone(), "type".to_string()) {
        Some(Json::Str(x)) => x,
        _ => return errs,
    };
    if !type_ok(t.clone(), v.clone()) {
        let mut e2 = errs;
        let msg = format!("expected {}", t);
        e2.push((path, msg));
        return e2;
    }
    match v {
        Json::Obj(vf) => check_object(fields, vf, path, errs),
        Json::Arr(items) => check_array(fields, items, path, errs),
        Json::Str(s) => match str_issue(fields, s) {
            Some(msg) => {
                let mut e2 = errs;
                e2.push((path, msg));
                e2
            }
            None => errs,
        },
        Json::Num(n, _) => match num_issue(fields, n) {
            Some(msg) => {
                let mut e2 = errs;
                e2.push((path, msg));
                e2
            }
            None => errs,
        },
        _ => errs,
    }
}

fn is_blank(line: Str) -> bool {
    let cs: Vec<Str> = line.chars().collect();
    for c in cs {
        if !(c == " ".to_string() || c == "\t".to_string() || c == "\r".to_string()) {
            return false;
        }
    }
    true
}

// Splits on newlines; the segment after the last newline is included.
fn split_lines(text: Str) -> Vec<Str> {
    let mut lines: Vec<Str> = Vec::new();
    let mut cur: Str = "".to_string();
    for c in text.chars() {
        if c == "\n".to_string() {
            lines.push(cur);
            cur = "".to_string();
        } else {
            cur = format!("{}{}", cur, c);
        }
    }
    lines.push(cur);
    lines
}

fn main(input: Dir) -> Result<Str, Str> {
    let schema_text = input.read("schema.json")?;
    let schema_json = parse_json(schema_text)?;
    let schema = obj_fields(schema_json);
    let records = input.read("records.jsonl")?;

    let mut out: Vec<Str> = Vec::new();
    let mut total: i64 = 0;
    let mut valid: i64 = 0;
    let mut lineno: usize = 0;

    for raw in split_lines(records) {
        lineno += 1;
        if is_blank(raw.clone()) {
            continue;
        }
        total += 1;
        match parse_json(raw) {
            Err(_) => out.push(format!("line {}: invalid JSON", lineno)),
            Ok(v) => {
                let errs = validate(schema.clone(), v, "$".to_string(), Vec::new());
                if errs.is_empty() {
                    valid += 1;
                    out.push(format!("line {}: ok", lineno));
                } else {
                    let mut sorted = errs;
                    sorted.sort();
                    for (p, m) in sorted {
                        out.push(format!("line {}: {}: {}", lineno, p, m));
                    }
                }
            }
        }
    }

    out.push(format!("valid {} of {}", valid, total));
    Ok(out.join("\n"))
}

use std::collections::BTreeMap;

struct Rec {
    version: i64,
    body: Str,
}

fn push_one(api: &Http, path: &Str, body: &Str) -> (Str, bool) {
    let mut attempts = 0;
    loop {
        attempts += 1;
        let resp = api.put(path, &[("content-type", "application/json")], body);
        match resp {
            Ok(r) => {
                let code = r.status();
                if code >= 200 && code < 300 {
                    return ("synced".to_string(), true);
                } else if code >= 400 && code < 500 {
                    return (format!("rejected {}", code), false);
                } else if code >= 500 && code < 600 {
                    // retry below
                } else {
                    return ("failed".to_string(), false);
                }
            }
            Err(_) => {
                // no response: retry below
            }
        }
        if attempts == 3 {
            return ("failed".to_string(), false);
        }
    }
}

fn main(input: Dir, state: Kv, api: Http) -> Result<Str, Str> {
    let text = input.read("records.jsonl").map_err(|e| format!("cannot read input: {}", e))?;

    let mut invalid: Vec<usize> = Vec::new();
    let mut recs: BTreeMap<Str, Rec> = BTreeMap::new();

    let mut n: usize = 0;
    for raw in text.split('\n') {
        n += 1;
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }
        let mut ok = false;
        if let Ok(v) = json::parse(line) {
            let id = v.get("id").and_then(|x| x.as_str());
            let ver = v.get("version").and_then(|x| x.as_i64());
            if let (Some(id), Some(ver)) = (id, ver) {
                recs.insert(
                    id.to_string(),
                    Rec { version: ver, body: line.to_string() },
                );
                ok = true;
            }
        }
        if !ok {
            invalid.push(n);
        }
    }

    let mut lines: Vec<Str> = Vec::new();
    for l in &invalid {
        lines.push(format!("line {} invalid", l));
    }

    let mut synced = 0;
    let mut unchanged = 0;
    let mut rejected = 0;
    let mut failed = 0;

    // BTreeMap iterates in byte order of the id.
    for (id, rec) in recs.iter() {
        let key = format!("v:{}", id);
        let last: Option<i64> = state.get(&key).and_then(|s| s.parse::<i64>().ok());

        let needs_push = match last {
            Some(prev) => rec.version > prev,
            None => true,
        };

        if !needs_push {
            lines.push(format!("{} unchanged", id));
            unchanged += 1;
            continue;
        }

        let path = format!("/records/{}", id);
        let (outcome, was_synced) = push_one(&api, &path, &rec.body);

        if was_synced {
            state.set(&key, &rec.version.to_string());
            synced += 1;
        } else if outcome == "failed" {
            failed += 1;
        } else {
            rejected += 1;
        }
        lines.push(format!("{} {}", id, outcome));
    }

    lines.push(format!(
        "synced {} unchanged {} rejected {} failed {}",
        synced, unchanged, rejected, failed
    ));

    Ok(lines.join("\n"))
}

use std::collections::BTreeMap;

struct Rec {
    version: i64,
    body: Str,
}

fn main(input: Dir, state: Kv, api: Http) -> Result<Str, Str> {
    let text = input.read("records.jsonl").map_err(|e| format!("cannot read input: {}", e))?;

    let mut invalid: Vec<usize> = Vec::new();
    let mut recs: BTreeMap<Str, Rec> = BTreeMap::new();

    let mut n: usize = 0;
    for raw in text.split('\n') {
        n += 1;
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }
        let mut ok = false;
        if let Ok(v) = json::parse(line) {
            let id = v.get("id").and_then(|x| x.as_str());
            let ver = v.get("version").and_then(|x| x.as_i64());
            if let (Some(id), Some(ver)) = (id, ver) {
                recs.insert(
                    id.to_string(),
                    Rec { version: ver, body: line.to_string() },
                );
                ok = true;
            }
        }
        if !ok {
            invalid.push(n);
        }
    }

    let mut lines: Vec<Str> = Vec::new();
    for l in invalid {
        lines.push(format!("line {} invalid", l));
    }

    let mut synced = 0;
    let mut unchanged = 0;
    let mut rejected = 0;
    let mut failed = 0;

    // BTreeMap iterates in byte order of the id.
    for (id, rec) in recs.iter() {
        let key = format!("v:{}", id);
        let last: Option<i64> = state.get(key.clone()).and_then(|s| s.parse::<i64>().ok());

        let needs_push = match last {
            Some(prev) => rec.version > prev,
            None => true,
