enum Outcome {
    Ok,
    Dup,
    Fail(Str),
}

struct Prior {
    src: Str,
    dst: Str,
    cents: i64,
}

fn fail(m: &str) -> Outcome {
    Outcome::Fail(Str::from(m))
}

fn text(s: &str) -> Arg {
    Arg::Text(Str::from(s))
}

fn int(v: i64) -> Arg {
    Arg::Int(v)
}

// Howard Hinnant's civil-from-days algorithm.
fn civil(z0: i64) -> (i64, i64, i64) {
    let z = z0 + 719468;
    let era = z.div_euclid(146097);
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn fmt_time(ms: i64) -> Str {
    let secs = ms.div_euclid(1000);
    let days = secs.div_euclid(86400);
    let sod = secs.rem_euclid(86400);
    let (y, m, d) = civil(days);
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z",
        y,
        m,
        d,
        sod / 3600,
        (sod % 3600) / 60,
        sod % 60
    )
}

fn balance(db: &Db, name: &str) -> Result<Option<i64>, Str> {
    let rows = db.query(
        "SELECT balance FROM accounts WHERE name = ?1 AND open = 1",
        [text(name)],
    )?;
    Ok(rows.first().map(|r| r.int(0)))
}

fn ever_opened(db: &Db, name: &str) -> Result<bool, Str> {
    let rows = db.query("SELECT 1 FROM accounts WHERE name = ?1", [text(name)])?;
    Ok(!rows.is_empty())
}

fn prior_transfer(db: &Db, id: &str) -> Result<Option<Prior>, Str> {
    let rows = db.query(
        "SELECT src, dst, cents FROM transfers WHERE id = ?1",
        [text(id)],
    )?;
    Ok(rows.first().map(|r| Prior {
        src: r.text(0),
        dst: r.text(1),
        cents: r.int(2),
    }))
}

fn apply(db: &Db, line: &str, now: &str) -> Result<Outcome, Str> {
    let w: Vec<&str> = line.split(' ').collect();
    let kind = w[0];

    if kind == "open" && w.len() == 3 {
        let cents = match w[2].parse::<i64>() {
            Ok(v) => v,
            Err(_) => return Ok(fail("malformed")),
        };
        if cents < 0 {
            return Ok(fail("bad amount"));
        }
        if ever_opened(db, w[1])? {
            return Ok(fail("account exists"));
        }
        db.exec(
            "INSERT INTO accounts (name, balance, open, last) VALUES (?1, ?2, 1, ?3)",
            [text(w[1]), int(cents), text(now)],
        )?;
        return Ok(Outcome::Ok);
    }

    if kind == "transfer" && w.len() == 5 {
        let cents = match w[4].parse::<i64>() {
            Ok(v) => v,
            Err(_) => return Ok(fail("malformed")),
        };
        let (id, from, to) = (w[1], w[2], w[3]);

        if let Some(p) = prior_transfer(db, id)? {
            if p.src == from && p.dst == to && p.cents == cents {
                return Ok(Outcome::Dup);
            }
            return Ok(fail("id reused"));
        }
        if cents <= 0 {
            return Ok(fail("bad amount"));
        }
        if from == to {
            return Ok(fail("same account"));
        }
        let fb = match balance(db, from)? {
            Some(b) => b,
            None => return Ok(fail(&format!("no account {}", from))),
        };
        let tb = match balance(db, to)? {
            Some(b) => b,
            None => return Ok(fail(&format!("no account {}", to))),
        };
        if fb < cents {
            return Ok(fail("insufficient funds"));
        }
        if tb > i64::MAX - cents {
            return Ok(fail("overflow"));
        }

        db.exec("BEGIN", [])?;
        db.exec(
            "UPDATE accounts SET balance = balance - ?1, last = ?2 WHERE name = ?3",
            [int(cents), text(now), text(from)],
        )?;
        db.exec(
            "UPDATE accounts SET balance = balance + ?1, last = ?2 WHERE name = ?3",
            [int(cents), text(now), text(to)],
        )?;
        db.exec(
            "INSERT INTO transfers (id, src, dst, cents) VALUES (?1, ?2, ?3, ?4)",
            [text(id), text(from), text(to), int(cents)],
        )?;
        db.exec("COMMIT", [])?;
        return Ok(Outcome::Ok);
    }

    if kind == "close" && w.len() == 2 {
        let b = match balance(db, w[1])? {
            Some(b) => b,
            None => return Ok(fail(&format!("no account {}", w[1]))),
        };
        if b != 0 {
            return Ok(fail("balance not zero"));
        }
        db.exec(
            "UPDATE accounts SET open = 0 WHERE name = ?1",
            [text(w[1])],
        )?;
        return Ok(Outcome::Ok);
    }

    Ok(fail("malformed"))
}

fn main(input: Dir, db: Db, log: Log, clock: Clock) -> Result<Str, Str> {
    db.exec(
        "CREATE TABLE IF NOT EXISTS accounts (name TEXT PRIMARY KEY, balance INTEGER NOT NULL, open INTEGER NOT NULL, last TEXT NOT NULL)",
        [],
    )?;
    db.exec(
        "CREATE TABLE IF NOT EXISTS transfers (id TEXT PRIMARY KEY, src TEXT NOT NULL, dst TEXT NOT NULL, cents INTEGER NOT NULL)",
        [],
    )?;

    let now = fmt_time(clock.now_ms());
    let body = input.read("ops.txt")?;

    let mut ok = 0;
    let mut failed = 0;
    let mut dup = 0;
    let mut n = 0;

    for raw in body.lines() {
        n += 1;
        let line = raw.trim_end_matches('\r');
        if line.is_empty() {
            continue;
        }
        match apply(&db, line, &now)? {
            Outcome::Ok => ok += 1,
            Outcome::Dup => dup += 1,
            Outcome::Fail(msg) => {
                failed += 1;
                log.append(&format!("{} line {}: {}\n", now, n, msg))?;
            }
        }
    }

    let mut out = format!("ok {} failed {} duplicate {}", ok, failed, dup);
    let rows = db.query(
        "SELECT name, balance, last FROM accounts WHERE open = 1 ORDER BY name",
        [],
    )?;
    for r in rows {
        out.push_str(&format!("\n{} {} last {}", r.text(0), r.int(1), r.text(2)));
    }

    Ok(out)
}

