fn main(input: Dir, db: Db, log: Log, clock: Clock) -> Result<Str, Str> {
    db.exec(
        "CREATE TABLE IF NOT EXISTS accounts (name TEXT PRIMARY KEY, balance INTEGER NOT NULL, open INTEGER NOT NULL, last TEXT NOT NULL)",
        [],
    )?;
    db.exec(
        "CREATE TABLE IF NOT EXISTS transfers (id TEXT PRIMARY KEY, src TEXT NOT NULL, dst TEXT NOT NULL, cents INTEGER NOT NULL)",
        [],
    )?;

    let now = fmt_time(clock.now_ms());
    let body = input.read("ops.txt")?;

    let mut ok = 0;
    let mut failed = 0;
    let mut dup = 0;
    let mut n = 0;

    for raw in body.lines() {
        n += 1;
        let line = raw.trim_end_matches('\r');
        if line.is_empty() {
            continue;
        }
        let w: Vec<Str> = line.split(' ').collect();
        let mut v = Str::from("");

        if w[0] == "open" && w.len() == 3 {
            match w[2].parse::<i64>() {
                Err(_) => v = Str::from("malformed"),
                Ok(cents) => {
                    if cents < 0 {
                        v = Str::from("bad amount");
                    } else {
                        let rows = db.query(
                            "SELECT 1 FROM accounts WHERE name = ?1",
                            [text(w[1])],
                        )?;
                        if !rows.is_empty() {
                            v = Str::from("account exists");
                        } else {
                            db.exec(
                                "INSERT INTO accounts (name, balance, open, last) VALUES (?1, ?2, 1, ?3)",
                                [text(w[1]), int(cents), text(now)],
                            )?;
                            v = Str::from("ok");
                        }
                    }
                }
            }
        } else if w[0] == "transfer" && w.len() == 5 {
            match w[4].parse::<i64>() {
                Err(_) => v = Str::from("malformed"),
                Ok(cents) => {
                    let prior = db.query(
                        "SELECT src, dst, cents FROM transfers WHERE id = ?1",
                        [text(w[1])],
                    )?;
                    match prior.first() {
                        Some(p) => {
                            if p.text(0) == w[2] && p.text(1) == w[3] && p.int(2) == cents {
                                v = Str::from("dup");
                            } else {
                                v = Str::from("id reused");
                            }
                        }
                        None => {
                            if cents <= 0 {
                                v = Str::from("bad amount");
                            } else if w[2] == w[3] {
                                v = Str::from("same account");
                            } else {
                                let fa = db.query(
                                    "SELECT balance FROM accounts WHERE name = ?1 AND open = 1",
                                    [text(w[2])],
                                )?;
                                let ta = db.query(
                                    "SELECT balance FROM accounts WHERE name = ?1 AND open = 1",
                                    [text(w[3])],
                                )?;
                                match fa.first().map(|r| r.int(0)) {
                                    None => v = format!("no account {}", w[2]),
                                    Some(fb) => match ta.first().map(|r| r.int(0)) {
                                        None => v = format!("no account {}", w[3]),
                                        Some(tb) => {
                                            if fb < cents {
                                                v = Str::from("insufficient funds");
                                            } else if tb > i64::MAX - cents {
                                                v = Str::from("overflow");
                                            } else {
                                                db.exec("BEGIN", [])?;
                                                db.exec(
                                                    "UPDATE accounts SET balance = balance - ?1, last = ?2 WHERE name = ?3",
                                                    [int(cents), text(now), text(w[2])],
                                                )?;
                                                db.exec(
                                                    "UPDATE accounts SET balance = balance + ?1, last = ?2 WHERE name = ?3",
                                                    [int(cents), text(now), text(w[3])],
                                                )?;
                                                db.exec(
                                                    "INSERT INTO transfers (id, src, dst, cents) VALUES (?1, ?2, ?3, ?4)",
                                                    [text(w[1]), text(w[2]), text(w[3]), int(cents)],
                                                )?;
                                                db.exec("COMMIT", [])?;
                                                v = Str::from("ok");
                                            }
                                        }
                                    },
                                }
                            }
                        }
                    }
                }
            }
        } else if w[0] == "close" && w.len() == 2 {
            let b = db.query(
                "SELECT balance FROM accounts WHERE name = ?1 AND open = 1",
                [text(w[1])],
            )?;
            match b.first().map(|r| r.int(0)) {
                None => v = format!("no account {}", w[1]),
                Some(bal) => {
                    if bal != 0 {
                        v = Str::from("balance not zero");
                    } else {
                        db.exec(
                            "UPDATE accounts SET open = 0 WHERE name = ?1",
                            [text(w[1])],
                        )?;
                        v = Str::from("ok");
                    }
                }
