                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }

        let mut a = h[0];
        let mut b = h[1];
        let mut c = h[2];
        let mut d = h[3];
        let mut e = h[4];
        let mut f = h[5];
        let mut g = h[6];
        let mut hh = h[7];

        for i in 0..64 {
            let s1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
            let ch = (e & f) ^ (!e & g);
            let t1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(K[i])
                .wrapping_add(w[i]);
            let s0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let t2 = s0.wrapping_add(maj);
            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }

        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);

        block += 64;
    }

    let mut out: Vec<u8> = Vec::new();
    for x in h.iter() {
        let v = *x;
        for i in (0..4).rev() {
            out.push((v >> (i * 8)) as u8);
        }
    }
    out
}

fn hex(bytes: &[u8]) -> Str {
    let digits = "0123456789abcdef".as_bytes();
    let mut s = String::new();
    for b in bytes {
        let v = *b;
        s.push(digits[(v >> 4) as usize] as char);
        s.push(digits[(v & 15) as usize] as char);
    }
    s
}

fn hash_pw(salt: &str, pw: &str) -> Str {
    let mut data: Vec<u8> = salt.as_bytes().to_vec();
    data.extend_from_slice(pw.as_bytes());
    hex(&sha256(&data))
}

fn valid_name(s: &str) -> bool {
    let b = s.as_bytes();
    if b.len() < 3 || b.len() > 20 {
        return false;
    }
    b.iter()
        .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || *c == b'_')
}

fn err(msg: &str) -> Str {
    format!("{{\"error\":\"{}\"}}", msg)
}

fn creds(body: &str) -> Option<(Str, Str)> {
    let j = json::parse(body)?;
    let name = j.get("name")?.as_str()?;
    let pw = j.get("password")?.as_str()?;
    Some((name, pw))
}

fn get_num(store: &Kv, key: &str) -> u64 {
    match store.get(key) {
        Some(s) => s.parse::<u64>().unwrap_or(0),
        None => 0,
    }
}

fn session(store: &Kv, clock: &Clock, auth: Option<Str>) -> Option<(Str, Str)> {
    let h = auth?;
    let token: Str = h.strip_prefix("Bearer ")?.to_string();
    let name = store.get(&format!("sess:{}", token))?;
    let exp = get_num(store, &format!("sexp:{}", token));
    if clock.now() < exp {
        Some((token, name))
    } else {
        None
    }
}

fn register(store: &Kv, rng: &Rng, body: &str) -> (u16, Str) {
    let (name, pw) = match creds(body) {
        Some(x) => x,
        None => return (400, err("invalid")),
    };
    if !valid_name(&name) || pw.len() < 8 {
        return (400, err("invalid"));
    }
    let key = format!("pw:{}", name);
    if store.get(&key).is_some() {
        return (409, err("name taken"));
    }
    let salt = hex(&rng.bytes(16));
    let h = hash_pw(&salt, &pw);
    store.set(&key, &format!("{}:{}", salt, h));
    (201, format!("{{\"name\":\"{}\"}}", name))
}

fn login(store: &Kv, clock: &Clock, rng: &Rng, body: &str) -> (u16, Str) {
    let now = clock.now();
    let (name, pw) = match creds(body) {
        Some(x) => x,
        None => return (401, err("bad credentials")),
    };
    if !valid_name(&name) {
        return (401, err("bad credentials"));
    }
    let pwkey = format!("pw:{}", name);
    let stored = match store.get(&pwkey) {
        Some(s) => s,
        None => return (401, err("bad credentials")),
    };

    let lockkey = format!("lock:{}", name);
    if now < get_num(store, &lockkey) {
        return (429, err("locked"));
    }

    let failkey = format!("fails:{}", name);
    let logkey = format!("logins:{}", name);

    let parts: Vec<&str> = stored.split(':').collect();
    let ok = parts.len() == 2 && hash_pw(parts[0], &pw) == parts[1];
    if !ok {
        let fails = get_num(store, &failkey) + 1;
        if fails >= 3 {
            store.set(&lockkey, &(now + LOCK_MS).to_string());
            store.set(&failkey, "0");
        } else {
            store.set(&failkey, &fails.to_string());
        }
        return (401, err("bad credentials"));
    }

    store.set(&failkey, "0");
    let logins = get_num(store, &logkey) + 1;
    store.set(&logkey, &logins.to_string());

    let token = hex(&rng.bytes(16));
    store.set(&format!("sess:{}", token), &name);
    store.set(&format!("sexp:{}", token), &(now + SESSION_MS).to_string());
    (200, format!("{{\"token\":\"{}\",\"expires_in\":1800}}", token))
}

fn me(store: &Kv, clock: &Clock, auth: Option<Str>) -> (u16, Str) {
    match session(store, clock, auth) {
        None => (401, err("unauthorized")),
        Some((token, name)) => {
            store.set(
                &format!("sexp:{}", token),
                &(clock.now() + SESSION_MS).to_string(),
            );
            let n = get_num(store, &format!("logins:{}", name));
            (200, format!("{{\"name\":\"{}\",\"logins\":{}}}", name, n))
        }
    }
}

fn logout(store: &Kv, clock: &Clock, auth: Option<Str>) -> (u16, Str) {
    match session(store, clock, auth) {
        None => (401, err("unauthorized")),
        Some((token, _name)) => {
            store.remove(&format!("sess:{}", token));
            store.remove(&format!("sexp:{}", token));
            (204, Str::new())
        }
    }
}

fn route(
    store: &Kv,
    clock: &Clock,
    rng: &Rng,
    method: &str,
    path: &str,
    auth: Option<Str>,
    body: &str,
) -> (u16, Str) {
    if method == "POST" && path == "/users" {
        return register(store, rng, body);
    }
    if method == "POST" && path == "/login" {
        return login(store, clock, rng, body);
    }
    if method == "GET" && path == "/me" {
        return me(store, clock, auth);
    }
    if method == "POST" && path == "/logout" {
        return logout(store, clock, auth);
    }
    (404, err("not found"))
}

fn main(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Result<Str, Str> {
    let method = req.method();
    let path = req.path();
    let auth = req.header("authorization");
    let body = req.body();

    let (status, out) = route(&store, &clock, &rng, &method, &path, auth, &body);

    if status == 204 {
        res.send(204, "", "");
    } else {
        res.send(status, "application/json", &out);
    }

    Ok(format!("{} {} {}", method, path, status))
}

