fn rotr(x: u32, n: u32) -> u32 {
    x.rotate_right(n)
}

fn sha256(data: Vec<u8>) -> Vec<u8> {
    let mut h: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
    ];
    let bit_len: u64 = (data.len() as u64) * 8;
    let mut msg: Vec<u8> = data;
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0);
    }
    for i in (0..8).rev() {
        msg.push((bit_len >> (i * 8)) as u8);
    }

    let mut block = 0;
    while block < msg.len() {
        let mut w = [0u32; 64];
        for i in 0..16 {
            let p = block + i * 4;
            w[i] = ((msg[p] as u32) << 24)
                | ((msg[p + 1] as u32) << 16)
                | ((msg[p + 2] as u32) << 8)
                | (msg[p + 3] as u32);
        }
        for i in 16..64 {
            let s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >> 3);
            let s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16]
                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }

        let mut a = h[0];
        let mut b = h[1];
        let mut c = h[2];
        let mut d = h[3];
        let mut e = h[4];
        let mut f = h[5];
        let mut g = h[6];
        let mut hh = h[7];

        for i in 0..64 {
            let s1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
            let ch = (e & f) ^ (!e & g);
            let t1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(K[i])
                .wrapping_add(w[i]);
            let s0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let t2 = s0.wrapping_add(maj);
            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }

        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);

        block += 64;
    }

    let mut out: Vec<u8> = Vec::new();
    for i in 0..8 {
        let v = h[i];
        for j in (0..4).rev() {
