}

fn hex(bytes: Vec<u8>) -> Str {
    let digits = "0123456789abcdef".as_bytes().to_vec();
    let mut s = String::new();
    for b in bytes {
        let v = b;
        s.push(digits[(v >> 4) as usize] as char);
        s.push(digits[(v & 15) as usize] as char);
    }
    s
}

fn hash_pw(salt: Str, pw: Str) -> Str {
    let data = format!("{}{}", salt, pw);
    hex(sha256(data.as_bytes().to_vec()))
}

fn valid_name(s: Str) -> bool {
    let b: Vec<u8> = s.as_bytes().to_vec();
    if b.len() < 3 || b.len() > 20 {
        return false;
    }
    for c in b {
        let ok = (c >= b'a' && c <= b'z') || (c >= b'0' && c <= b'9') || c == b'_';
        if !ok {
            return false;
        }
    }
    true
}

fn err(msg: Str) -> Str {
    format!("{{\"error\":\"{}\"}}", msg)
}

fn creds(body: Str) -> Option<(Str, Str)> {
    let j = json::parse(body)?;
    let name = j.get("name")?.as_str()?;
    let pw = j.get("password")?.as_str()?;
    Some((name, pw))
}

fn num_of(v: Option<Str>) -> u64 {
    match v {
        Some(s) => s.parse::<u64>().unwrap_or(0),
        None => 0,
    }
}

fn bearer(auth: Option<Str>) -> Str {
    match auth {
        None => String::new(),
        Some(h) => match h.strip_prefix("Bearer ") {
            Some(t) => t.to_string(),
            None => String::new(),
        },
    }
}

fn main(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Result<Str, Str> {
    let method = req.method();
    let path = req.path();
    let body = req.body();
    let now: u64 = clock.now();

    let tok = bearer(req.header("authorization"));
    let sname = store.get(format!("sess:{}", tok.clone()));
    let sexp = num_of(store.get(format!("sexp:{}", tok.clone())));
    let authed = sname.is_some() && now < sexp;
    let user: Str = match sname {
        Some(n) => n,
        None => String::new(),
    };

    let mut status: u16 = 404;
    let mut out: Str = err("not found");
    let mut empty = false;

    if method == "POST" && path == "/users" {
        match creds(body) {
            None => {
                status = 400;
                out = err("invalid");
            }
            Some((name, pw)) => {
                if !valid_name(name.clone()) || pw.len() < 8 {
                    status = 400;
                    out = err("invalid");
                } else if store.get(format!("pw:{}", name.clone())).is_some() {
                    status = 409;
                    out = err("name taken");
                } else {
                    let salt = hex(rng.bytes(16));
                    let h = hash_pw(salt.clone(), pw);
                    store.set(format!("pw:{}", name.clone()), h);
                    store.set(format!("salt:{}", name.clone()), salt);
                    status = 201;
                    out = format!("{{\"name\":\"{}\"}}", name);
                }
            }
        }
    } else if method == "POST" && path == "/login" {
        match creds(body) {
            None => {
                status = 401;
                out = err("bad credentials");
            }
            Some((name, pw)) => match store.get(format!("pw:{}", name.clone())) {
                None => {
                    status = 401;
                    out = err("bad credentials");
                }
                Some(want) => {
                    let lock_until = num_of(store.get(format!("lock:{}", name.clone())));
                    if now < lock_until {
                        status = 429;
                        out = err("locked");
                    } else {
                        let salt = match store.get(format!("salt:{}", name.clone())) {
                            Some(s) => s,
                            None => String::new(),
                        };
                        let fails = num_of(store.get(format!("fails:{}", name.clone())));
                        if hash_pw(salt, pw) == want {
                            store.set(format!("fails:{}", name.clone()), "0".to_string());
                            let logins = num_of(store.get(format!("logins:{}", name.clone()))) + 1;
                            store.set(format!("logins:{}", name.clone()), logins.to_string());

                            let token = hex(rng.bytes(16));
                            store.set(format!("sess:{}", token.clone()), name.clone());
                            store.set(
                                format!("sexp:{}", token.clone()),
                                (now + SESSION_MS).to_string(),
                            );
                            status = 200;
                            out = format!(
                                "{{\"token\":\"{}\",\"expires_in\":1800}}",
                                token
                            );
                        } else {
                            let f = fails + 1;
                            if f >= 3 {
                                store.set(
                                    format!("lock:{}", name.clone()),
                                    (now + LOCK_MS).to_string(),
                                );
                                store.set(format!("fails:{}", name.clone()), "0".to_string());
                            } else {
                                store.set(format!("fails:{}", name.clone()), f.to_string());
                            }
                            status = 401;
                            out = err("bad credentials");
                        }
                    }
                }
            },
        }
    } else if method == "GET" && path == "/me" {
        if authed {
            store.set(
                format!("sexp:{}", tok.clone()),
                (now + SESSION_MS).to_string(),
            );
            let n = num_of(store.get(format!("logins:{}", user.clone())));
            status = 200;
            out = format!("{{\"name\":\"{}\",\"logins\":{}}}", user, n);
        } else {
            status = 401;
            out = err("unauthorized");
        }
    } else if method == "POST" && path == "/logout" {
        if authed {
            store.remove(format!("sess:{}", tok.clone()));
            store.remove(format!("sexp:{}", tok.clone()));
            status = 204;
            empty = true;
        } else {
            status = 401;
            out = err("unauthorized");
        }
    }

    if empty {
        res.send(204, "", "");
    } else {
        res.send(status, "application/json", out);
    }

    Ok(format!("{} {} {}", method, path, status))
}

