const M: u64 = 4294967296;
const SESSION_MS: u64 = 1800000;
const LOCK_MS: u64 = 900000;

fn add(a: u64, b: u64) -> u64 {
    (a + b) % M
}

fn pow2(n: u64) -> u64 {
    let mut p: u64 = 1;
    let mut i: u64 = 0;
    while i < n {
        p = p * 2;
        i = i + 1;
    }
    p
}

fn rotr(x: u64, n: u64) -> u64 {
    (x / pow2(n)) + (x * pow2(32 - n)) % M
}

fn bxor(a: u64, b: u64) -> u64 {
    let mut r: u64 = 0;
    let mut p: u64 = 1;
    let mut i: u64 = 0;
    while i < 32 {
        if (a / p) % 2 != (b / p) % 2 {
            r = r + p;
        }
        p = p * 2;
        i = i + 1;
    }
    r
}

fn band(a: u64, b: u64) -> u64 {
    let mut r: u64 = 0;
    let mut p: u64 = 1;
    let mut i: u64 = 0;
    while i < 32 {
        if (a / p) % 2 == 1 && (b / p) % 2 == 1 {
            r = r + p;
        }
        p = p * 2;
        i = i + 1;
    }
    r
}

fn bnot(x: u64) -> u64 {
    4294967295 - x
}

fn sha256(data: Vec<u8>) -> Vec<u8> {
