            let maj = bxor(bxor(band(a, b), band(a, c)), band(b, c));
            let t2 = add(s0, maj);
            hh = g;
            g = f;
            f = e;
            e = add(d, t1);
            d = c;
            c = b;
            b = a;
            a = add(t1, t2);
        }

        h[0] = add(h[0], a);
        h[1] = add(h[1], b);
        h[2] = add(h[2], c);
        h[3] = add(h[3], d);
        h[4] = add(h[4], e);
        h[5] = add(h[5], f);
        h[6] = add(h[6], g);
        h[7] = add(h[7], hh);

        block += 64;
    }

    let mut out: Vec<u8> = Vec::new();
    for i in 0..8 {
        let v = h[i];
        for j in (0..4).rev() {
            out.push(((v / pow2(j * 8)) % 256) as u8);
        }
    }
    out
}

fn hex(bytes: Vec<u8>) -> Str {
    let digits = "0123456789abcdef".as_bytes().to_vec();
    let mut s = String::new();
    for b in bytes {
        let v = b;
        s.push(digits[(v / 16) as usize] as char);
        s.push(digits[(v % 16) as usize] as char);
    }
    s
}

