const M: u64 = 4294967296;
const SESSION_MS: u64 = 1800000;
const LOCK_MS: u64 = 900000;

fn add(a: u64, b: u64) -> u64 {
    (a + b) % M
}

fn pow2(n: u64) -> u64 {
    let mut p: u64 = 1;
    let mut i: u64 = 0;
    while i < n {
        p = p * 2;
        i = i + 1;
    }
    p
}

fn rotr(x: u64, n: u64) -> u64 {
    (x / pow2(n)) + (x * pow2(32 - n)) % M
}

fn bxor(a: u64, b: u64) -> u64 {
    let mut r: u64 = 0;
    let mut p: u64 = 1;
    let mut i: u64 = 0;
    while i < 32 {
        if (a / p) % 2 != (b / p) % 2 {
            r = r + p;
        }
        p = p * 2;
        i = i + 1;
    }
    r
}

fn band(a: u64, b: u64) -> u64 {
    let mut r: u64 = 0;
    let mut p: u64 = 1;
    let mut i: u64 = 0;
    while i < 32 {
        if (a / p) % 2 == 1 && (b / p) % 2 == 1 {
            r = r + p;
        }
        p = p * 2;
        i = i + 1;
    }
    r
}

fn bnot(x: u64) -> u64 {
    4294967295 - x
}

fn sha256(data: Vec<u8>) -> Vec<u8> {
    let mut h: [u64; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
    ];
    let bit_len: u64 = (data.len() as u64) * 8;
    let mut msg: Vec<u8> = data;
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0);
    }
    for i in (0..8).rev() {
        msg.push((bit_len >> (i * 8)) as u8);
    }

    let mut block = 0;
    while block < msg.len() {
        let mut w = [0u64; 64];
        for i in 0..16 {
            let p = block + i * 4;
            w[i] = (msg[p] as u64) * 16777216
                + (msg[p + 1] as u64) * 65536
                + (msg[p + 2] as u64) * 256
                + (msg[p + 3] as u64);
        }
        for i in 16..64 {
            let s0 = bxor(bxor(rotr(w[i - 15], 7), rotr(w[i - 15], 18)), w[i - 15] / 8);
            let s1 = bxor(bxor(rotr(w[i - 2], 17), rotr(w[i - 2], 19)), w[i - 2] / 1024);
            w[i] = add(add(w[i - 16], s0), add(w[i - 7], s1));
        }

        let mut a = h[0];
        let mut b = h[1];
        let mut c = h[2];
        let mut d = h[3];
        let mut e = h[4];
        let mut f = h[5];
        let mut g = h[6];
        let mut hh = h[7];

        for i in 0..64 {
            let s1 = bxor(bxor(rotr(e, 6), rotr(e, 11)), rotr(e, 25));
            let ch = add(band(e, f), band(bnot(e), g));
            let t1 = add(add(hh, s1), add(ch, add(K[i], w[i])));
            let s0 = bxor(bxor(rotr(a, 2), rotr(a, 13)), rotr(a, 22));
            let maj = bxor(bxor(band(a, b), band(a, c)), band(b, c));
            let t2 = add(s0, maj);
            hh = g;
            g = f;
            f = e;
            e = add(d, t1);
            d = c;
            c = b;
            b = a;
            a = add(t1, t2);
        }

        h[0] = add(h[0], a);
        h[1] = add(h[1], b);
        h[2] = add(h[2], c);
        h[3] = add(h[3], d);
        h[4] = add(h[4], e);
        h[5] = add(h[5], f);
        h[6] = add(h[6], g);
        h[7] = add(h[7], hh);

        block += 64;
    }

    let mut out: Vec<u8> = Vec::new();
    for i in 0..8 {
        let v = h[i];
        for j in (0..4).rev() {
            out.push(((v / pow2(j * 8)) % 256) as u8);
        }
    }
    out
}

