        }
        p = p * 2;
        i = i + 1;
    }
    r
}

fn bnot(x: u64) -> u64 {
    4294967295 - x
}

fn sha256(data: Vec<u8>) -> Vec<u8> {
    let k = kconst();
    let mut h: [u64; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
    ];
    let bit_len: u64 = (data.len() as u64) * 8;
    let mut msg: Vec<u8> = data;
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0);
    }
    let mut j: u64 = 0;
    while j < 8 {
        let sh: u64 = (7 - j) * 8;
        msg.push(((bit_len / pow2(sh)) % 256) as u8);
        j = j + 1;
    }

    let mut block = 0;
    while block < msg.len() {
        let mut w = [0u64; 64];
        for i in 0..16 {
            let p = block + i * 4;
            w[i] = (msg[p] as u64) * 16777216
                + (msg[p + 1] as u64) * 65536
                + (msg[p + 2] as u64) * 256
                + (msg[p + 3] as u64);
        }
        for i in 16..64 {
            let s0 = bxor(bxor(rotr(w[i - 15], 7), rotr(w[i - 15], 18)), w[i - 15] / 8);
            let s1 = bxor(bxor(rotr(w[i - 2], 17), rotr(w[i - 2], 19)), w[i - 2] / 1024);
            w[i] = add(add(w[i - 16], s0), add(w[i - 7], s1));
        }

        let mut a = h[0];
        let mut b = h[1];
        let mut c = h[2];
        let mut d = h[3];
        let mut e = h[4];
        let mut f = h[5];
        let mut g = h[6];
        let mut hh = h[7];

        for i in 0..64 {
            let s1 = bxor(bxor(rotr(e, 6), rotr(e, 11)), rotr(e, 25));
            let ch = add(band(e, f), band(bnot(e), g));
            let t1 = add(add(hh, s1), add(ch, add(k[i], w[i])));
            let s0 = bxor(bxor(rotr(a, 2), rotr(a, 13)), rotr(a, 22));
            let maj = bxor(bxor(band(a, b), band(a, c)), band(b, c));
            let t2 = add(s0, maj);
            hh = g;
            g = f;
            f = e;
            e = add(d, t1);
            d = c;
            c = b;
            b = a;
            a = add(t1, t2);
        }

        h[0] = add(h[0], a);
        h[1] = add(h[1], b);
        h[2] = add(h[2], c);
        h[3] = add(h[3], d);
        h[4] = add(h[4], e);
        h[5] = add(h[5], f);
        h[6] = add(h[6], g);
        h[7] = add(h[7], hh);

        block += 64;
    }

    let mut out: Vec<u8> = Vec::new();
    for i in 0..8 {
        let v = h[i];
        let mut q: u64 = 0;
        while q < 4 {
            let sh: u64 = (3 - q) * 8;
            out.push(((v / pow2(sh)) % 256) as u8);
            q = q + 1;
        }
    }
    out
}

fn hex_digit(v: u64) -> Str {
    match v {
        0 => "0".to_string(),
        1 => "1".to_string(),
        2 => "2".to_string(),
        3 => "3".to_string(),
        4 => "4".to_string(),
        5 => "5".to_string(),
        6 => "6".to_string(),
        7 => "7".to_string(),
        8 => "8".to_string(),
        9 => "9".to_string(),
        10 => "a".to_string(),
        11 => "b".to_string(),
        12 => "c".to_string(),
        13 => "d".to_string(),
        14 => "e".to_string(),
        15 => "f".to_string(),
        _ => "0".to_string(),
    }
}

fn hex(bytes: Vec<u8>) -> Str {
    let mut s: Str = String::new();
    for b in bytes {
        let v: u64 = b as u64;
        s = format!("{}{}{}", s, hex_digit(v / 16), hex_digit(v % 16));
    }
    s
}

fn hash_pw(salt: Str, pw: Str) -> Str {
    let data = format!("{}{}", salt, pw);
    hex(sha256(data.as_bytes().to_vec()))
}

fn valid_name(s: Str) -> bool {
    let b: Vec<u8> = s.as_bytes().to_vec();
    if b.len() < 3 || b.len() > 20 {
        return false;
    }
    for c in b {
        let lower = c >= 97 && c <= 122;
        let digit = c >= 48 && c <= 57;
        let under = c == 95;
        let ok = lower || digit || under;
        if !ok {
            return false;
        }
    }
    true
}

fn err(msg: Str) -> Str {
    format!("{{\"error\":\"{}\"}}", msg)
}

fn creds(body: Str) -> Option<(Str, Str)> {
    let j = json::parse(body)?;
    let name = j.get("name")?.as_str()?;
    let pw = j.get("password")?.as_str()?;
    Some((name, pw))
}

fn num_of(v: Option<Str>) -> u64 {
    match v {
        Some(s) => s.parse::<u64>().unwrap_or(0),
        None => 0,
    }
}

fn bearer(auth: Option<Str>) -> Str {
    match auth {
        None => String::new(),
        Some(h) => match h.strip_prefix("Bearer ") {
            Some(t) => t.to_string(),
            None => String::new(),
        },
    }
}

fn main(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Result<Str, Str> {
    let method = req.method();
    let path = req.path();
    let body = req.body();
    let now: u64 = clock.now();

    let tok = bearer(req.header("authorization"));
    let sname = store.get(format!("sess:{}", tok.clone()));
    let sexp = num_of(store.get(format!("sexp:{}", tok.clone())));
    let authed = sname.is_some() && now < sexp;
    let user: Str = match sname {
        Some(n) => n,
        None => String::new(),
    };

    let mut status: u16 = 404;
    let mut out: Str = err("not found");
    let mut empty = false;

    if method == "POST" && path == "/users" {
        match creds(body) {
            None => {
                status = 400;
                out = err("invalid");
            }
            Some((name, pw)) => {
                if !valid_name(name.clone()) || pw.len() < 8 {
                    status = 400;
                    out = err("invalid");
                } else if store.get(format!("pw:{}", name.clone())).is_some() {
                    status = 409;
                    out = err("name taken");
                } else {
                    let salt = hex(rng.bytes(16));
                    let h = hash_pw(salt.clone(), pw);
                    store.set(format!("pw:{}", name.clone()), h);
                    store.set(format!("salt:{}", name.clone()), salt);
                    status = 201;
                    out = format!("{{\"name\":\"{}\"}}", name);
                }
            }
        }
    } else if method == "POST" && path == "/login" {
        match creds(body) {
            None => {
                status = 401;
                out = err("bad credentials");
            }
            Some((name, pw)) => match store.get(format!("pw:{}", name.clone())) {
                None => {
                    status = 401;
                    out = err("bad credentials");
                }
                Some(want) => {
                    let lock_until = num_of(store.get(format!("lock:{}", name.clone())));
                    if now < lock_until {
                        status = 429;
                        out = err("locked");
                    } else {
                        let salt = match store.get(format!("salt:{}", name.clone())) {
                            Some(s) => s,
                            None => String::new(),
                        };
                        let fails = num_of(store.get(format!("fails:{}", name.clone())));
                        if hash_pw(salt, pw) == want {
                            store.set(format!("fails:{}", name.clone()), "0".to_string());
                            let logins = num_of(store.get(format!("logins:{}", name.clone()))) + 1;
                            store.set(format!("logins:{}", name.clone()), logins.to_string());

                            let token = hex(rng.bytes(16));
                            store.set(format!("sess:{}", token.clone()), name.clone());
                            store.set(
                                format!("sexp:{}", token.clone()),
                                (now + 1800000).to_string(),
                            );
                            status = 200;
                            out = format!(
                                "{{\"token\":\"{}\",\"expires_in\":1800}}",
                                token
                            );
                        } else {
                            let f = fails + 1;
                            if f >= 3 {
                                store.set(
                                    format!("lock:{}", name.clone()),
                                    (now + 900000).to_string(),
                                );
                                store.set(format!("fails:{}", name.clone()), "0".to_string());
                            } else {
                                store.set(format!("fails:{}", name.clone()), f.to_string());
                            }
                            status = 401;
                            out = err("bad credentials");
                        }
                    }
                }
            },
        }
    } else if method == "GET" && path == "/me" {
        if authed {
            store.set(
                format!("sexp:{}", tok.clone()),
                (now + 1800000).to_string(),
            );
            let n = num_of(store.get(format!("logins:{}", user.clone())));
            status = 200;
            out = format!("{{\"name\":\"{}\",\"logins\":{}}}", user, n);
        } else {
            status = 401;
            out = err("unauthorized");
        }
    } else if method == "POST" && path == "/logout" {
        if authed {
            store.remove(format!("sess:{}", tok.clone()));
            store.remove(format!("sexp:{}", tok.clone()));
            status = 204;
            empty = true;
        } else {
            status = 401;
            out = err("unauthorized");
        }
    }

    if empty {
        res.send(204, "", "");
    } else {
        res.send(status, "application/json", out);
    }

    Ok(format!("{} {} {}", method, path, status))
}

// Assumed kio APIs. Check these against the kio reference before running:
//   req.method() -> Str, req.path() -> Str (may include "?query"),
//   req.header(name) -> Option<Str>, req.body() -> Str
//   res.status(i64), res.header(name, value), res.send(body)
//   db.exec(sql, Vec<Sql>), db.query(sql, Vec<Sql>) -> Vec<Row>, db.last_id() -> i64
//   Row::int(i) -> i64, Row::text(i) -> Str; Sql::Int(i64) | Sql::Text(Str)
//   json::parse(&str) -> Option<Value>
//   json::canonical(&str) -> Option<Str>   (sorted keys, compact output)
//   json::quote(&str) -> Str               (JSON string literal, escaped)
//   Value::as_object() -> Option<..> with len(), get(key) -> Option<&Value>,
//   Value::as_str() -> Option<&str>, Value::as_int() -> Option<i64> (None for non-integers)

struct Payment {
    id: i64,
    account: Str,
    cents: i64,
    currency: Str,
    status: Str,
    refunded: i64,
}

fn init(db: &Db) {
    db.exec(
        "CREATE TABLE IF NOT EXISTS payments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            account TEXT NOT NULL,
            cents INTEGER NOT NULL,
            currency TEXT NOT NULL,
            status TEXT NOT NULL,
            refunded INTEGER NOT NULL)",
        vec![],
    );
    db.exec(
        "CREATE TABLE IF NOT EXISTS idem (
            key TEXT PRIMARY KEY,
            method TEXT NOT NULL,
            path TEXT NOT NULL,
            body TEXT NOT NULL,
            status INTEGER NOT NULL,
            response TEXT NOT NULL)",
        vec![],
    );
}

fn reply(res: &Outgoing, status: i64, body: &str) -> Str {
    res.status(status);
    res.header("content-type", "application/json");
    res.send(body);
    "ok".to_string()
}

fn fail(res: &Outgoing, status: i64, msg: &str) -> Str {
    reply(res, status, &format!("{{\"error\": \"{}\"}}", msg))
}

fn payment_json(p: &Payment) -> Str {
    format!(
        "{{\"id\":\"pay_{}\",\"account\":{},\"cents\":{},\"currency\":{},\"status\":{},\"refunded\":{}}}",
        p.id,
        json::quote(&p.account),
        p.cents,
        json::quote(&p.currency),
        json::quote(&p.status),
        p.refunded
    )
}

fn row_payment(r: &Row) -> Payment {
    Payment {
        id: r.int(0),
        account: r.text(1),
        cents: r.int(2),
        currency: r.text(3),
        status: r.text(4),
        refunded: r.int(5),
    }
}

fn load(db: &Db, id: i64) -> Option<Payment> {
    let rows = db.query(
        "SELECT id,account,cents,currency,status,refunded FROM payments WHERE id = ?1",
        vec![Sql::Int(id)],
    );
    let r = rows.first()?;
    Some(row_payment(r))
}

fn parse_id(seg: &str) -> Option<i64> {
    let digits = seg.strip_prefix("pay_")?;
    if digits.is_empty() || !digits.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    digits.parse::<i64>().ok()
}

// Idempotency gate. Err(..) means the response has already been sent
// (missing key, replay, or key reuse). Ok((key, canonical body)) means proceed.
fn gate(
    res: &Outgoing,
    db: &Db,
    method: &str,
    path: &str,
    body: &str,
    key: Option<Str>,
) -> Result<(Str, Str), Str> {
    let key = match key {
        Some(k) => k,
        None => return Err(fail(res, 400, "missing idempotency key")),
    };
    // Stored bodies are always valid JSON, so an invalid body (empty canon) never matches.
    let canon = json::canonical(body).unwrap_or(String::new());
    let rows = db.query(
        "SELECT method,path,body,status,response FROM idem WHERE key = ?1",
        vec![Sql::Text(key.clone())],
    );
    if let Some(r) = rows.first() {
        if r.text(0) == method && r.text(1) == path && r.text(2) == canon {
            return Err(reply(res, r.int(3), &r.text(4)));
        }
        return Err(fail(res, 409, "key reused"));
    }
    Ok((key, canon))
}

fn remember(db: &Db, key: &str, method: &str, path: &str, canon: &str, status: i64, resp: &str) {
    db.exec(
        "INSERT INTO idem (key,method,path,body,status,response) VALUES (?1,?2,?3,?4,?5,?6)",
        vec![
            Sql::Text(key.to_string()),
            Sql::Text(method.to_string()),
            Sql::Text(path.to_string()),
            Sql::Text(canon.to_string()),
            Sql::Int(status),
            Sql::Text(resp.to_string()),
        ],
    );
}

fn parse_create(v: &Value) -> Option<(String, i64, String)> {
    let obj = v.as_object()?;
    if obj.len() != 3 {
        return None;
    }
    let account = v.get("account")?.as_str()?;
    if account.is_empty() {
        return None;
    }
    let cents = v.get("cents")?.as_int()?;
    if cents <= 0 {
        return None;
    }
    let currency = v.get("currency")?.as_str()?;
    if currency != "EUR" && currency != "USD" {
        return None;
    }
    Some((account.to_string(), cents, currency.to_string()))
}

fn create(req: &Incoming, res: &Outgoing, db: &Db) -> Str {
    let body = req.body();
    let (key, canon) = match gate(res, db, "POST", "/payments", &body, req.header("idempotency-key")) {
        Ok(v) => v,
        Err(s) => return s,
    };
    let (account, cents, currency) = match json::parse(&body).and_then(|v| parse_create(&v)) {
        Some(t) => t,
        None => return fail(res, 422, "invalid payment"),
    };
    db.exec(
        "INSERT INTO payments (account,cents,currency,status,refunded) VALUES (?1,?2,?3,'pending',0)",
        vec![Sql::Text(account), Sql::Int(cents), Sql::Text(currency)],
    );
    let id = db.last_id();
    let out = match load(db, id) {
        Some(p) => payment_json(&p),
        None => return fail(res, 500, "internal error"),
    };
    remember(db, &key, "POST", "/payments", &canon, 201, &out);
    reply(res, 201, &out)
}

fn transition(res: &Outgoing, db: &Db, id: i64, action: &str) -> Str {
    let p = match load(db, id) {
        Some(p) => p,
        None => return fail(res, 404, "not found"),
    };
    if action == "capture" {
        if p.status == "captured" {
            return reply(res, 200, &payment_json(&p));
        }
        if p.status != "pending" {
            return fail(res, 409, "invalid transition");
        }
        db.exec(
            "UPDATE payments SET status = 'captured' WHERE id = ?1",
            vec![Sql::Int(id)],
        );
    } else {
        if p.status != "pending" {
            return fail(res, 409, "invalid transition");
        }
        db.exec(
            "UPDATE payments SET status = 'canceled' WHERE id = ?1",
            vec![Sql::Int(id)],
        );
    }
    match load(db, id) {
        Some(p) => reply(res, 200, &payment_json(&p)),
        None => fail(res, 500, "internal error"),
    }
}

fn refund(req: &Incoming, res: &Outgoing, db: &Db, id: i64, path: &str) -> Str {
    let body = req.body();
    let (key, canon) = match gate(res, db, "POST", path, &body, req.header("idempotency-key")) {
        Ok(v) => v,
        Err(s) => return s,
    };
    let p = match load(db, id) {
        Some(p) => p,
        None => return fail(res, 404, "not found"),
    };
    let n = match json::parse(&body).and_then(|v| v.get("cents").and_then(|c| c.as_int())) {
        Some(n) if n > 0 => n,
        _ => return fail(res, 422, "invalid refund"),
    };
    if p.status != "captured" {
        return fail(res, 409, "invalid transition");
    }
    if p.refunded + n > p.cents {
        return fail(res, 409, "exceeds captured");
    }
    let total = p.refunded + n;
    let status = if total == p.cents { "refunded" } else { "captured" };
    db.exec(
        "UPDATE payments SET refunded = ?1, status = ?2 WHERE id = ?3",
        vec![Sql::Int(total), Sql::Text(status.to_string()), Sql::Int(id)],
    );
    let out = match load(db, id) {
        Some(p) => payment_json(&p),
        None => return fail(res, 500, "internal error"),
    };
    remember(db, &key, "POST", path, &canon, 200, &out);
    reply(res, 200, &out)
}

fn list(res: &Outgoing, db: &Db, query: &str) -> Str {
    let mut account = String::new();
    for kv in query.split('&') {
        if let Some(v) = kv.strip_prefix("account=") {
            account = v.to_string();
        }
    }
    let rows = db.query(
        "SELECT id,account,cents,currency,status,refunded FROM payments WHERE account = ?1 ORDER BY id",
        vec![Sql::Text(account)],
    );
    let items: Vec<Str> = rows
        .iter()
        .map(|r| payment_json(&row_payment(r)))
        .collect();
    reply(res, 200, &format!("[{}]", items.join(",")))
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Str {
    init(&db);
    let method = req.method();
    let full = req.path();
    let (path, query) = match full.find('?') {
        Some(i) => (full[..i].to_string(), full[i + 1..].to_string()),
        None => (full.clone(), String::new()),
    };
    let segs: Vec<&str> = path.split('/').collect();
    if segs.len() < 2 || segs[0] != "" || segs[1] != "payments" {
        return fail(&res, 404, "not found");
    }
    match (method.as_str(), segs.len()) {
        ("POST", 2) => create(&req, &res, &db),
        ("GET", 2) => list(&res, &db, &query),
        ("GET", 3) => match parse_id(segs[2]).and_then(|id| load(&db, id)) {
            Some(p) => reply(&res, 200, &payment_json(&p)),
            None => fail(&res, 404, "not found"),
        },
        ("POST", 4) => {
            let id = match parse_id(segs[2]) {
                Some(i) => i,
                None => return fail(&res, 404, "not found"),
            };
            match segs[3] {
                "capture" => transition(&res, &db, id, "capture"),
                "cancel" => transition(&res, &db, id, "cancel"),
                "refund" => refund(&req, &res, &db, id, &path),
                _ => fail(&res, 404, "not found"),
            }
        }
        _ => fail(&res, 404, "not found"),
    }
}

struct Payment {
    id: i64,
    account: Str,
    cents: i64,
    currency: Str,
    status: Str,
    refunded: i64,
}

fn err(msg: Str) -> Str {
    format!("{{\"error\": \"{}\"}}", msg)
}

fn payment_json(p: Payment) -> Str {
    format!(
        "{{\"id\":\"pay_{}\",\"account\":{},\"cents\":{},\"currency\":{},\"status\":{},\"refunded\":{}}}",
        p.id,
        json::quote(p.account.clone()),
        p.cents,
        json::quote(p.currency.clone()),
        json::quote(p.status.clone()),
        p.refunded
    )
}

fn row_payment(r: Row) -> Payment {
    Payment {
        id: r.int(0),
        account: r.text(1),
        cents: r.int(2),
        currency: r.text(3),
        status: r.text(4),
        refunded: r.int(5),
    }
}

fn many(rows: Vec<Row>) -> Vec<Payment> {
    let mut out: Vec<Payment> = Vec::new();
    for r in rows {
        out.push(row_payment(r));
    }
    out
}

fn one(rows: Vec<Row>) -> Option<Payment> {
    let mut v = many(rows);
    if v.len() == 0 {
        return None;
    }
    Some(v.remove(0))
}

fn parse_id(seg: Str) -> Option<i64> {
    let digits = match seg.strip_prefix("pay_") {
        Some(d) => d.to_string(),
        None => return None,
    };
    if digits.len() == 0 || !digits.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    digits.parse::<i64>().ok()
}

// Looks at the stored response for a key. None: no prior request with this key.
// Some: the response to send now (replayed, or key reused).
fn replayed(rows: Vec<Row>, method: Str, path: Str, canon: Str) -> Option<(i64, Str)> {
    let r = match rows.first() {
        Some(r) => r,
        None => return None,
    };
    if r.text(0) == method && r.text(1) == path && r.text(2) == canon {
        return Some((r.int(3), r.text(4)));
    }
    Some((409, err("key reused".to_string())))
}

fn remember(db: Db, key: Str, path: Str, canon: Str, status: i64, out: Str) -> (i64, Str) {
    db.exec(
        "INSERT INTO idem (key,method,path,body,status,response) VALUES (?1,?2,?3,?4,?5,?6)",
        vec![
            Sql::Text(key),
            Sql::Text("POST".to_string()),
            Sql::Text(path),
            Sql::Text(canon),
            Sql::Int(status),
            Sql::Text(out.clone()),
        ],
    );
    (status, out)
}

fn parse_create(v: Value) -> Option<(Str, i64, Str)> {
    let obj = v.as_object()?;
    if obj.len() != 3 {
        return None;
    }
    let account = v.get("account")?.as_str()?.to_string();
    if account.len() == 0 {
        return None;
    }
    let cents = v.get("cents")?.as_int()?;
    if cents <= 0 {
        return None;
    }
    let currency = v.get("currency")?.as_str()?.to_string();
    if currency != "EUR" && currency != "USD" {
        return None;
    }
    Some((account, cents, currency))
}

