fn v1(a: Sql) -> Vec<Sql> {
    let mut v: Vec<Sql> = Vec::new();
    v.push(a);
    v
}

fn v2(a: Sql, b: Sql) -> Vec<Sql> {
    let mut v: Vec<Sql> = Vec::new();
    v.push(a);
    v.push(b);
    v
}

fn v3(a: Sql, b: Sql, c: Sql) -> Vec<Sql> {
    let mut v: Vec<Sql> = Vec::new();
    v.push(a);
    v.push(b);
    v.push(c);
    v
}

fn v6(a: Sql, b: Sql, c: Sql, d: Sql, e: Sql, f: Sql) -> Vec<Sql> {
    let mut v: Vec<Sql> = Vec::new();
    v.push(a);
    v.push(b);
    v.push(c);
    v.push(d);
    v.push(e);
    v.push(f);
    v
}

fn no_args() -> Vec<Sql> {
