fn payment_json(p: Payment) -> Str {
    "{\"id\":\"pay_".to_string()
        + p.id.to_str()
        + "\",\"account\":"
        + json::quote(p.account.clone())
        + ",\"cents\":"
        + p.cents.to_str()
        + ",\"currency\":"
