fn num(b: &[u8], from: usize, to: usize) -> Option<i64> {
    let mut v: i64 = 0;
    let mut i = from;
    while i < to {
        let c = b[i];
        if c < 48 || c > 57 {
            return None;
        }
        v = v * 10 + (c - 48) as i64;
        i += 1;
    }
    Some(v)
}

fn parse_time(t: &Str) -> Option<i64> {
    let b = t.as_bytes();
    if b.len() != 20 {
        return None;
    }
    // '-' '-' 'T' ':' ':' 'Z'
    if b[4] != 45 || b[7] != 45 || b[10] != 84 || b[13] != 58 || b[16] != 58 || b[19] != 90 {
        return None;
    }
    let y = num(b, 0, 4)?;
    let mo = num(b, 5, 7)?;
    let d = num(b, 8, 10)?;
    let h = num(b, 11, 13)?;
    let mi = num(b, 14, 16)?;
    let s = num(b, 17, 19)?;

    if mo < 1 || mo > 12 || d < 1 {
        return None;
    }
    let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    let mut dim: i64 = 31;
    if mo == 4 || mo == 6 || mo == 9 || mo == 11 {
        dim = 30;
    }
    if mo == 2 {
        dim = if leap { 29 } else { 28 };
    }
    if d > dim {
        return None;
    }
    if h > 23 || mi > 59 || s > 59 {
        return None;
    }

    // days since a fixed epoch (proleptic Gregorian), shifted to keep values positive
    let mut yy = y + 400;
    if mo <= 2 {
        yy -= 1;
    }
    let era = yy / 400;
    let yoe = yy - era * 400;
    let mp = if mo > 2 { mo - 3 } else { mo + 9 };
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    let days = era * 146097 + doe;
    Some(days * 86400 + h * 3600 + mi * 60 + s)
}

fn fmt_hms(s: i64) -> String {
    let h = s / 3600;
    let m = (s % 3600) / 60;
    let sec = s % 60;
    format!("{:02}:{:02}:{:02}", h, m, sec)
}

fn main(input: Dir) -> Result<Str, Str> {
    let text = input.read_to_string("events.log")?;

    let mut seen: HashSet<Str> = HashSet::new();
    let mut events: Vec<(Str, i64, Str)> = Vec::new();
    let mut malformed: i64 = 0;
    let mut duplicates: i64 = 0;

    for line in text.lines() {
        if line.trim().is_empty() {
            continue;
        }
        let owned: Str = line.to_string();
        if seen.contains(&owned) {
            duplicates += 1;
            continue;
        }
        seen.insert(owned);

        let parts: Vec<Str> = line.split(' ').map(|p| p.to_string()).collect();
        if parts.len() != 3 || parts[0].is_empty() || parts[1].is_empty() || parts[2].is_empty() {
            malformed += 1;
            continue;
        }
        match parse_time(&parts[0]) {
            None => {
                malformed += 1;
            }
            Some(t) => {
                events.push((parts[1].clone(), t, parts[2].clone()));
            }
        }
    }

    if events.is_empty() {
        let mut only = String::new();
        only.push_str(&format!("malformed {} duplicates {}\n", malformed, duplicates));
        return Ok(only);
    }

    events.sort();

    let mut out = String::new();
    let mut page_counts: HashMap<Str, i64> = HashMap::new();
    let mut durations: Vec<i64> = Vec::new();

    let n = events.len();
    let mut i: usize = 0;
