fn parse_time(t: Str) -> Option<i64> {
    let b = t.as_bytes();
    if b.len() != 20 {
        return None;
    }
    // '-' '-' 'T' ':' ':' 'Z'
    if b[4] != 45 || b[7] != 45 || b[10] != 84 || b[13] != 58 || b[16] != 58 || b[19] != 90 {
        return None;
    }
    let y = num(t.clone(), 0, 4)?;
    let mo = num(t.clone(), 5, 7)?;
    let d = num(t.clone(), 8, 10)?;
    let h = num(t.clone(), 11, 13)?;
    let mi = num(t.clone(), 14, 16)?;
    let s = num(t.clone(), 17, 19)?;

    if mo < 1 || mo > 12 || d < 1 {
        return None;
    }
    let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    let mut dim: i64 = 31;
    if mo == 4 || mo == 6 || mo == 9 || mo == 11 {
        dim = 30;
    }
    if mo == 2 {
        dim = if leap { 29 } else { 28 };
    }
    if d > dim {
        return None;
    }
    if h > 23 || mi > 59 || s > 59 {
        return None;
    }

    // days since a fixed epoch (proleptic Gregorian), shifted to keep values positive
    let mut yy = y + 400;
    if mo <= 2 {
        yy -= 1;
    }
    let era = yy / 400;
    let yoe = yy - era * 400;
