fn main(input: Dir) -> Result<Str, Str> {
    let text = input.read_to_string("events.log")?;

    // Collect non-blank lines and sort them so exact duplicates are adjacent.
    let mut raw: Vec<Str> = Vec::new();
    for line in text.lines() {
        if line.trim().is_empty() {
            continue;
        }
        raw.push(line.to_string());
    }
    raw.sort();

    let mut events: Vec<(Str, i64, Str)> = Vec::new();
    let mut malformed: i64 = 0;
    let mut duplicates: i64 = 0;
    let mut prev_line: Str = String::new();

    for line in raw {
        if line == prev_line {
            duplicates += 1;
            continue;
        }
        prev_line = line.clone();

        let parts: Vec<Str> = line.split(' ').map(|p| p.to_string()).collect();
        if parts.len() != 3 || parts[0].is_empty() || parts[1].is_empty() || parts[2].is_empty() {
            malformed += 1;
            continue;
        }
        match parse_time(parts[0].clone()) {
            None => {
                malformed += 1;
            }
            Some(t) => {
                events.push((parts[1].clone(), t, parts[2].clone()));
            }
        }
    }

    if events.is_empty() {
        return Ok(format!("malformed {} duplicates {}\n", malformed, duplicates));
    }

    events.sort();

    let mut out = String::new();
    let mut all_pages: Vec<Str> = Vec::new();
    let mut durations: Vec<i64> = Vec::new();

    let n = events.len();
    let mut i: usize = 0;
    while i < n {
        let user = events[i].0.clone();
        let mut j = i;
        while j < n && events[j].0 == user {
            j += 1;
        }

        let mut sessions: i64 = 1;
        let mut longest: i64 = 0;
        let mut start: i64 = events[i].1;
        let mut prev: i64 = events[i].1;
        let mut user_pages: Vec<Str> = Vec::new();

        let mut k = i;
        while k < j {
            let t = events[k].1;
            if k > i && t - prev > 1800 {
                let gap_d = prev - start;
                durations.push(gap_d);
                if gap_d > longest {
                    longest = gap_d;
                }
                start = t;
                sessions += 1;
            }
            prev = t;
            user_pages.push(events[k].2.clone());
            all_pages.push(events[k].2.clone());
            k += 1;
        }
        let last_d = prev - start;
        durations.push(last_d);
        if last_d > longest {
            longest = last_d;
        }

        user_pages.sort();
        let mut distinct: i64 = 0;
        let mut last_page: Str = String::new();
        for p in user_pages {
            if p != last_page {
                distinct += 1;
                last_page = p;
            }
        }

        out.push_str(format!(
            "{} sessions {} events {} longest {} pages {}\n",
            user,
            sessions,
            j - i,
            fmt_hms(longest),
