        let mut longest: i64 = 0;
        let mut start: i64 = events[i].1;
        let mut prev: i64 = events[i].1;
        let mut user_pages: Vec<Str> = Vec::new();

        let mut k = i;
        while k < j {
            let t = events[k].1;
            if k > i && t - prev > 1800 {
                let gap_d = prev - start;
                durations.push(gap_d);
                if gap_d > longest {
                    longest = gap_d;
                }
                start = t;
                sessions += 1;
            }
            prev = t;
            user_pages.push(events[k].2.clone());
            all_pages.push(events[k].2.clone());
            k += 1;
        }
        let last_d = prev - start;
        durations.push(last_d);
        if last_d > longest {
            longest = last_d;
        }

        user_pages.sort();
        let mut distinct: i64 = 0;
        let mut last_page: Str = String::new();
        for p in user_pages {
            if p != last_page {
                distinct += 1;
                last_page = p;
            }
        }

        out.push_str(format!(
            "{} sessions {} events {} longest {} pages {}\n",
            user,
            sessions,
            j - i,
            fmt_hms(longest),
            distinct
        ));
        i = j;
    }

    durations.sort();
    let med = durations[(durations.len() - 1) / 2];
    out.push_str(format!("median {}\n", med));

    all_pages.sort();
    let total = all_pages.len();
    let mut pc: Vec<(i64, Str)> = Vec::new();
    let mut idx: usize = 0;
    while idx < total {
        let p = all_pages[idx].clone();
        let mut c: i64 = 0;
        while idx < total && all_pages[idx] == p {
            c += 1;
            idx += 1;
        }
        pc.push((0 - c, p));
    }
    pc.sort();

    let mut tops: Vec<String> = Vec::new();
    for (nc, p) in pc.into_iter().take(3) {
        tops.push(format!("{} ({})", p, 0 - nc));
    }
    out.push_str(format!("top: {}\n", tops.join(", ")));
    out.push_str(format!("malformed {} duplicates {}\n", malformed, duplicates));

    Ok(out)
}

