fn eol(cs: &Vec<char>, i: usize) -> bool {
    if i >= cs.len() {
        return false;
    }
    if cs[i] == '\n' {
        return true;
    }
    cs[i] == '\r' && i + 1 < cs.len() && cs[i + 1] == '\n'
}

// Parses one record starting at `start`; returns (fields, malformed, index after record).
fn parse_record(cs: &Vec<char>, start: usize) -> (Vec<Str>, bool, usize) {
    let n = cs.len();
    let mut i = start;
    let mut fields: Vec<Str> = Vec::new();
    let mut bad = false;
    loop {
        let mut field = String::new();
        if i < n && cs[i] == '"' {
            i += 1;
            let mut closed = false;
            while i < n {
                if cs[i] == '"' {
                    if i + 1 < n && cs[i + 1] == '"' {
                        field.push('"');
                        i += 2;
                    } else {
                        closed = true;
                        i += 1;
                        break;
                    }
                } else {
                    field.push(cs[i]);
                    i += 1;
                }
            }
            if !closed {
                bad = true;
            } else if i < n && cs[i] != ',' && !eol(cs, i) {
                bad = true;
            }
        } else {
            while i < n && cs[i] != ',' && !eol(cs, i) {
                if cs[i] == '"' {
                    bad = true;
                }
                field.push(cs[i]);
                i += 1;
            }
        }
        fields.push(field);
        if i < n && cs[i] == ',' {
            i += 1;
            continue;
        }
        break;
    }
    // Malformed remainder of the line: skip to the record terminator.
    while i < n && !eol(cs, i) {
        bad = true;
        i += 1;
    }
    if eol(cs, i) {
        i += if cs[i] == '\n' { 1 } else { 2 };
    }
    (fields, bad, i)
}

fn parse_qty(s: &Str) -> Option<i64> {
    let cs: Vec<char> = s.chars().collect();
    let mut i = 0;
    let mut neg = false;
    if cs.len() > 0 && cs[0] == '-' {
        neg = true;
        i = 1;
    }
    if i >= cs.len() {
        return None;
    }
    let mut v: i64 = 0;
    while i < cs.len() {
        match cs[i].to_digit(10) {
            Some(d) => {
                v = v * 10 + d as i64;
            }
            None => return None,
        }
        i += 1;
    }
    Some(if neg { -v } else { v })
}

// Returns the price in cents.
fn parse_price(s: &Str) -> Option<i64> {
    let cs: Vec<char> = s.chars().collect();
    let n = cs.len();
    let mut i = 0;
    let mut whole: i64 = 0;
    let mut nd = 0;
    while i < n {
        match cs[i].to_digit(10) {
            Some(d) => {
                whole = whole * 10 + d as i64;
                nd += 1;
                i += 1;
            }
            None => break,
        }
    }
    if nd == 0 {
        return None;
    }
    let mut frac: i64 = 0;
    if i < n && cs[i] == '.' {
        i += 1;
        let mut fd = 0;
        while i < n {
            match cs[i].to_digit(10) {
                Some(d) => {
                    if fd >= 2 {
                        return None;
                    }
                    frac = frac * 10 + d as i64;
                    fd += 1;
                    i += 1;
                }
                None => break,
            }
        }
        if fd == 0 {
            return None;
        }
        if fd == 1 {
            frac = frac * 10;
        }
    }
    if i != n {
        return None;
    }
    Some(whole * 100 + frac)
}

fn money(c: i64) -> Str {
    let neg = c < 0;
    let a = if neg { -c } else { c };
    let s = format!("{}.{:02}", a / 100, a % 100);
    if neg {
        format!("-{}", s)
    } else {
        s
    }
}

fn enc(s: &Str) -> Str {
    let mut needs = false;
    for c in s.chars() {
        if c == ',' || c == '"' || c == '\r' || c == '\n' {
            needs = true;
        }
    }
    if !needs {
        return s.clone();
    }
    let mut o = String::from("\"");
    for c in s.chars() {
        if c == '"' {
            o.push('"');
        }
        o.push(c);
    }
    o.push('"');
    o
}

fn main(input: Dir, out: Dir) -> Result<Str, Str> {
    let text: Str = input.read("sales.csv")?;
    let cs: Vec<char> = text.chars().collect();
    let n = cs.len();

    // Split into records, skipping empty lines.
    let mut recs: Vec<(Vec<Str>, bool)> = Vec::new();
    let mut i = 0;
    while i < n {
        if eol(&cs, i) {
            i += if cs[i] == '\n' { 1 } else { 2 };
            continue;
        }
        let (f, bad, next) = parse_record(&cs, i);
        recs.push((f, bad));
        i = next;
    }

    // recs[0] is the header; data records are numbered from 1.
    let nrec = if recs.len() > 0 { recs.len() - 1 } else { 0 };
    let mut clean = String::from("region,product,qty,price,note\n");
    let mut regions: Vec<Region> = Vec::new();
    let mut bad_list: Vec<usize> = Vec::new();

    let mut k: usize = 1;
    while k < recs.len() {
        let f: Vec<Str> = recs[k].0.clone();
        let bad = recs[k].1;
        let mut ok = !bad && f.len() == 5;
        let mut qty: i64 = 0;
        let mut price: i64 = 0;
        if ok {
            if f[0].is_empty() || f[1].is_empty() {
                ok = false;
            }
            match parse_qty(&f[2]) {
                Some(q) => qty = q,
                None => ok = false,
            }
            match parse_price(&f[3]) {
                Some(p) => price = p,
                None => ok = false,
            }
        }
        if !ok {
            bad_list.push(k);
        } else {
            clean.push_str(&format!(
                "{},{},{},{},{}\n",
                enc(&f[0]),
                enc(&f[1]),
                enc(&f[2]),
                enc(&money(price)),
                enc(&f[4])
            ));

            let rev = qty * price;

            let mut ri = regions.len();
            for j in 0..regions.len() {
                if regions[j].name == f[0] {
                    ri = j;
                }
            }
            if ri == regions.len() {
                regions.push(Region {
                    name: f[0].clone(),
                    revenue: 0,
                    items: 0,
                    products: Vec::new(),
                });
            }

            let mut pi = regions[ri].products.len();
            for j in 0..regions[ri].products.len() {
                if regions[ri].products[j].0 == f[1] {
                    pi = j;
                }
            }
            if pi == regions[ri].products.len() {
                regions[ri].products.push((f[1].clone(), 0));
            }
            regions[ri].products[pi].1 += rev;
            regions[ri].revenue += rev;
            regions[ri].items += qty;
        }
        k += 1;
    }

    // Sort regions by name (byte order).
    let m = regions.len();
    for a in 0..m {
        for b in (a + 1)..m {
            if regions[b].name < regions[a].name {
                regions.swap(a, b);
            }
        }
    }

    let mut report = String::new();
    for a in 0..regions.len() {
        let mut bname = String::new();
        let mut brev: i64 = 0;
        let mut have = false;
        for j in 0..regions[a].products.len() {
            let pname = regions[a].products[j].0.clone();
            let prev = regions[a].products[j].1;
            if !have || prev > brev || (prev == brev && pname < bname) {
                bname = pname;
                brev = prev;
                have = true;
            }
        }
        report.push_str(&format!(
            "{} revenue {} items {} top {}\n",
            regions[a].name,
            money(regions[a].revenue),
            regions[a].items,
            bname
        ));
    }

    if bad_list.len() == 0 {
        report.push_str(&format!("records {} bad 0\n", nrec));
    } else {
        let mut bl = String::new();
        for j in 0..bad_list.len() {
            if j > 0 {
                bl.push_str(", ");
            }
            bl.push_str(&format!("{}", bad_list[j]));
        }
        report.push_str(&format!(
            "records {} bad {}: {}\n",
            nrec,
            bad_list.len(),
            bl
        ));
    }

    out.write("clean.csv", clean)?;
    Ok(report)
}

