fn is_eol(c: char, nx: char) -> bool {
    c == '\n' || (c == '\r' && nx == '\n')
}

// Splits the whole text into records, skipping empty lines.
// Each entry is (fields, malformed).
fn split(text: Str) -> Vec<(Vec<Str>, bool)> {
    let cs: Vec<char> = text.chars().collect();
    let n = cs.len();
    let mut recs: Vec<(Vec<Str>, bool)> = Vec::new();
    let mut i: usize = 0;
    while i < n {
        let c0 = cs[i];
        let nx0 = if i + 1 < n { cs[i + 1] } else { ' ' };
        if is_eol(c0, nx0) {
            if c0 == '\n' {
                i += 1;
            } else {
                i += 2;
            }
            continue;
        }
        let mut fields: Vec<Str> = Vec::new();
        let mut bad = false;
        loop {
            let mut field = String::new();
            if i < n && cs[i] == '"' {
                i += 1;
                let mut closed = false;
                while i < n {
                    if cs[i] == '"' {
                        if i + 1 < n && cs[i + 1] == '"' {
                            field.push('"');
                            i += 2;
                        } else {
                            closed = true;
                            i += 1;
                            break;
                        }
                    } else {
                        field.push(cs[i]);
                        i += 1;
                    }
                }
                if !closed {
                    bad = true;
                } else if i < n {
                    let c = cs[i];
                    let nx = if i + 1 < n { cs[i + 1] } else { ' ' };
                    if c != ',' && !is_eol(c, nx) {
                        bad = true;
                    }
                }
            } else {
                let mut go = true;
                while go && i < n {
                    let c = cs[i];
                    let nx = if i + 1 < n { cs[i + 1] } else { ' ' };
                    if c == ',' || is_eol(c, nx) {
                        go = false;
                    } else {
                        if c == '"' {
                            bad = true;
                        }
                        field.push(c);
                        i += 1;
                    }
                }
            }
            fields.push(field);
            if i < n && cs[i] == ',' {
                i += 1;
            } else {
                break;
            }
        }
        // Malformed remainder of the line: skip to the record terminator.
        let mut more = true;
        while more && i < n {
            let c = cs[i];
            let nx = if i + 1 < n { cs[i + 1] } else { ' ' };
            if is_eol(c, nx) {
                more = false;
            } else {
                bad = true;
                i += 1;
            }
        }
        if i < n {
            let c = cs[i];
            let nx = if i + 1 < n { cs[i + 1] } else { ' ' };
            if is_eol(c, nx) {
                if c == '\n' {
                    i += 1;
                } else {
                    i += 2;
                }
            }
        }
        recs.push((fields, bad));
    }
    recs
}

