fn enc(s: Str) -> Str {
    let cs: Vec<Str> = units(s.clone());
    let mut needs = false;
    for j in 0..cs.len() {
        if cs[j] == "," || cs[j] == "\"" || cs[j] == "\r" || cs[j] == "\n" {
            needs = true;
        }
    }
    if !needs {
        return s;
    }
    let mut o = String::from("\"");
    for j in 0..cs.len() {
        if cs[j] == "\"" {
            o = format!("{}\"", o);
        }
        o = format!("{}{}", o, cs[j]);
    }
    format!("{}\"", o)
}

