            }
            match parse_price(f[3].clone()) {
                Some(p) => price = p,
                None => ok = false,
            }
        }
        if !ok {
            bad_list.push(k);
        } else {
            clean.push_str(format!(
                "{},{},{},{},{}\n",
                enc(f[0].clone()),
                enc(f[1].clone()),
                enc(f[2].clone()),
                enc(money(price)),
