// Formats cents as a decimal with two places.
fn money(c: i64) -> Str {
    let neg = c < 0;
    let a = if neg { -c } else { c };
    let w: Str = (a / 100).to_str();
    let r = a % 100;
    let fr: Str = if r < 10 {
        String::from("0") + r.to_str()
    } else {
        r.to_str()
    };
    let s: Str = w + "." + fr;
    if neg {
        String::from("-") + s
    } else {
        s
    }
}

fn enc(s: Str) -> Str {
    let cs: Vec<Str> = units(s.clone());
