        if cs[j] == "," || cs[j] == "\"" || cs[j] == "\r" || cs[j] == "\n" {
            needs = true;
        }
    }
    if !needs {
        return s;
    }
    let mut o = String::from("\"");
    for j in 0..cs.len() {
        if cs[j] == "\"" {
            o = o + "\"";
        }
        o = o + cs[j].clone();
    }
    o + "\""
}

fn main(input: Dir, out: Dir) -> Result<Str, Str> {
    let text: Str = input.read("sales.csv")?;
    let recs = split(text);

    // recs[0] is the header; data records are numbered from 1.
    let nrec: usize = if recs.len() > 0 { recs.len() - 1 } else { 0 };
    let mut clean = String::from("region,product,qty,price,note\n");
    let mut regions: Vec<Region> = Vec::new();
    let mut bad_list: Vec<usize> = Vec::new();

    let mut k: usize = 1;
    while k < recs.len() {
        let f: Vec<Str> = recs[k].fields.clone();
        let bad = recs[k].bad;
        let mut ok = !bad && f.len() == 5;
        let mut qty: i64 = 0;
        let mut price: i64 = 0;
        if ok {
            if f[0].is_empty() || f[1].is_empty() {
                ok = false;
            }
            match parse_qty(f[2].clone()) {
                Some(q) => qty = q,
                None => ok = false,
            }
            match parse_price(f[3].clone()) {
                Some(p) => price = p,
                None => ok = false,
            }
        }
        if !ok {
            bad_list.push(k);
        } else {
            let line: Str = enc(f[0].clone())
                + ","
                + enc(f[1].clone())
                + ","
                + enc(f[2].clone())
                + ","
                + enc(money(price))
                + ","
                + enc(f[4].clone())
                + "\n";
            clean.push_str(line);

            let rev = qty * price;

            let mut ri = regions.len();
            for j in 0..regions.len() {
                if regions[j].name == f[0] {
                    ri = j;
                }
            }
            if ri == regions.len() {
                regions.push(Region {
                    name: f[0].clone(),
                    revenue: 0,
                    items: 0,
                    products: Vec::new(),
                });
            }

            let mut pi = regions[ri].products.len();
            for j in 0..regions[ri].products.len() {
                if regions[ri].products[j].name == f[1] {
                    pi = j;
                }
            }
            if pi == regions[ri].products.len() {
                regions[ri].products.push(Prod { name: f[1].clone(), rev: 0 });
            }
            regions[ri].products[pi].rev += rev;
            regions[ri].revenue += rev;
            regions[ri].items += qty;
        }
        k += 1;
    }

    // Sort regions by name (byte order).
    let m = regions.len();
    for a in 0..m {
        for b in (a + 1)..m {
            if regions[b].name < regions[a].name {
                regions.swap(a, b);
            }
        }
    }

    let mut report = String::new();
    for a in 0..regions.len() {
        let mut bname = String::new();
        let mut brev: i64 = 0;
        let mut have = false;
        for j in 0..regions[a].products.len() {
            let pname = regions[a].products[j].name.clone();
            let prev = regions[a].products[j].rev;
            if !have || prev > brev || (prev == brev && pname < bname) {
                bname = pname;
                brev = prev;
                have = true;
            }
        }
        let line: Str = regions[a].name.clone()
            + " revenue "
            + money(regions[a].revenue)
            + " items "
            + regions[a].items.to_str()
            + " top "
            + bname
            + "\n";
        report.push_str(line);
    }

    if bad_list.len() == 0 {
        let line: Str = String::from("records ") + nrec.to_str() + " bad 0\n";
        report.push_str(line);
    } else {
        let mut bl = String::new();
        for j in 0..bad_list.len() {
            if j > 0 {
                bl.push_str(", ");
            }
            bl.push_str(bad_list[j].to_str());
        }
        let line: Str = String::from("records ")
            + nrec.to_str()
            + " bad "
            + bad_list.len().to_str()
            + ": "
            + bl
            + "\n";
        report.push_str(line);
    }

    out.write("clean.csv", clean)?;
    Ok(report)
}

// Assumes the kio std API: Dir::entries/open_dir/read, Kv::get/set/remove,
// Str::from_utf8/to_lowercase/split/splitn/trim. Adjust names if they differ.

struct Rec {
    hash: Str,
    words: BTreeSet<Str>,
    changed: bool,
}

fn hash_bytes(data: &Vec<u8>) -> u64 {
    let mut h: u64 = 14695981039346656037;
    for b in data.iter() {
        h = h ^ (*b as u64);
        h = h.wrapping_mul(1099511628211);
    }
    h
}

fn flush(cur: &mut Vec<u8>, out: &mut BTreeSet<Str>) -> Result<(), Str> {
    if !cur.is_empty() {
        let w = Str::from_utf8(cur.clone())?.to_lowercase();
        out.insert(w);
        cur.clear();
    }
    Ok(())
}

fn words_of(data: &Vec<u8>) -> Result<BTreeSet<Str>, Str> {
    let mut out: BTreeSet<Str> = BTreeSet::new();
    let mut cur: Vec<u8> = Vec::new();
    for b in data.iter() {
        let c = *b;
        let alnum = (c >= b'a' && c <= b'z') || (c >= b'A' && c <= b'Z') || (c >= b'0' && c <= b'9');
        let sep = c < 128 && !alnum;
        if sep {
            flush(&mut cur, &mut out)?;
        } else {
            cur.push(c);
        }
    }
    flush(&mut cur, &mut out)?;
    Ok(out)
}

fn load_manifest(index: &Kv) -> Result<BTreeMap<Str, Rec>, Str> {
    let mut m: BTreeMap<Str, Rec> = BTreeMap::new();
    if let Some(text) = index.get(&"manifest".to_string())? {
        for line in text.split('\n') {
            if line.is_empty() {
                continue;
            }
            let parts: Vec<Str> = line.splitn(3, '\t').map(|s| s.to_string()).collect();
            let words: BTreeSet<Str> = parts[2]
                .split(' ')
                .filter(|w| !w.is_empty())
                .map(|w| w.to_string())
                .collect();
            m.insert(
                parts[1].clone(),
                Rec { hash: parts[0].clone(), words: words, changed: false },
            );
        }
    }
    Ok(m)
}

fn post_get(index: &Kv, word: &Str) -> Result<BTreeSet<Str>, Str> {
    let key = format!("w:{}", word);
    let mut set: BTreeSet<Str> = BTreeSet::new();
    if let Some(v) = index.get(&key)? {
        for p in v.split('\n') {
            if !p.is_empty() {
                set.insert(p.to_string());
            }
        }
    }
    Ok(set)
}

fn post_put(index: &Kv, word: &Str, set: &BTreeSet<Str>) -> Result<(), Str> {
    let key = format!("w:{}", word);
    if set.is_empty() {
        index.remove(&key)?;
    } else {
        let mut v = String::new();
        for p in set.iter() {
            v.push_str(p);
            v.push('\n');
        }
        index.set(&key, &v)?;
    }
    Ok(())
}

fn post_add(index: &Kv, word: &Str, path: &Str) -> Result<(), Str> {
    let mut set = post_get(index, word)?;
    set.insert(path.clone());
    post_put(index, word, &set)
}

fn post_del(index: &Kv, word: &Str, path: &Str) -> Result<(), Str> {
    let mut set = post_get(index, word)?;
    set.remove(path);
    post_put(index, word, &set)
}

fn walk(
    dir: &Dir,
    prefix: &Str,
    old: &BTreeMap<Str, Rec>,
    seen: &mut BTreeMap<Str, Rec>,
) -> Result<(), Str> {
    for e in dir.entries()? {
        let name = e.name();
        let path = if prefix.is_empty() {
            name.clone()
        } else {
            format!("{}/{}", prefix, name)
        };
        if e.is_dir() {
            let sub = dir.open_dir(&name)?;
            walk(&sub, &path, old, seen)?;
        } else {
            let data = dir.read(&name)?;
            let h = format!("{}", hash_bytes(&data));
            let same = match old.get(&path) {
                Some(r) => r.hash == h,
                None => false,
            };
            if same {
                let words = old.get(&path).unwrap().words.clone();
                seen.insert(path, Rec { hash: h, words: words, changed: false });
            } else {
                let words = words_of(&data)?;
                seen.insert(path, Rec { hash: h, words: words, changed: true });
            }
        }
    }
    Ok(())
}

fn main(docs: Dir, queries: Dir, index: Kv) -> Result<Str, Str> {
    let old = load_manifest(&index)?;
    let mut seen: BTreeMap<Str, Rec> = BTreeMap::new();
    walk(&docs, &String::new(), &old, &mut seen)?;

    let mut out = String::new();
    let mut unchanged: usize = 0;

    let mut paths: BTreeSet<Str> = BTreeSet::new();
    for p in old.keys() {
        paths.insert(p.clone());
    }
    for p in seen.keys() {
        paths.insert(p.clone());
    }

    for path in paths.iter() {
        match (old.get(path), seen.get(path)) {
            (None, Some(s)) => {
                out.push_str(&format!("added {}\n", path));
                for w in s.words.iter() {
                    post_add(&index, w, path)?;
                }
            }
            (Some(o), None) => {
                out.push_str(&format!("removed {}\n", path));
                for w in o.words.iter() {
                    post_del(&index, w, path)?;
                }
            }
            (Some(o), Some(s)) => {
                if s.changed {
                    out.push_str(&format!("changed {}\n", path));
                    for w in o.words.iter() {
                        if !s.words.contains(w) {
                            post_del(&index, w, path)?;
                        }
                    }
                    for w in s.words.iter() {
                        if !o.words.contains(w) {
                            post_add(&index, w, path)?;
                        }
                    }
                } else {
                    unchanged += 1;
                }
            }
            (None, None) => {}
        }
    }
    out.push_str(&format!("unchanged {}\n", unchanged));

    // Save the new manifest: hash, path, words for every current file.
    let mut text = String::new();
    for (path, s) in seen.iter() {
        let ws: Vec<Str> = s.words.iter().cloned().collect();
        text.push_str(&format!("{}\t{}\t{}\n", s.hash, path, ws.join(" ")));
    }
    index.set(&"manifest".to_string(), &text)?;

    // Answer queries against the updated index.
    let qbytes = queries.read(&"queries.txt".to_string())?;
    let qtext = Str::from_utf8(qbytes)?;
    for raw in qtext.split('\n') {
        let line = raw.trim_end_matches('\r');
        if line.trim().is_empty() {
            continue;
        }
        let words = words_of(&line.as_bytes().to_vec())?;
        let mut hits: Option<BTreeSet<Str>> = None;
        for w in words.iter() {
            let p = post_get(&index, w)?;
            hits = Some(match hits {
                None => p,
                Some(h) => {
                    let inter: BTreeSet<Str> = h.intersection(&p).cloned().collect();
                    inter
                }
            });
        }
        let matched: BTreeSet<Str> = match hits {
            None => {
                let mut all: BTreeSet<Str> = BTreeSet::new();
                for p in seen.keys() {
                    all.insert(p.clone());
                }
                all
            }
            Some(h) => h,
        };
        if matched.is_empty() {
            out.push_str(&format!("{}: none\n", line));
        } else {
            let list: Vec<Str> = matched.into_iter().collect();
            out.push_str(&format!("{}: {}\n", line, list.join(", ")));
        }
    }

    Ok(out)
}

// Assumes the kio std API: Dir::entries/open_dir/read, Kv::get/set/remove,
// Str::from_utf8/to_lowercase/split/splitn/trim. Adjust names if they differ.
// No reference types are used: values are passed by value and returned.

struct Rec {
    hash: Str,
    words: BTreeSet<Str>,
}

fn hash_bytes(data: Vec<u8>) -> u64 {
    let mut h: u64 = 14695981039346656037;
    for b in data.iter() {
        h = h ^ (*b as u64);
        h = h.wrapping_mul(1099511628211);
    }
    h
}

fn words_of(data: Vec<u8>) -> Result<BTreeSet<Str>, Str> {
    let mut out: BTreeSet<Str> = BTreeSet::new();
    let mut cur: Vec<u8> = Vec::new();
    for b in data.iter() {
        let c = *b;
        let alnum = (c >= b'a' && c <= b'z') || (c >= b'A' && c <= b'Z') || (c >= b'0' && c <= b'9');
        if c < 128 && !alnum {
            if !cur.is_empty() {
                out.insert(Str::from_utf8(cur)?.to_lowercase());
                cur = Vec::new();
            }
        } else {
            cur.push(c);
        }
    }
    if !cur.is_empty() {
        out.insert(Str::from_utf8(cur)?.to_lowercase());
    }
    Ok(out)
}

fn parse_manifest(text: Str) -> BTreeMap<Str, Rec> {
    let mut m: BTreeMap<Str, Rec> = BTreeMap::new();
    for line in text.split('\n') {
        if line.is_empty() {
            continue;
        }
        let parts: Vec<Str> = line.splitn(3, '\t').map(|s| s.to_string()).collect();
        if parts.len() < 3 {
            continue;
        }
        let words: BTreeSet<Str> = parts[2]
            .split(' ')
            .filter(|w| !w.is_empty())
            .map(|w| w.to_string())
            .collect();
        m.insert(parts[1].clone(), Rec { hash: parts[0].clone(), words: words });
    }
    m
}

fn set_of(text: Str) -> BTreeSet<Str> {
    let mut s: BTreeSet<Str> = BTreeSet::new();
    for p in text.split('\n') {
        if !p.is_empty() {
            s.insert(p.to_string());
        }
    }
    s
}

fn text_of(set: BTreeSet<Str>) -> Str {
    let mut v = String::new();
    for p in set.iter() {
        v.push_str(p);
        v.push('\n');
    }
    v
}

fn add_to(map: BTreeMap<Str, BTreeSet<Str>>, w: Str, p: Str) -> BTreeMap<Str, BTreeSet<Str>> {
    let mut m = map;
    let mut s: BTreeSet<Str> = match m.get(w.clone()) {
        Some(x) => x.clone(),
        None => BTreeSet::new(),
    };
    s.insert(p);
    m.insert(w, s);
    m
}

fn intersect(h: BTreeSet<Str>, p: BTreeSet<Str>) -> BTreeSet<Str> {
    let mut r: BTreeSet<Str> = BTreeSet::new();
    for x in h.iter() {
        if p.contains(x.clone()) {
            r.insert(x.clone());
        }
    }
    r
}

fn walk(dir: Dir, prefix: Str, acc: BTreeMap<Str, Vec<u8>>) -> Result<BTreeMap<Str, Vec<u8>>, Str> {
    let mut acc = acc;
    for e in dir.entries()? {
        let name = e.name();
        let path = if prefix.is_empty() {
            name.clone()
        } else {
            format!("{}/{}", prefix, name)
        };
        if e.is_dir() {
            let sub = dir.open_dir(name.clone())?;
            acc = walk(sub, path, acc)?;
        } else {
            let data = dir.read(name.clone())?;
            acc.insert(path, data);
        }
    }
    Ok(acc)
}

fn main(docs: Dir, queries: Dir, index: Kv) -> Result<Str, Str> {
    let contents = walk(docs, String::new(), BTreeMap::new())?;

    let mut old: BTreeMap<Str, Rec> = BTreeMap::new();
    if let Some(text) = index.get("manifest".to_string())? {
        old = parse_manifest(text);
    }

    // Build the new state: unchanged files reuse their stored words.
    let mut seen: BTreeMap<Str, Rec> = BTreeMap::new();
    for (path, data) in contents.into_iter() {
        let h = format!("{}", hash_bytes(data.clone()));
        let (same, prev_words) = match old.get(path.clone()) {
            Some(r) => {
                if r.hash == h {
                    (true, r.words.clone())
                } else {
                    (false, BTreeSet::new())
                }
            }
            None => (false, BTreeSet::new()),
        };
        let words = if same { prev_words } else { words_of(data)? };
        seen.insert(path, Rec { hash: h, words: words });
    }

    let mut paths: BTreeSet<Str> = BTreeSet::new();
    for p in old.keys() {
        paths.insert(p.clone());
    }
    for p in seen.keys() {
        paths.insert(p.clone());
    }

    let mut out = String::new();
    let mut unchanged: usize = 0;
    let mut adds: BTreeMap<Str, BTreeSet<Str>> = BTreeMap::new();
    let mut dels: BTreeMap<Str, BTreeSet<Str>> = BTreeMap::new();

    for path in paths.iter() {
        let (in_old, o_hash, o_words) = match old.get(path.clone()) {
            Some(r) => (true, r.hash.clone(), r.words.clone()),
            None => (false, String::new(), BTreeSet::new()),
        };
        let (in_new, s_hash, s_words) = match seen.get(path.clone()) {
            Some(r) => (true, r.hash.clone(), r.words.clone()),
            None => (false, String::new(), BTreeSet::new()),
        };

        if in_old && in_new {
            if o_hash == s_hash {
                unchanged += 1;
            } else {
                out.push_str(&format!("changed {}\n", path));
                for w in o_words.iter() {
                    if !s_words.contains(w.clone()) {
                        dels = add_to(dels, w.clone(), path.clone());
                    }
                }
                for w in s_words.iter() {
                    if !o_words.contains(w.clone()) {
                        adds = add_to(adds, w.clone(), path.clone());
                    }
                }
            }
        } else if in_new {
            out.push_str(&format!("added {}\n", path));
            for w in s_words.iter() {
                adds = add_to(adds, w.clone(), path.clone());
            }
        } else if in_old {
            out.push_str(&format!("removed {}\n", path));
            for w in o_words.iter() {
                dels = add_to(dels, w.clone(), path.clone());
            }
        }
    }
    out.push_str(&format!("unchanged {}\n", unchanged));

    // Apply posting-list changes, one read-modify-write per touched word.
    let mut touched: BTreeSet<Str> = BTreeSet::new();
    for w in adds.keys() {
        touched.insert(w.clone());
    }
    for w in dels.keys() {
        touched.insert(w.clone());
    }
    for w in touched.iter() {
        let key = format!("w:{}", w);
        let mut set: BTreeSet<Str> = match index.get(key.clone())? {
            Some(t) => set_of(t),
            None => BTreeSet::new(),
        };
        if let Some(d) = dels.get(w.clone()) {
            for p in d.iter() {
                set.remove(p.clone());
            }
        }
        if let Some(a) = adds.get(w.clone()) {
            for p in a.iter() {
                set.insert(p.clone());
            }
        }
        if set.is_empty() {
            index.remove(key)?;
        } else {
            index.set(key, text_of(set))?;
        }
    }

    // Save the new manifest: hash, path, words for every current file.
    let mut text = String::new();
    for (path, s) in seen.iter() {
        let ws: Vec<Str> = s.words.iter().cloned().collect();
        text.push_str(&format!("{}\t{}\t{}\n", s.hash, path, ws.join(" ")));
    }
    index.set("manifest".to_string(), text)?;

    // Answer queries against the updated index.
    let qbytes = queries.read("queries.txt".to_string())?;
    let qtext = Str::from_utf8(qbytes)?;
    for raw in qtext.split('\n') {
        let line: Str = raw.trim_end_matches('\r').to_string();
        if line.trim().is_empty() {
            continue;
        }
        let words = words_of(line.as_bytes().to_vec())?;
        let mut hits: Option<BTreeSet<Str>> = None;
        for w in words.iter() {
            let key = format!("w:{}", w);
            let p: BTreeSet<Str> = match index.get(key)? {
                Some(t) => set_of(t),
                None => BTreeSet::new(),
            };
            hits = Some(match hits {
                None => p,
                Some(h) => intersect(h, p),
            });
        }
        let matched: BTreeSet<Str> = match hits {
            None => {
                let mut all: BTreeSet<Str> = BTreeSet::new();
                for p in seen.keys() {
                    all.insert(p.clone());
                }
                all
            }
            Some(h) => h,
        };
        if matched.is_empty() {
            out.push_str(&format!("{}: none\n", line));
        } else {
            let list: Vec<Str> = matched.into_iter().collect();
            out.push_str(&format!("{}: {}\n", line, list.join(", ")));
        }
    }

    Ok(out)
}

// Assumes the kio std API: Dir::entries/open_dir/read, Kv::get/set/remove,
// Str::from_utf8/to_lowercase/split/splitn/trim. Adjust names if they differ.
// No reference types are used: values are passed by value and returned.

struct Rec {
    hash: Str,
    words: BTreeSet<Str>,
}

fn hash_bytes(data: Vec<u8>) -> u64 {
    // FNV-style hash. Constants are kept below 2^63 so every literal fits in Int (i64).
    let mut h: u64 = 1469598103934665603;
    for b in data.iter() {
        h = h ^ (*b as u64);
        h = h.wrapping_mul(1099511628211);
    }
    h
}

fn words_of(data: Vec<u8>) -> Result<BTreeSet<Str>, Str> {
    let mut out: BTreeSet<Str> = BTreeSet::new();
    let mut cur: Vec<u8> = Vec::new();
    for b in data.iter() {
        let c = *b;
        let alnum = (c >= b'a' && c <= b'z') || (c >= b'A' && c <= b'Z') || (c >= b'0' && c <= b'9');
        if c < 128 && !alnum {
            if !cur.is_empty() {
                out.insert(Str::from_utf8(cur)?.to_lowercase());
                cur = Vec::new();
            }
        } else {
            cur.push(c);
        }
    }
    if !cur.is_empty() {
        out.insert(Str::from_utf8(cur)?.to_lowercase());
    }
    Ok(out)
}

fn parse_manifest(text: Str) -> BTreeMap<Str, Rec> {
    let mut m: BTreeMap<Str, Rec> = BTreeMap::new();
    for line in text.split('\n') {
        if line.is_empty() {
            continue;
        }
        let parts: Vec<Str> = line.splitn(3, '\t').map(|s| s.to_string()).collect();
        if parts.len() < 3 {
            continue;
        }
        let words: BTreeSet<Str> = parts[2]
            .split(' ')
            .filter(|w| !w.is_empty())
            .map(|w| w.to_string())
            .collect();
        m.insert(parts[1].clone(), Rec { hash: parts[0].clone(), words: words });
    }
    m
}

fn set_of(text: Str) -> BTreeSet<Str> {
    let mut s: BTreeSet<Str> = BTreeSet::new();
    for p in text.split('\n') {
        if !p.is_empty() {
            s.insert(p.to_string());
        }
    }
    s
}

fn text_of(set: BTreeSet<Str>) -> Str {
    let mut v = String::new();
    for p in set.iter() {
        v.push_str(p);
        v.push('\n');
    }
    v
}

fn add_to(map: BTreeMap<Str, BTreeSet<Str>>, w: Str, p: Str) -> BTreeMap<Str, BTreeSet<Str>> {
    let mut m = map;
    let mut s: BTreeSet<Str> = match m.get(w.clone()) {
        Some(x) => x.clone(),
        None => BTreeSet::new(),
    };
    s.insert(p);
