        text.push_str(&format!("{}\t{}\t{}\n", s.hash, path, ws.join(" ")));
    }
    index.set("manifest".to_string(), text)?;

    // Answer queries against the updated index.
    let qbytes = queries.read("queries.txt".to_string())?;
    let qtext = Str::from_utf8(qbytes)?;
    for raw in qtext.split("\n") {
        let line: Str = raw.trim_end_matches("\r").to_string();
        if line.trim().is_empty() {
            continue;
        }
        let words = words_of(line.as_bytes().to_vec())?;
        let mut hits: Option<BTreeSet<Str>> = None;
        for w in words.iter() {
            let key = format!("w:{}", w);
            let p: BTreeSet<Str> = match index.get(key)? {
                Some(t) => set_of(t),
                None => BTreeSet::new(),
            };
            hits = Some(match hits {
                None => p,
                Some(h) => intersect(h, p),
            });
        }
        let matched: BTreeSet<Str> = match hits {
            None => {
                let mut all: BTreeSet<Str> = BTreeSet::new();
                for p in seen.keys() {
                    all.insert(p.clone());
                }
                all
            }
            Some(h) => h,
        };
        if matched.is_empty() {
            out.push_str(&format!("{}: none\n", line));
        } else {
            let list: Vec<Str> = matched.into_iter().collect();
            out.push_str(&format!("{}: {}\n", line, list.join(", ")));
        }
    }

    Ok(out)
}

