//   db.exec(sql, params) -> Result<(), Str>; db.query(sql, params) -> Result<Vec<Row>, Str>
//   Row.get_str(col) / Row.get_int(col) -> Result<T, Str>
//   json::parse(&Str) -> Result<Json, Str>
//   Json.get(key) -> Option<Json>; get_str(key) / get_int(key) / get_array(key) -> Option<T>
//   Json.as_str() -> Option<Str>; Json.is_null() -> bool; Json.iter() over arrays

struct Counts {
    applied: i64,
    stale: i64,
    invalid: i64,
}

// Outer None: the page is invalid. Inner None: next is null (last page).
fn next_of(page: &Json) -> Option<Option<Str>> {
    match page.get("next") {
        None => None,
        Some(j) => {
            if j.is_null() {
                Some(None)
            } else {
                match j.as_str() {
                    Some(s) => Some(Some(s)),
                    None => None,
                }
            }
        }
    }
}

fn apply_change(db: &Db, ch: &Json, c: &mut Counts) -> Result<(), Str> {
    let (op, sku, version) = match (ch.get_str("op"), ch.get_str("sku"), ch.get_int("version")) {
        (Some(o), Some(s), Some(v)) => (o, s, v),
        _ => {
            c.invalid += 1;
            return Ok(());
        }
    };

    let (name, qty) = if op == "upsert" {
        match (ch.get_str("name"), ch.get_int("qty")) {
            (Some(n), Some(q)) => (n, q),
            _ => {
                c.invalid += 1;
                return Ok(());
            }
        }
    } else if op == "delete" {
        ("".to_string(), 0)
    } else {
        c.invalid += 1;
        return Ok(());
    };

    // A stale change is one whose version is not greater than the last applied
    // version for this sku. Tombstones keep their version, so deletes are remembered.
    let rows = db.query("SELECT version FROM items WHERE sku = ?", [sku.clone()])?;
    if rows.len() > 0 {
        let last = rows[0].get_int("version")?;
        if version <= last {
            c.stale += 1;
            return Ok(());
        }
    }

    let live: i64 = if op == "upsert" { 1 } else { 0 };
    db.exec(
        "INSERT OR REPLACE INTO items (sku, name, qty, version, live) VALUES (?, ?, ?, ?, ?)",
        [sku, name, qty, version, live],
    )?;
    c.applied += 1;
    Ok(())
}

fn apply_page(
    db: &Db,
    changes: &Vec<Json>,
    cursor: &Str,
    next: &Option<Str>,
    c: &mut Counts,
) -> Result<(), Str> {
    for ch in changes.iter() {
        apply_change(db, ch, c)?;
    }
    // Store the new cursor with the changes. On the last page, keep the last
    // page's own cursor so the next run starts there again.
    let new_cursor = match next {
        Some(n) => n.clone(),
        None => cursor.clone(),
    };
    db.exec(
        "INSERT OR REPLACE INTO meta (key, value) VALUES ('cursor', ?)",
        [new_cursor],
    )?;
    Ok(())
}

fn main(api: Http, db: Db) -> Result<Str, Str> {
    db.exec(
        "CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)",
        [],
    )?;
    db.exec(
        "CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL, version INTEGER NOT NULL, live INTEGER NOT NULL)",
        [],
    )?;

    let mut cursor: Str = "0".to_string();
    let saved = db.query("SELECT value FROM meta WHERE key = 'cursor'", [])?;
    if saved.len() > 0 {
        match saved[0].get_str("value")? {
            v => cursor = v,
        }
    }

    let mut pages: i64 = 0;
    let mut totals = Counts { applied: 0, stale: 0, invalid: 0 };
    let mut status = "complete".to_string();

    loop {
        let resp = match api.get(&format!("/changes?cursor={}", cursor)) {
            Ok(r) => r,
            Err(_) => {
                status = format!("stopped at {} (no response)", cursor);
                break;
            }
        };
        if resp.status != 200 {
            status = format!("stopped at {} (status {})", cursor, resp.status);
            break;
        }

        let page = match json::parse(&resp.body) {
            Ok(j) => j,
            Err(_) => {
                status = format!("stopped at {} (invalid page)", cursor);
                break;
            }
        };
        let changes = match page.get_array("changes") {
            Some(a) => a,
            None => {
                status = format!("stopped at {} (invalid page)", cursor);
                break;
            }
        };
        let next: Option<Str> = match next_of(&page) {
            Some(n) => n,
            None => {
                status = format!("stopped at {} (invalid page)", cursor);
                break;
            }
        };

        // Apply the page and advance the cursor in one transaction.
        db.exec("BEGIN", [])?;
        let mut c = Counts { applied: 0, stale: 0, invalid: 0 };
        if let Err(e) = apply_page(&db, &changes, &cursor, &next, &mut c) {
            let _ = db.exec("ROLLBACK", []);
            return Err(e);
        }
        db.exec("COMMIT", [])?;

        pages += 1;
        totals.applied += c.applied;
        totals.stale += c.stale;
        totals.invalid += c.invalid;

        match next {
            Some(n) => cursor = n,
            None => {
                status = "complete".to_string();
                break;
            }
        }
    }

    let mut out = format!(
        "pages {} applied {} stale {} invalid {}\n{}",
        pages, totals.applied, totals.stale, totals.invalid, status
    );

    let items = db.query(
        "SELECT sku, qty, name FROM items WHERE live = 1 ORDER BY sku",
        [],
    )?;
    for r in items.iter() {
        let sku = r.get_str("sku")?;
        let qty = r.get_int("qty")?;
        let name = r.get_str("name")?;
        out = format!("{}\n{} {} {}", out, sku, qty, name);
    }

    Ok(out)
}

