            let is_delete = op == "delete";
            if !is_upsert && !is_delete {
                page_invalid += 1;
                continue;
            }

            let mut name: Str = "".to_string();
            let mut qty: i64 = 0;
            if is_upsert {
                match (ch.get_str("name"), ch.get_int("qty")) {
                    (Some(n), Some(q)) => {
                        name = n;
                        qty = q;
                    }
                    _ => {
                        page_invalid += 1;
                        continue;
                    }
                }
            }

            // Tombstones keep their version, so a delete is remembered and
            // an older upsert cannot bring the item back.
            let rows = match db.query("SELECT version FROM items WHERE sku = ?", [sku.clone()]) {
                Ok(r) => r,
                Err(e) => {
                    let _ = db.exec("ROLLBACK", []);
                    return Err(e);
                }
            };
            let mut is_stale = false;
            if rows.len() > 0 {
                let last = match rows[0].get_int("version") {
                    Ok(v) => v,
                    Err(e) => {
                        let _ = db.exec("ROLLBACK", []);
                        return Err(e);
                    }
                };
                if version <= last {
                    is_stale = true;
                }
            }
            if is_stale {
                page_stale += 1;
                continue;
            }

            let live: i64 = if is_upsert { 1 } else { 0 };
            match db.exec(
                "INSERT OR REPLACE INTO items (sku, name, qty, version, live) VALUES (?, ?, ?, ?, ?)",
                [sku, name, qty, version, live],
            ) {
                Ok(_) => {}
                Err(e) => {
                    let _ = db.exec("ROLLBACK", []);
                    return Err(e);
                }
            }
            page_applied += 1;
        }

        // On the last page (next is null), keep this page's own cursor so the
        // next run starts there again.
        let new_cursor: Str = match next.clone() {
            Some(n) => n,
            None => cursor.clone(),
        };
        match db.exec(
            "INSERT OR REPLACE INTO meta (key, value) VALUES ('cursor', ?)",
            [new_cursor],
        ) {
            Ok(_) => {}
            Err(e) => {
                let _ = db.exec("ROLLBACK", []);
                return Err(e);
            }
        }
        db.exec("COMMIT", [])?;

        pages += 1;
        applied += page_applied;
        stale += page_stale;
        invalid += page_invalid;

        match next {
            Some(n) => cursor = n,
            None => {
                status = "complete".to_string();
                break;
            }
        }
    }

    let mut out: Str = "pages ".to_string()
        + pages.to_str()
        + " applied "
        + applied.to_str()
        + " stale "
        + stale.to_str()
        + " invalid "
        + invalid.to_str()
        + "\n"
        + status;

    let items = db.query(
        "SELECT sku, qty, name FROM items WHERE live = 1 ORDER BY sku",
        [],
    )?;
    for r in items.iter() {
        let sku = r.get_str("sku")?;
        let qty = r.get_int("qty")?;
        let name = r.get_str("name")?;
        out = out + "\n" + sku + " " + qty.to_str() + " " + name;
    }

    Ok(out)
}

// Assumed kio surface (names may differ from the actual std API):
//   api.get(path) -> Result<Resp, Str>, with Resp.status: i64 and Resp.body: Str
//   db.exec(sql, params) -> Result<(), Str>; db.query(sql, params) -> Result<Vec<Row>, Str>
//   Row.get_str(col) / Row.get_int(col) -> Result<T, Str>
//   json::parse(Str) -> Result<Json, Str>
//   Json.get(key) -> Option<Json>; get_str(key) / get_int(key) / get_array(key) -> Option<T>
//   Json.as_str() -> Option<Str>; Json.is_null() -> bool; Json.iter() over arrays
//   Str and i64 provide to_str() for building text with `+`.

// Outer None: the page is invalid. Inner None: next is null (last page).
fn next_of(page: Json) -> Option<Option<Str>> {
    match page.get("next") {
        None => None,
        Some(j) => {
            if j.is_null() {
                Some(None)
            } else {
                match j.as_str() {
                    Some(s) => Some(Some(s)),
                    None => None,
                }
            }
        }
    }
}

fn main(api: Http, db: Db) -> Result<Str, Str> {
    db.exec(
        "CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)",
        [],
    )?;
    db.exec(
        "CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL, version INTEGER NOT NULL, live INTEGER NOT NULL)",
        [],
    )?;

    let mut cursor: Str = "0".to_string();
    let saved = db.query("SELECT value FROM meta WHERE key = 'cursor'", [])?;
    if saved.len() > 0 {
        cursor = saved[0].get_str("value")?;
    }

    let mut pages: i64 = 0;
    let mut applied: i64 = 0;
    let mut stale: i64 = 0;
    let mut invalid: i64 = 0;
    let mut status: Str = "complete".to_string();

    loop {
        let resp = match api.get("/changes?cursor=".to_string() + cursor.clone()) {
            Ok(r) => r,
            Err(_) => {
                status = "stopped at ".to_string() + cursor.clone() + " (no response)";
                break;
            }
        };
        if resp.status != 200 {
            status = "stopped at ".to_string() + cursor.clone() + " (status " + resp.status.to_str() + ")";
            break;
        }

        let page = match json::parse(resp.body.clone()) {
            Ok(j) => j,
            Err(_) => {
                status = "stopped at ".to_string() + cursor.clone() + " (invalid page)";
                break;
            }
        };
        let changes = match page.get_array("changes") {
            Some(a) => a,
            None => {
                status = "stopped at ".to_string() + cursor.clone() + " (invalid page)";
                break;
            }
        };
        let next: Option<Str> = match next_of(page) {
            Some(n) => n,
            None => {
                status = "stopped at ".to_string() + cursor.clone() + " (invalid page)";
                break;
            }
        };

        // Apply the page and advance the cursor in one transaction.
        db.exec("BEGIN", [])?;
        let mut page_applied: i64 = 0;
        let mut page_stale: i64 = 0;
        let mut page_invalid: i64 = 0;

        for ch in changes.iter() {
            let op = match ch.get_str("op") {
                Some(o) => o,
                None => {
                    page_invalid += 1;
                    continue;
                }
            };
            let sku = match ch.get_str("sku") {
                Some(s) => s,
                None => {
                    page_invalid += 1;
                    continue;
                }
            };
            let version = match ch.get_int("version") {
                Some(v) => v,
                None => {
                    page_invalid += 1;
                    continue;
                }
            };

            let is_upsert = op == "upsert";
            let is_delete = op == "delete";
            if !is_upsert && !is_delete {
                page_invalid += 1;
                continue;
            }

            let mut name: Str = "".to_string();
            let mut qty: i64 = 0;
            if is_upsert {
                let n = match ch.get_str("name") {
                    Some(x) => x,
                    None => {
                        page_invalid += 1;
                        continue;
                    }
                };
                let q = match ch.get_int("qty") {
                    Some(x) => x,
                    None => {
                        page_invalid += 1;
                        continue;
                    }
                };
                name = n;
                qty = q;
            }

            // Tombstones keep their version, so a delete is remembered and
            // an older upsert cannot bring the item back.
            let rows = match db.query("SELECT version FROM items WHERE sku = ?", [sku.clone()]) {
                Ok(r) => r,
                Err(e) => {
                    let _ = db.exec("ROLLBACK", []);
                    return Err(e);
                }
            };
            let mut is_stale = false;
            if rows.len() > 0 {
                let last = match rows[0].get_int("version") {
                    Ok(v) => v,
                    Err(e) => {
                        let _ = db.exec("ROLLBACK", []);
                        return Err(e);
                    }
                };
                if version <= last {
                    is_stale = true;
                }
            }
            if is_stale {
                page_stale += 1;
                continue;
            }

            let live: i64 = if is_upsert { 1 } else { 0 };
            match db.exec(
                "INSERT OR REPLACE INTO items (sku, name, qty, version, live) VALUES (?, ?, ?, ?, ?)",
                [sku, name, qty, version, live],
            ) {
                Ok(_) => {}
                Err(e) => {
                    let _ = db.exec("ROLLBACK", []);
                    return Err(e);
                }
            }
            page_applied += 1;
        }

        // On the last page (next is null), keep this page's own cursor so the
        // next run starts there again.
        let new_cursor: Str = match next.clone() {
            Some(n) => n,
            None => cursor.clone(),
        };
        match db.exec(
            "INSERT OR REPLACE INTO meta (key, value) VALUES ('cursor', ?)",
            [new_cursor],
        ) {
            Ok(_) => {}
            Err(e) => {
                let _ = db.exec("ROLLBACK", []);
                return Err(e);
            }
        }
        db.exec("COMMIT", [])?;

        pages += 1;
        applied += page_applied;
        stale += page_stale;
        invalid += page_invalid;

        match next {
            Some(n) => cursor = n,
            None => {
                status = "complete".to_string();
                break;
            }
        }
    }

    let mut out: Str = "pages ".to_string()
        + pages.to_str()
        + " applied "
        + applied.to_str()
        + " stale "
        + stale.to_str()
        + " invalid "
        + invalid.to_str()
        + "\n"
        + status;

    let items = db.query(
        "SELECT sku, qty, name FROM items WHERE live = 1 ORDER BY sku",
        [],
    )?;
    for r in items.iter() {
        let sku = r.get_str("sku")?;
        let qty = r.get_int("qty")?;
        let name = r.get_str("name")?;
        out = out + "\n" + sku + " " + qty.to_str() + " " + name;
    }

    Ok(out)
}

use json;

struct Job {
    id: String,
    priority: i64,
    attempts: i64,
    due: i64,
    state: String,
}

fn encode(j: &Job) -> String {
    format!("{}|{}|{}|{}", j.priority, j.attempts, j.due, j.state)
}

fn decode(id: &str, s: &str) -> Job {
    let parts: Vec<&str> = s.split('|').collect();
    Job {
        id: id.to_string(),
        priority: parts[0].parse::<i64>().unwrap(),
        attempts: parts[1].parse::<i64>().unwrap(),
        due: parts[2].parse::<i64>().unwrap(),
        state: parts[3].to_string(),
    }
}

fn load_index(queue: &Kv) -> Vec<String> {
    match queue.get("index") {
        Some(s) => s.split('\n').filter(|x| !x.is_empty()).map(|x| x.to_string()).collect(),
        None => Vec::new(),
    }
}

fn save_index(queue: &Kv, index: &Vec<String>) {
    queue.set("index", &index.join("\n"));
}

fn load_job(queue: &Kv, id: &str) -> Job {
    let key = format!("job:{}", id);
    decode(id, &queue.get(&key).unwrap())
}

fn save_job(queue: &Kv, job: &Job) {
    let key = format!("job:{}", job.id);
    queue.set(&key, &encode(job));
}

fn load_script(input: &Dir) -> Vec<(String, Vec<String>)> {
    let mut result: Vec<(String, Vec<String>)> = Vec::new();
    if let Ok(text) = input.read("script.json") {
        if let Ok(v) = json::parse(&text) {
            for (k, arr) in v.entries() {
                let mut outs: Vec<String> = Vec::new();
                for item in arr.items() {
                    if let Some(s) = item.as_str() {
                        outs.push(s.to_string());
                    }
                }
                result.push((k.to_string(), outs));
            }
        }
    }
    result
}

fn outcome_for(script: &Vec<(String, Vec<String>)>, id: &str, attempt: usize) -> String {
    for (k, list) in script.iter() {
        if k == id {
            if list.is_empty() {
                return "ok".to_string();
            }
            let idx = if attempt < list.len() { attempt } else { list.len() - 1 };
            return list[idx].clone();
        }
    }
    "ok".to_string()
}

fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, Str> {
    let now: i64 = clock.now();
    let mut index: Vec<String> = load_index(&queue);
    let mut out: Vec<String> = Vec::new();

    // Enqueue phase
    if let Ok(text) = input.read("enqueue.jsonl") {
        for (i, line) in text.lines().enumerate() {
            let n = i + 1;
            if line.trim().is_empty() {
                continue;
            }
            let mut parsed_ok = false;
            if let Ok(v) = json::parse(line) {
                let id_opt = v.get("id").and_then(|x| x.as_str());
                let pr_opt = v.get("priority").and_then(|x| x.as_int());
                if let (Some(id), Some(priority)) = (id_opt, pr_opt) {
                    parsed_ok = true;
                    let id = id.to_string();
                    if index.contains(&id) {
                        out.push("duplicate ID".to_string());
                    } else {
                        let job = Job {
                            id: id.clone(),
                            priority: priority,
                            attempts: 0,
                            due: now,
                            state: "pending".to_string(),
                        };
                        save_job(&queue, &job);
                        index.push(id);
                        save_index(&queue, &index);
                    }
                }
            }
            if !parsed_ok {
                out.push(format!("invalid line {}", n));
            }
        }
    }

    // Work phase
    let script = load_script(&input);
    let mut jobs: Vec<Job> = index.iter().map(|id| load_job(&queue, id)).collect();

    let mut picks: Vec<usize> = (0..jobs.len())
        .filter(|&i| jobs[i].state == "pending" && jobs[i].due <= now)
        .collect();

    picks.sort_by(|&a, &b| {
        let x = &jobs[a];
        let y = &jobs[b];
        y.priority
            .cmp(&x.priority)
            .then(x.due.cmp(&y.due))
            .then(x.id.cmp(&y.id))
    });
    picks.truncate(5);

    for &i in picks.iter() {
        let job = &mut jobs[i];
        let attempt = job.attempts as usize;
        let res = outcome_for(&script, &job.id, attempt);
        job.attempts += 1;

        if res == "ok" {
            job.state = "done".to_string();
            out.push(format!("done {}", job.id));
        } else if job.attempts == 4 {
            job.state = "dead".to_string();
            out.push(format!("dead {}", job.id));
        } else {
            let wait: i64 = match job.attempts {
                1 => 60,
                2 => 120,
                _ => 240,
            };
            job.due = now + wait * 1000;
            out.push(format!("retry {} in {}", job.id, wait));
        }
        save_job(&queue, job);
    }

    // Summary
    let mut pending: i64 = 0;
    let mut done: i64 = 0;
    let mut dead: i64 = 0;
    for job in jobs.iter() {
        match job.state.as_str() {
            "pending" => pending += 1,
            "done" => done += 1,
            "dead" => dead += 1,
            _ => {}
        }
    }
    out.push(format!("pending {} done {} dead {}", pending, done, dead));

    Ok(out.join("\n"))
}

use json;

struct Job {
    id: Str,
    priority: i64,
