    Job {
        id: id,
        priority: parts[0].parse::<i64>().unwrap(),
        attempts: parts[1].parse::<i64>().unwrap(),
        due: parts[2].parse::<i64>().unwrap(),
        state: parts[3].to_string(),
    }
}

fn load_script(input: Dir) -> Vec<(Str, Vec<Str>)> {
    let mut result: Vec<(Str, Vec<Str>)> = Vec::new();
    if let Ok(text) = input.read("script.json") {
        if let Ok(v) = json::parse(text) {
            for (k, arr) in v.entries() {
                let mut outs: Vec<Str> = Vec::new();
                for item in arr.items() {
                    if let Some(s) = item.as_str() {
                        outs.push(s.to_string());
                    }
                }
                result.push((k.to_string(), outs));
            }
        }
    }
    result
}

fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, Str> {
    let now: i64 = clock.now();
    let mut out: Vec<Str> = Vec::new();

    let mut n: i64 = match queue.get("n") {
        Some(s) => s.parse::<i64>().unwrap(),
        None => 0,
    };

    // Enqueue phase
    if let Ok(text) = input.read("enqueue.jsonl") {
        let mut lineno: i64 = 0;
        for line in text.lines() {
            lineno = lineno + 1;
            if line.trim().is_empty() {
                continue;
            }
            let mut parsed_ok = false;
            if let Ok(v) = json::parse(line) {
                let id_opt = v.get("id").and_then(|x| x.as_str());
                let pr_opt = v.get("priority").and_then(|x| x.as_int());
                if let (Some(id), Some(priority)) = (id_opt, pr_opt) {
                    parsed_ok = true;
                    let key = format!("job:{}", id);
                    if queue.get(key.clone()).is_some() {
                        out.push("duplicate ID".to_string());
                    } else {
                        queue.set(key, encode(priority, 0, now, "pending".to_string()));
                        queue.set(format!("id:{}", n), id.clone());
                        n = n + 1;
                        queue.set("n", format!("{}", n));
                    }
                }
            }
            if !parsed_ok {
                out.push(format!("invalid line {}", lineno));
            }
        }
    }

    // Load all jobs
    let mut jobs: Vec<Job> = Vec::new();
    for k in 0..n {
        let jid: Str = queue.get(format!("id:{}", k)).unwrap();
        let rec: Str = queue.get(format!("job:{}", jid)).unwrap();
        jobs.push(decode(jid, rec));
    }

    // Work phase
    let script = load_script(input);

    for _r in 0..5 {
        // Find the best due pending job
        let mut best: i64 = -1;
        for i in 0..jobs.len() {
            if jobs[i].state == "pending" && jobs[i].due <= now {
                if best < 0 {
                    best = i as i64;
                } else {
                    let b = best as usize;
                    let better = if jobs[i].priority != jobs[b].priority {
                        jobs[i].priority > jobs[b].priority
                    } else if jobs[i].due != jobs[b].due {
                        jobs[i].due < jobs[b].due
                    } else {
                        jobs[i].id < jobs[b].id
                    };
                    if better {
                        best = i as i64;
                    }
                }
            }
        }
        if best < 0 {
            break;
        }

        let k = best as usize;
        let attempt: usize = jobs[k].attempts as usize;
        let jid: Str = jobs[k].id.clone();

        // Look up the scripted outcome for this attempt
        let mut res: Str = "ok".to_string();
        let mut found = false;
        for (sk, list) in script.iter() {
            if !found && sk == jid {
                found = true;
                if list.len() > 0 {
                    let idx: usize = if attempt < list.len() { attempt } else { list.len() - 1 };
                    res = list[idx].clone();
                }
            }
        }

        jobs[k].attempts = jobs[k].attempts + 1;

        if res == "ok" {
            jobs[k].state = "done".to_string();
            out.push(format!("done {}", jid));
        } else if jobs[k].attempts == 4 {
            jobs[k].state = "dead".to_string();
            out.push(format!("dead {}", jid));
        } else {
            let wait: i64 = if jobs[k].attempts == 1 {
                60
            } else if jobs[k].attempts == 2 {
                120
            } else {
                240
            };
            jobs[k].due = now + wait * 1000;
            out.push(format!("retry {} in {}", jid, wait));
        }

        queue.set(
            format!("job:{}", jid),
            encode(jobs[k].priority, jobs[k].attempts, jobs[k].due, jobs[k].state.clone()),
        );
    }

    // Summary
    let mut npend: i64 = 0;
    let mut ndone: i64 = 0;
    let mut ndead: i64 = 0;
    for i in 0..jobs.len() {
        if jobs[i].state == "pending" {
            npend = npend + 1;
        } else if jobs[i].state == "done" {
            ndone = ndone + 1;
        } else if jobs[i].state == "dead" {
            ndead = ndead + 1;
        }
    }
    out.push(format!("pending {} done {} dead {}", npend, ndone, ndead));

    Ok(out.join("\n"))
}

