                    let better = if jobs[i].priority != jobs[b].priority {
                        jobs[i].priority > jobs[b].priority
                    } else if jobs[i].due != jobs[b].due {
                        jobs[i].due < jobs[b].due
                    } else {
                        jobs[i].id < jobs[b].id
                    };
                    if better {
                        best = i as i64;
                    }
                }
            }
