        } else if jobs[k].attempts == 4 {
            jobs[k].state = "dead".to_string();
            out.push(format!("dead {}", jid));
        } else {
            let wait: i64 = if jobs[k].attempts == 1 {
                60
            } else if jobs[k].attempts == 2 {
                120
            } else {
                240
            };
            jobs[k].due = now + wait * 1000;
            out.push(format!("retry {} in {}", jid, wait));
        }

        queue.set(
            format!("job:{}", jid),
            encode(jobs[k].priority, jobs[k].attempts, jobs[k].due, jobs[k].state.clone()),
        );
    }

    // Summary
    let mut npend: i64 = 0;
    let mut ndone: i64 = 0;
    let mut ndead: i64 = 0;
    for i in 0..jobs.len() {
        if jobs[i].state == "pending" {
