        } else if jobs[i].state == "done" {
            ndone = ndone + 1;
        } else if jobs[i].state == "dead" {
            ndead = ndead + 1;
        }
    }
    out.push(format!("pending {} done {} dead {}", npend, ndone, ndead));

    Ok(out.join("\n"))
}

