const MAX: i64 = 9223372036854775807;
const MIN: i64 = -9223372036854775807 - 1;

fn ovf() -> String {
    "overflow".to_string()
}

fn is_punct(c: char) -> bool {
    c == '+' || c == '-' || c == '*' || c == '/' || c == '%'
        || c == '^' || c == '(' || c == ')' || c == ',' || c == '='
}

fn tokenize(line: &str) -> Option<Vec<String>> {
    let chars: Vec<char> = line.chars().collect();
    let mut toks: Vec<String> = Vec::new();
    let mut i: usize = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == ' ' {
            i += 1;
        } else if c.is_ascii_digit() {
            let mut t = String::new();
            while i < chars.len() && chars[i].is_ascii_digit() {
                t.push(chars[i]);
                i += 1;
            }
            toks.push(t);
        } else if c.is_ascii_alphabetic() || c == '_' {
            let mut t = String::new();
            while i < chars.len() && (chars[i].is_ascii_alphanumeric() || chars[i] == '_') {
                t.push(chars[i]);
                i += 1;
            }
            toks.push(t);
        } else if is_punct(c) {
            toks.push(c.to_string());
            i += 1;
        } else {
            return None;
        }
    }
    Some(toks)
}

fn first_char(t: &str) -> char {
    t.chars().next().unwrap()
}

fn is_int(t: &str) -> bool {
    first_char(t).is_ascii_digit()
}

fn is_name(t: &str) -> bool {
    let c = first_char(t);
    c.is_ascii_alphabetic() || c == '_'
}

// ---------- syntax check (no evaluation) ----------

struct Checker {
    toks: Vec<String>,
    pos: usize,
}

impl Checker {
    fn at(&self, s: &str) -> bool {
        self.pos < self.toks.len() && self.toks[self.pos] == s
    }

    fn expr(&mut self) -> bool {
        if !self.term() {
            return false;
        }
        while self.at("+") || self.at("-") {
            self.pos += 1;
            if !self.term() {
                return false;
            }
        }
        true
    }

    fn term(&mut self) -> bool {
        if !self.factor() {
            return false;
        }
        while self.at("*") || self.at("/") || self.at("%") {
            self.pos += 1;
            if !self.factor() {
                return false;
            }
        }
        true
    }

    fn factor(&mut self) -> bool {
        if self.at("-") {
            self.pos += 1;
            return self.factor();
        }
        self.power()
    }

    fn power(&mut self) -> bool {
        if !self.atom() {
            return false;
        }
        if self.at("^") {
            self.pos += 1;
            return self.factor();
        }
        true
    }

    fn atom(&mut self) -> bool {
        if self.pos >= self.toks.len() {
            return false;
        }
        let t = self.toks[self.pos].clone();
        if is_int(&t) {
            self.pos += 1;
            return true;
        }
        if is_name(&t) {
            self.pos += 1;
            if self.at("(") {
                self.pos += 1;
                if !self.expr() {
                    return false;
                }
                while self.at(",") {
                    self.pos += 1;
                    if !self.expr() {
                        return false;
                    }
                }
                if !self.at(")") {
                    return false;
                }
                self.pos += 1;
            }
            return true;
        }
        if t == "(" {
            self.pos += 1;
            if !self.expr() {
                return false;
            }
            if !self.at(")") {
                return false;
            }
            self.pos += 1;
            return true;
        }
        false
    }
}

fn is_valid(toks: &Vec<String>) -> bool {
    let mut ch = Checker { toks: toks.clone(), pos: 0 };
    if toks[0] == "let" {
        if toks.len() < 4 || !is_name(&toks[1]) || toks[2] != "=" {
            return false;
        }
        ch.pos = 3;
    }
    ch.expr() && ch.pos == toks.len()
}

// ---------- arithmetic (no u64, no large literals) ----------

fn neg(a: i64) -> Result<i64, String> {
    if a == MIN {
        Err(ovf())
    } else {
        Ok(-a)
    }
}

fn add(a: i64, b: i64) -> Result<i64, String> {
    if (b > 0 && a > MAX - b) || (b < 0 && a < MIN - b) {
        return Err(ovf());
    }
    Ok(a + b)
}

fn sub(a: i64, b: i64) -> Result<i64, String> {
    if (b > 0 && a < MIN + b) || (b < 0 && a > MAX + b) {
        return Err(ovf());
    }
    Ok(a - b)
}

fn mul(a: i64, b: i64) -> Result<i64, String> {
    if a == 0 || b == 0 {
        return Ok(0);
    }
    if a == 1 {
        return Ok(b);
    }
    if b == 1 {
        return Ok(a);
    }
    if a == -1 {
        return neg(b);
    }
    if b == -1 {
        return neg(a);
    }
    // Now |a| >= 2 and |b| >= 2.
    if b > 0 {
        if a > MAX / b || a < MIN / b {
            return Err(ovf());
        }
    } else {
        if a < MAX / b || a > MIN / b {
            return Err(ovf());
        }
    }
    Ok(a * b)
}

fn div(a: i64, b: i64) -> Result<i64, String> {
    if b == 0 {
        return Err("division by zero".to_string());
    }
    if a == MIN && b == -1 {
        return Err(ovf());
    }
    Ok(a / b)
}

fn rem(a: i64, b: i64) -> Result<i64, String> {
    if b == 0 {
        return Err("division by zero".to_string());
    }
    if b == -1 {
        return Ok(0);
    }
    Ok(a % b)
}

fn ipow(base: i64, e: i64) -> Result<i64, String> {
    if e < 0 {
        return Err("negative exponent".to_string());
    }
    let mut result: i64 = 1;
    let mut b: i64 = base;
    let mut k: i64 = e;
    while k > 0 {
        if k % 2 == 1 {
            result = mul(result, b)?;
        }
        k = k / 2;
        if k > 0 {
            b = mul(b, b)?;
        }
    }
    Ok(result)
}

fn parse_lit(t: &str) -> Result<i64, String> {
    let mut v: i64 = 0;
    for c in t.chars() {
        let d: i64 = (c as i64) - 48;
        if v > (MAX - d) / 10 {
            return Err(ovf());
        }
        v = v * 10 + d;
    }
    Ok(v)
}

fn call(name: &str, args: &Vec<i64>) -> Result<i64, String> {
    if name == "min" {
        Ok(if args[0] < args[1] { args[0] } else { args[1] })
    } else if name == "max" {
        Ok(if args[0] > args[1] { args[0] } else { args[1] })
    } else {
        if args[0] < 0 {
            neg(args[0])
        } else {
            Ok(args[0])
        }
    }
}

// ---------- evaluation (syntax already verified) ----------

struct Eval {
    toks: Vec<String>,
    pos: usize,
    names: Vec<String>,
    vals: Vec<i64>,
}

impl Eval {
    fn at(&self, s: &str) -> bool {
        self.pos < self.toks.len() && self.toks[self.pos] == s
    }

    fn count_args(&self) -> usize {
        let mut depth: usize = 0;
        let mut n: usize = 1;
        let mut i = self.pos;
        loop {
            let t = self.toks[i].as_str();
            if t == "(" {
                depth += 1;
            } else if t == ")" {
                if depth == 0 {
                    return n;
                }
                depth -= 1;
            } else if t == "," && depth == 0 {
                n += 1;
            }
            i += 1;
        }
    }

    fn lookup(&self, name: &str) -> Result<i64, String> {
        let mut i = self.names.len();
        while i > 0 {
            i -= 1;
            if self.names[i] == name {
                return Ok(self.vals[i]);
            }
        }
        Err(format!("unknown variable {}", name))
    }

    fn expr(&mut self) -> Result<i64, String> {
        let mut v = self.term()?;
        while self.at("+") || self.at("-") {
            let op = self.toks[self.pos].clone();
            self.pos += 1;
            let r = self.term()?;
            v = if op == "+" { add(v, r)? } else { sub(v, r)? };
        }
        Ok(v)
    }

    fn term(&mut self) -> Result<i64, String> {
        let mut v = self.factor()?;
        while self.at("*") || self.at("/") || self.at("%") {
            let op = self.toks[self.pos].clone();
            self.pos += 1;
            let r = self.factor()?;
            v = if op == "*" {
                mul(v, r)?
            } else if op == "/" {
                div(v, r)?
            } else {
                rem(v, r)?
            };
        }
        Ok(v)
    }

    fn factor(&mut self) -> Result<i64, String> {
        if self.at("-") {
            self.pos += 1;
            let v = self.factor()?;
            return neg(v);
        }
        self.power()
    }

    fn power(&mut self) -> Result<i64, String> {
        let base = self.atom()?;
        if self.at("^") {
            self.pos += 1;
            let e = self.factor()?;
            return ipow(base, e);
        }
        Ok(base)
    }

    fn atom(&mut self) -> Result<i64, String> {
        let t = self.toks[self.pos].clone();
        self.pos += 1;
        if is_int(&t) {
            return parse_lit(&t);
        }
        if t == "(" {
            let v = self.expr()?;
            self.pos += 1; // ')'
            return Ok(v);
        }
        if self.at("(") {
            let arity: usize = match t.as_str() {
                "min" => 2,
                "max" => 2,
                "abs" => 1,
                _ => return Err(format!("unknown function {}", t)),
            };
            self.pos += 1; // '('
            let n = self.count_args();
            if n != arity {
                return Err(format!("wrong number of arguments to {}", t));
            }
            let mut args: Vec<i64> = Vec::new();
            loop {
                let v = self.expr()?;
                args.push(v);
                if self.at(",") {
                    self.pos += 1;
                } else {
                    break;
                }
            }
            self.pos += 1; // ')'
            return call(t.as_str(), &args);
        }
        self.lookup(t.as_str())
    }
}

