fn is_digit(c: u8) -> bool {
    c >= 48 && c <= 57
}

fn is_alpha(c: u8) -> bool {
    (c >= 65 && c <= 90) || (c >= 97 && c <= 122)
}

fn is_punct(c: u8) -> bool {
    // + - * / % ^ ( ) , =
    c == 43 || c == 45 || c == 42 || c == 47 || c == 37
        || c == 94 || c == 40 || c == 41 || c == 44 || c == 61
}

fn tokenize(line: &str) -> Option<Vec<String>> {
    let b = line.as_bytes();
    let mut toks: Vec<String> = Vec::new();
    let mut i: usize = 0;
    while i < b.len() {
        let c = b[i];
        if c == 32 || c == 13 {
            i += 1;
        } else if is_digit(c) {
            let s = i;
            while i < b.len() && is_digit(b[i]) {
                i += 1;
            }
            toks.push(line[s..i].to_string());
        } else if is_alpha(c) || c == 95 {
            let s = i;
            while i < b.len() && (is_alpha(b[i]) || is_digit(b[i]) || b[i] == 95) {
                i += 1;
            }
            toks.push(line[s..i].to_string());
        } else if is_punct(c) {
            toks.push(line[i..i + 1].to_string());
            i += 1;
        } else {
            return None;
        }
    }
    Some(toks)
}

