}

impl Eval {
    fn at(&self, s: &str) -> bool {
        self.pos < self.toks.len() && self.toks[self.pos] == s
    }

    fn count_args(&self) -> usize {
        let mut depth: usize = 0;
        let mut n: usize = 1;
        let mut i = self.pos;
        loop {
            let t = self.toks[i].as_str();
            if t == "(" {
                depth += 1;
            } else if t == ")" {
                if depth == 0 {
                    return n;
                }
                depth -= 1;
            } else if t == "," && depth == 0 {
                n += 1;
            }
            i += 1;
        }
    }

    fn lookup(&self, name: &str) -> Result<i64, String> {
        let mut i = self.names.len();
        while i > 0 {
            i -= 1;
            if self.names[i] == name {
                return Ok(self.vals[i]);
            }
        }
        Err(format!("unknown variable {}", name))
    }

    fn expr(&mut self) -> Result<i64, String> {
        let mut v = self.term()?;
        while self.at("+") || self.at("-") {
            let op = self.toks[self.pos].clone();
            self.pos += 1;
            let r = self.term()?;
            v = if op == "+" { add(v, r)? } else { sub(v, r)? };
        }
        Ok(v)
    }

    fn term(&mut self) -> Result<i64, String> {
        let mut v = self.factor()?;
        while self.at("*") || self.at("/") || self.at("%") {
            let op = self.toks[self.pos].clone();
            self.pos += 1;
            let r = self.factor()?;
            v = if op == "*" {
                mul(v, r)?
            } else if op == "/" {
                div(v, r)?
            } else {
                rem(v, r)?
            };
        }
        Ok(v)
    }

    fn factor(&mut self) -> Result<i64, String> {
        if self.at("-") {
            self.pos += 1;
            let v = self.factor()?;
            return neg(v);
        }
        self.power()
    }

    fn power(&mut self) -> Result<i64, String> {
        let base = self.atom()?;
        if self.at("^") {
            self.pos += 1;
            let e = self.factor()?;
            return ipow(base, e);
        }
        Ok(base)
    }

    fn atom(&mut self) -> Result<i64, String> {
        let t = self.toks[self.pos].clone();
        self.pos += 1;
        if is_int(&t) {
            return parse_lit(&t);
        }
        if t == "(" {
            let v = self.expr()?;
            self.pos += 1; // ')'
            return Ok(v);
        }
        if self.at("(") {
            let arity: usize = match t.as_str() {
                "min" => 2,
                "max" => 2,
                "abs" => 1,
                _ => return Err(format!("unknown function {}", t)),
            };
            self.pos += 1; // '('
            let n = self.count_args();
            if n != arity {
                return Err(format!("wrong number of arguments to {}", t));
            }
            let mut args: Vec<i64> = Vec::new();
            loop {
                let v = self.expr()?;
                args.push(v);
                if self.at(",") {
                    self.pos += 1;
                } else {
                    break;
                }
            }
            self.pos += 1; // ')'
            return call(t.as_str(), &args);
        }
        self.lookup(t.as_str())
    }
}

// ---------- entry point ----------

fn main(input: Dir) -> Result<Str, Str> {
    let text = match input.read("program.txt") {
        Ok(t) => t,
        Err(_) => return Err("cannot read program.txt".to_string()),
    };

    let b = text.as_bytes();
    let mut lines: Vec<String> = Vec::new();
    let mut start: usize = 0;
    let mut i: usize = 0;
    while i < b.len() {
        if b[i] == 10 {
            lines.push(text[start..i].to_string());
            start = i + 1;
        }
        i += 1;
    }
    lines.push(text[start..b.len()].to_string());

    let mut results: Vec<String> = Vec::new();
    let mut names: Vec<String> = Vec::new();
    let mut vals: Vec<i64> = Vec::new();
    let mut lineno: usize = 0;

    for line in lines.iter() {
        lineno += 1;
        let toks = match tokenize(line) {
            Some(t) => t,
            None => {
                results.push(format!("{}: error: syntax error", lineno));
                continue;
            }
        };
        if toks.is_empty() {
            continue;
        }
        if !is_valid(&toks) {
            results.push(format!("{}: error: syntax error", lineno));
            continue;
        }
        if toks[0] == "let" {
            let name = toks[1].clone();
            let mut ev = Eval {
                toks: toks.clone(),
                pos: 3,
                names: names.clone(),
                vals: vals.clone(),
            };
            match ev.expr() {
                Ok(v) => {
                    names.push(name.clone());
                    vals.push(v);
                    results.push(format!("{}: {} = {}", lineno, name, v));
                }
                Err(e) => results.push(format!("{}: error: {}", lineno, e)),
            }
        } else {
            let mut ev = Eval {
                toks: toks.clone(),
                pos: 0,
                names: names.clone(),
                vals: vals.clone(),
            };
            match ev.expr() {
                Ok(v) => results.push(format!("{}: {}", lineno, v)),
                Err(e) => results.push(format!("{}: error: {}", lineno, e)),
            }
        }
    }

    Ok(results.join("\n"))
}

const MAX: i64 = 9223372036854775807;
const MIN: i64 = -9223372036854775807 - 1;

fn ovf() -> Str {
    "overflow".to_string()
}

fn is_digit(c: u8) -> bool {
    c >= 48 && c <= 57
}

fn is_alpha(c: u8) -> bool {
    (c >= 65 && c <= 90) || (c >= 97 && c <= 122)
}

fn is_punct(c: u8) -> bool {
    // + - * / % ^ ( ) , =
    c == 43 || c == 45 || c == 42 || c == 47 || c == 37
        || c == 94 || c == 40 || c == 41 || c == 44 || c == 61
}

fn tokenize(line: Str) -> Option<Vec<Str>> {
    let b = line.as_bytes();
    let mut toks: Vec<Str> = Vec::new();
    let mut i: usize = 0;
    while i < b.len() {
        let c = b[i];
        if c == 32 || c == 13 {
            i += 1;
        } else if is_digit(c) {
            let s = i;
            while i < b.len() && is_digit(b[i]) {
                i += 1;
            }
            toks.push(line[s..i].to_string());
        } else if is_alpha(c) || c == 95 {
            let s = i;
            while i < b.len() && (is_alpha(b[i]) || is_digit(b[i]) || b[i] == 95) {
                i += 1;
            }
            toks.push(line[s..i].to_string());
        } else if is_punct(c) {
            toks.push(line[i..i + 1].to_string());
            i += 1;
        } else {
            return None;
        }
    }
    Some(toks)
}

fn first_byte(t: Str) -> u8 {
    t.as_bytes()[0]
}

fn is_int(t: Str) -> bool {
    is_digit(first_byte(t))
}

fn is_name(t: Str) -> bool {
    let c = first_byte(t);
    is_alpha(c) || c == 95
}

// ---------- evaluator/checker state (passed by value) ----------

struct St {
    toks: Vec<Str>,
    pos: usize,
    cur: Str,
    acc: i64,
    names: Vec<Str>,
    vals: Vec<i64>,
}

fn mk(toks: Vec<Str>, pos: usize, names: Vec<Str>, vals: Vec<i64>) -> St {
    let cur = if pos < toks.len() {
        toks[pos].clone()
    } else {
        "".to_string()
    };
    St {
        toks: toks,
        pos: pos,
        cur: cur,
        acc: 0,
        names: names,
        vals: vals,
    }
}

fn adv(s: St) -> St {
    let mut t = s;
    t.pos += 1;
    if t.pos < t.toks.len() {
        t.cur = t.toks[t.pos].clone();
    } else {
        t.cur = "".to_string();
    }
    t
}

// ---------- syntax check (no evaluation) ----------

fn c_expr(s: St) -> Result<St, Str> {
    let mut t = c_term(s)?;
    while t.cur == "+" || t.cur == "-" {
        t = adv(t);
        t = c_term(t)?;
    }
    Ok(t)
}

fn c_term(s: St) -> Result<St, Str> {
    let mut t = c_factor(s)?;
    while t.cur == "*" || t.cur == "/" || t.cur == "%" {
        t = adv(t);
        t = c_factor(t)?;
    }
    Ok(t)
}

fn c_factor(s: St) -> Result<St, Str> {
    if s.cur == "-" {
        return c_factor(adv(s));
    }
    c_power(s)
}

fn c_power(s: St) -> Result<St, Str> {
    let t = c_atom(s)?;
    if t.cur == "^" {
        return c_factor(adv(t));
    }
    Ok(t)
}

fn c_atom(s: St) -> Result<St, Str> {
    if s.pos >= s.toks.len() {
        return Err("bad".to_string());
    }
    let tok = s.toks[s.pos].clone();
    if is_int(tok.clone()) {
        return Ok(adv(s));
    }
    if tok == "(" {
        let mut t = adv(s);
        t = c_expr(t)?;
        if t.cur != ")" {
            return Err("bad".to_string());
        }
        return Ok(adv(t));
    }
    if is_name(tok) {
        let mut t = adv(s);
        if t.cur == "(" {
            t = adv(t);
            t = c_expr(t)?;
            while t.cur == "," {
                t = adv(t);
                t = c_expr(t)?;
            }
            if t.cur != ")" {
                return Err("bad".to_string());
            }
            t = adv(t);
        }
        return Ok(t);
    }
    Err("bad".to_string())
}

fn is_valid(toks: Vec<Str>) -> bool {
    let names: Vec<Str> = Vec::new();
    let vals: Vec<i64> = Vec::new();
    if toks[0] == "let" {
        if toks.len() < 4 || !is_name(toks[1].clone()) || toks[2] != "=" {
            return false;
        }
        let st = mk(toks.clone(), 3, names, vals);
        return match c_expr(st) {
            Ok(t) => t.pos == t.toks.len(),
            Err(_) => false,
        };
    }
    let st = mk(toks.clone(), 0, names, vals);
    match c_expr(st) {
        Ok(t) => t.pos == t.toks.len(),
        Err(_) => false,
    }
}

// ---------- arithmetic ----------

fn neg(a: i64) -> Result<i64, Str> {
    if a == MIN {
        Err(ovf())
    } else {
        Ok(-a)
    }
}

fn add(a: i64, b: i64) -> Result<i64, Str> {
    if (b > 0 && a > MAX - b) || (b < 0 && a < MIN - b) {
        return Err(ovf());
    }
    Ok(a + b)
}

fn sub(a: i64, b: i64) -> Result<i64, Str> {
    if (b > 0 && a < MIN + b) || (b < 0 && a > MAX + b) {
        return Err(ovf());
    }
    Ok(a - b)
}

fn mul(a: i64, b: i64) -> Result<i64, Str> {
    if a == 0 || b == 0 {
        return Ok(0);
    }
    if a == 1 {
        return Ok(b);
    }
    if b == 1 {
        return Ok(a);
    }
    if a == -1 {
        return neg(b);
    }
    if b == -1 {
        return neg(a);
    }
    // Now |a| >= 2 and |b| >= 2.
    if b > 0 {
        if a > MAX / b || a < MIN / b {
            return Err(ovf());
        }
    } else {
        if a < MAX / b || a > MIN / b {
            return Err(ovf());
        }
    }
    Ok(a * b)
}

fn div(a: i64, b: i64) -> Result<i64, Str> {
    if b == 0 {
        return Err("division by zero".to_string());
    }
    if a == MIN && b == -1 {
        return Err(ovf());
    }
    Ok(a / b)
}

fn rem(a: i64, b: i64) -> Result<i64, Str> {
    if b == 0 {
        return Err("division by zero".to_string());
    }
    if b == -1 {
        return Ok(0);
    }
    Ok(a % b)
}

fn ipow(base: i64, e: i64) -> Result<i64, Str> {
    if e < 0 {
        return Err("negative exponent".to_string());
    }
    let mut result: i64 = 1;
    let mut b: i64 = base;
    let mut k: i64 = e;
    while k > 0 {
        if k % 2 == 1 {
            result = mul(result, b)?;
        }
        k = k / 2;
        if k > 0 {
            b = mul(b, b)?;
        }
    }
    Ok(result)
}

fn parse_lit(t: Str) -> Result<i64, Str> {
    let b = t.as_bytes();
    let mut v: i64 = 0;
    let mut i: usize = 0;
    while i < b.len() {
        let d: i64 = (b[i] as i64) - 48;
        if v > (MAX - d) / 10 {
            return Err(ovf());
        }
        v = v * 10 + d;
        i += 1;
    }
    Ok(v)
}

fn call_fn(name: Str, args: Vec<i64>) -> Result<i64, Str> {
    if name == "min" {
        let a = args[0];
        let b = args[1];
        Ok(if a < b { a } else { b })
    } else if name == "max" {
        let a = args[0];
        let b = args[1];
        Ok(if a > b { a } else { b })
    } else {
        if args[0] < 0 {
            neg(args[0])
        } else {
            Ok(args[0])
        }
    }
}

// ---------- evaluation (syntax already verified) ----------

fn e_expr(s: St) -> Result<St, Str> {
    let mut t = e_term(s)?;
    while t.cur == "+" || t.cur == "-" {
        let plus = t.cur == "+";
        let v0 = t.acc;
        t = adv(t);
        t = e_term(t)?;
        let r = t.acc;
        t.acc = if plus { add(v0, r)? } else { sub(v0, r)? };
    }
    Ok(t)
}

fn e_term(s: St) -> Result<St, Str> {
    let mut t = e_factor(s)?;
    while t.cur == "*" || t.cur == "/" || t.cur == "%" {
        let op = t.cur.clone();
        let v0 = t.acc;
        t = adv(t);
        t = e_factor(t)?;
        let r = t.acc;
        t.acc = if op == "*" {
            mul(v0, r)?
        } else if op == "/" {
            div(v0, r)?
        } else {
            rem(v0, r)?
        };
    }
    Ok(t)
}

fn e_factor(s: St) -> Result<St, Str> {
    if s.cur == "-" {
        let mut t = adv(s);
        t = e_factor(t)?;
        t.acc = neg(t.acc)?;
        return Ok(t);
    }
    e_power(s)
}

fn e_power(s: St) -> Result<St, Str> {
    let mut t = e_atom(s)?;
    if t.cur == "^" {
        let base = t.acc;
        t = adv(t);
        t = e_factor(t)?;
        t.acc = ipow(base, t.acc)?;
    }
    Ok(t)
}

fn e_atom(s: St) -> Result<St, Str> {
    let tok = s.toks[s.pos].clone();
    if is_int(tok.clone()) {
        let v = parse_lit(tok.clone())?;
        let mut t = adv(s);
        t.acc = v;
        return Ok(t);
    }
    if tok == "(" {
        let mut t = adv(s);
        t = e_expr(t)?;
        t = adv(t); // ')'
        return Ok(t);
    }
    let mut t = adv(s);
    if t.cur == "(" {
        if tok != "min" && tok != "max" && tok != "abs" {
            return Err(format!("unknown function {}", tok));
        }
        let arity: usize = if tok == "abs" { 1 } else { 2 };
        // Count arguments before evaluating any of them.
        let mut depth: usize = 0;
        let mut n: usize = 1;
        let mut i: usize = t.pos + 1;
        loop {
            if t.toks[i] == "(" {
                depth += 1;
            } else if t.toks[i] == ")" {
                if depth == 0 {
                    break;
                }
                depth -= 1;
            } else if t.toks[i] == "," && depth == 0 {
                n += 1;
            }
            i += 1;
        }
        if n != arity {
            return Err(format!("wrong number of arguments to {}", tok));
        }
        let mut args: Vec<i64> = Vec::new();
        loop {
            t = adv(t); // past '(' or ','
            t = e_expr(t)?;
            args.push(t.acc);
            if t.cur != "," {
                break;
            }
        }
        t = adv(t); // ')'
        let v = call_fn(tok.clone(), args)?;
        t.acc = v;
        return Ok(t);
    }
    // Variable reference.
    let mut found = false;
    let mut v: i64 = 0;
    let mut i: usize = t.names.len();
    while i > 0 {
        i -= 1;
        if t.names[i] == tok {
            v = t.vals[i];
            found = true;
            break;
        }
    }
    if !found {
        return Err(format!("unknown variable {}", tok));
    }
    t.acc = v;
    Ok(t)
}

// ---------- entry point ----------

fn main(input: Dir) -> Result<Str, Str> {
    let text = match input.read("program.txt") {
        Ok(t) => t,
        Err(_) => return Err("cannot read program.txt".to_string()),
    };

    let b = text.as_bytes();
    let mut lines: Vec<Str> = Vec::new();
    let mut start: usize = 0;
    let mut i: usize = 0;
    while i < b.len() {
        if b[i] == 10 {
            lines.push(text[start..i].to_string());
            start = i + 1;
        }
        i += 1;
    }
    lines.push(text[start..b.len()].to_string());

    let mut results: Vec<Str> = Vec::new();
    let mut names: Vec<Str> = Vec::new();
    let mut vals: Vec<i64> = Vec::new();
    let mut lineno: usize = 0;

    for line in lines.iter() {
        lineno += 1;
        let toks = match tokenize(line.clone()) {
            Some(t) => t,
            None => {
                results.push(format!("{}: error: syntax error", lineno));
                continue;
            }
        };
        if toks.len() == 0 {
            continue;
        }
        if !is_valid(toks.clone()) {
            results.push(format!("{}: error: syntax error", lineno));
            continue;
        }
        let is_let = toks[0] == "let";
        let start_pos: usize = if is_let { 3 } else { 0 };
        let st = mk(toks.clone(), start_pos, names.clone(), vals.clone());
        match e_expr(st) {
            Ok(t) => {
                if is_let {
                    let name = toks[1].clone();
                    names.push(name.clone());
                    vals.push(t.acc);
                    results.push(format!("{}: {} = {}", lineno, name, t.acc));
                } else {
                    results.push(format!("{}: {}", lineno, t.acc));
                }
            }
            Err(e) => results.push(format!("{}: error: {}", lineno, e)),
        }
    }

    Ok(results.join("\n"))
}

const MAX: i64 = 9223372036854775807;
const MIN: i64 = -9223372036854775807 - 1;

fn ovf() -> Str {
    "overflow".to_string()
}

fn is_digit(c: u8) -> bool {
    c >= 48 && c <= 57
}

fn is_alpha(c: u8) -> bool {
    (c >= 65 && c <= 90) || (c >= 97 && c <= 122)
}

fn is_punct(c: u8) -> bool {
    // + - * / % ^ ( ) , =
    c == 43 || c == 45 || c == 42 || c == 47 || c == 37
        || c == 94 || c == 40 || c == 41 || c == 44 || c == 61
}

fn ch(c: u8) -> Str {
    format!("{}", c as char)
}

fn substr(s: Str, from: usize, to: usize) -> Str {
    let b = s.as_bytes();
    let mut out = "".to_string();
    let mut k: usize = from;
    while k < to {
        let c = b[k];
        out = format!("{}{}", out, c as char);
        k += 1;
    }
    out
}

fn tokenize(line: Str) -> Option<Vec<Str>> {
    let b = line.as_bytes();
    let mut toks: Vec<Str> = Vec::new();
    let mut i: usize = 0;
    while i < b.len() {
        let c = b[i];
        if c == 32 || c == 13 {
            i += 1;
        } else if is_digit(c) {
            let s = i;
            while i < b.len() && is_digit(b[i]) {
                i += 1;
            }
            toks.push(substr(line.clone(), s, i));
        } else if is_alpha(c) || c == 95 {
            let s = i;
            while i < b.len() && (is_alpha(b[i]) || is_digit(b[i]) || b[i] == 95) {
                i += 1;
            }
            toks.push(substr(line.clone(), s, i));
        } else if is_punct(c) {
            toks.push(ch(c));
            i += 1;
        } else {
            return None;
        }
    }
    Some(toks)
}

fn first_byte(t: Str) -> u8 {
    t.as_bytes()[0]
}

fn is_int(t: Str) -> bool {
    is_digit(first_byte(t))
}

fn is_name(t: Str) -> bool {
    let c = first_byte(t);
    is_alpha(c) || c == 95
}

// ---------- evaluator/checker state (passed by value) ----------

struct St {
    toks: Vec<Str>,
    pos: usize,
    cur: Str,
    acc: i64,
    names: Vec<Str>,
    vals: Vec<i64>,
}

fn mk(toks: Vec<Str>, pos: usize, names: Vec<Str>, vals: Vec<i64>) -> St {
    let cur = if pos < toks.len() {
        toks[pos].clone()
    } else {
        "".to_string()
    };
    St {
        toks: toks,
        pos: pos,
        cur: cur,
        acc: 0,
        names: names,
        vals: vals,
    }
}

fn adv(s: St) -> St {
    let mut t = s;
    t.pos += 1;
    if t.pos < t.toks.len() {
        t.cur = t.toks[t.pos].clone();
    } else {
        t.cur = "".to_string();
    }
    t
}

// ---------- syntax check (no evaluation) ----------

fn c_expr(s: St) -> Result<St, Str> {
    let mut t = c_term(s)?;
    while t.cur == "+" || t.cur == "-" {
        t = adv(t);
        t = c_term(t)?;
    }
    Ok(t)
}

fn c_term(s: St) -> Result<St, Str> {
    let mut t = c_factor(s)?;
    while t.cur == "*" || t.cur == "/" || t.cur == "%" {
        t = adv(t);
        t = c_factor(t)?;
    }
    Ok(t)
}

fn c_factor(s: St) -> Result<St, Str> {
    if s.cur == "-" {
        return c_factor(adv(s));
    }
    c_power(s)
}

fn c_power(s: St) -> Result<St, Str> {
    let t = c_atom(s)?;
    if t.cur == "^" {
        return c_factor(adv(t));
    }
    Ok(t)
}

fn c_atom(s: St) -> Result<St, Str> {
    if s.pos >= s.toks.len() {
        return Err("bad".to_string());
    }
    let tok = s.toks[s.pos].clone();
    if is_int(tok.clone()) {
        return Ok(adv(s));
    }
    if tok == "(" {
        let mut t = adv(s);
        t = c_expr(t)?;
        if t.cur != ")" {
            return Err("bad".to_string());
        }
        return Ok(adv(t));
    }
    if is_name(tok) {
        let mut t = adv(s);
        if t.cur == "(" {
            t = adv(t);
            t = c_expr(t)?;
            while t.cur == "," {
                t = adv(t);
                t = c_expr(t)?;
            }
            if t.cur != ")" {
                return Err("bad".to_string());
            }
            t = adv(t);
        }
        return Ok(t);
    }
    Err("bad".to_string())
}

fn is_valid(toks: Vec<Str>) -> bool {
    let names: Vec<Str> = Vec::new();
    let vals: Vec<i64> = Vec::new();
    if toks[0] == "let" {
        if toks.len() < 4 || !is_name(toks[1].clone()) || toks[2] != "=" {
            return false;
        }
        let st = mk(toks.clone(), 3, names, vals);
        return match c_expr(st) {
            Ok(t) => t.pos == t.toks.len(),
            Err(_) => false,
        };
    }
    let st = mk(toks.clone(), 0, names, vals);
    match c_expr(st) {
        Ok(t) => t.pos == t.toks.len(),
        Err(_) => false,
    }
}

// ---------- arithmetic ----------

fn neg(a: i64) -> Result<i64, Str> {
    if a == MIN {
        Err(ovf())
    } else {
        Ok(-a)
    }
}

fn add(a: i64, b: i64) -> Result<i64, Str> {
    if (b > 0 && a > MAX - b) || (b < 0 && a < MIN - b) {
        return Err(ovf());
    }
    Ok(a + b)
}

fn sub(a: i64, b: i64) -> Result<i64, Str> {
    if (b > 0 && a < MIN + b) || (b < 0 && a > MAX + b) {
        return Err(ovf());
    }
    Ok(a - b)
}

fn mul(a: i64, b: i64) -> Result<i64, Str> {
    if a == 0 || b == 0 {
        return Ok(0);
    }
    if a == 1 {
        return Ok(b);
    }
    if b == 1 {
        return Ok(a);
    }
    if a == -1 {
        return neg(b);
    }
    if b == -1 {
        return neg(a);
    }
    // Now |a| >= 2 and |b| >= 2.
    if b > 0 {
        if a > MAX / b || a < MIN / b {
            return Err(ovf());
        }
    } else {
        if a < MAX / b || a > MIN / b {
            return Err(ovf());
        }
    }
    Ok(a * b)
}

fn div(a: i64, b: i64) -> Result<i64, Str> {
    if b == 0 {
        return Err("division by zero".to_string());
    }
    if a == MIN && b == -1 {
        return Err(ovf());
    }
    Ok(a / b)
}

fn rem(a: i64, b: i64) -> Result<i64, Str> {
    if b == 0 {
        return Err("division by zero".to_string());
    }
    if b == -1 {
        return Ok(0);
    }
    Ok(a % b)
}

fn ipow(base: i64, e: i64) -> Result<i64, Str> {
    if e < 0 {
        return Err("negative exponent".to_string());
    }
    let mut result: i64 = 1;
    let mut b: i64 = base;
    let mut k: i64 = e;
    while k > 0 {
        if k % 2 == 1 {
            result = mul(result, b)?;
        }
        k = k / 2;
        if k > 0 {
            b = mul(b, b)?;
        }
    }
    Ok(result)
}

fn parse_lit(t: Str) -> Result<i64, Str> {
    let b = t.as_bytes();
    let mut v: i64 = 0;
    let mut i: usize = 0;
    while i < b.len() {
        let d: i64 = (b[i] as i64) - 48;
        if v > (MAX - d) / 10 {
            return Err(ovf());
        }
        v = v * 10 + d;
        i += 1;
    }
    Ok(v)
}

fn call_fn(name: Str, args: Vec<i64>) -> Result<i64, Str> {
    if name == "min" {
        let a = args[0];
        let b = args[1];
        Ok(if a < b { a } else { b })
    } else if name == "max" {
        let a = args[0];
        let b = args[1];
        Ok(if a > b { a } else { b })
    } else {
        if args[0] < 0 {
            neg(args[0])
        } else {
            Ok(args[0])
        }
    }
}

// ---------- evaluation (syntax already verified) ----------

fn e_expr(s: St) -> Result<St, Str> {
    let mut t = e_term(s)?;
    while t.cur == "+" || t.cur == "-" {
        let plus = t.cur == "+";
        let v0 = t.acc;
        t = adv(t);
        t = e_term(t)?;
        let r = t.acc;
        t.acc = if plus { add(v0, r)? } else { sub(v0, r)? };
    }
    Ok(t)
}

fn e_term(s: St) -> Result<St, Str> {
    let mut t = e_factor(s)?;
    while t.cur == "*" || t.cur == "/" || t.cur == "%" {
        let op = t.cur.clone();
        let v0 = t.acc;
        t = adv(t);
        t = e_factor(t)?;
        let r = t.acc;
        t.acc = if op == "*" {
            mul(v0, r)?
        } else if op == "/" {
            div(v0, r)?
        } else {
            rem(v0, r)?
        };
    }
    Ok(t)
}

fn e_factor(s: St) -> Result<St, Str> {
    if s.cur == "-" {
        let mut t = adv(s);
        t = e_factor(t)?;
        t.acc = neg(t.acc)?;
        return Ok(t);
    }
    e_power(s)
}

fn e_power(s: St) -> Result<St, Str> {
    let mut t = e_atom(s)?;
    if t.cur == "^" {
        let base = t.acc;
        t = adv(t);
        t = e_factor(t)?;
        t.acc = ipow(base, t.acc)?;
    }
    Ok(t)
}

fn e_atom(s: St) -> Result<St, Str> {
    let tok = s.toks[s.pos].clone();
    if is_int(tok.clone()) {
        let v = parse_lit(tok.clone())?;
        let mut t = adv(s);
        t.acc = v;
        return Ok(t);
    }
    if tok == "(" {
        let mut t = adv(s);
        t = e_expr(t)?;
        t = adv(t); // ')'
        return Ok(t);
    }
    let mut t = adv(s);
    if t.cur == "(" {
        if tok != "min" && tok != "max" && tok != "abs" {
            return Err(format!("unknown function {}", tok));
        }
        let arity: usize = if tok == "abs" { 1 } else { 2 };
        // Count arguments before evaluating any of them.
        let mut depth: usize = 0;
        let mut n: usize = 1;
        let mut i: usize = t.pos + 1;
        loop {
            if t.toks[i] == "(" {
                depth += 1;
            } else if t.toks[i] == ")" {
                if depth == 0 {
                    break;
                }
                depth -= 1;
            } else if t.toks[i] == "," && depth == 0 {
                n += 1;
            }
            i += 1;
        }
        if n != arity {
            return Err(format!("wrong number of arguments to {}", tok));
        }
        let mut args: Vec<i64> = Vec::new();
        loop {
            t = adv(t); // past '(' or ','
            t = e_expr(t)?;
            args.push(t.acc);
            if t.cur != "," {
                break;
            }
        }
        t = adv(t); // ')'
        let v = call_fn(tok.clone(), args)?;
        t.acc = v;
        return Ok(t);
    }
    // Variable reference.
    let mut found = false;
    let mut v: i64 = 0;
    let mut i: usize = t.names.len();
    while i > 0 {
        i -= 1;
        if t.names[i] == tok {
            v = t.vals[i];
            found = true;
            break;
        }
    }
    if !found {
        return Err(format!("unknown variable {}", tok));
    }
    t.acc = v;
    Ok(t)
}

// ---------- entry point ----------

fn main(input: Dir) -> Result<Str, Str> {
    let text = match input.read("program.txt") {
        Ok(t) => t,
        Err(_) => return Err("cannot read program.txt".to_string()),
    };

    let b = text.as_bytes();
    let mut lines: Vec<Str> = Vec::new();
    let mut start: usize = 0;
    let mut i: usize = 0;
    while i < b.len() {
        if b[i] == 10 {
            lines.push(substr(text.clone(), start, i));
            start = i + 1;
        }
        i += 1;
    }
    lines.push(substr(text.clone(), start, b.len()));

    let mut results: Vec<Str> = Vec::new();
    let mut names: Vec<Str> = Vec::new();
    let mut vals: Vec<i64> = Vec::new();
    let mut lineno: usize = 0;

    for line in lines.iter() {
        lineno += 1;
        let toks = match tokenize(line.clone()) {
            Some(t) => t,
            None => {
                results.push(format!("{}: error: syntax error", lineno));
                continue;
            }
        };
        if toks.len() == 0 {
            continue;
        }
        if !is_valid(toks.clone()) {
            results.push(format!("{}: error: syntax error", lineno));
            continue;
        }
        let is_let = toks[0] == "let";
        let start_pos: usize = if is_let { 3 } else { 0 };
        let st = mk(toks.clone(), start_pos, names.clone(), vals.clone());
        match e_expr(st) {
            Ok(t) => {
                if is_let {
                    let name = toks[1].clone();
                    names.push(name.clone());
                    vals.push(t.acc);
                    results.push(format!("{}: {} = {}", lineno, name, t.acc));
                } else {
                    results.push(format!("{}: {}", lineno, t.acc));
                }
            }
            Err(e) => results.push(format!("{}: error: {}", lineno, e)),
        }
    }

    Ok(results.join("\n"))
}

// Signed, ordered webhooks into SQLite.

const SCHEMA: [&str; 5] = [
    "CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY)",
    "CREATE TABLE IF NOT EXISTS pending (
        sub TEXT NOT NULL,
        seq INTEGER NOT NULL,
        id TEXT NOT NULL,
        type TEXT NOT NULL,
        PRIMARY KEY (sub, seq))",
    "CREATE TABLE IF NOT EXISTS subs (
        id TEXT PRIMARY KEY,
        state TEXT NOT NULL,
        seq INTEGER NOT NULL)",
    "CREATE TABLE IF NOT EXISTS history (
        n INTEGER PRIMARY KEY AUTOINCREMENT,
        sub TEXT NOT NULL,
        state TEXT NOT NULL)",
    "CREATE INDEX IF NOT EXISTS history_sub ON history (sub, n)",
];

struct Event {
    id: Str,
    kind: Str,
    sub: Str,
    seq: i64,
}

fn main(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<Str, Str> {
    for stmt in SCHEMA {
        db.exec(stmt, [])?;
    }
    let (status, body) = match route(&req, &db, &secrets, &log) {
        Ok(r) => r,
        Err(_) => (500, err("internal error")),
    };
    res.set_status(status);
    res.set_header("content-type", "application/json");
    res.send(body)?;
    Ok("handled".to_string())
}

fn route(req: &Incoming, db: &Db, secrets: &Dir, log: &Log) -> Result<(i64, Str), Str> {
    let path = req.path();
    if req.method() == "POST" && path == "/webhooks" {
        return handle_webhook(req, db, secrets, log);
    }
    if req.method() == "GET" {
        if let Some(id) = path.strip_prefix("/subscriptions/") {
            return handle_get(db, id);
        }
    }
    Ok((404, err("not found")))
}

fn handle_webhook(req: &Incoming, db: &Db, secrets: &Dir, log: &Log) -> Result<(i64, Str), Str> {
    let body: Vec<u8> = req.body();

    // Signature: sha256 over (secret || "." || body).
    let raw = secrets.read_string("webhook.key")?;
    let key = raw.strip_suffix('\n').unwrap_or(&raw).to_string();
    let mut msg: Vec<u8> = Vec::new();
    msg.extend(key.as_bytes());
    msg.push(b'.');
    msg.extend(body.iter());
    let expected = format!("sha256={}", sha256_hex(&msg));
    let given = req.header("x-signature").unwrap_or("".to_string());
    if !ct_eq(given.as_bytes(), expected.as_bytes()) {
        log.append("rejected signature")?;
        return Ok((401, err("bad signature")));
    }

    let ev = match parse_event(&body) {
        Some(e) => e,
        None => return Ok((400, err("invalid event"))),
    };

    db.exec("BEGIN IMMEDIATE", [])?;
    match ingest(db, log, ev) {
        Ok(out) => {
            db.exec("COMMIT", [])?;
            Ok(out)
        }
        Err(e) => {
            db.exec("ROLLBACK", [])?;
            Err(e)
        }
    }
}

fn parse_event(body: &[u8]) -> Option<Event> {
    let text = std::str::from_utf8(body).ok()?;
    let v = json::parse(text).ok()?;
    let obj = v.as_object()?;
    let id = obj.get("id")?.as_str()?;
    let kind = obj.get("type")?.as_str()?;
    let sub = obj.get("subscription")?.as_str()?;
    let seq = obj.get("seq")?.as_int()?;
    let known = kind == "subscription.created"
        || kind == "subscription.activated"
        || kind == "payment.failed"
        || kind == "subscription.canceled";
    if !known || seq < 1 {
        return None;
    }
    Some(Event { id, kind, sub, seq })
}

fn ingest(db: &Db, log: &Log, ev: Event) -> Result<(i64, Str), Str> {
    if !db.query("SELECT 1 FROM events WHERE id = ?", [ev.id.clone()])?.is_empty() {
        return Ok((200, "{\"status\": \"duplicate\"}".to_string()));
    }
    db.exec("INSERT INTO events (id) VALUES (?)", [ev.id.clone()])?;

    let last = last_seq(db, &ev.sub)?;
    if ev.seq <= last {
        return Ok((200, "{\"status\": \"stale\"}".to_string()));
    }
    if ev.seq > last + 1 {
        db.exec(
            "INSERT OR IGNORE INTO pending (sub, seq, id, type) VALUES (?, ?, ?, ?)",
            [ev.sub.clone(), ev.seq, ev.id.clone(), ev.kind.clone()],
        )?;
        return Ok((202, "{\"status\": \"queued\"}".to_string()));
    }

    apply(db, log, &ev)?;
    let mut applied: i64 = 1;
    let mut next = ev.seq + 1;
    loop {
        let rows = db.query(
            "SELECT id, type FROM pending WHERE sub = ? AND seq = ?",
            [ev.sub.clone(), next],
        )?;
        if rows.is_empty() {
            break;
        }
        let p = Event {
            id: rows[0].get_str(0)?,
            kind: rows[0].get_str(1)?,
            sub: ev.sub.clone(),
            seq: next,
        };
        db.exec("DELETE FROM pending WHERE sub = ? AND seq = ?", [p.sub.clone(), next])?;
        apply(db, log, &p)?;
        applied += 1;
        next += 1;
    }
    // Drop any leftover queued entries that are now stale.
    db.exec("DELETE FROM pending WHERE sub = ? AND seq <= ?", [ev.sub.clone(), next - 1])?;

    Ok((200, format!("{{\"status\": \"applied\", \"applied\": {}}}", applied)))
}

fn apply(db: &Db, log: &Log, ev: &Event) -> Result<(), Str> {
    let rows = db.query("SELECT state FROM subs WHERE id = ?", [ev.sub.clone()])?;
    let state: Str = if rows.is_empty() {
        "none".to_string()
    } else {
        rows[0].get_str(0)?
    };
    match next_state(&state, &ev.kind) {
        Some(new) => {
            db.exec(
                "INSERT INTO subs (id, state, seq) VALUES (?, ?, ?)
                 ON CONFLICT(id) DO UPDATE SET state = excluded.state, seq = excluded.seq",
                [ev.sub.clone(), new.clone(), ev.seq],
            )?;
            db.exec("INSERT INTO history (sub, state) VALUES (?, ?)", [ev.sub.clone(), new])?;
        }
        None => {
            log.append(&format!("invalid transition {}", ev.id))?;
            db.exec(
                "INSERT INTO subs (id, state, seq) VALUES (?, ?, ?)
                 ON CONFLICT(id) DO UPDATE SET seq = excluded.seq",
                [ev.sub.clone(), state, ev.seq],
            )?;
        }
    }
    Ok(())
}

fn next_state(state: &str, kind: &str) -> Option<Str> {
    let new = match (state, kind) {
        ("none", "subscription.created") => "created",
        ("created", "subscription.activated") => "active",
        ("past_due", "subscription.activated") => "active",
        ("active", "payment.failed") => "past_due",
        ("created", "subscription.canceled") => "canceled",
        ("active", "subscription.canceled") => "canceled",
        ("past_due", "subscription.canceled") => "canceled",
        _ => return None,
    };
    Some(new.to_string())
}

fn last_seq(db: &Db, sub: &str) -> Result<i64, Str> {
    let rows = db.query("SELECT seq FROM subs WHERE id = ?", [sub.to_string()])?;
    if rows.is_empty() {
        Ok(0)
    } else {
        rows[0].get_int(0)
    }
}

fn handle_get(db: &Db, id: &str) -> Result<(i64, Str), Str> {
    let rows = db.query("SELECT state, seq FROM subs WHERE id = ?", [id.to_string()])?;
    if rows.is_empty() {
        return Ok((404, err("not found")));
    }
    let state = rows[0].get_str(0)?;
    let seq = rows[0].get_int(1)?;
    let hist = db.query("SELECT state FROM history WHERE sub = ? ORDER BY n", [id.to_string()])?;
    let mut items: Vec<Str> = Vec::new();
    for h in hist {
        items.push(jstr(&h.get_str(0)?));
    }
    let body = format!(
        "{{\"id\": {}, \"state\": {}, \"seq\": {}, \"history\": [{}]}}",
        jstr(id),
        jstr(&state),
        seq,
        items.join(", ")
    );
    Ok((200, body))
}

fn ct_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut diff: u8 = 0;
    for i in 0..a.len() {
        diff |= a[i] ^ b[i];
    }
    diff == 0
}

fn jstr(s: &str) -> Str {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn err(msg: &str) -> Str {
    format!("{{\"error\": {}}}", jstr(msg))
}

